{"command":"cd /workspace/src && cat > lexer.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

type TokType int

const (
	TEOF TokType = iota
	TInlineHTML
	TOpenTagEcho // <?= : acts like "echo"
	TIdent       // identifiers, keywords, names (may contain backslashes)
	TVariable    // $name (Text = name without $)
	TInt
	TFloat
	TString       // constant string (already unescaped)
	TInterpString // interpolated string; Parts
	TOp           // operator / punctuation; Text is the operator
	TCast         // (int) etc; Text = normalized cast type
	TSemiClose    // ?> acting as ;
	THeredocStart // unused
)

type StrPart struct {
	Lit    string
	IsExpr bool
	Toks   []Token
}

type Token struct {
	Type  TokType
	Text  string
	Line  int
	Int   int64
	Float float64
	Parts []StrPart
	// for TInt/TFloat: raw text
}

func (t Token) String() string {
	switch t.Type {
	case TEOF:
		return "end of file"
	case TVariable:
		return "variable \"$" + t.Text + "\""
	case TIdent:
		return "identifier \"" + t.Text + "\""
	case TInt:
		return "integer \"" + t.Text + "\""
	case TFloat:
		return "floating-point number \"" + t.Text + "\""
	case TString, TInterpString:
		return "string content"
	case TSemiClose:
		return "token \"?>\""
	case TCast:
		return "\"(" + t.Text + ")\""
	}
	return "token \"" + t.Text + "\""
}

type LexError struct {
	Msg  string
	Line int
}

func (e *LexError) Error() string { return e.Msg }

type Lexer struct {
	src    string
	pos    int
	line   int
	toks   []Token
	inPHP  bool
	file   string
	// when lexing a sub-expression (inside {$...}), we stop at matching brace
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}
func isDigit(c byte) bool { return c >= '0' && c <= '9' }
func isHex(c byte) bool {
	return isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

var threeCharOps = []string{"<=>", "**=", "...", "<<=", ">>=", "===", "!==", "??=", "?->", "<<<"}
var twoCharOps = []string{"++", "--", "->", "=>", "::", "==", "!=", "<>", "<=", ">=", "&&", "||", "??", "+=", "-=", "*=", "/=", ".=", "%=", "&=", "|=", "^=", "<<", ">>", "**"}

var castTypes = map[string]string{
	"int": "int", "integer": "int", "bool": "bool", "boolean": "bool", "float": "float", "double": "float", "real": "float",
	"string": "string", "binary": "string", "array": "array", "object": "object", "unset": "unset",
}

func Lex(src string, file string) ([]Token, error) {
	lx := &Lexer{src: src, line: 1, file: file}
	err := lx.run()
	if err != nil {
		return nil, err
	}
	lx.toks = append(lx.toks, Token{Type: TEOF, Line: lx.line})
	return lx.toks, nil
}

// LexPHP lexes a string already in PHP mode (for -r code and interpolation)
func LexPHP(src string, file string, line int) ([]Token, error) {
	lx := &Lexer{src: src, line: line, file: file, inPHP: true}
	err := lx.run()
	if err != nil {
		return nil, err
	}
	lx.toks = append(lx.toks, Token{Type: TEOF, Line: lx.line})
	return lx.toks, nil
}

func (lx *Lexer) errf(format string, a ...interface{}) error {
	return &LexError{Msg: fmt.Sprintf(format, a...), Line: lx.line}
}

func (lx *Lexer) emit(t Token) {
	lx.toks = append(lx.toks, t)
}

func (lx *Lexer) run() error {
	for lx.pos < len(lx.src) {
		if !lx.inPHP {
			lx.lexHTML()
			continue
		}
		if err := lx.lexPHPToken(); err != nil {
			return err
		}
	}
	return nil
}

func (lx *Lexer) lexHTML() {
	start := lx.pos
	src := lx.src
	for lx.pos < len(src) {
		if src[lx.pos] == '<' && lx.pos+1 < len(src) && src[lx.pos+1] == '?' {
			rest := src[lx.pos+2:]
			if len(rest) >= 3 && strings.EqualFold(rest[:3], "php") && (len(rest) == 3 || isWS(rest[3])) {
				html := src[start:lx.pos]
				if html != "" {
					lx.emit(Token{Type: TInlineHTML, Text: html, Line: lx.line})
				}
				lx.countLines(html)
				lx.pos += 5
				// consume one whitespace char (newline) after <?php
				if lx.pos < len(src) {
					if src[lx.pos] == '\n' {
						lx.line++
						lx.pos++
					} else if src[lx.pos] == '\r' {
						lx.pos++
						if lx.pos < len(src) && src[lx.pos] == '\n' {
							lx.pos++
						}
						lx.line++
					} else if isWS(src[lx.pos]) {
						lx.pos++
					}
				}
				lx.inPHP = true
				return
			}
			if len(rest) >= 1 && rest[0] == '=' {
				html := src[start:lx.pos]
				if html != "" {
					lx.emit(Token{Type: TInlineHTML, Text: html, Line: lx.line})
				}
				lx.countLines(html)
				lx.pos += 3
				lx.emit(Token{Type: TOpenTagEcho, Text: "echo", Line: lx.line})
				lx.inPHP = true
				return
			}
			// short open tag
			html := src[start:lx.pos]
			if html != "" {
				lx.emit(Token{Type: TInlineHTML, Text: html, Line: lx.line})
			}
			lx.countLines(html)
			lx.pos += 2
			lx.inPHP = true
			return
		}
		lx.pos++
	}
	html := src[start:lx.pos]
	if html != "" {
		lx.emit(Token{Type: TInlineHTML, Text: html, Line: lx.line})
	}
	lx.countLines(html)
}

func isWS(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' }

func (lx *Lexer) countLines(s string) {
	lx.line += strings.Count(s, "\n")
}

func (lx *Lexer) lexPHPToken() error {
	src := lx.src
	c := src[lx.pos]
	// whitespace
	if isWS(c) {
		if c == '\n' {
			lx.line++
		}
		lx.pos++
		return nil
	}
	// close tag
	if c == '?' && lx.pos+1 < len(src) && src[lx.pos+1] == '>' {
		lx.emit(Token{Type: TSemiClose, Text: "?>", Line: lx.line})
		lx.pos += 2
		if lx.pos < len(src) && src[lx.pos] == '\n' {
			lx.pos++
			lx.line++
		} else if lx.pos+1 < len(src) && src[lx.pos] == '\r' && src[lx.pos+1] == '\n' {
			lx.pos += 2
			lx.line++
		}
		lx.inPHP = false
		return nil
	}
	// comments
	if c == '#' {
		if lx.pos+1 < len(src) && src[lx.pos+1] == '[' {
			// attribute: skip until matching ]
			return lx.skipAttribute()
		}
		lx.skipLineComment()
		return nil
	}
	if c == '/' && lx.pos+1 < len(src) {
		if src[lx.pos+1] == '/' {
			lx.skipLineComment()
			return nil
		}
		if src[lx.pos+1] == '*' {
			end := strings.Index(src[lx.pos+2:], "*/")
			if end < 0 {
				return lx.errf("Unterminated comment starting line %d", lx.line)
			}
			lx.countLines(src[lx.pos : lx.pos+2+end+2])
			lx.pos += 2 + end + 2
			return nil
		}
	}
	// variable
	if c == '$' && lx.pos+1 < len(src) && isIdentStart(src[lx.pos+1]) {
		start := lx.pos + 1
		p := start
		for p < len(src) && isIdentChar(src[p]) {
			p++
		}
		lx.emit(Token{Type: TVariable, Text: src[start:p], Line: lx.line})
		lx.pos = p
		return nil
	}
	// numbers
	if isDigit(c) || (c == '.' && lx.pos+1 < len(src) && isDigit(src[lx.pos+1])) {
		return lx.lexNumber()
	}
	// identifiers / names
	if isIdentStart(c) || (c == '\\' && lx.pos+1 < len(src) && isIdentStart(src[lx.pos+1])) {
		start := lx.pos
		p := lx.pos
		if src[p] == '\\' {
			p++
		}
		for p < len(src) {
			if isIdentChar(src[p]) {
				p++
			} else if src[p] == '\\' && p+1 < len(src) && isIdentStart(src[p+1]) {
				p++
			} else {
				break
			}
		}
		text := src[start:p]
		lx.pos = p
		// heredoc check not here
		// "yield from"
		if strings.EqualFold(text, "yield") {
			q := p
			for q < len(src) && isWS(src[q]) {
				q++
			}
			if q+4 <= len(src) && strings.EqualFold(src[q:q+4], "from") && (q+4 == len(src) || !isIdentChar(src[q+4])) {
				lx.countLines(src[p:q])
				lx.pos = q + 4
				lx.emit(Token{Type: TIdent, Text: "yield from", Line: lx.line})
				return nil
			}
		}
		lx.emit(Token{Type: TIdent, Text: text, Line: lx.line})
		return nil
	}
	// strings
	if c == '\'' {
		return lx.lexSingleQuoted()
	}
	if c == '"' {
		return lx.lexDoubleQuoted()
	}
	if c == '`' {
		// backtick shell exec: treat as string (unsupported) -> lex as double quoted-ish
		end := strings.IndexByte(src[lx.pos+1:], '`')
		if end < 0 {
			return lx.errf("syntax error, unexpected end of file")
		}
		lx.emit(Token{Type: TString, Text: src[lx.pos+1 : lx.pos+1+end], Line: lx.line})
		lx.pos += end + 2
		return nil
	}
	// heredoc
	if c == '<' && strings.HasPrefix(src[lx.pos:], "<<<") {
		return lx.lexHeredoc()
	}
	// casts
	if c == '(' {
		p := lx.pos + 1
		for p < len(src) && (src[p] == ' ' || src[p] == '\t') {
			p++
		}
		q := p
		for q < len(src) && isIdentChar(src[q]) {
			q++
		}
		if q > p {
			word := strings.ToLower(src[p:q])
			r := q
			for r < len(src) && (src[r] == ' ' || src[r] == '\t') {
				r++
			}
			if r < len(src) && src[r] == ')' {
				if ct, ok := castTypes[word]; ok {
					lx.emit(Token{Type: TCast, Text: ct, Line: lx.line})
					lx.pos = r + 1
					return nil
				}
			}
		}
	}
	// operators
	for _, op := range threeCharOps {
		if strings.HasPrefix(src[lx.pos:], op) {
			lx.emit(Token{Type: TOp, Text: op, Line: lx.line})
			lx.pos += 3
			return nil
		}
	}
	for _, op := range twoCharOps {
		if strings.HasPrefix(src[lx.pos:], op) {
			lx.emit(Token{Type: TOp, Text: op, Line: lx.line})
			lx.pos += 2
			return nil
		}
	}
	switch c {
	case '+', '-', '*', '/', '%', '=', '<', '>', '!', '.', ',', ';', ':', '?', '(', ')', '[', ']', '{', '}', '&', '|', '^', '~', '@', '$', '\\':
		lx.emit(Token{Type: TOp, Text: string(c), Line: lx.line})
		lx.pos++
		return nil
	}
	return lx.errf("syntax error, unexpected character 0x%02X", c)
}

func (lx *Lexer) skipLineComment() {
	src := lx.src
	for lx.pos < len(src) {
		if src[lx.pos] == '\n' {
			return
		}
		if src[lx.pos] == '?' && lx.pos+1 < len(src) && src[lx.pos+1] == '>' {
			return
		}
		lx.pos++
	}
}

func (lx *Lexer) skipAttribute() error {
	// skip #[ ... ] with nesting of brackets, strings
	src := lx.src
	depth := 0
	for lx.pos < len(src) {
		c := src[lx.pos]
		switch c {
		case '[':
			depth++
		case ']':
			depth--
			if depth == 0 {
				lx.pos++
				return nil
			}
		case '\n':
			lx.line++
		case '\'', '"':
			q := c
			lx.pos++
			for lx.pos < len(src) && src[lx.pos] != q {
				if src[lx.pos] == '\\' {
					lx.pos++
				}
				if lx.pos < len(src) && src[lx.pos] == '\n' {
					lx.line++
				}
				lx.pos++
			}
		}
		lx.pos++
	}
	return lx.errf("syntax error, unexpected end of file")
}

func (lx *Lexer) lexNumber() error {
	src := lx.src
	start := lx.pos
	p := lx.pos
	isFloat := false
	if src[p] == '0' && p+1 < len(src) && (src[p+1] == 'x' || src[p+1] == 'X') {
		p += 2
		for p < len(src) && (isHex(src[p]) || src[p] == '_') {
			p++
		}
		text := src[start:p]
		digits := strings.ReplaceAll(text[2:], "_", "")
		lx.pos = p
		v, err := strconv.ParseUint(digits, 16, 64)
		if err != nil || v > math.MaxInt64 {
			f := 0.0
			for _, d := range digits {
				f = f*16 + float64(hexVal(byte(d)))
			}
			lx.emit(Token{Type: TFloat, Text: text, Float: f, Line: lx.line})
		} else {
			lx.emit(Token{Type: TInt, Text: text, Int: int64(v), Line: lx.line})
		}
		return nil
	}
	if src[p] == '0' && p+1 < len(src) && (src[p+1] == 'b' || src[p+1] == 'B') {
		p += 2
		for p < len(src) && (src[p] == '0' || src[p] == '1' || src[p] == '_') {
			p++
		}
		text := src[start:p]
		digits := strings.ReplaceAll(text[2:], "_", "")
		lx.pos = p
		v, err := strconv.ParseUint(digits, 2, 64)
		if err != nil || v > math.MaxInt64 {
			f := 0.0
			for _, d := range digits {
				f = f*2 + float64(d-'0')
			}
			lx.emit(Token{Type: TFloat, Text: text, Float: f, Line: lx.line})
		} else {
			lx.emit(Token{Type: TInt, Text: text, Int: int64(v), Line: lx.line})
		}
		return nil
	}
	if src[p] == '0' && p+1 < len(src) && (src[p+1] == 'o' || src[p+1] == 'O') {
		p += 2
		for p < len(src) && ((src[p] >= '0' && src[p] <= '7') || src[p] == '_') {
			p++
		}
		text := src[start:p]
		digits := strings.ReplaceAll(text[2:], "_", "")
		lx.pos = p
		v, err := strconv.ParseUint(digits, 8, 64)
		if err != nil || v > math.MaxInt64 {
			f := 0.0
			for _, d := range digits {
				f = f*8 + float64(d-'0')
			}
			lx.emit(Token{Type: TFloat, Text: text, Float: f, Line: lx.line})
		} else {
			lx.emit(Token{Type: TInt, Text: text, Int: int64(v), Line: lx.line})
		}
		return nil
	}
	for p < len(src) && (isDigit(src[p]) || (src[p] == '_' && p+1 < len(src) && isDigit(src[p+1]))) {
		p++
	}
	if p < len(src) && src[p] == '.' && !(p+1 < len(src) && src[p+1] == '.') {
		// decimal point (but not "..." )
		isFloat = true
		p++
		for p < len(src) && (isDigit(src[p]) || (src[p] == '_' && p+1 < len(src) && isDigit(src[p+1]))) {
			p++
		}
	}
	if p < len(src) && (src[p] == 'e' || src[p] == 'E') {
		q := p + 1
		if q < len(src) && (src[q] == '+' || src[q] == '-') {
			q++
		}
		if q < len(src) && isDigit(src[q]) {
			isFloat = true
			p = q
			for p < len(src) && isDigit(src[p]) {
				p++
			}
		}
	}
	text := src[start:p]
	clean := strings.ReplaceAll(text, "_", "")
	lx.pos = p
	if isFloat {
		f, _ := strconv.ParseFloat(clean, 64)
		lx.emit(Token{Type: TFloat, Text: text, Float: f, Line: lx.line})
		return nil
	}
	// octal with leading 0
	if len(clean) > 1 && clean[0] == '0' {
		allOct := true
		for i := 1; i < len(clean); i++ {
			if clean[i] > '7' {
				allOct = false
			}
		}
		if !allOct {
			return lx.errf("Invalid numeric literal")
		}
		v, err := strconv.ParseUint(clean[1:], 8, 64)
		if err != nil || v > math.MaxInt64 {
			f := 0.0
			for _, d := range clean[1:] {
				f = f*8 + float64(d-'0')
			}
			lx.emit(Token{Type: TFloat, Text: text, Float: f, Line: lx.line})
		} else {
			lx.emit(Token{Type: TInt, Text: text, Int: int64(v), Line: lx.line})
		}
		return nil
	}
	v, err := strconv.ParseInt(clean, 10, 64)
	if err != nil {
		f, _ := strconv.ParseFloat(clean, 64)
		lx.emit(Token{Type: TFloat, Text: text, Float: f, Line: lx.line})
		return nil
	}
	lx.emit(Token{Type: TInt, Text: text, Int: v, Line: lx.line})
	return nil
}

func hexVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return 0
}

func (lx *Lexer) lexSingleQuoted() error {
	src := lx.src
	startLine := lx.line
	p := lx.pos + 1
	var sb strings.Builder
	for p < len(src) {
		c := src[p]
		if c == '\'' {
			lx.emit(Token{Type: TString, Text: sb.String(), Line: startLine})
			lx.pos = p + 1
			return nil
		}
		if c == '\\' && p+1 < len(src) && (src[p+1] == '\'' || src[p+1] == '\\') {
			sb.WriteByte(src[p+1])
			p += 2
			continue
		}
		if c == '\n' {
			lx.line++
		}
		sb.WriteByte(c)
		p++
	}
	return lx.errf("syntax error, unexpected end of file")
}

// parseInterp parses the body of a double-quoted/heredoc string into parts.
// body is the raw content (without delimiters). heredoc: whether '"' needs no escape
func (lx *Lexer) parseInterp(body string, heredoc bool, line int) ([]StrPart, error) {
	var parts []StrPart
	var lit strings.Builder
	flushLit := func() {
		if lit.Len() > 0 {
			parts = append(parts, StrPart{Lit: lit.String()})
			lit.Reset()
		}
	}
	p := 0
	curLine := line
	for p < len(body) {
		c := body[p]
		if c == '\\' && p+1 < len(body) {
			n := body[p+1]
			switch n {
			case 'n':
				lit.WriteByte('\n')
				p += 2
			case 't':
				lit.WriteByte('\t')
				p += 2
			case 'r':
				lit.WriteByte('\r')
				p += 2
			case 'v':
				lit.WriteByte('\v')
				p += 2
			case 'e':
				lit.WriteByte(27)
				p += 2
			case 'f':
				lit.WriteByte('\f')
				p += 2
			case '\\':
				lit.WriteByte('\\')
				p += 2
			case '$':
				lit.WriteByte('$')
				p += 2
			case '"':
				if heredoc {
					lit.WriteString("\\\"")
				} else {
					lit.WriteByte('"')
				}
				p += 2
			case 'x':
				q := p + 2
				v := 0
				cnt := 0
				for q < len(body) && cnt < 2 && isHex(body[q]) {
					v = v*16 + hexVal(body[q])
					q++
					cnt++
				}
				if cnt == 0 {
					lit.WriteString("\\x")
					p += 2
				} else {
					lit.WriteByte(byte(v))
					p = q
				}
			case 'u':
				if p+2 < len(body) && body[p+2] == '{' {
					end := strings.IndexByte(body[p+3:], '}')
					if end >= 0 {
						hex := body[p+3 : p+3+end]
						v, err := strconv.ParseUint(hex, 16, 32)
						if err == nil {
							lit.WriteString(string(rune(v)))
							p = p + 3 + end + 1
							break
						}
					}
				}
				lit.WriteString("\\u")
				p += 2
			default:
				if n >= '0' && n <= '7' {
					q := p + 1
					v := 0
					cnt := 0
					for q < len(body) && cnt < 3 && body[q] >= '0' && body[q] <= '7' {
						v = v*8 + int(body[q]-'0')
						q++
						cnt++
					}
					lit.WriteByte(byte(v))
					p = q
				} else {
					lit.WriteByte('\\')
					lit.WriteByte(n)
					if n == '\n' {
						curLine++
					}
					p += 2
				}
			}
			continue
		}
		if c == '$' && p+1 < len(body) && isIdentStart(body[p+1]) {
			// simple variable interpolation
			q := p + 1
			for q < len(body) && isIdentChar(body[q]) {
				q++
			}
			name := body[p+1 : q]
			toks := []Token{{Type: TVariable, Text: name, Line: curLine}}
			if q < len(body) && body[q] == '[' {
				// simple array index
				r := q + 1
				if r < len(body) && body[r] == '$' {
					s := r + 1
					for s < len(body) && isIdentChar(body[s]) {
						s++
					}
					if s < len(body) && body[s] == ']' {
						toks = append(toks, Token{Type: TOp, Text: "[", Line: curLine}, Token{Type: TVariable, Text: body[r+1 : s], Line: curLine}, Token{Type: TOp, Text: "]", Line: curLine})
						q = s + 1
					}
				} else {
					s := r
					neg := false
					if s < len(body) && body[s] == '-' {
						neg = true
						s++
					}
					if s < len(body) && isDigit(body[s]) {
						for s < len(body) && isDigit(body[s]) {
							s++
						}
						if s < len(body) && body[s] == ']' {
							numText := body[r:s]
							// numeric index: if it is a canonical decimal int -> int, else string
							var kt Token
							iv, err := strconv.ParseInt(numText, 10, 64)
							canon := err == nil && (numText == "0" || (numText[0] != '0' && !(neg && numText[1] == '0')))
							_ = neg
							if canon {
								kt = Token{Type: TInt, Text: numText, Int: iv, Line: curLine}
							} else {
								kt = Token{Type: TString, Text: numText, Line: curLine}
							}
							toks = append(toks, Token{Type: TOp, Text: "[", Line: curLine}, kt, Token{Type: TOp, Text: "]", Line: curLine})
							q = s + 1
						}
					} else if s < len(body) && isIdentStart(body[s]) && !neg {
						for s < len(body) && isIdentChar(body[s]) {
							s++
						}
						if s < len(body) && body[s] == ']' {
							toks = append(toks, Token{Type: TOp, Text: "[", Line: curLine}, Token{Type: TString, Text: body[r:s], Line: curLine}, Token{Type: TOp, Text: "]", Line: curLine})
							q = s + 1
						}
					}
				}
			} else if q+2 < len(body) && body[q] == '-' && body[q+1] == '>' && isIdentStart(body[q+2]) {
				s := q + 2
				for s < len(body) && isIdentChar(body[s]) {
					s++
				}
				toks = append(toks, Token{Type: TOp, Text: "->", Line: curLine}, Token{Type: TIdent, Text: body[q+2 : s], Line: curLine})
				q = s
			} else if q+3 < len(body) && body[q] == '?' && body[q+1] == '-' && body[q+2] == '>' && isIdentStart(body[q+3]) {
				s := q + 3
				for s < len(body) && isIdentChar(body[s]) {
					s++
				}
				toks = append(toks, Token{Type: TOp, Text: "?->", Line: curLine}, Token{Type: TIdent, Text: body[q+3 : s], Line: curLine})
				q = s
			}
			flushLit()
			toks = append(toks, Token{Type: TEOF, Line: curLine})
			parts = append(parts, StrPart{IsExpr: true, Toks: toks})
			p = q
			continue
		}
		if c == '{' && p+1 < len(body) && body[p+1] == '$' {
			// complex expression: find matching }
			depth := 0
			q := p
			for q < len(body) {
				if body[q] == '{' {
					depth++
				} else if body[q] == '}' {
					depth--
					if depth == 0 {
						break
					}
				} else if body[q] == '\'' || body[q] == '"' {
					// skip string
					qc := body[q]
					q++
					for q < len(body) && body[q] != qc {
						if body[q] == '\\' {
							q++
						}
						q++
					}
				}
				q++
			}
			if q >= len(body) {
				return nil, lx.errf("syntax error, unexpected end of file")
			}
			exprSrc := body[p+1 : q]
			toks, err := LexPHP(exprSrc, lx.file, curLine)
			if err != nil {
				return nil, err
			}
			flushLit()
			parts = append(parts, StrPart{IsExpr: true, Toks: toks})
			curLine += strings.Count(exprSrc, "\n")
			p = q + 1
			continue
		}
		if c == '$' && p+1 < len(body) && body[p+1] == '{' {
			// ${name} or ${expr}
			depth := 0
			q := p + 1
			for q < len(body) {
				if body[q] == '{' {
					depth++
				} else if body[q] == '}' {
					depth--
					if depth == 0 {
						break
					}
				}
				q++
			}
			if q >= len(body) {
				return nil, lx.errf("syntax error, unexpected end of file")
			}
			inner := body[p+2 : q]
			var toks []Token
			if isSimpleName(inner) {
				toks = []Token{{Type: TVariable, Text: inner, Line: curLine}, {Type: TEOF, Line: curLine}}
			} else if idx := strings.IndexByte(inner, '['); idx > 0 && isSimpleName(inner[:idx]) {
				// ${name[expr]}
				sub, err := LexPHP(inner[idx:], lx.file, curLine)
				if err != nil {
					return nil, err
				}
				toks = append([]Token{{Type: TVariable, Text: inner[:idx], Line: curLine}}, sub...)
			} else {
				sub, err := LexPHP(inner, lx.file, curLine)
				if err != nil {
					return nil, err
				}
				// variable variable: ${expr}
				toks = append([]Token{{Type: TOp, Text: "$", Line: curLine}, {Type: TOp, Text: "{", Line: curLine}}, sub[:len(sub)-1]...)
				toks = append(toks, Token{Type: TOp, Text: "}", Line: curLine}, Token{Type: TEOF, Line: curLine})
			}
			flushLit()
			parts = append(parts, StrPart{IsExpr: true, Toks: toks})
			p = q + 1
			continue
		}
		if c == '\n' {
			curLine++
		}
		lit.WriteByte(c)
		p++
	}
	flushLit()
	return parts, nil
}

func isSimpleName(s string) bool {
	if s == "" || !isIdentStart(s[0]) {
		return false
	}
	for i := 1; i < len(s); i++ {
		if !isIdentChar(s[i]) {
			return false
		}
	}
	return true
}

func (lx *Lexer) lexDoubleQuoted() error {
	src := lx.src
	startLine := lx.line
	p := lx.pos + 1
	for p < len(src) {
		c := src[p]
		if c == '\\' {
			p += 2
			continue
		}
		if c == '"' {
			break
		}
		p++
	}
	if p >= len(src) {
		return lx.errf("syntax error, unexpected end of file")
	}
	body := src[lx.pos+1 : p]
	lx.pos = p + 1
	parts, err := lx.parseInterp(body, false, startLine)
	if err != nil {
		return err
	}
	lx.countLines(body)
	lx.emitStringParts(parts, startLine)
	return nil
}

func (lx *Lexer) emitStringParts(parts []StrPart, line int) {
	if len(parts) == 0 {
		lx.emit(Token{Type: TString, Text: "", Line: line})
		return
	}
	if len(parts) == 1 && !parts[0].IsExpr {
		lx.emit(Token{Type: TString, Text: parts[0].Lit, Line: line})
		return
	}
	lx.emit(Token{Type: TInterpString, Parts: parts, Line: line})
}

func (lx *Lexer) lexHeredoc() error {
	src := lx.src
	startLine := lx.line
	p := lx.pos + 3
	for p < len(src) && (src[p] == ' ' || src[p] == '\t') {
		p++
	}
	nowdoc := false
	quoted := false
	if p < len(src) && src[p] == '\'' {
		nowdoc = true
		p++
	} else if p < len(src) && src[p] == '"' {
		quoted = true
		p++
	}
	s := p
	for p < len(src) && isIdentChar(src[p]) {
		p++
	}
	label := src[s:p]
	if label == "" {
		return lx.errf("syntax error, unexpected character")
	}
	if nowdoc {
		if p >= len(src) || src[p] != '\'' {
			return lx.errf("syntax error")
		}
		p++
	} else if quoted {
		if p >= len(src) || src[p] != '"' {
			return lx.errf("syntax error")
		}
		p++
	}
	// expect newline
	if p < len(src) && src[p] == '\r' {
		p++
	}
	if p >= len(src) || src[p] != '\n' {
		return lx.errf("syntax error, unexpected character")
	}
	p++
	bodyStart := p
	// find closing label: at line start (after optional whitespace), followed by non-ident char
	lines := []string{}
	indent := ""
	found := false
	bodyEnd := bodyStart
	q := p
	for q <= len(src) {
		// find end of this line
		e := strings.IndexByte(src[q:], '\n')
		var lineStr string
		if e < 0 {
			lineStr = src[q:]
			e = len(src)
		} else {
			lineStr = src[q : q+e]
			e = q + e
		}
		// check closing
		t := 0
		for t < len(lineStr) && (lineStr[t] == ' ' || lineStr[t] == '\t') {
			t++
		}
		if strings.HasPrefix(lineStr[t:], label) && (len(lineStr) == t+len(label) || !isIdentChar(lineStr[t+len(label)])) {
			indent = lineStr[:t]
			bodyEnd = q
			found = true
			lx.pos = q + t + len(label)
			break
		}
		lines = append(lines, lineStr)
		if e >= len(src) {
			break
		}
		q = e + 1
	}
	if !found {
		return lx.errf("syntax error, unexpected end of file")
	}
	_ = bodyEnd
	// remove indentation
	var body string
	if len(lines) > 0 {
		for i, l := range lines {
			if indent != "" {
				// remove up to len(indent) whitespace chars
				k := 0
				for k < len(indent) && k < len(l) && (l[k] == ' ' || l[k] == '\t') {
					k++
				}
				l = l[k:]
			}
			lines[i] = l
		}
		body = strings.Join(lines, "\n")
		// trailing CR handling
		body = strings.ReplaceAll(body, "\r\n", "\n")
	}
	lx.line = startLine + 1
	var parts []StrPart
	if nowdoc {
		parts = []StrPart{{Lit: body}}
	} else {
		var err error
		parts, err = lx.parseInterp(body, true, startLine+1)
		if err != nil {
			return err
		}
	}
	lx.emitStringParts(parts, startLine)
	lx.line = startLine + len(lines) + 1
	return nil
}
