// ---------- Statements ----------

func (p *Parser) parseBlockOrStmt() Stmt {
	if p.isOp("{") {
		return p.parseBlock()
	}
	return p.parseStmt()
}

func (p *Parser) parseBlock() *BlockStmt {
	p.expectOp("{")
	var stmts []Stmt
	for !p.isOp("}") {
		if p.cur().Type == TEOF {
			p.failUnexpected()
		}
		s := p.parseStmt()
		if s != nil {
			stmts = append(stmts, s)
		}
	}
	p.next()
	return &BlockStmt{Stmts: stmts}
}

// parse statements until one of the given keywords (for alt syntax)
func (p *Parser) parseStmtsUntilKw(kws ...string) *BlockStmt {
	var stmts []Stmt
	for {
		for _, k := range kws {
			if p.isKw(k) {
				return &BlockStmt{Stmts: stmts}
			}
		}
		if p.cur().Type == TEOF {
			p.failUnexpected()
		}
		s := p.parseStmt()
		if s != nil {
			stmts = append(stmts, s)
		}
	}
}

func (p *Parser) parseStmt() Stmt {
	t := p.cur()
	line := t.Line
	switch t.Type {
	case TInlineHTML:
		p.next()
		return &InlineHTMLStmt{Line: line, Text: t.Text}
	case TOpenTagEcho:
		p.next()
		exprs := []Expr{p.parseExpr()}
		for p.acceptOp(",") {
			exprs = append(exprs, p.parseExpr())
		}
		p.expectSemi()
		return &EchoStmt{Line: line, Exprs: exprs}
	case TSemiClose:
		p.next()
		return nil
	case TOp:
		switch t.Text {
		case "{":
			return p.parseBlock()
		case ";":
			p.next()
			return nil
		}
	case TIdent:
		lower := strings.ToLower(t.Text)
		// label?
		if p.peek(1).Type == TOp && p.peek(1).Text == ":" && !isReserved(lower) && p.peek(2).Type != TOp {
			// could be label (goto). Only if not followed by "::"
			p.next()
			p.next()
			return &LabelStmt{Line: line, Label: t.Text}
		}
		switch lower {
		case "echo":
			p.next()
			exprs := []Expr{p.parseExpr()}
			for p.acceptOp(",") {
				exprs = append(exprs, p.parseExpr())
			}
			p.expectSemi()
			return &EchoStmt{Line: line, Exprs: exprs}
		case "if":
			return p.parseIf()
		case "while":
			p.next()
			p.expectOp("(")
			cond := p.parseExpr()
			p.expectOp(")")
			var body Stmt
			if p.acceptOp(":") {
				body = p.parseStmtsUntilKw("endwhile")
				p.next()
				p.expectSemi()
			} else {
				body = p.parseBlockOrStmt()
			}
			return &WhileStmt{Line: line, Cond: cond, Body: body}
		case "do":
			p.next()
			body := p.parseBlockOrStmt()
			p.expectKw("while")
			p.expectOp("(")
			cond := p.parseExpr()
			p.expectOp(")")
			p.expectSemi()
			return &DoWhileStmt{Line: line, Body: body, Cond: cond}
		case "for":
			return p.parseFor()
		case "foreach":
			return p.parseForeach()
		case "switch":
			return p.parseSwitch()
		case "break", "continue":
			p.next()
			depth := 1
			if p.cur().Type == TInt {
				depth = int(p.next().Int)
			}
			p.expectSemi()
			if lower == "break" {
				return &BreakStmt{Line: line, Depth: depth}
			}
			return &ContinueStmt{Line: line, Depth: depth}
		case "return":
			p.next()
			var e Expr
			if !p.isOp(";") && p.cur().Type != TEOF {
				e = p.parseExpr()
			}
			p.expectSemi()
			return &ReturnStmt{Line: line, E: e}
		case "global":
			p.next()
			var names []Expr
			for {
				names = append(names, p.parseSimpleVariable())
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectSemi()
			return &GlobalStmt{Line: line, Names: names}
		case "static":
			// static var decl vs static:: / static fn / static function
			nt := p.peek(1)
			if nt.Type == TVariable {
				p.next()
				var vars []StaticVar
				for {
					name := p.next()
					if name.Type != TVariable {
						p.failUnexpected("variable")
					}
					var init Expr
					if p.acceptOp("=") {
						init = p.parseExpr()
					}
					vars = append(vars, StaticVar{Name: name.Text, Init: init})
					if !p.acceptOp(",") {
						break
					}
				}
				p.expectSemi()
				return &StaticVarStmt{Line: line, Vars: vars}
			}
		case "unset":
			if p.peek(1).Type == TOp && p.peek(1).Text == "(" {
				p.next()
				p.next()
				var vars []Expr
				for !p.isOp(")") {
					vars = append(vars, p.parseExpr())
					if !p.acceptOp(",") {
						break
					}
				}
				p.expectOp(")")
				p.expectSemi()
				return &UnsetStmt{Line: line, Vars: vars}
			}
		case "function":
			// function declaration (not closure) if followed by name
			nt := p.peek(1)
			if nt.Type == TIdent || (nt.Type == TOp && nt.Text == "&" && p.peek(2).Type == TIdent) {
				p.next()
				byRef := p.acceptOp("&")
				name := p.expectIdent()
				fn := p.parseFuncRest(name, byRef, false)
				fn.Name = p.prefixNS(name)
				return &FuncDeclStmt{Line: line, Fn: fn}
			}
		case "abstract", "final", "class", "interface", "trait", "readonly":
			if lower == "class" || lower == "interface" || lower == "trait" || p.isClassDeclAhead() {
				return p.parseClassDecl()
			}
		case "enum":
			if p.peek(1).Type == TIdent && !(p.peek(2).Type == TOp && p.peek(2).Text == "(") {
				return p.parseClassDecl()
			}
		case "try":
			return p.parseTry()
		case "throw":
			p.next()
			e := p.parseExpr()
			p.expectSemi()
			return &ThrowStmt{Line: line, E: e}
		case "namespace":
			if !(p.peek(1).Type == TOp && p.peek(1).Text == "\\") {
				p.next()
				name := ""
				if p.cur().Type == TIdent {
					name = p.next().Text
				}
				if p.isOp("{") {
					old := p.namespace
					p.namespace = name
					body := p.parseBlock()
					p.namespace = old
					return &NamespaceStmt{Line: line, Name: name, Body: body}
				}
				p.expectSemi()
				p.namespace = name
				p.useClass = map[string]string{}
				p.useFunc = map[string]string{}
				p.useConst = map[string]string{}
				return &NamespaceStmt{Line: line, Name: name}
			}
		case "use":
			return p.parseUse()
		case "const":
			p.next()
			var consts []ConstDef
			for {
				name := p.expectIdent()
				p.expectOp("=")
				val := p.parseExpr()
				consts = append(consts, ConstDef{Name: p.prefixNS(name), Value: val})
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectSemi()
			return &ConstStmt{Line: line, Consts: consts}
		case "declare":
			p.next()
			p.expectOp("(")
			for !p.isOp(")") {
				p.next()
			}
			p.expectOp(")")
			if p.isOp(";") {
				p.next()
				return nil
			}
			if p.acceptOp(":") {
				body := p.parseStmtsUntilKw("enddeclare")
				p.next()
				p.expectSemi()
				return &DeclareStmt{Line: line, Body: body}
			}
			body := p.parseBlockOrStmt()
			return &DeclareStmt{Line: line, Body: body}
		case "goto":
			p.next()
			label := p.expectIdent()
			p.expectSemi()
			return &GotoStmt{Line: line, Label: label}
		case "__halt_compiler":
			p.next()
			p.expectOp("(")
			p.expectOp(")")
			// stop parsing
			p.pos = len(p.toks) - 1
			return nil
		}
	}
	e := p.parseExpr()
	p.expectSemi()
	return &ExprStmt{Line: line, E: e}
}

func (p *Parser) isClassDeclAhead() bool {
	i := 0
	for {
		t := p.peek(i)
		if t.Type != TIdent {
			return false
		}
		l := strings.ToLower(t.Text)
		if l == "class" || l == "interface" || l == "trait" || l == "enum" {
			return true
		}
		if l != "abstract" && l != "final" && l != "readonly" {
			return false
		}
		i++
	}
}

func (p *Parser) parseSimpleVariable() Expr {
	t := p.cur()
	if t.Type == TVariable {
		p.next()
		return &VarExpr{Line: t.Line, Name: t.Text}
	}
	if p.isOp("$") {
		p.next()
		if p.isOp("{") {
			p.next()
			e := p.parseExpr()
			p.expectOp("}")
			return &VarVarExpr{Line: t.Line, Name: e}
		}
		inner := p.parseSimpleVariable()
		return &VarVarExpr{Line: t.Line, Name: inner}
	}
	p.failUnexpected("variable")
	return nil
}

func (p *Parser) parseIf() Stmt {
	line := p.line()
	p.next() // if
	p.expectOp("(")
	cond := p.parseExpr()
	p.expectOp(")")
	if p.acceptOp(":") {
		// alternative syntax
		then := p.parseStmtsUntilKw("elseif", "else", "endif")
		stmt := &IfStmt{Line: line, Cond: cond, Then: then}
		curIf := stmt
		for {
			if p.acceptKw("elseif") {
				p.expectOp("(")
				c := p.parseExpr()
				p.expectOp(")")
				p.expectOp(":")
				body := p.parseStmtsUntilKw("elseif", "else", "endif")
				ni := &IfStmt{Line: line, Cond: c, Then: body}
				curIf.Else = ni
				curIf = ni
				continue
			}
			if p.acceptKw("else") {
				if p.isKw("if") {
					// "else if" in alt syntax: treat as elseif
					p.next()
					p.expectOp("(")
					c := p.parseExpr()
					p.expectOp(")")
					p.expectOp(":")
					body := p.parseStmtsUntilKw("elseif", "else", "endif")
					ni := &IfStmt{Line: line, Cond: c, Then: body}
					curIf.Else = ni
					curIf = ni
					continue
				}
				p.expectOp(":")
				body := p.parseStmtsUntilKw("endif")
				curIf.Else = body
			}
			p.expectKw("endif")
			p.expectSemi()
			return stmt
		}
	}
	then := p.parseBlockOrStmt()
	stmt := &IfStmt{Line: line, Cond: cond, Then: then}
	if p.isKw("elseif") {
		p.toks[p.pos].Text = "if"
		stmt.Else = p.parseIf()
	} else if p.isKw("else") {
		p.next()
		if p.isKw("if") {
			stmt.Else = p.parseIf()
		} else {
			stmt.Else = p.parseBlockOrStmt()
		}
	}
	return stmt
}

func (p *Parser) parseFor() Stmt {
	line := p.line()
	p.next()
	p.expectOp("(")
	parseList := func(end string) []Expr {
		var es []Expr
		for !p.isOp(end) {
			es = append(es, p.parseExpr())
			if !p.acceptOp(",") {
				break
			}
		}
		p.expectOp(end)
		return es
	}
	init := parseList(";")
	cond := parseList(";")
	step := parseList(")")
	var body Stmt
	if p.acceptOp(":") {
		body = p.parseStmtsUntilKw("endfor")
		p.next()
		p.expectSemi()
	} else {
		body = p.parseBlockOrStmt()
	}
	return &ForStmt{Line: line, Init: init, Cond: cond, Step: step, Body: body}
}

func (p *Parser) parseForeach() Stmt {
	line := p.line()
	p.next()
	p.expectOp("(")
	subject := p.parseExpr()
	p.expectKw("as")
	var key, val Expr
	byRef := false
	if p.acceptOp("&") {
		byRef = true
		val = p.parseExprPrec(precAssign + 1)
	} else {
		val = p.parseExprPrec(precAssign + 1)
		if p.acceptOp("=>") {
			key = val
			if p.acceptOp("&") {
				byRef = true
			}
			val = p.parseExprPrec(precAssign + 1)
		}
	}
	if al, ok := val.(*ArrayLit); ok {
		val = &ListExpr{Line: al.Line, Items: al.Items}
	}
	p.expectOp(")")
	var body Stmt
	if p.acceptOp(":") {
		body = p.parseStmtsUntilKw("endforeach")
		p.next()
		p.expectSemi()
	} else {
		body = p.parseBlockOrStmt()
	}
	return &ForeachStmt{Line: line, Subject: subject, Key: key, Value: val, ByRef: byRef, Body: body}
}

func (p *Parser) parseSwitch() Stmt {
	line := p.line()
	p.next()
	p.expectOp("(")
	subj := p.parseExpr()
	p.expectOp(")")
	alt := false
	if p.acceptOp(":") {
		alt = true
	} else {
		p.expectOp("{")
	}
	var cases []SwitchCase
	for {
		if alt && p.isKw("endswitch") {
			p.next()
			p.expectSemi()
			break
		}
		if !alt && p.isOp("}") {
			p.next()
			break
		}
		if p.cur().Type == TEOF {
			p.failUnexpected()
		}
		var c SwitchCase
		if p.acceptKw("case") {
			c.Cond = p.parseExpr()
		} else if p.acceptKw("default") {
		} else {
			p.failUnexpected("\"case\"")
		}
		if !p.acceptOp(":") && !p.acceptOp(";") {
			p.failUnexpected("\":\"")
		}
		for !p.isKw("case") && !p.isKw("default") && !p.isOp("}") && !p.isKw("endswitch") {
			if p.cur().Type == TEOF {
				p.failUnexpected()
			}
			s := p.parseStmt()
			if s != nil {
				c.Body = append(c.Body, s)
			}
		}
		cases = append(cases, c)
	}
	return &SwitchStmt{Line: line, Subject: subj, Cases: cases}
}

func (p *Parser) parseTry() Stmt {
	line := p.line()
	p.next()
	body := p.parseBlock()
	ts := &TryStmt{Line: line, Body: body}
	for p.acceptKw("catch") {
		p.expectOp("(")
		var types []string
		for {
			types = append(types, p.resolveClassName(p.expectIdent()))
			if !p.acceptOp("|") {
				break
			}
		}
		varName := ""
		if p.cur().Type == TVariable {
			varName = p.next().Text
		}
		p.expectOp(")")
		cb := p.parseBlock()
		ts.Catches = append(ts.Catches, CatchClause{Types: types, Var: varName, Body: cb})
	}
	if p.acceptKw("finally") {
		ts.Finally = p.parseBlock()
	}
	if len(ts.Catches) == 0 && ts.Finally == nil {
		p.fail("Cannot use try without catch or finally")
	}
	return ts
}

func (p *Parser) parseUse() Stmt {
	line := p.line()
	p.next()
	kind := "class"
	if p.isKw("function") {
		kind = "function"
		p.next()
	} else if p.isKw("const") {
		kind = "const"
		p.next()
	}
	for {
		name := p.expectIdent()
		name = strings.TrimPrefix(name, "\\")
		if p.isOp("\\") || p.isOp("{") {
			// group use: prefix\{A, B as C}
			p.acceptOp("\\")
			p.expectOp("{")
			for !p.isOp("}") {
				k := kind
				if p.isKw("function") {
					k = "function"
					p.next()
				} else if p.isKw("const") {
					k = "const"
					p.next()
				}
				sub := p.expectIdent()
				alias := sub
				if i := strings.LastIndexByte(sub, '\\'); i >= 0 {
					alias = sub[i+1:]
				}
				if p.acceptKw("as") {
					alias = p.expectIdent()
				}
				p.addUse(k, name+"\\"+sub, alias)
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp("}")
		} else {
			alias := name
			if i := strings.LastIndexByte(name, '\\'); i >= 0 {
				alias = name[i+1:]
			}
			if p.acceptKw("as") {
				alias = p.expectIdent()
			}
			p.addUse(kind, name, alias)
		}
		if !p.acceptOp(",") {
			break
		}
	}
	p.expectSemi()
	return &UseStmt{Line: line}
}

func (p *Parser) addUse(kind, fq, alias string) {
	switch kind {
	case "function":
		p.useFunc[strings.ToLower(alias)] = fq
	case "const":
		p.useConst[alias] = fq
	default:
		p.useClass[strings.ToLower(alias)] = fq
	}
}

// ---------- Types ----------

func (p *Parser) parseTypeOpt() *TypeHint {
	// returns nil if no type present
	t := p.cur()
	if t.Type == TOp && t.Text == "?" {
		p.next()
		th := p.parseTypeOpt()
		if th == nil {
			p.failUnexpected()
		}
		th.Nullable = true
		return th
	}
	if t.Type == TOp && t.Text == "(" {
		// DNF types (A&B)|null
		p.next()
		th := p.parseTypeOpt()
		p.expectOp(")")
		for p.isOp("|") {
			p.next()
			sub := p.parseTypeOpt()
			th.Names = append(th.Names, sub.Names...)
		}
		return th
	}
	if t.Type != TIdent {
		return nil
	}
	lower := strings.ToLower(t.Text)
	if isReserved(lower) && lower != "array" && lower != "callable" && lower != "static" {
		return nil
	}
	p.next()
	th := &TypeHint{}
	th.Names = append(th.Names, p.resolveClassName(t.Text))
	for p.isOp("|") || (p.isOp("&") && p.peek(1).Type != TVariable && !(p.peek(1).Type == TOp && (p.peek(1).Text == "..." || p.peek(1).Text == "&"))) {
		if p.isOp("&") {
			th.Intersection = true
		}
		p.next()
		if p.isOp("(") {
			p.next()
			sub := p.parseTypeOpt()
			p.expectOp(")")
			th.Names = append(th.Names, sub.Names...)
			continue
		}
		nt := p.expectIdent()
		th.Names = append(th.Names, p.resolveClassName(nt))
	}
	for _, n := range th.Names {
		if n == "null" {
			th.Nullable = true
		}
	}
	return th
}

// ---------- Functions ----------

func (p *Parser) parseParams() []*Param {
	p.expectOp("(")
	var params []*Param
	for !p.isOp(")") {
		prm := &Param{}
		// modifiers (ctor promotion)
		for {
			if p.isKw("public") || p.isKw("protected") || p.isKw("private") {
				prm.Promote = strings.ToLower(p.next().Text)
				continue
			}
			if p.isKw("readonly") {
				prm.PromoteReadonly = true
				p.next()
				if prm.Promote == "" {
					prm.Promote = "public"
				}
				continue
			}
			break
		}
		prm.Type = p.parseTypeOpt()
		if p.acceptOp("&") {
			prm.ByRef = true
		}
		if p.acceptOp("...") {
			prm.Variadic = true
		}
		v := p.cur()
		if v.Type != TVariable {
			p.failUnexpected("variable")
		}
		p.next()
		prm.Name = v.Text
		if p.acceptOp("=") {
			prm.Default = p.parseExpr()
		}
		params = append(params, prm)
		if !p.acceptOp(",") {
			break
		}
	}
	p.expectOp(")")
	return params
}

// parseFuncRest parses after the name: params, return type, body
func (p *Parser) parseFuncRest(name string, byRef bool, isMethod bool) *FuncDecl {
	fn := &FuncDecl{Name: name, ByRefReturn: byRef, Line: p.line(), File: p.file, Namespace: p.namespace, Visibility: "public"}
	fn.Params = p.parseParams()
	if p.acceptOp(":") {
		fn.ReturnType = p.parseTypeOpt()
		if fn.ReturnType == nil {
			p.failUnexpected()
		}
	}
	if p.isOp("{") {
		p.funcStack = append(p.funcStack, fn)
		body := p.parseBlock()
		p.funcStack = p.funcStack[:len(p.funcStack)-1]
		fn.Body = body.Stmts
		if fn.Body == nil {
			fn.Body = []Stmt{}
		}
		fn.HasBody = true
		fn.EndLine = p.toks[p.pos-1].Line
	} else {
		p.expectSemi()
	}
	return fn
}

func (p *Parser) markGenerator() {
	if len(p.funcStack) > 0 {
		p.funcStack[len(p.funcStack)-1].IsGenerator = true
	}
}

// ---------- Classes ----------

func (p *Parser) parseClassDecl() Stmt {
	line := p.line()
	cd := &ClassDecl{Kind: "class", Line: line, File: p.file, Namespace: p.namespace}
	for {
		if p.acceptKw("abstract") {
			cd.Abstract = true
		} else if p.acceptKw("final") {
			cd.Final = true
		} else if p.acceptKw("readonly") {
			cd.Readonly = true
		} else {
			break
		}
	}
	kw := strings.ToLower(p.next().Text)
	cd.Kind = kw
	name := p.expectIdent()
	cd.Name = p.prefixNS(name)
	if kw == "enum" && p.acceptOp(":") {
		cd.EnumBackingType = strings.ToLower(p.expectIdent())
	}
	if p.acceptKw("extends") {
		if kw == "interface" {
			for {
				cd.Interfaces = append(cd.Interfaces, p.resolveClassName(p.expectIdent()))
				if !p.acceptOp(",") {
					break
				}
			}
		} else {
			cd.Parent = p.resolveClassName(p.expectIdent())
		}
	}
	if p.acceptKw("implements") {
		for {
			cd.Interfaces = append(cd.Interfaces, p.resolveClassName(p.expectIdent()))
			if !p.acceptOp(",") {
				break
			}
		}
	}
	p.parseClassBody(cd)
	return &ClassDeclStmt{Line: line, Class: cd}
}

func (p *Parser) parseClassBody(cd *ClassDecl) {
	p.expectOp("{")
	oldClass := p.inClass
	p.inClass = cd
	defer func() { p.inClass = oldClass }()
	for !p.isOp("}") {
		if p.cur().Type == TEOF {
			p.failUnexpected()
		}
		if p.acceptKw("use") {
			tu := TraitUse{}
			for {
				tu.Names = append(tu.Names, p.resolveClassName(p.expectIdent()))
				if !p.acceptOp(",") {
					break
				}
			}
			if p.acceptOp("{") {
				for !p.isOp("}") {
					rule := TraitRule{}
					n := p.expectIdent()
					if p.acceptOp("::") {
						rule.Trait = p.resolveClassName(n)
						rule.Method = p.expectIdent()
					} else {
						rule.Method = n
					}
					if p.acceptKw("insteadof") {
						for {
							rule.InsteadOf = append(rule.InsteadOf, p.resolveClassName(p.expectIdent()))
							if !p.acceptOp(",") {
								break
							}
						}
					} else if p.acceptKw("as") {
						if p.isKw("public") || p.isKw("protected") || p.isKw("private") {
							rule.Visibility = strings.ToLower(p.next().Text)
						}
						if p.cur().Type == TIdent {
							rule.Alias = p.next().Text
						}
					}
					p.expectSemi()
					tu.Rules = append(tu.Rules, rule)
				}
				p.expectOp("}")
			} else {
				p.expectSemi()
			}
			cd.Traits = append(cd.Traits, tu)
			continue
		}
		if p.acceptKw("case") {
			ec := &EnumCase{Name: p.expectIdent(), Line: p.line()}
			if p.acceptOp("=") {
				ec.Value = p.parseExpr()
			}
			p.expectSemi()
			cd.Cases = append(cd.Cases, ec)
			continue
		}
		// modifiers
		vis := ""
		isStatic, isAbstract, isFinal, isReadonly, isVar := false, false, false, false, false
		for {
			if p.isKw("public") || p.isKw("protected") || p.isKw("private") {
				vis = strings.ToLower(p.next().Text)
			} else if p.isKw("static") {
				isStatic = true
				p.next()
			} else if p.isKw("abstract") {
				isAbstract = true
				p.next()
			} else if p.isKw("final") {
				isFinal = true
				p.next()
			} else if p.isKw("readonly") {
				isReadonly = true
				p.next()
			} else if p.isKw("var") {
				isVar = true
				p.next()
			} else {
				break
			}
		}
		_ = isVar
		if p.acceptKw("const") {
			// optional type
			if p.cur().Type == TIdent && p.peek(1).Type == TIdent {
				p.next()
			}
			for {
				name := p.expectIdent()
				p.expectOp("=")
				val := p.parseExpr()
				cc := &ClassConstDecl{Name: name, Value: val, Visibility: vis, Final: isFinal}
				if cc.Visibility == "" {
					cc.Visibility = "public"
				}
				cd.Consts = append(cd.Consts, cc)
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectSemi()
			continue
		}
		if p.acceptKw("function") {
			byRef := p.acceptOp("&")
			name := p.expectIdent()
			fn := p.parseFuncRest(name, byRef, true)
			fn.Static = isStatic
			fn.Abstract = isAbstract || cd.Kind == "interface"
			fn.Final = isFinal
			if vis != "" {
				fn.Visibility = vis
			}
			cd.Methods = append(cd.Methods, fn)
			continue
		}
		// property
		var th *TypeHint
		if p.cur().Type != TVariable {
			th = p.parseTypeOpt()
		}
		if p.cur().Type != TVariable {
			p.failUnexpected("variable")
		}
		for {
			v := p.next()
			if v.Type != TVariable {
				p.failUnexpected("variable")
			}
			pd := &PropDecl{Name: v.Text, Static: isStatic, Visibility: vis, Readonly: isReadonly || cd.Readonly, Type: th, Line: v.Line}
			if pd.Visibility == "" {
				pd.Visibility = "public"
			}
			if p.acceptOp("=") {
				pd.Default = p.parseExpr()
				pd.HasDefault = true
			}
			if p.isOp("{") {
				// property hooks
				p.next()
				pd.Hooks = map[string]*FuncDecl{}
				for !p.isOp("}") {
					for p.isKw("final") || p.isKw("public") || p.isKw("private") || p.isKw("protected") {
						p.next()
					}
					byRef := p.acceptOp("&")
					hn := strings.ToLower(p.expectIdent())
					fn := &FuncDecl{Name: hn, ByRefReturn: byRef, Line: p.line(), File: p.file, Visibility: "public"}
					if p.isOp("(") {
						fn.Params = p.parseParams()
					} else if hn == "set" {
						fn.Params = []*Param{{Name: "value"}}
					}
					if p.acceptOp("=>") {
						e := p.parseExpr()
						fn.Body = []Stmt{&ReturnStmt{Line: fn.Line, E: e}}
						if hn == "set" {
							fn.Body = []Stmt{&ExprStmt{Line: fn.Line, E: &AssignExpr{Line: fn.Line, Target: &PropExpr{Line: fn.Line, Obj: &VarExpr{Name: "this"}, Name: &StringLit{V: v.Text}}, Value: e}}}
						}
						fn.HasBody = true
						p.expectSemi()
					} else if p.isOp("{") {
						p.funcStack = append(p.funcStack, fn)
						body := p.parseBlock()
						p.funcStack = p.funcStack[:len(p.funcStack)-1]
						fn.Body = body.Stmts
						fn.HasBody = true
					} else {
						p.expectSemi()
					}
					pd.Hooks[hn] = fn
				}
				p.expectOp("}")
				cd.Props = append(cd.Props, pd)
				break
			}
			cd.Props = append(cd.Props, pd)
			if !p.acceptOp(",") {
				break
			}
		}
		p.expectSemi()
	}
	p.expectOp("}")
}

// ---------- Expressions ----------

const (
	precLowest   = 0
	precOr       = 1
	precXor      = 2
	precAnd      = 3
	precPrint    = 4
	precYield    = 5
	precAssign   = 6
	precTernary  = 7
	precCoalesce = 8
	precBoolOr   = 9
	precBoolAnd  = 10
	precBitOr    = 11
	precBitXor   = 12
	precBitAnd   = 13
	precEquality = 14
	precCompare  = 15
	precConcat   = 16
	precShift    = 17
	precAdd      = 18
	precMul      = 19
	precNot      = 20
	precInstance = 21
	precUnary    = 22
	precPow      = 23
	precNew      = 24
)

func binPrec(t Token) (int, bool) {
	if t.Type == TIdent {
		switch strings.ToLower(t.Text) {
		case "or":
			return precOr, true
		case "xor":
			return precXor, true
		case "and":
			return precAnd, true
		case "instanceof":
			return precInstance, true
		}
		return 0, false
	}
	if t.Type != TOp {
		return 0, false
	}
	switch t.Text {
	case "?":
		return precTernary, true
	case "??":
		return precCoalesce, true
	case "||":
		return precBoolOr, true
	case "&&":
		return precBoolAnd, true
	case "|":
		return precBitOr, true
	case "^":
		return precBitXor, true
	case "&":
		return precBitAnd, true
	case "==", "!=", "===", "!==", "<>", "<=>":
		return precEquality, true
	case "<", "<=", ">", ">=":
		return precCompare, true
	case ".":
		return precConcat, true
	case "<<", ">>":
		return precShift, true
	case "+", "-":
		return precAdd, true
	case "*", "/", "%":
		return precMul, true
	case "**":
		return precPow, true
	}
	return 0, false
}

var assignOps = map[string]string{
	"=": "", "+=": "+", "-=": "-", "*=": "*", "/=": "/", ".=": ".", "%=": "%", "**=": "**", "??=": "??", "&=": "&", "|=": "|", "^=": "^", "<<=": "<<", ">>=": ">>",
}

func isLvalue(e Expr) bool {
	switch e.(type) {
	case *VarExpr, *VarVarExpr, *IndexExpr, *PropExpr, *StaticPropExpr, *ArrayLit, *ListExpr:
		return true
	}
	return false
}

func (p *Parser) parseExpr() Expr {
	return p.parseExprPrec(precLowest)
}

func (p *Parser) parseExprPrec(minPrec int) Expr {
	left := p.parseUnary()
	for {
		t := p.cur()
		// assignment (special: lhs must be lvalue, ignores minPrec)
		if t.Type == TOp {
			if op, ok := assignOps[t.Text]; ok && isLvalue(left) {
				if minPrec > precAssign && !isLvalue(left) {
					break
				}
				p.next()
				line := t.Line
				if t.Text == "=" {
					if p.isOp("&") {
						// by-ref assignment
						p.next()
						rhs := p.parseExprPrec(precAssign)
						left = &AssignRefExpr{Line: line, Target: left, Value: rhs}
						continue
					}
					rhs := p.parseExprPrec(precAssign)
					if al, ok := left.(*ArrayLit); ok {
						left = &ListExpr{Line: al.Line, Items: al.Items}
					}
					left = &AssignExpr{Line: line, Target: left, Value: rhs}
					continue
				}
				rhs := p.parseExprPrec(precAssign)
				left = &CompoundAssignExpr{Line: line, Op: op, Target: left, Value: rhs}
				continue
			}
		}
		prec, ok := binPrec(t)
		if !ok || prec < minPrec {
			break
		}
		// non-assoc / left-assoc handled: for left assoc, require prec > minPrec? we use prec >= minPrec and parse rhs with prec+1
		p.next()
		line := t.Line
		if t.Type == TIdent {
			lower := strings.ToLower(t.Text)
			if lower == "instanceof" {
				var cls Expr
				if p.cur().Type == TIdent {
					nt := p.next()
					cls = &NameExpr{Line: nt.Line, Name: p.resolveClassName(nt.Text)}
				} else {
					cls = p.parseUnary()
				}
				left = &InstanceofExpr{Line: line, E: left, Class: cls}
				continue
			}
			rhs := p.parseExprPrec(prec + 1)
			left = &LogicalExpr{Line: line, Op: lower, L: left, R: rhs}
			continue
		}
		switch t.Text {
		case "?":
			// ternary
			if p.acceptOp(":") {
				els := p.parseExprPrec(precTernary + 1)
				left = &TernaryExpr{Line: line, Cond: left, Then: nil, Else: els}
			} else {
				then := p.parseExprPrec(precAssign)
				p.expectOp(":")
				els := p.parseExprPrec(precTernary + 1)
				left = &TernaryExpr{Line: line, Cond: left, Then: then, Else: els}
			}
		case "??":
			rhs := p.parseExprPrec(precCoalesce) // right assoc
			left = &BinaryExpr{Line: line, Op: "??", L: left, R: rhs}
		case "||", "&&":
			rhs := p.parseExprPrec(prec + 1)
			left = &LogicalExpr{Line: line, Op: t.Text, L: left, R: rhs}
		case "**":
			rhs := p.parseExprPrec(prec) // right assoc
			left = &BinaryExpr{Line: line, Op: "**", L: left, R: rhs}
		default:
			rhs := p.parseExprPrec(prec + 1)
			left = &BinaryExpr{Line: line, Op: t.Text, L: left, R: rhs}
		}
	}
	return left
}

func (p *Parser) parseUnary() Expr {
	t := p.cur()
	line := t.Line
	switch t.Type {
	case TOp:
		switch t.Text {
		case "!":
			p.next()
			e := p.parseExprPrec(precNot)
			return &UnaryExpr{Line: line, Op: "!", E: e}
		case "-", "+", "~":
			p.next()
			e := p.parseExprPrec(precUnary)
			return &UnaryExpr{Line: line, Op: t.Text, E: e}
		case "@":
			p.next()
			e := p.parseExprPrec(precUnary)
			return &SilenceExpr{Line: line, E: e}
		case "++", "--":
			p.next()
			e := p.parseExprPrec(precUnary)
			return &IncDecExpr{Line: line, Inc: t.Text == "++", Prefix: true, Target: e}
		case "&":
			// by-ref in array literal context handled elsewhere; error
			p.failUnexpected()
		}
	case TCast:
		p.next()
		e := p.parseExprPrec(precUnary)
		return &CastExpr{Line: line, Type: t.Text, E: e}
	case TIdent:
		switch strings.ToLower(t.Text) {
		case "new":
			return p.parsePostfix(p.parseNew())
		case "clone":
			p.next()
			e := p.parseExprPrec(precNew)
			return &CloneExpr{Line: line, E: e}
		case "print":
			p.next()
			e := p.parseExprPrec(precPrint)
			return &PrintExpr{Line: line, E: e}
		case "yield":
			p.next()
			p.markGenerator()
			if p.isOp(";") || p.isOp(")") || p.isOp(",") || p.isOp("]") {
				return &YieldExpr{Line: line}
			}
			v := p.parseExprPrec(precYield)
			if p.acceptOp("=>") {
				val := p.parseExprPrec(precYield)
				return &YieldExpr{Line: line, Key: v, Value: val}
			}
			return &YieldExpr{Line: line, Value: v}
		case "yield from":
			p.next()
			p.markGenerator()
			e := p.parseExprPrec(precYield)
			return &YieldFromExpr{Line: line, E: e}
		case "throw":
			p.next()
			e := p.parseExprPrec(precLowest)
			return &ThrowExpr{Line: line, E: e}
		case "include", "include_once", "require", "require_once":
			p.next()
			e := p.parseExprPrec(precLowest)
			return &IncludeExpr{Line: line, Kind: strings.ToLower(t.Text), E: e}
		}
	}
	return p.parsePostfix(p.parsePrimary())
}

func (p *Parser) parseArgs() []Arg {
	p.expectOp("(")
	var args []Arg
	for !p.isOp(")") {
		a := Arg{}
		if p.acceptOp("...") {
			if p.isOp(")") {
				// first-class callable syntax
				args = append(args, Arg{Spread: true, Expr: nil})
				break
			}
			a.Spread = true
		}
		// named argument?
		if p.cur().Type == TIdent && p.peek(1).Type == TOp && p.peek(1).Text == ":" && !(p.peek(2).Type == TOp && p.peek(2).Text == ":") {
			a.Name = p.next().Text
			p.next()
		}
		a.Expr = p.parseExpr()
		args = append(args, a)
		if !p.acceptOp(",") {
			break
		}
	}
	p.expectOp(")")
	return args
}

func isCallableSyntax(args []Arg) bool {
	return len(args) == 1 && args[0].Spread && args[0].Expr == nil
}

func (p *Parser) parseNew() Expr {
	line := p.line()
	p.next() // new
	if p.isKw("class") {
		// anonymous class
		p.next()
		var args []Arg
		if p.isOp("(") {
			args = p.parseArgs()
		}
		p.anonCount++
		cd := &ClassDecl{Kind: "class", Line: line, File: p.file, Namespace: p.namespace}
		cd.Name = fmt.Sprintf("class@anonymous%s:%d$%x", p.file, line, p.anonCount-1)
		if p.acceptKw("extends") {
			cd.Parent = p.resolveClassName(p.expectIdent())
		}
		if p.acceptKw("implements") {
			for {
				cd.Interfaces = append(cd.Interfaces, p.resolveClassName(p.expectIdent()))
				if !p.acceptOp(",") {
					break
				}
			}
		}
		p.parseClassBody(cd)
		return &NewExpr{Line: line, Anon: cd, Args: args}
	}
	var cls Expr
	t := p.cur()
	if t.Type == TIdent {
		p.next()
		cls = &NameExpr{Line: t.Line, Name: p.resolveClassName(t.Text)}
	} else if t.Type == TVariable || (t.Type == TOp && t.Text == "$") {
		cls = p.parseSimpleVariable()
		// allow property fetch / index / static prop chain (no calls)
		for {
			if p.isOp("->") || p.isOp("?->") {
				ns := p.next().Text == "?->"
				var name Expr
				if p.cur().Type == TIdent {
					name = &StringLit{Line: line, V: p.next().Text}
				} else if p.cur().Type == TVariable {
					name = p.parseSimpleVariable()
				} else {
					p.expectOp("{")
					name = p.parseExpr()
					p.expectOp("}")
				}
				cls = &PropExpr{Line: line, Obj: cls, Name: name, NullSafe: ns}
			} else if p.isOp("[") {
				p.next()
				idx := p.parseExpr()
				p.expectOp("]")
				cls = &IndexExpr{Line: line, Base: cls, Index: idx}
			} else if p.isOp("::") {
				p.next()
				v := p.cur()
				if v.Type != TVariable {
					p.failUnexpected("variable")
				}
				p.next()
				cls = &StaticPropExpr{Line: line, Class: cls, Name: &StringLit{V: v.Text}}
			} else {
				break
			}
		}
	} else if t.Type == TOp && t.Text == "(" {
		p.next()
		cls = p.parseExpr()
		p.expectOp(")")
	} else {
		p.failUnexpected()
	}
	var args []Arg
	if p.isOp("(") {
		args = p.parseArgs()
	}
	return &NewExpr{Line: line, Class: cls, Args: args}
}

func (p *Parser) parsePostfix(e Expr) Expr {
	for {
		t := p.cur()
		if t.Type != TOp {
			return e
		}
		line := t.Line
		switch t.Text {
		case "[":
			p.next()
			if p.isOp("]") {
				p.next()
				e = &IndexExpr{Line: line, Base: e, Index: nil}
				continue
			}
			idx := p.parseExpr()
			p.expectOp("]")
			e = &IndexExpr{Line: line, Base: e, Index: idx}
		case "{":
			// legacy string offset $s{0} - not supported in PHP 8; stop
			return e
		case "->", "?->":
			p.next()
			nullSafe := t.Text == "?->"
			var name Expr
			nt := p.cur()
			if nt.Type == TIdent {
				p.next()
				name = &StringLit{Line: nt.Line, V: nt.Text}
			} else if nt.Type == TVariable || (nt.Type == TOp && nt.Text == "$") {
				name = p.parseSimpleVariable()
			} else if nt.Type == TOp && nt.Text == "{" {
				p.next()
				name = p.parseExpr()
				p.expectOp("}")
			} else {
				p.failUnexpected()
			}
			if p.isOp("(") {
				args := p.parseArgs()
				e = &MethodCallExpr{Line: line, Obj: e, Name: name, Args: args, NullSafe: nullSafe, IsCallableSyntax: isCallableSyntax(args)}
			} else {
				e = &PropExpr{Line: line, Obj: e, Name: name, NullSafe: nullSafe}
			}
		case "::":
			p.next()
			nt := p.cur()
			if nt.Type == TVariable {
				p.next()
				name := &StringLit{Line: nt.Line, V: nt.Text}
				if p.isOp("(") {
					// $class::$method()
					args := p.parseArgs()
					e = &StaticCallExpr{Line: line, Class: e, Name: &VarExpr{Line: nt.Line, Name: nt.Text}, Args: args, IsCallableSyntax: isCallableSyntax(args)}
				} else {
					e = &StaticPropExpr{Line: line, Class: e, Name: name}
				}
			} else if nt.Type == TOp && nt.Text == "$" {
				v := p.parseSimpleVariable()
				e = &StaticPropExpr{Line: line, Class: e, Name: v}
			} else if nt.Type == TIdent {
				p.next()
				if p.isOp("(") {
					args := p.parseArgs()
					e = &StaticCallExpr{Line: line, Class: e, Name: &StringLit{Line: nt.Line, V: nt.Text}, Args: args, IsCallableSyntax: isCallableSyntax(args)}
				} else if strings.EqualFold(nt.Text, "class") {
					e = &ClassConstExpr{Line: line, Class: e, Name: "class"}
				} else {
					e = &ClassConstExpr{Line: line, Class: e, Name: nt.Text}
				}
			} else if nt.Type == TOp && nt.Text == "{" {
				p.next()
				ne := p.parseExpr()
				p.expectOp("}")
				if p.isOp("(") {
					args := p.parseArgs()
					e = &StaticCallExpr{Line: line, Class: e, Name: ne, Args: args}
				} else {
					e = &ClassConstExpr{Line: line, Class: e, NameExpr: ne}
				}
			} else {
				p.failUnexpected()
			}
		case "(":
			args := p.parseArgs()
			e = &CallExpr{Line: line, Fn: e, Args: args, IsCallableSyntax: isCallableSyntax(args)}
		case "++", "--":
			if !isLvalue(e) {
				return e
			}
			p.next()
			e = &IncDecExpr{Line: line, Inc: t.Text == "++", Prefix: false, Target: e}
		default:
			return e
		}
	}
}

func (p *Parser) parseArrayItems(end string) []ArrayItem {
	var items []ArrayItem
	for !p.isOp(end) {
		if p.isOp(",") {
			// skipped element (list syntax)
			p.next()
			items = append(items, ArrayItem{})
			continue
		}
		item := ArrayItem{}
		if p.acceptOp("...") {
			item.Spread = true
			item.Value = p.parseExpr()
		} else if p.acceptOp("&") {
			item.ByRef = true
			item.Value = p.parseExprPrec(precAssign + 1)
		} else {
			v := p.parseExpr()
			if p.acceptOp("=>") {
				item.Key = v
				if p.acceptOp("&") {
					item.ByRef = true
					item.Value = p.parseExprPrec(precAssign + 1)
				} else {
					item.Value = p.parseExpr()
				}
			} else {
				item.Value = v
			}
		}
		items = append(items, item)
		if !p.acceptOp(",") {
			break
		}
	}
	p.expectOp(end)
	return items
}

func (p *Parser) parseClosure(isStatic bool) Expr {
	line := p.line()
	if p.acceptKw("fn") {
		byRef := p.acceptOp("&")
		fn := &FuncDecl{Name: "{closure}", ByRefReturn: byRef, Line: line, File: p.file, Namespace: p.namespace, IsArrow: true, Visibility: "public"}
		fn.Params = p.parseParams()
		if p.acceptOp(":") {
			fn.ReturnType = p.parseTypeOpt()
		}
		p.expectOp("=>")
		p.funcStack = append(p.funcStack, fn)
		body := p.parseExprPrec(precAssign)
		p.funcStack = p.funcStack[:len(p.funcStack)-1]
		fn.ArrowExpr = body
		fn.Body = []Stmt{&ReturnStmt{Line: line, E: body}}
		fn.HasBody = true
		fn.EndLine = p.toks[p.pos-1].Line
		return &ArrowFnExpr{Line: line, Fn: fn, Static: isStatic}
	}
	p.expectKw("function")
	byRef := p.acceptOp("&")
	fn := &FuncDecl{Name: "{closure}", ByRefReturn: byRef, Line: line, File: p.file, Namespace: p.namespace, Visibility: "public"}
	fn.Params = p.parseParams()
	var uses []ClosureUse
	if p.acceptKw("use") {
		p.expectOp("(")
		for !p.isOp(")") {
			u := ClosureUse{}
			if p.acceptOp("&") {
				u.ByRef = true
			}
			v := p.cur()
			if v.Type != TVariable {
				p.failUnexpected("variable")
			}
			p.next()
			u.Name = v.Text
			uses = append(uses, u)
			if !p.acceptOp(",") {
				break
			}
		}
		p.expectOp(")")
	}
	if p.acceptOp(":") {
		fn.ReturnType = p.parseTypeOpt()
	}
	p.funcStack = append(p.funcStack, fn)
	body := p.parseBlock()
	p.funcStack = p.funcStack[:len(p.funcStack)-1]
	fn.Body = body.Stmts
	if fn.Body == nil {
		fn.Body = []Stmt{}
	}
	fn.HasBody = true
	fn.EndLine = p.toks[p.pos-1].Line
	return &ClosureExpr{Line: line, Fn: fn, Uses: uses, Static: isStatic}
}

func (p *Parser) parsePrimary() Expr {
	t := p.cur()
	line := t.Line
	switch t.Type {
	case TVariable:
		p.next()
		return &VarExpr{Line: line, Name: t.Text}
	case TInt:
		p.next()
		return &IntLit{Line: line, V: t.Int}
	case TFloat:
		p.next()
		return &FloatLit{Line: line, V: t.Float}
	case TString:
		p.next()
		return &StringLit{Line: line, V: t.Text}
	case TInterpString:
		p.next()
		is := &InterpString{Line: line}
		for _, part := range t.Parts {
			if !part.IsExpr {
				is.Parts = append(is.Parts, &StringLit{Line: line, V: part.Lit})
			} else {
				sub := &Parser{toks: part.Toks, file: p.file, namespace: p.namespace, useClass: p.useClass, useFunc: p.useFunc, useConst: p.useConst, funcStack: p.funcStack}
				e := sub.parseExpr()
				if sub.cur().Type != TEOF {
					sub.failUnexpected()
				}
				is.Parts = append(is.Parts, e)
			}
		}
		return is
	case TOp:
		switch t.Text {
		case "(":
			p.next()
			e := p.parseExpr()
			p.expectOp(")")
			return e
		case "[":
			p.next()
			items := p.parseArrayItems("]")
			return &ArrayLit{Line: line, Items: items}
		case "$":
			return p.parseSimpleVariable()
		case "&":
			p.failUnexpected()
		}
	case TIdent:
		lower := strings.ToLower(t.Text)
		switch lower {
		case "true":
			p.next()
			return &BoolLit{Line: line, V: true}
		case "false":
			p.next()
			return &BoolLit{Line: line, V: false}
		case "null":
			p.next()
			return &NullLit{Line: line}
		case "array":
			if p.peek(1).Type == TOp && p.peek(1).Text == "(" {
				p.next()
				p.next()
				items := p.parseArrayItems(")")
				return &ArrayLit{Line: line, Items: items}
			}
		case "list":
			if p.peek(1).Type == TOp && p.peek(1).Text == "(" {
				p.next()
				p.next()
				items := p.parseArrayItems(")")
				return &ListExpr{Line: line, Items: items}
			}
		case "isset":
			p.next()
			p.expectOp("(")
			var vars []Expr
			for !p.isOp(")") {
				vars = append(vars, p.parseExpr())
				if !p.acceptOp(",") {
					break
				}
			}
			p.expectOp(")")
			return &IssetExpr{Line: line, Vars: vars}
		case "empty":
			p.next()
			p.expectOp("(")
			e := p.parseExpr()
			p.expectOp(")")
			return &EmptyExpr{Line: line, E: e}
		case "exit", "die":
			p.next()
			var e Expr
			if p.acceptOp("(") {
				if !p.isOp(")") {
					e = p.parseExpr()
				}
				p.expectOp(")")
			}
			return &ExitExpr{Line: line, E: e}
		case "function", "fn":
			return p.parseClosure(false)
		case "static":
			nt := p.peek(1)
			if nt.Type == TIdent && (strings.EqualFold(nt.Text, "function") || strings.EqualFold(nt.Text, "fn")) {
				p.next()
				return p.parseClosure(true)
			}
			p.next()
			return &NameExpr{Line: line, Name: "static"}
		case "match":
			if p.peek(1).Type == TOp && p.peek(1).Text == "(" {
				return p.parseMatch()
			}
		case "new":
			return p.parseNew()
		case "__line__":
			p.next()
			return &IntLit{Line: line, V: int64(line)}
		case "__file__", "__dir__", "__function__", "__class__", "__method__", "__namespace__", "__trait__", "__property__":
			p.next()
			if lower == "__namespace__" {
				return &StringLit{Line: line, V: p.namespace}
			}
			if lower == "__class__" && p.inClass != nil && p.inClass.Name != "" && !strings.HasPrefix(p.inClass.Name, "class@anonymous") && p.inClass.Kind != "trait" {
				return &StringLit{Line: line, V: p.inClass.Name}
			}
			return &MagicConstExpr{Line: line, Name: lower}
		}
		// name: constant, function call, or class reference
		p.next()
		name := t.Text
		if p.isOp("(") {
			resolved, fallback := p.resolveFuncName(name)
			args := p.parseArgs()
			return &CallExpr{Line: line, Fn: &NameExpr{Line: line, Name: resolved, Alt: fallback}, Args: args, IsCallableSyntax: isCallableSyntax(args)}
		}
		if p.isOp("::") {
			return &NameExpr{Line: line, Name: p.resolveClassName(name)}
		}
		resolved, fallback := p.resolveConstName(name)
		return &ConstExpr{Line: line, Name: resolved, Alt: fallback}
	}
	p.failUnexpected()
	return nil
}

func (p *Parser) parseMatch() Expr {
	line := p.line()
	p.next()
	p.expectOp("(")
	subj := p.parseExpr()
	p.expectOp(")")
	p.expectOp("{")
	m := &MatchExpr{Line: line, Subject: subj}
	for !p.isOp("}") {
		arm := MatchArm{}
		if p.acceptKw("default") {
			arm.Conds = nil
		} else {
			for {
				arm.Conds = append(arm.Conds, p.parseExpr())
				if !p.acceptOp(",") {
					break
				}
				if p.isOp("=>") {
					break
				}
			}
		}
		p.expectOp("=>")
		arm.Body = p.parseExpr()
		m.Arms = append(m.Arms, arm)
		if !p.acceptOp(",") {
			break
		}
	}
	p.expectOp("}")
	return m
}
