// Value is one of: nil, bool, int64, float64, string, *Array, *Object, *Resource
type Value interface{}

// Ref is a reference cell (variable slot).
type Ref struct {
	V  Value
	rc int // number of bindings sharing this ref
}

func newRef(v Value) *Ref { return &Ref{V: v, rc: 1} }

type Resource struct {
