// numeric string parsing: returns (isNumeric, isInt, intVal, floatVal, trailingGarbage)
// allowErrors: 0 = whole string must be numeric (allow leading/trailing whitespace)
type numInfo struct {
	ok      bool // is (at least leading) numeric
	whole   bool // whole string numeric (allowing whitespace)
	isInt   bool
	i       int64
	f       float64
	overflow bool
}

func parseNumeric(s string) numInfo {
	var ni numInfo
	p := 0
	n := len(s)
	for p < n && (s[p] == ' ' || s[p] == '\t' || s[p] == '\n' || s[p] == '\r' || s[p] == '\v' || s[p] == '\f') {
		p++
	}
	start := p
	if p < n && (s[p] == '+' || s[p] == '-') {
		p++
	}
	digStart := p
	for p < n && isDigit(s[p]) {
		p++
	}
	intDigits := p - digStart
	isInt := true
	fracDigits := 0
	if p < n && s[p] == '.' {
		q := p + 1
		for q < n && isDigit(s[q]) {
			q++
		}
		fracDigits = q - p - 1
		if intDigits > 0 || fracDigits > 0 {
			isInt = false
			p = q
		}
	}
	if intDigits == 0 && fracDigits == 0 {
		return ni
	}
	// exponent
	if p < n && (s[p] == 'e' || s[p] == 'E') {
		q := p + 1
		if q < n && (s[q] == '+' || s[q] == '-') {
			q++
		}
		if q < n && isDigit(s[q]) {
			for q < n && isDigit(s[q]) {
				q++
			}
			isInt = false
			p = q
		}
	}
	numEnd := p
	// trailing whitespace
	for p < n && (s[p] == ' ' || s[p] == '\t' || s[p] == '\n' || s[p] == '\r' || s[p] == '\v' || s[p] == '\f') {
		p++
	}
	ni.ok = true
	ni.whole = p == n
	numStr := s[start:numEnd]
	if isInt {
		iv, err := strconv.ParseInt(numStr, 10, 64)
		if err != nil {
			// overflow -> float
			ni.isInt = false
			ni.f, _ = strconv.ParseFloat(numStr, 64)
			ni.overflow = true
		} else {
			ni.isInt = true
			ni.i = iv
			ni.f = float64(iv)
		}
	} else {
		ni.isInt = false
		ni.f, _ = strconv.ParseFloat(numStr, 64)
	}
	return ni
}

func isNumericStr(s string) bool {
	ni := parseNumeric(s)
	return ni.ok && ni.whole
}

// floatToIntCast replicates PHP's modular float->int conversion (zend_dval_to_lval)
func floatToInt(f float64) int64 {
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return 0
	}
	if f >= -9223372036854775808.0 && f < 9223372036854775808.0 {
		return int64(f)
	}
	// modular arithmetic
	two64 := 18446744073709551616.0
	dmod := math.Mod(f, two64)
	if dmod < 0 {
		// we're going to make this number positive; call ourselves recursively
		// if the result is -zero, then the result is zero.
		dmod = dmod + two64
	}
	if dmod > 9223372036854775807.0 {
		dmod -= two64
	}
	return int64(dmod)
}

func floatFitsInt(f float64) bool {
	return !math.IsNaN(f) && !math.IsInf(f, 0) && f >= -9223372036854775808.0 && f < 9223372036854775808.0
}

func toInt(v Value) int64 {
	switch x := v.(type) {
	case nil:
		return 0
	case bool:
		if x {
			return 1
		}
		return 0
	case int64:
		return x
	case float64:
		return floatToInt(x)
	case string:
		return strToInt(x)
	case *Array:
		if x.Len() > 0 {
			return 1
		}
		return 0
	case *Object:
		return 1
	case *Resource:
		return int64(x.id)
	case *Ref:
		return toInt(x.V)
	}
	return 0
}

func strToInt(s string) int64 {
	ni := parseNumeric(s)
	if !ni.ok {
		return 0
	}
	if ni.isInt {
		return ni.i
	}
	// float: saturate for integer-like overflow strings (strtol behavior), else cast
	if ni.overflow {
		if ni.f > 0 {
			return math.MaxInt64
		}
		return math.MinInt64
	}
	if !floatFitsInt(ni.f) {
		// PHP uses zend_dval_to_lval_cap for strings
		if math.IsNaN(ni.f) || math.IsInf(ni.f, 0) {
			return 0
		}
		if ni.f > 0 {
			return math.MaxInt64
		}
		return math.MinInt64
	}
	return int64(ni.f)
}

func toFloat(v Value) float64 {
	switch x := v.(type) {
	case nil:
		return 0
	case bool:
		if x {
			return 1
		}
		return 0
	case int64:
		return float64(x)
	case float64:
		return x
	case string:
		ni := parseNumeric(x)
		if !ni.ok {
			return 0
		}
		return ni.f
	case *Array:
		if x.Len() > 0 {
			return 1
		}
		return 0
	case *Object:
		return 1
	case *Resource:
		return float64(x.id)
	case *Ref:
		return toFloat(x.V)
	}
	return 0
}

// formatFloatPrec formats a float like PHP's zend_gcvt with given precision (-1 for shortest round-trip, uses 17)
func formatFloatPrec(f float64, precision int) string {
	if math.IsNaN(f) {
		return "NAN"
	}
	if math.IsInf(f, 1) {
		return "INF"
	}
	if math.IsInf(f, -1) {
		return "-INF"
	}
	if f == 0 {
		if math.Signbit(f) {
			return "-0"
		}
		return "0"
	}
	var digits string
	var exp int
	neg := f < 0
	if neg {
		f = -f
	}
	ndigit := precision
	var s string
	if precision <= 0 {
		s = strconv.FormatFloat(f, 'e', -1, 64)
		ndigit = 17
	} else {
		s = strconv.FormatFloat(f, 'e', precision-1, 64)
	}
	// s like d.dddde+XX
	epos := strings.IndexByte(s, 'e')
	mant := s[:epos]
	exp, _ = strconv.Atoi(s[epos+1:])
	digits = strings.Replace(mant, ".", "", 1)
	digits = strings.TrimRight(digits, "0")
	if digits == "" {
		digits = "0"
	}
	decpt := exp + 1 // position of decimal point relative to digits start
	var out string
	if (decpt < 0 && decpt < -3) || (decpt >= 0 && decpt > ndigit) {
		// exponential
		var sb strings.Builder
		sb.WriteByte(digits[0])
		sb.WriteByte('.')
		if len(digits) > 1 {
			sb.WriteString(digits[1:])
		} else {
			sb.WriteByte('0')
		}
		sb.WriteByte('E')
		e := decpt - 1
		if e < 0 {
			sb.WriteByte('-')
			e = -e
		} else {
			sb.WriteByte('+')
		}
		sb.WriteString(strconv.Itoa(e))
		out = sb.String()
	} else if decpt <= 0 {
		out = "0." + strings.Repeat("0", -decpt) + digits
	} else if decpt >= len(digits) {
		out = digits + strings.Repeat("0", decpt-len(digits))
	} else {
		out = digits[:decpt] + "." + digits[decpt:]
	}
	if neg {
		return "-" + out
	}
	return out
}

func formatFloat(f float64) string {
	return formatFloatPrec(f, 14)
}

// formatFloatRepr: for var_dump/var_export/json (serialize_precision=-1)
func formatFloatRepr(f float64) string {
	return formatFloatPrec(f, -1)
}

func intToStr(i int64) string { return strconv.FormatInt(i, 10) }

func isIntKeyString(s string) (int64, bool) {
	// canonical decimal integer string => int key
	n := len(s)
	if n == 0 || n > 20 {
		return 0, false
	}
	p := 0
	if s[0] == '-' {
		p = 1
		if n == 1 {
			return 0, false
		}
	}
	if s[p] == '0' && n > p+1 {
		return 0, false
	}
	if s[p] == '0' && p == 1 {
		return 0, false // "-0"
	}
	for i := p; i < n; i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

