}

var objToString func(o *Object) string
var objCompare func(a, b *Object) int

func objectLooseEquals(x, y *Object) bool {
	if objCompare != nil {
		return objCompare(x, y) == 0
	}
	return x == y
}

func arrayLooseEquals(x, y *Array) bool {
	if x.Len() != y.Len() {
		return false
	}
	eq := true
	x.Each(func(k Key, v Value) bool {
		w, ok := y.Get(k)
