func compareIntString(i int64, s string) int {
	ni := parseNumeric(s)
	if ni.ok && ni.whole {
		if ni.isInt {
			return cmpInt(i, ni.i)
		}
		return cmpFloat(float64(i), ni.f)
	}
	return cmpStr(intToStr(i), s)
}

func compareFloatString(f float64, s string) int {
	ni := parseNumeric(s)
	if ni.ok && ni.whole {
		return cmpFloat(f, ni.f)
	}
	return cmpStr(formatFloat(f), s)
}

func compareStrings(a, b string) int {
	na := parseNumeric(a)
	nb := parseNumeric(b)
	if na.ok && na.whole && nb.ok && nb.whole {
		if na.isInt && nb.isInt {
			return cmpInt(na.i, nb.i)
		}
		return cmpFloat(na.f, nb.f)
	}
	return cmpStr(a, b)
}

func cmpInt(a, b int64) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}
func cmpFloat(a, b float64) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	if a == b {
		return 0
	}
	return 1 // NaN: uncomparable
