// compareValues implements <=> (PHP 8 semantics)
func compareValues(a, b Value) int {
	a = deref(a)
	b = deref(b)
	switch x := a.(type) {
	case nil:
		switch y := b.(type) {
		case nil:
			return 0
		case string:
			return cmpStr("", y)
		case *Array:
			if y.Len() == 0 {
				return 0
			}
			return -1
		case *Object:
			return -1
		default:
			return cmpBool(false, toBool(b))
		}
	case bool:
		return cmpBool(x, toBool(b))
	case int64:
		switch y := b.(type) {
		case nil:
			return cmpBool(x != 0, false)
		case bool:
			return cmpBool(x != 0, y)
		case int64:
			return cmpInt(x, y)
		case float64:
			return cmpFloat(float64(x), y)
		case string:
			return compareIntString(x, y)
		case *Array:
			return -1
		case *Object:
			return cmpInt(x, 1)
		case *Resource:
			return cmpInt(x, int64(y.id))
		}
	case float64:
		switch y := b.(type) {
		case nil:
			return cmpBool(x != 0, false)
		case bool:
			return cmpBool(x != 0, y)
		case int64:
			return cmpFloat(x, float64(y))
		case float64:
			return cmpFloat(x, y)
		case string:
			return compareFloatString(x, y)
		case *Array:
			return -1
		case *Object:
			return cmpFloat(x, 1)
		}
	case string:
		switch y := b.(type) {
		case nil:
			return cmpStr(x, "")
		case bool:
			return cmpBool(toBool(x), y)
