			return -compareIntString(y, x)
		case float64:
			return -compareFloatString(y, x)
		case string:
			return compareStrings(x, y)
		case *Array:
			return -1
		case *Object:
			if y.class.findMethod("__tostring") != nil {
				return cmpStr(x, objToString(y))
			}
			return -1
		}
	case *Array:
		switch y := b.(type) {
		case nil:
			if x.Len() == 0 {
				return 0
			}
			return 1
		case bool:
			return cmpBool(x.Len() > 0, y)
		case *Array:
			return compareArrays(x, y)
		case *Object:
			return -1
		}
		return 1
	case *Object:
		switch y := b.(type) {
		case nil:
			return 1
		case bool:
			return cmpBool(true, y)
		case *Object:
			if x == y {
				return 0
			}
			if x.class != y.class {
				return 1
			}
			if objCompare != nil {
				return objCompare(x, y)
			}
			return 1
		case string:
			if x.class.findMethod("__tostring") != nil {
				return cmpStr(objToString(x), y)
			}
			return 1
		case int64:
			return cmpInt(1, y)
		case float64:
			return cmpFloat(1, y)
		}
		return 1
	case *Resource:
		switch y := b.(type) {
		case *Resource:
			return cmpInt(int64(x.id), int64(y.id))
		case bool:
			return cmpBool(true, y)
		case nil:
			return 1
		default:
			return cmpInt(int64(x.id), toInt(b))
		}
	}
	return 0
}

func cmpBool(a, b bool) int {
	if a == b {
		return 0
	}
	if !a && b {
		return -1
	}
	return 1
}

func compareArrays(x, y *Array) int {
	if x.Len() < y.Len() {
		return -1
	}
	if x.Len() > y.Len() {
		return 1
	}
	result := 0
	x.Each(func(k Key, v Value) bool {
		w, ok := y.Get(k)
		if !ok {
			result = 1
			return false
		}
		c := compareValues(deref(v), deref(w))
		if c != 0 {
			result = c
			return false
		}
		return true
	})
	return result
}

func strictEquals(a, b Value) bool {
	a = deref(a)
	b = deref(b)
	switch x := a.(type) {
	case nil:
		return b == nil
	case bool:
		y, ok := b.(bool)
		return ok && x == y
	case int64:
		y, ok := b.(int64)
		return ok && x == y
	case float64:
		y, ok := b.(float64)
		return ok && x == y
	case string:
		y, ok := b.(string)
		return ok && x == y
	case *Array:
		y, ok := b.(*Array)
		if !ok {
			return false
		}
		if x == y {
			return true
		}
		if x.Len() != y.Len() {
			return false
		}
		// same key/value pairs in same order
		eq := true
		i := 0
		ykeys := y.Keys()
		x.Each(func(k Key, v Value) bool {
			if i >= len(ykeys) || ykeys[i] != k {
				eq = false
				return false
			}
			w, _ := y.Get(k)
			if !strictEquals(deref(v), deref(w)) {
				eq = false
				return false
			}
			i++
			return true
		})
		return eq
	case *Object:
		y, ok := b.(*Object)
		return ok && x == y
	case *Resource:
		y, ok := b.(*Resource)
		return ok && x == y
	}
	return false
}
