// numeric string parsing: returns (isNumeric, isInt, intVal, floatVal, trailingGarbage)
// allowErrors: 0 = whole string must be numeric (allow leading/trailing whitespace)
type numInfo struct {
	ok      bool // is (at least leading) numeric
	whole   bool // whole string numeric (allowing whitespace)
	isInt   bool
	i       int64
	f       float64
	overflow bool
}

func parseNumeric(s string) numInfo {
	var ni numInfo
	p := 0
	n := len(s)
	for p < n && (s[p] == ' ' || s[p] == '\t' || s[p] == '\n' || s[p] == '\r' || s[p] == '\v' || s[p] == '\f') {
		p++
	}
	start := p
	if p < n && (s[p] == '+' || s[p] == '-') {
		p++
	}
	digStart := p
	for p < n && isDigit(s[p]) {
		p++
	}
	intDigits := p - digStart
	isInt := true
	fracDigits := 0
	if p < n && s[p] == '.' {
		q := p + 1
		for q < n && isDigit(s[q]) {
			q++
		}
		fracDigits = q - p - 1
		if intDigits > 0 || fracDigits > 0 {
			isInt = false
			p = q
		}
	}
	if intDigits == 0 && fracDigits == 0 {
		return ni
	}
	// exponent
	if p < n && (s[p] == 'e' || s[p] == 'E') {
		q := p + 1
		if q < n && (s[q] == '+' || s[q] == '-') {
			q++
		}
		if q < n && isDigit(s[q]) {
			for q < n && isDigit(s[q]) {
				q++
			}
			isInt = false
			p = q
		}
	}
	numEnd := p
	// trailing whitespace
	for p < n && (s[p] == ' ' || s[p] == '\t' || s[p] == '\n' || s[p] == '\r' || s[p] == '\v' || s[p] == '\f') {
		p++
	}
	ni.ok = true
	ni.whole = p == n
	numStr := s[start:numEnd]
	if isInt {
		iv, err := strconv.ParseInt(numStr, 10, 64)
		if err != nil {
			// overflow -> float
			ni.isInt = false
			ni.f, _ = strconv.ParseFloat(numStr, 64)
			ni.overflow = true
		} else {
			ni.isInt = true
			ni.i = iv
			ni.f = float64(iv)
		}
	} else {
		ni.isInt = false
		ni.f, _ = strconv.ParseFloat(numStr, 64)
	}
	return ni
}

