	// canonical decimal integer string => int key
	n := len(s)
	if n == 0 || n > 20 {
		return 0, false
	}
	p := 0
	if s[0] == '-' {
		p = 1
		if n == 1 {
			return 0, false
		}
	}
	if s[p] == '0' && n > p+1 {
		return 0, false
	}
	if s[p] == '0' && p == 1 {
		return 0, false // "-0"
	}
	for i := p; i < n; i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

