}

// ---- errors ----

func errorTypeName(t int64) string {
	switch t {
	case E_ERROR, E_CORE_ERROR, E_COMPILE_ERROR, E_USER_ERROR, E_RECOVERABLE_ERROR:
		return "Fatal error"
	case E_WARNING, E_CORE_WARNING, E_COMPILE_WARNING, E_USER_WARNING:
		return "Warning"
	case E_PARSE:
		return "Parse error"
	case E_NOTICE, E_USER_NOTICE:
		return "Notice"
	case E_STRICT:
		return "Strict Standards"
	case E_DEPRECATED, E_USER_DEPRECATED:
		return "Deprecated"
	}
	return "Unknown error"
}

func (in *Interp) curFile() string {
	if in.frame != nil {
		return in.frame.file
	}
	return in.scriptFile
}

func (in *Interp) curLine() int {
	if in.frame != nil {
		return in.frame.line
	}
	return 0
}

func (in *Interp) raiseError(t int64, msg string) {
	in.raiseErrorAt(t, msg, in.curFile(), in.curLine())
}

func (in *Interp) raiseErrorAt(t int64, msg string, file string, line int) {
	in.lastErrorMsg = msg
	in.lastErrorType = t
	in.lastErrorFile = file
	in.lastErrorLine = line
	// user error handler
	if len(in.errorHandlers) > 0 && !in.inErrorHandler {
		h := in.errorHandlers[len(in.errorHandlers)-1]
		mask := in.errorHandlerMask[len(in.errorHandlerMask)-1]
		if h != nil && (mask&t) != 0 {
			in.inErrorHandler = true
			var res Value
			func() {
				defer func() { in.inErrorHandler = false }()
				res = in.callValue(h, []Value{t, msg, file, int64(line)})
			}()
			if b, ok := res.(bool); !ok || b {
				return
			}
		}
	}
	if in.silenceDepth > 0 && t != E_ERROR && t != E_CORE_ERROR && t != E_COMPILE_ERROR && t != E_USER_ERROR && t != E_RECOVERABLE_ERROR && t != E_PARSE {
		return
	}
	if in.errorReporting&t == 0 {
		return
	}
	if in.ini["display_errors"] == "0" || in.ini["display_errors"] == "" || strings.EqualFold(in.ini["display_errors"], "off") {
		if strings.EqualFold(in.ini["display_errors"], "stderr") {
			fmt.Fprintf(os.Stderr, "\n%s: %s in %s on line %d\n", errorTypeName(t), msg, file, line)
		}
		return
	}
	if strings.EqualFold(in.ini["display_errors"], "stderr") {
		in.out.Flush()
		fmt.Fprintf(os.Stderr, "\n%s: %s in %s on line %d\n", errorTypeName(t), msg, file, line)
		return
	}
