	inErrorHandler bool
	hrStart      int64
	uniqCounter  int64
	includeStack []string
	traceStack   []*Frame
	envLoaded    bool
	stdoutRes    *Resource
	stderrRes    *Resource
	stdinRes     *Resource
	closureCounter int
}

type shutdownFn struct {
	fn   Value
	args []Value
}

const (
	E_ERROR             = 1
	E_WARNING           = 2
	E_PARSE             = 4
	E_NOTICE            = 8
	E_CORE_ERROR        = 16
	E_CORE_WARNING      = 32
	E_COMPILE_ERROR     = 64
	E_COMPILE_WARNING   = 128
	E_USER_ERROR        = 256
	E_USER_WARNING      = 512
	E_USER_NOTICE       = 1024
	E_STRICT            = 2048
	E_RECOVERABLE_ERROR = 4096
	E_DEPRECATED        = 8192
	E_USER_DEPRECATED   = 16384
	E_ALL               = 32767
)

func NewInterp() *Interp {
	in := &Interp{
		globals:    map[string]*Ref{},
		functions:  map[string]*Function{},
		classes:    map[string]*Class{},
		pendingClasses: map[string]*ClassDecl{},
		constants:  map[string]Value{},
		constCase:  map[string]string{},
		included:   map[string]bool{},
		nextObjID:  1,
		nextResID:  1,
		errorReporting: E_ALL,
		ini:        map[string]string{},
		liveObjects: map[int]*Object{},
		precision:  14,
		serializePrecision: -1,
		fileLines:  map[string][]string{},
		timezone:   "UTC",
	}
	in.out = NewOutput()
	in.stdin = bufio.NewReader(os.Stdin)
	theInterp = in
	cwd, _ := os.Getwd()
	in.cwd = cwd
	in.initIni()
	in.initConstants()
	in.initBuiltinClasses()
	in.initBuiltinFunctions()
	// resources for STDIN/STDOUT/STDERR
	in.stdinRes = in.newResource("stream", &Stream{kind: "stdin", reader: in.stdin})
	in.stdoutRes = in.newResource("stream", &Stream{kind: "stdout"})
	in.stderrRes = in.newResource("stream", &Stream{kind: "stderr"})
	return in
}

func (in *Interp) initIni() {
	defaults := map[string]string{
		"display_errors": "1", "error_reporting": "", "precision": "14", "serialize_precision": "-1",
		"short_open_tag": "1", "html_errors": "0", "log_errors": "0", "date.timezone": "UTC", "memory_limit": "128M",
		"max_execution_time": "0", "zend.assertions": "1", "error_log": "", "output_buffering": "0", "implicit_flush": "1",
		"default_charset": "UTF-8", "include_path": ".:/usr/local/lib/php", "assert.exception": "1", "assert.active": "1",
		"arg_separator.output": "&", "auto_detect_line_endings": "0", "default_socket_timeout": "60", "file_uploads": "1",
		"allow_url_fopen": "1", "max_input_time": "-1", "post_max_size": "8M", "upload_max_filesize": "2M", "variables_order": "EGPCS",
		"register_argc_argv": "1", "zend.exception_ignore_args": "0", "zend.exception_string_param_max_len": "15",
		"xdebug.mode": "", "open_basedir": "", "user_agent": "", "sys_temp_dir": "", "pcre.backtrack_limit": "1000000",
		"pcre.recursion_limit": "100000", "pcre.jit": "1", "session.save_path": "", "date.default_latitude": "31.7667",
		"error_prepend_string": "", "error_append_string": "", "docref_root": "", "ignore_repeated_errors": "0",
		"track_errors": "0", "report_memleaks": "1", "unserialize_callback_func": "", "disable_functions": "", "disable_classes": "",
		"expose_php": "1", "max_input_nesting_level": "64", "max_input_vars": "1000", "ignore_user_abort": "0", "mbstring.language": "neutral",
		"zend.enable_gc": "1", "hard_timeout": "2", "highlight.comment": "#FF8000", "highlight.default": "#0000BB", "highlight.html": "#000000", "highlight.keyword": "#007700", "highlight.string": "#DD0000",
		"input_encoding": "", "internal_encoding": "", "output_encoding": "", "output_handler": "", "realpath_cache_size": "4096K", "realpath_cache_ttl": "120", "sendmail_path": "/usr/sbin/sendmail -t -i", "serialize_precision ": "-1", "smtp_port": "25", "SMTP": "localhost", "sys_temp_dir ": "", "unserialize_max_depth": "4096", "user_dir": "", "user_ini.cache_ttl": "300", "user_ini.filename": ".user.ini", "xmlrpc_errors": "0", "zend.detect_unicode": "1", "zend.multibyte": "0", "zend.script_encoding": "", "zend.signal_check": "0", "auto_append_file": "", "auto_prepend_file": "", "auto_globals_jit": "1", "browscap": "", "default_mimetype": "text/html", "doc_root": "", "enable_dl": "1", "enable_post_data_reading": "1", "extension_dir": "/usr/local/lib/php/extensions/no-debug-non-zts-20240924", "mail.add_x_header": "0", "mail.force_extra_parameters": "", "mail.log": "", "cli_server.color": "0",
	}
	for k, v := range defaults {
		in.ini[k] = v
	}
}

// ---- output ----

type Output struct {
	w      *bufio.Writer
	stack  []*OutBuffer
}

type OutBuffer struct {
	buf      strings.Builder
	callback Value
	name     string
}

func NewOutput() *Output {
	return &Output{w: bufio.NewWriterSize(os.Stdout, 65536)}
}

func (o *Output) Write(s string) {
	if len(o.stack) > 0 {
		o.stack[len(o.stack)-1].buf.WriteString(s)
		return
	}
	o.w.WriteString(s)
}

func (o *Output) Flush() {
	o.w.Flush()
}

func (in *Interp) echo(s string) {
	in.out.Write(s)
}

// ---- errors ----

func errorTypeName(t int64) string {
	switch t {
	case E_ERROR, E_CORE_ERROR, E_COMPILE_ERROR, E_USER_ERROR, E_RECOVERABLE_ERROR:
		return "Fatal error"
	case E_WARNING, E_CORE_WARNING, E_COMPILE_WARNING, E_USER_WARNING:
		return "Warning"
	case E_PARSE:
		return "Parse error"
	case E_NOTICE, E_USER_NOTICE:
		return "Notice"
	case E_STRICT:
		return "Strict Standards"
	case E_DEPRECATED, E_USER_DEPRECATED:
		return "Deprecated"
	}
	return "Unknown error"
}

func (in *Interp) curFile() string {
	if in.frame != nil {
		return in.frame.file
	}
	return in.scriptFile
}

func (in *Interp) curLine() int {
	if in.frame != nil {
		return in.frame.line
	}
	return 0
}

func (in *Interp) raiseError(t int64, msg string) {
	in.raiseErrorAt(t, msg, in.curFile(), in.curLine())
}

func (in *Interp) raiseErrorAt(t int64, msg string, file string, line int) {
	in.lastErrorMsg = msg
	in.lastErrorType = t
	in.lastErrorFile = file
	in.lastErrorLine = line
	// user error handler
	if len(in.errorHandlers) > 0 && !in.inErrorHandler {
		h := in.errorHandlers[len(in.errorHandlers)-1]
		mask := in.errorHandlerMask[len(in.errorHandlerMask)-1]
		if h != nil && (mask&t) != 0 {
			in.inErrorHandler = true
			var res Value
			func() {
				defer func() { in.inErrorHandler = false }()
				res = in.callValue(h, []Value{t, msg, file, int64(line)})
			}()
			if b, ok := res.(bool); !ok || b {
				return
			}
		}
	}
	if in.silenceDepth > 0 && t != E_ERROR && t != E_CORE_ERROR && t != E_COMPILE_ERROR && t != E_USER_ERROR && t != E_RECOVERABLE_ERROR && t != E_PARSE {
		return
	}
	if in.errorReporting&t == 0 {
		return
	}
	if in.ini["display_errors"] == "0" || in.ini["display_errors"] == "" || strings.EqualFold(in.ini["display_errors"], "off") {
		if strings.EqualFold(in.ini["display_errors"], "stderr") {
			fmt.Fprintf(os.Stderr, "\n%s: %s in %s on line %d\n", errorTypeName(t), msg, file, line)
		}
		return
	}
	if strings.EqualFold(in.ini["display_errors"], "stderr") {
		in.out.Flush()
		fmt.Fprintf(os.Stderr, "\n%s: %s in %s on line %d\n", errorTypeName(t), msg, file, line)
		return
	}
	in.echo(fmt.Sprintf("\n%s: %s in %s on line %d\n", errorTypeName(t), msg, file, line))
}

func (in *Interp) warn(msg string)       { in.raiseError(E_WARNING, msg) }
func (in *Interp) notice(msg string)     { in.raiseError(E_NOTICE, msg) }
func (in *Interp) deprecated(msg string) { in.raiseError(E_DEPRECATED, msg) }

func (in *Interp) fatal(msg string) {
	panic(&FatalSignal{msg: msg, file: in.curFile(), line: in.curLine()})
}

// throwError creates and throws an exception of the given builtin class
func (in *Interp) throwError(class string, msg string) {
	panic(&ThrowSignal{obj: in.newException(class, msg, 0)})
}

func (in *Interp) throwObj(o *Object) {
	panic(&ThrowSignal{obj: o})
}

// ---- object ids / candidates ----

func (in *Interp) allocObjID() int {
	if n := len(in.freeIDs); n > 0 {
		id := in.freeIDs[n-1]
		in.freeIDs = in.freeIDs[:n-1]
		return id
	}
	id := in.nextObjID
	in.nextObjID++
	return id
}

func (in *Interp) newObject(c *Class) *Object {
	o := &Object{class: c, props: NewArray(), id: in.allocObjID()}
	in.liveObjects[o.id] = o
	in.addCandidate(o)
	return o
}

func (in *Interp) addCandidate(v Value) {
	in.candidates = append(in.candidates, candidate{v: v, depth: in.depth})
}

// processCandidates frees values whose refcount dropped to zero (at statement boundaries)
func (in *Interp) processCandidates() {
	if len(in.candidates) == 0 {
		return
	}
	d := in.depth
	// iterate; freeing may add more candidates
	for i := 0; i < len(in.candidates); i++ {
		c := in.candidates[i]
		if c.depth < d {
			continue
		}
		switch x := c.v.(type) {
		case *Object:
			if x.rc <= 0 && !x.freed {
				in.freeObject(x)
			}
		case *Array:
			if x.rc <= 0 {
				x.rc = -1000000 // mark released
				x.release()
			}
		}
		in.candidates[i].v = nil
	}
	// compact: keep those with depth < d
	j := 0
	for _, c := range in.candidates {
		if c.v != nil {
			in.candidates[j] = c
			j++
		}
	}
	in.candidates = in.candidates[:j]
}

func (in *Interp) retagCandidates(newDepth int) {
	for i := range in.candidates {
		if in.candidates[i].depth > newDepth {
			in.candidates[i].depth = newDepth
		}
	}
}

func (in *Interp) freeObject(o *Object) {
	if o.freed {
		return
	}
	if !o.destructed {
		o.destructed = true
		if m := o.class.findMethod("__destruct"); m != nil {
			o.rc++ // keep alive during destructor
			func() {
				defer func() {
					if r := recover(); r != nil {
						if ts, ok := r.(*ThrowSignal); ok && in.inShutdown {
							in.reportUncaught(ts.obj)
							return
						}
						panic(r)
					}
				}()
				in.callMethod(o, m, nil)
			}()
			o.rc--
			if o.rc > 0 {
				// resurrected
				return
			}
		}
	}
	o.freed = true
	delete(in.liveObjects, o.id)
	in.freeIDs = append(in.freeIDs, o.id)
	// release props
	if o.props != nil {
		o.props.release()
	}
	if cl, ok := o.internal.(*Closure); ok {
		if cl.this != nil {
			decRef(cl.this)
		}
		for _, r := range cl.bound {
			r.release()
		}
	}
	if g, ok := o.internal.(*Generator); ok {
		g.destroy(in)
	}
	if st, ok := o.internal.(*Array); ok {
		decRef(st)
	}
}

// ---- running ----

func (in *Interp) Run(stmts []Stmt, file string) (exitCode int) {
	in.scriptFile = file
	in.scriptDir = dirOf(file)
	in.initGlobals()
	fr := &Frame{vars: in.globals, file: file, funcName: "{main}"}
	in.frame = fr
	in.traceStack = []*Frame{fr}
	exitCode = 0
	func() {
		defer func() {
			if r := recover(); r != nil {
				exitCode = in.handleTopLevelPanic(r)
			}
		}()
		in.hoistDecls(stmts, fr)
		in.execStmts(fr, stmts)
	}()
	// shutdown functions
	func() {
		defer func() {
			if r := recover(); r != nil {
				exitCode = in.handleTopLevelPanic(r)
			}
		}()
		in.runShutdown()
	}()
	in.shutdownDestructors(fr)
	in.out.Flush()
	return exitCode
}

func (in *Interp) runShutdown() {
	for i := 0; i < len(in.shutdownFns); i++ {
		sf := in.shutdownFns[i]
		in.callValue(sf.fn, sf.args)
	}
}

func (in *Interp) handleTopLevelPanic(r interface{}) int {
	switch sig := r.(type) {
	case *ExitSignal:
		return sig.code
	case *ThrowSignal:
		// uncaught exception
		if len(in.exceptionHandlers) > 0 && in.exceptionHandlers[len(in.exceptionHandlers)-1] != nil {
			h := in.exceptionHandlers[len(in.exceptionHandlers)-1]
			in.exceptionHandlers = in.exceptionHandlers[:len(in.exceptionHandlers)-1]
			code := 255
			func() {
				defer func() {
					if r2 := recover(); r2 != nil {
						code = in.handleTopLevelPanic(r2)
					}
				}()
				in.callValue(h, []Value{sig.obj})
			}()
			return code
		}
		in.reportUncaught(sig.obj)
		return 255
	case *FatalSignal:
		in.raiseErrorAt(E_ERROR, sig.msg, sig.file, sig.line)
		return 255
	}
	panic(r)
}

func (in *Interp) reportUncaught(ex *Object) {
	// Build message as PHP does: "Uncaught " + (string)$e + "\n  thrown"
	str := in.throwableToString(ex)
	file := toStr(in.getProp(ex, "file"))
	line := toInt(in.getProp(ex, "line"))
	msg := "Uncaught " + str + "\n  thrown"
	in.raiseErrorAt(E_ERROR, msg, file, int(line))
}

func (in *Interp) shutdownDestructors(fr *Frame) {
	in.inShutdown = true
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(*ExitSignal); ok {
				return
			}
			if ts, ok := r.(*ThrowSignal); ok {
				in.reportUncaught(ts.obj)
				return
			}
			if fs, ok := r.(*FatalSignal); ok {
				in.raiseErrorAt(E_ERROR, fs.msg, fs.file, fs.line)
				return
			}
			panic(r)
		}
	}()
	// 1. globals in reverse order: objects with rc == 1
	for {
		n := len(in.globalOrder)
		for i := len(in.globalOrder) - 1; i >= 0; i-- {
			name := in.globalOrder[i]
			r, ok := in.globals[name]
			if !ok {
				continue
			}
			if o, ok := r.V.(*Object); ok && o.rc == 1 && r.rc <= 1 {
				r.V = nil
				o.rc = 0
				in.freeObject(o)
			}
		}
		if n == len(in.globalOrder) {
			break
		}
	}
	// 2. remaining objects in id order
	ids := make([]int, 0, len(in.liveObjects))
	for id := range in.liveObjects {
		ids = append(ids, id)
	}
	sort.Ints(ids)
	for _, id := range ids {
		o := in.liveObjects[id]
		if o != nil && !o.destructed {
			o.destructed = true
			if m := o.class.findMethod("__destruct"); m != nil {
				in.callMethod(o, m, nil)
			}
		}
	}
	in.out.Flush()
}

func (in *Interp) initGlobals() {
	argv := NewArray()
	for _, a := range in.argv {
		argv.Append(a)
	}
	in.setGlobal("argv", argv)
	in.setGlobal("argc", int64(len(in.argv)))
	server := NewArray()
	for _, e := range os.Environ() {
		if i := strings.IndexByte(e, '='); i > 0 {
			server.SetStr(e[:i], e[i+1:])
		}
	}
	server.SetStr("PHP_SELF", in.scriptFile)
	server.SetStr("SCRIPT_NAME", in.scriptFile)
	server.SetStr("SCRIPT_FILENAME", in.scriptFile)
	server.SetStr("PATH_TRANSLATED", in.scriptFile)
	server.SetStr("DOCUMENT_ROOT", "")
	server.SetStr("REQUEST_TIME_FLOAT", nowFloat())
	server.SetStr("REQUEST_TIME", int64(nowFloat()))
	server.SetStr("argv", argv)
	server.SetStr("argc", int64(len(in.argv)))
	in.setGlobal("_SERVER", server)
	in.setGlobal("_GET", NewArray())
	in.setGlobal("_POST", NewArray())
	in.setGlobal("_COOKIE", NewArray())
	in.setGlobal("_FILES", NewArray())
	in.setGlobal("_REQUEST", NewArray())
	env := NewArray()
	in.setGlobal("_ENV", env)
	in.setGlobal("_SESSION", nil)
	delete(in.globals, "_SESSION")
}

func (in *Interp) setGlobal(name string, v Value) {
	if r, ok := in.globals[name]; ok {
		r.set(v)
		return
	}
	r := &Ref{rc: 1}
	r.set(v)
	in.globals[name] = r
	in.globalOrder = append(in.globalOrder, name)
}

// hoistDecls declares functions and classes ahead of execution
func (in *Interp) hoistDecls(stmts []Stmt, fr *Frame) {
	for _, s := range stmts {
		if fd, ok := s.(*FuncDeclStmt); ok {
			in.declareFunction(fd.Fn, fr)
		}
	}
	// classes: declare those whose dependencies are satisfied, iteratively
	var pending []*ClassDecl
	for _, s := range stmts {
		if cd, ok := s.(*ClassDeclStmt); ok {
			pending = append(pending, cd.Class)
		}
	}
	for _, cd := range pending {
		in.pendingClasses[strings.ToLower(cd.Name)] = cd
	}
	for len(pending) > 0 {
		progress := false
		var rest []*ClassDecl
		for _, cd := range pending {
			if in.classDepsReady(cd) {
				if _, exists := in.classes[strings.ToLower(cd.Name)]; !exists {
					in.declareClass(cd, fr)
				}
				progress = true
			} else {
				rest = append(rest, cd)
			}
		}
		pending = rest
		if !progress {
			break
		}
	}
}

func (in *Interp) classDepsReady(cd *ClassDecl) bool {
	if cd.Parent != "" {
		if _, ok := in.classes[strings.ToLower(cd.Parent)]; !ok {
			return false
		}
	}
	for _, i := range cd.Interfaces {
		if _, ok := in.classes[strings.ToLower(i)]; !ok {
			return false
		}
	}
	for _, t := range cd.Traits {
		for _, n := range t.Names {
			if _, ok := in.classes[strings.ToLower(n)]; !ok {
				return false
			}
		}
	}
	return true
}

func (in *Interp) declareFunction(fd *FuncDecl, fr *Frame) {
	lname := strings.ToLower(fd.Name)
	if existing, ok := in.functions[lname]; ok {
		if existing.Decl == fd {
			return
		}
		in.frame.line = fd.Line
		in.fatal(fmt.Sprintf("Cannot redeclare function %s() (previously declared in %s:%d)", fd.Name, existing.Decl.File, existing.Decl.Line))
	}
	in.functions[lname] = &Function{Name: fd.Name, Decl: fd}
}

// ---- statement execution ----

func (in *Interp) execStmts(fr *Frame, stmts []Stmt) ctrl {
	for _, s := range stmts {
		c := in.execStmt(fr, s)
		if len(in.candidates) > 0 {
			in.processCandidates()
		}
		if c != cNone {
			return c
		}
	}
	return cNone
}

func (in *Interp) execBlock(fr *Frame, s Stmt) ctrl {
	if b, ok := s.(*BlockStmt); ok {
		return in.execStmts(fr, b.Stmts)
	}
	c := in.execStmt(fr, s)
	if len(in.candidates) > 0 {
		in.processCandidates()
	}
	return c
}

func (in *Interp) execStmt(fr *Frame, s Stmt) ctrl {
	switch st := s.(type) {
	case *ExprStmt:
		fr.line = st.Line
		in.eval(fr, st.E)
		return cNone
	case *EchoStmt:
		fr.line = st.Line
		for _, e := range st.Exprs {
			v := in.eval(fr, e)
			in.echo(in.toStr(v))
		}
		return cNone
	case *InlineHTMLStmt:
		in.echo(st.Text)
		return cNone
	case *BlockStmt:
		return in.execStmts(fr, st.Stmts)
	case *IfStmt:
		fr.line = st.Line
		if toBool(in.eval(fr, st.Cond)) {
			return in.execBlock(fr, st.Then)
		} else if st.Else != nil {
			return in.execBlock(fr, st.Else)
		}
		return cNone
	case *WhileStmt:
		fr.line = st.Line
		for toBool(in.eval(fr, st.Cond)) {
			c := in.execBlock(fr, st.Body)
			if c == cBreak {
				if fr.brkDepth > 1 {
					fr.brkDepth--
					return cBreak
				}
				break
			}
			if c == cContinue {
				if fr.brkDepth > 1 {
					fr.brkDepth--
					return cContinue
				}
				continue
			}
			if c == cReturn {
				return c
			}
			fr.line = st.Line
		}
		return cNone
	case *DoWhileStmt:
		for {
			c := in.execBlock(fr, st.Body)
			if c == cBreak {
				if fr.brkDepth > 1 {
					fr.brkDepth--
					return cBreak
				}
				break
			}
			if c == cContinue {
				if fr.brkDepth > 1 {
					fr.brkDepth--
					return cContinue
				}
			}
			if c == cReturn {
				return c
			}
			fr.line = st.Line
			if !toBool(in.eval(fr, st.Cond)) {
				break
			}
		}
		return cNone
	case *ForStmt:
		fr.line = st.Line
		for _, e := range st.Init {
			in.eval(fr, e)
		}
		for {
			cond := true
			for i, e := range st.Cond {
				v := in.eval(fr, e)
				if i == len(st.Cond)-1 {
					cond = toBool(v)
				}
			}
			if !cond {
				break
			}
			c := in.execBlock(fr, st.Body)
			if c == cBreak {
				if fr.brkDepth > 1 {
					fr.brkDepth--
					return cBreak
				}
				break
			}
			if c == cContinue {
				if fr.brkDepth > 1 {
					fr.brkDepth--
					return cContinue
				}
			}
			if c == cReturn {
				return c
			}
			fr.line = st.Line
			for _, e := range st.Step {
				in.eval(fr, e)
			}
		}
		return cNone
	case *ForeachStmt:
		return in.execForeach(fr, st)
	case *SwitchStmt:
		fr.line = st.Line
		subj := in.eval(fr, st.Subject)
		matched := -1
		for i, c := range st.Cases {
			if c.Cond == nil {
				continue
			}
			if looseEquals(subj, in.eval(fr, c.Cond)) {
				matched = i
				break
			}
		}
		if matched < 0 {
			for i, c := range st.Cases {
				if c.Cond == nil {
					matched = i
					break
				}
			}
		}
		if matched < 0 {
			return cNone
		}
		for i := matched; i < len(st.Cases); i++ {
			c := in.execStmts(fr, st.Cases[i].Body)
			if c == cBreak || c == cContinue {
				if fr.brkDepth > 1 {
					fr.brkDepth--
					return c
				}
				return cNone
			}
			if c == cReturn {
				return c
			}
		}
		return cNone
	case *BreakStmt:
		fr.brkDepth = st.Depth
		return cBreak
	case *ContinueStmt:
		fr.brkDepth = st.Depth
		return cContinue
	case *ReturnStmt:
		fr.line = st.Line
		if st.E != nil {
			if fr.fn != nil && fr.fn.Decl != nil && fr.fn.Decl.ByRefReturn {
				if isLvalue(st.E) {
					if _, isCall := st.E.(*CallExpr); !isCall {
						fr.retVal = in.getRef(fr, st.E)
						return cReturn
					}
				}
			}
			fr.retVal = in.eval(fr, st.E)
		} else {
			fr.retVal = nil
		}
		return cReturn
	case *GlobalStmt:
		fr.line = st.Line
		for _, n := range st.Names {
			var name string
			if v, ok := n.(*VarExpr); ok {
				name = v.Name
			} else {
				name = in.toStr(in.eval(fr, n.(*VarVarExpr).Name))
			}
			r, ok := in.globals[name]
			if !ok {
				r = &Ref{rc: 1}
				in.globals[name] = r
				in.globalOrder = append(in.globalOrder, name)
			}
			if fr.vars != nil {
				if old, ok := fr.vars[name]; ok && old != r {
					old.release()
				}
				r.rc++
				fr.vars[name] = r
			}
		}
		return cNone
	case *StaticVarStmt:
		fr.line = st.Line
		fn := fr.fn
		for _, sv := range st.Vars {
			var r *Ref
			if fn != nil {
				key := sv.Name
				statics := in.staticsFor(fr)
				if existing, ok := statics[key]; ok {
					r = existing
				} else {
					r = &Ref{rc: 1}
					if sv.Init != nil {
						r.set(in.eval(fr, sv.Init))
					}
					statics[key] = r
				}
			} else {
				r = &Ref{rc: 1}
				if sv.Init != nil {
					r.set(in.eval(fr, sv.Init))
				}
			}
			if old, ok := fr.vars[sv.Name]; ok && old != r {
				old.release()
			}
			r.rc++
			fr.vars[sv.Name] = r
		}
		return cNone
	case *UnsetStmt:
		fr.line = st.Line
		for _, v := range st.Vars {
			in.unset(fr, v)
		}
		return cNone
	case *FuncDeclStmt:
		fr.line = st.Line
		in.declareFunction(st.Fn, fr)
		return cNone
	case *ClassDeclStmt:
		fr.line = st.Line
		lname := strings.ToLower(st.Class.Name)
		if existing, ok := in.classes[lname]; ok {
			if existing.Decl == st.Class {
				return cNone
			}
			in.fatal(fmt.Sprintf("Cannot declare class %s, because the name is already in use", st.Class.Name))
		}
		in.declareClass(st.Class, fr)
		return cNone
	case *TryStmt:
		return in.execTry(fr, st)
	case *ThrowStmt:
		fr.line = st.Line
		v := in.eval(fr, st.E)
		in.doThrow(v)
		return cNone
	case *ConstStmt:
		fr.line = st.Line
		for _, c := range st.Consts {
			v := in.eval(fr, c.Value)
			in.defineConst(c.Name, v)
		}
		return cNone
	case *NamespaceStmt:
		if st.Body != nil {
			in.hoistDecls(st.Body.Stmts, fr)
			return in.execStmts(fr, st.Body.Stmts)
		}
		return cNone
	case *UseStmt, *NopStmt, *LabelStmt:
		return cNone
	case *DeclareStmt:
		return in.execBlock(fr, st.Body)
	case *GotoStmt:
		in.fatal("'goto' is not supported")
	}
	panic(fmt.Sprintf("unknown statement %T", s))
}

func (in *Interp) staticsFor(fr *Frame) map[string]*Ref {
	fn := fr.fn
	if fn.Method != nil && fr.staticClass != nil && fn.Decl != nil {
		// static vars in methods are per-class (since 8.1 shared with child classes... actually per method, shared)
	}
	if fn.statics == nil {
		fn.statics = map[string]*Ref{}
	}
	return fn.statics
}

func (in *Interp) doThrow(v Value) {
	o, ok := v.(*Object)
	if !ok || !o.class.instanceOf("Throwable") {
		in.throwError("Error", "Can only throw objects")
	}
	panic(&ThrowSignal{obj: o})
}

func (in *Interp) execTry(fr *Frame, st *TryStmt) (result ctrl) {
	runFinally := func() ctrl {
		if st.Finally != nil {
			savedRet := fr.retVal
			c := in.execStmts(fr, st.Finally.Stmts)
			if c == cNone {
				fr.retVal = savedRet
			}
			return c
		}
		return cNone
	}
	var caught *ThrowSignal
	var pending interface{}
	c := func() (c ctrl) {
		defer func() {
			if r := recover(); r != nil {
				if ts, ok := r.(*ThrowSignal); ok {
					caught = ts
					return
				}
				pending = r
			}
		}()
		return in.execStmts(fr, st.Body)
	}()
	if pending != nil {
		// exit or fatal: still run finally? PHP runs finally on exit? No - exit skips finally.
		panic(pending)
	}
	if caught != nil {
		handled := false
		for _, cc := range st.Catches {
			if in.catchMatches(caught.obj, cc.Types) {
				handled = true
				if cc.Var != "" {
					in.assignVar(fr, cc.Var, caught.obj)
				}
				var pending2 interface{}
				c = func() (c ctrl) {
					defer func() {
						if r := recover(); r != nil {
							pending2 = r
						}
					}()
					return in.execStmts(fr, cc.Body.Stmts)
				}()
				if pending2 != nil {
					fc := runFinally()
					if fc != cNone {
						return fc
					}
					panic(pending2)
				}
				break
			}
		}
		if !handled {
			fc := runFinally()
			if fc != cNone {
				return fc
			}
			panic(caught)
		}
	}
	fc := runFinally()
	if fc != cNone {
		return fc
	}
	return c
}

func (in *Interp) catchMatches(o *Object, types []string) bool {
	for _, t := range types {
		if o.class.instanceOf(t) {
			return true
		}
		if strings.EqualFold(t, "Throwable") || strings.EqualFold(t, "Exception") && o.class.instanceOf("Exception") {
			return true
		}
	}
	return false
}

// ---- foreach ----

func (in *Interp) execForeach(fr *Frame, st *ForeachStmt) ctrl {
	fr.line = st.Line
	handleBody := func() (ctrl, bool) {
		c := in.execBlock(fr, st.Body)
		if c == cBreak {
			if fr.brkDepth > 1 {
				fr.brkDepth--
				return cBreak, true
			}
			return cNone, true
		}
		if c == cContinue {
			if fr.brkDepth > 1 {
				fr.brkDepth--
				return cContinue, true
			}
			return cNone, false
		}
		if c == cReturn {
			return cReturn, true
		}
		fr.line = st.Line
		return cNone, false
	}
	if st.ByRef {
		// need reference to the array
		ref := in.getRef(fr, st.Subject)
		if ref.V == nil {
			ref.set(NewArray())
		}
		if arr, ok := ref.V.(*Array); ok {
			if arr.rc > 1 {
				arr = arr.Clone()
				ref.set(arr)
			}
			arr.iterating++
			defer func() { arr.iterating-- }()
			for i := 0; i < len(arr.entries); i++ {
				if arr.entries[i].deleted {
					continue
				}
				k := arr.entries[i].k
				elemRef := arr.GetRef(k)
				if st.Key != nil {
					in.assign(fr, st.Key, k.Value())
				}
				in.bindRef(fr, st.Value, elemRef)
				c, stop := handleBody()
				if stop {
					return c
				}
			}
			return cNone
		}
		if obj, ok := ref.V.(*Object); ok {
			return in.foreachObject(fr, st, obj, handleBody)
		}
		in.warn(fmt.Sprintf("foreach() argument must be of type array|object, %s given", typeName(ref.V)))
		return cNone
	}
	subj := in.eval(fr, st.Subject)
	switch x := subj.(type) {
	case *Array:
		x.rc++ // hold during iteration (snapshot semantics)
		x.iterating++
		defer func() {
			x.iterating--
			x.rc--
			if x.rc <= 0 {
				in.addCandidate(x)
			}
		}()
		n := len(x.entries)
		for i := 0; i < n && i < len(x.entries); i++ {
			e := x.entries[i]
			if e.deleted {
				continue
			}
			if st.Key != nil {
				in.assign(fr, st.Key, e.k.Value())
			}
			in.assign(fr, st.Value, deref(e.v))
			c, stop := handleBody()
			if stop {
				return c
			}
		}
		return cNone
	case *Object:
		return in.foreachObject(fr, st, x, handleBody)
	default:
		in.warn(fmt.Sprintf("foreach() argument must be of type array|object, %s given", typeName(subj)))
		return cNone
	}
}

func (in *Interp) foreachObject(fr *Frame, st *ForeachStmt, obj *Object, handleBody func() (ctrl, bool)) ctrl {
	// Generator
	if g, ok := obj.internal.(*Generator); ok {
		g.ensureStarted(in)
		if g.finished && g.started && g.advancedOnce {
			in.throwError("Exception", "Cannot traverse an already closed generator")
		}
		for !g.finished {
			if st.Key != nil {
				in.assign(fr, st.Key, g.curKey)
			}
			if st.ByRef {
				in.assign(fr, st.Value, g.curVal)
			} else {
				in.assign(fr, st.Value, g.curVal)
			}
			c, stop := handleBody()
			if stop {
				return c
			}
			g.next(in)
		}
		return cNone
	}
	// IteratorAggregate
	if obj.class.instanceOf("IteratorAggregate") {
		it := in.callMethodByName(obj, "getIterator", nil)
		ito, ok := it.(*Object)
		if !ok || !ito.class.instanceOf("Traversable") {
			in.throwError("Exception", fmt.Sprintf("Objects returned by %s::getIterator() must be traversable or implement interface Iterator", obj.class.Name))
		}
		return in.foreachObject(fr, st, ito, handleBody)
	}
	if obj.class.instanceOf("Iterator") {
		in.callMethodByName(obj, "rewind", nil)
		for toBool(in.callMethodByName(obj, "valid", nil)) {
			v := in.callMethodByName(obj, "current", nil)
			if st.Key != nil {
				k := in.callMethodByName(obj, "key", nil)
				in.assign(fr, st.Key, k)
			}
			in.assign(fr, st.Value, v)
			c, stop := handleBody()
			if stop {
				return c
			}
			in.callMethodByName(obj, "next", nil)
		}
		return cNone
	}
	// plain object: iterate visible properties
	props := in.visibleProps(obj, fr.class)
	for _, kv := range props {
		if st.Key != nil {
			in.assign(fr, st.Key, kv.k)
		}
		if st.ByRef {
			r := obj.props.GetRef(StrKey(kv.k))
			in.bindRef(fr, st.Value, r)
		} else {
			in.assign(fr, st.Value, deref(kv.v))
		}
		c, stop := handleBody()
		if stop {
			return c
		}
	}
	return cNone
}

type kv struct {
	k string
	v Value
}

func (in *Interp) visibleProps(obj *Object, scope *Class) []kv {
	var out []kv
	obj.props.Each(func(k Key, v Value) bool {
		name := k.String()
		if in.propAccessible(obj, name, scope) {
			out = append(out, kv{name, v})
		}
		return true
	})
	return out
}

func (in *Interp) propAccessible(obj *Object, name string, scope *Class) bool {
	pi := obj.class.findProp(name)
	if pi == nil {
		return true
	}
	switch pi.Visibility {
	case "public":
		return true
	case "protected":
		return scope != nil && (scope.isSubclassOf(pi.Class) || pi.Class.isSubclassOf(scope))
	case "private":
		return scope == pi.Class
	}
	return true
}

func dirOf(path string) string {
	i := strings.LastIndexByte(path, '/')
	if i < 0 {
		return "."
	}
	if i == 0 {
		return "/"
	}
	return path[:i]
}
