func (in *Interp) objectToString(o *Object) string {
	if m := o.class.findMethod("__tostring"); m != nil {
		r := in.callMethod(o, m, nil)
		s, ok := r.(string)
		if !ok {
			in.throwError("Error", fmt.Sprintf("%s::__toString(): Return value must be of type string, %s returned", o.class.Name, typeName(r)))
		}
		return s
	}
	in.throwError("Error", fmt.Sprintf("Object of class %s could not be converted to string", o.class.Name))
	return ""
}

// toNumber converts to int64 or float64 for arithmetic; op used for error message
func (in *Interp) toNumber(v Value, op string, other Value, leftSide bool) Value {
	switch x := v.(type) {
	case nil:
		return int64(0)
	case bool:
		if x {
			return int64(1)
		}
		return int64(0)
	case int64:
		return x
	case float64:
		return x
	case string:
		ni := parseNumeric(x)
		if !ni.ok {
			in.unsupportedOperands(op, v, other, leftSide)
		}
		if !ni.whole {
			in.warn("A non-numeric value encountered")
		}
		if ni.isInt {
			return ni.i
		}
		return ni.f
	case *Array:
		in.unsupportedOperands(op, v, other, leftSide)
	case *Object:
		if x.class.isEnum() {
			in.unsupportedOperands(op, v, other, leftSide)
		}
		in.warn(fmt.Sprintf("Object of class %s could not be converted to number", x.class.Name))
		return int64(1)
	case *Resource:
		return int64(x.id)
	case *Ref:
		return in.toNumber(x.V, op, other, leftSide)
	}
	return int64(0)
}

func (in *Interp) unsupportedOperands(op string, v Value, other Value, leftSide bool) {
	var l, r Value
	if leftSide {
		l, r = v, other
	} else {
		l, r = other, v
	}
	in.throwError("TypeError", fmt.Sprintf("Unsupported operand types: %s %s %s", typeName(l), op, typeName(r)))
}

func (in *Interp) arith(op string, a, b Value) Value {
	a = deref(a)
	b = deref(b)
	// array + array
	if op == "+" {
		if aa, ok := a.(*Array); ok {
			if ba, ok := b.(*Array); ok {
				res := aa.Clone()
				ba.Each(func(k Key, v Value) bool {
					if !res.Has(k) {
						res.Set(k, deref(v))
					}
					return true
				})
				return res
			}
		}
	}
	if _, ok := a.(*Array); ok {
		in.unsupportedOperands(op, a, b, true)
	}
	if _, ok := b.(*Array); ok {
		in.unsupportedOperands(op, b, a, false)
	}
	// fast path int/int
	if ai, ok := a.(int64); ok {
		if bi, ok := b.(int64); ok {
			return in.arithInt(op, ai, bi)
		}
	}
	na := in.toNumber(a, op, b, true)
	nb := in.toNumber(b, op, a, false)
	if ai, ok := na.(int64); ok {
		if bi, ok := nb.(int64); ok {
			return in.arithInt(op, ai, bi)
		}
	}
	fa := toFloat(na)
	fb := toFloat(nb)
	switch op {
	case "+":
		return fa + fb
	case "-":
		return fa - fb
	case "*":
		return fa * fb
	case "/":
		if fb == 0 {
			in.throwError("DivisionByZeroError", "Division by zero")
		}
		return fa / fb
	case "%":
		ia := in.floatToIntChecked(na)
		ib := in.floatToIntChecked(nb)
		if ib == 0 {
			in.throwError("DivisionByZeroError", "Modulo by zero")
		}
		if ib == -1 {
			return int64(0)
		}
		return ia % ib
	case "**":
		return powFloat(fa, fb)
	}
	return nil
}

func (in *Interp) floatToIntChecked(v Value) int64 {
	switch x := v.(type) {
	case int64:
		return x
	case float64:
		if !floatFitsInt(x) {
			in.warn(fmt.Sprintf("The float %s is not representable as an int, cast occurred", formatFloatRepr(x)))
			return floatToInt(x)
		}
		if x != math.Trunc(x) {
			in.deprecated(fmt.Sprintf("Implicit conversion from float %s to int loses precision", formatFloatRepr(x)))
		}
		return int64(x)
	}
	return toInt(v)
}

func powFloat(a, b float64) float64 {
	return math.Pow(a, b)
}

func (in *Interp) arithInt(op string, a, b int64) Value {
	switch op {
	case "+":
		r := a + b
		if (r > a) == (b > 0) {
			return r
		}
		return float64(a) + float64(b)
	case "-":
		r := a - b
		if (r < a) == (b > 0) {
			return r
		}
		return float64(a) - float64(b)
	case "*":
		if a == 0 || b == 0 {
			return int64(0)
		}
		r := a * b
		if r/b == a && !(a == -1 && b == math.MinInt64) && !(b == -1 && a == math.MinInt64) {
			// check overflow more precisely
			fa := float64(a) * float64(b)
			if fa > 9.3e18 || fa < -9.3e18 {
				return fa
			}
			return r
		}
		return float64(a) * float64(b)
	case "/":
		if b == 0 {
			in.throwError("DivisionByZeroError", "Division by zero")
		}
		if a%b == 0 && !(a == math.MinInt64 && b == -1) {
			return a / b
		}
		return float64(a) / float64(b)
	case "%":
		if b == 0 {
			in.throwError("DivisionByZeroError", "Modulo by zero")
		}
		if b == -1 {
			return int64(0)
		}
		return a % b
	case "**":
		if b >= 0 {
			// integer power with overflow detection
			result := int64(1)
			base := a
			exp := b
			overflow := false
			for exp > 0 {
				if exp&1 == 1 {
					r, ok := mulOverflow(result, base)
					if !ok {
						overflow = true
						break
					}
					result = r
				}
				exp >>= 1
				if exp > 0 {
					bb, ok := mulOverflow(base, base)
					if !ok {
						overflow = true
						break
					}
					base = bb
				}
			}
			if !overflow {
				return result
			}
			return math.Pow(float64(a), float64(b))
		}
		if a == 0 {
			in.deprecated("Power of base 0 and negative exponent is deprecated")
		}
		return math.Pow(float64(a), float64(b))
	}
	return nil
}

func mulOverflow(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	r := a * b
	if r/b != a || (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) {
		return 0, false
	}
	return r, true
}

func (in *Interp) bitwise(op string, a, b Value) Value {
	a = deref(a)
	b = deref(b)
	if sa, ok := a.(string); ok {
		if sb, ok := b.(string); ok && op != "<<" && op != ">>" {
			// string bitwise ops
			var res []byte
			switch op {
			case "|":
				n := len(sa)
				if len(sb) > n {
					n = len(sb)
				}
				res = make([]byte, n)
				for i := 0; i < n; i++ {
					var ca, cb byte
					if i < len(sa) {
						ca = sa[i]
					}
					if i < len(sb) {
						cb = sb[i]
					}
					res[i] = ca | cb
				}
			case "&":
				n := len(sa)
				if len(sb) < n {
					n = len(sb)
				}
				res = make([]byte, n)
				for i := 0; i < n; i++ {
					res[i] = sa[i] & sb[i]
				}
			case "^":
				n := len(sa)
				if len(sb) < n {
					n = len(sb)
				}
				res = make([]byte, n)
				for i := 0; i < n; i++ {
					res[i] = sa[i] ^ sb[i]
				}
			}
			return string(res)
		}
	}
	if _, ok := a.(*Array); ok {
		in.unsupportedOperands(op, a, b, true)
	}
	if _, ok := b.(*Array); ok {
		in.unsupportedOperands(op, b, a, false)
	}
	ia := in.floatToIntChecked(in.toNumber(a, op, b, true))
	ib := in.floatToIntChecked(in.toNumber(b, op, a, false))
	switch op {
	case "|":
		return ia | ib
	case "&":
		return ia & ib
	case "^":
		return ia ^ ib
	case "<<":
		if ib < 0 {
			in.throwError("ArithmeticError", "Bit shift by negative number")
		}
		if ib >= 64 {
			return int64(0)
		}
		return ia << uint(ib)
	case ">>":
		if ib < 0 {
			in.throwError("ArithmeticError", "Bit shift by negative number")
		}
		if ib >= 64 {
			if ia < 0 {
				return int64(-1)
			}
			return int64(0)
		}
		return ia >> uint(ib)
	}
	return nil
}

func (in *Interp) concat(a, b Value) string {
	return in.toStr(a) + in.toStr(b)
}

// binaryOp evaluates a non-short-circuit binary operator
func (in *Interp) binaryOp(op string, a, b Value) Value {
	switch op {
	case "+", "-", "*", "/", "%", "**":
		return in.arith(op, a, b)
	case ".":
		return in.concat(a, b)
	case "==":
		return looseEquals(a, b)
	case "!=", "<>":
		return !looseEquals(a, b)
	case "===":
		return strictEquals(a, b)
	case "!==":
		return !strictEquals(a, b)
	case "<":
		return in.compareLT(a, b)
	case "<=":
		return in.compareLE(a, b)
	case ">":
		return in.compareLT(b, a)
	case ">=":
		return in.compareLE(b, a)
	case "<=>":
		return int64(compareValues(a, b))
	case "|", "&", "^", "<<", ">>":
		return in.bitwise(op, a, b)
	}
	panic("unknown binary op " + op)
}

func (in *Interp) compareLT(a, b Value) bool {
	a, b = deref(a), deref(b)
	if fa, ok := a.(float64); ok {
		if math.IsNaN(fa) {
			return false
		}
	}
	if fb, ok := b.(float64); ok {
		if math.IsNaN(fb) {
			return false
		}
	}
	if oa, ok := a.(*Object); ok {
		if ob, ok := b.(*Object); ok && oa != ob && oa.class != ob.class {
			return false
		}
	}
	return compareValues(a, b) < 0
}

func (in *Interp) compareLE(a, b Value) bool {
	a, b = deref(a), deref(b)
	if fa, ok := a.(float64); ok {
		if math.IsNaN(fa) {
			return false
		}
	}
	if fb, ok := b.(float64); ok {
		if math.IsNaN(fb) {
			return false
		}
	}
	if oa, ok := a.(*Object); ok {
		if ob, ok := b.(*Object); ok && oa != ob && oa.class != ob.class {
			return false
		}
	}
	return compareValues(a, b) <= 0
}

// increment/decrement
func (in *Interp) incDec(v Value, inc bool) Value {
	switch x := v.(type) {
	case nil:
		if inc {
			return int64(1)
		}
		in.deprecated("Decrement on type null has no effect, this will change in the next major version of PHP")
		return nil
	case bool:
		if inc {
			in.deprecated("Increment on type bool has no effect, this will change in the next major version of PHP")
		} else {
			in.deprecated("Decrement on type bool has no effect, this will change in the next major version of PHP")
		}
		return x
	case int64:
		if inc {
			if x == math.MaxInt64 {
				return float64(x) + 1
			}
			return x + 1
		}
		if x == math.MinInt64 {
			return float64(x) - 1
		}
		return x - 1
	case float64:
		if inc {
			return x + 1
		}
		return x - 1
	case string:
		ni := parseNumeric(x)
		if ni.ok && ni.whole {
			if ni.isInt {
				return in.incDec(ni.i, inc)
			}
			return in.incDec(ni.f, inc)
		}
		if x == "" {
			if inc {
				in.deprecated("Increment on non-alphanumeric string is deprecated")
				return "1"
			}
			in.deprecated("Decrement on empty string is deprecated as non-numeric")
			return int64(-1)
		}
		if inc {
			return strIncrement(x, in)
		}
		in.deprecated("Decrement on non-numeric string has no effect and is deprecated")
		return x
	case *Array:
		if inc {
			in.throwError("TypeError", "Cannot increment array")
		}
		in.throwError("TypeError", "Cannot decrement array")
	case *Object:
		if inc {
			in.throwError("TypeError", "Cannot increment "+x.class.Name)
		}
		in.throwError("TypeError", "Cannot decrement "+x.class.Name)
	}
	return v
}

func strIncrement(s string, in *Interp) Value {
	b := []byte(s)
	// check alphanumeric
	for _, c := range b {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) {
			in.deprecated("Increment on non-alphanumeric string is deprecated")
			return s
		}
	}
	i := len(b) - 1
	for i >= 0 {
		c := b[i]
		switch {
		case c == 'z':
			b[i] = 'a'
			i--
		case c == 'Z':
			b[i] = 'A'
			i--
		case c == '9':
			b[i] = '0'
			i--
		default:
			b[i] = c + 1
			return string(b)
		}
	}
	// overflowed: prepend
	first := s[0]
	var prefix byte
	switch {
	case first >= 'a' && first <= 'z':
		prefix = 'a'
	case first >= 'A' && first <= 'Z':
		prefix = 'A'
	default:
		prefix = '1'
	}
	return string(prefix) + string(b)
}

func (in *Interp) castTo(t string, v Value) Value {
	v = deref(v)
	switch t {
	case "int":
		if f, ok := v.(float64); ok && !floatFitsInt(f) {
			in.warn(fmt.Sprintf("The float %s is not representable as an int, cast occurred", formatFloatRepr(f)))
		}
		if o, ok := v.(*Object); ok {
			in.warn(fmt.Sprintf("Object of class %s could not be converted to int", o.class.Name))
			return int64(1)
		}
		return toInt(v)
	case "float":
		if o, ok := v.(*Object); ok {
			in.warn(fmt.Sprintf("Object of class %s could not be converted to float", o.class.Name))
			return float64(1)
		}
		return toFloat(v)
	case "string":
		return in.toStr(v)
	case "bool":
		return toBool(v)
	case "array":
		switch x := v.(type) {
		case nil:
			return NewArray()
		case *Array:
			return x
		case *Object:
			return in.objectToArray(x)
		default:
			a := NewArray()
			a.Append(v)
			return a
		}
	case "object":
		switch x := v.(type) {
		case *Object:
			return x
		case *Array:
			o := in.newObject(in.classes["stdclass"])
			x.Each(func(k Key, val Value) bool {
				o.props.SetStr(k.String(), deref(val))
				return true
			})
			return o
		case nil:
			return in.newObject(in.classes["stdclass"])
		default:
			o := in.newObject(in.classes["stdclass"])
			o.props.SetStr("scalar", v)
			return o
		}
	case "unset":
		return nil
	}
	return v
}

func (in *Interp) objectToArray(o *Object) *Array {
	if st, ok := o.internal.(*Array); ok && (o.class.instanceOf("ArrayObject") || o.class.instanceOf("ArrayIterator")) {
		return st.Clone()
	}
	if cl, ok := o.internal.(*Closure); ok {
		_ = cl
		a := NewArray()
		a.Append(o)
		return a
	}
	a := NewArray()
	o.props.Each(func(k Key, v Value) bool {
		name := k.String()
		pi := o.class.findProp(name)
		if pi != nil && pi.Visibility != "public" {
			if pi.Visibility == "private" {
				name = "\x00" + pi.Class.Name + "\x00" + name
			} else {
				name = "\x00*\x00" + name
			}
			a.SetStr(name, deref(v))
			return true
		}
		if i, ok := isIntKeyString(name); ok {
			a.SetInt(i, deref(v))
		} else {
			a.SetStr(name, deref(v))
		}
		return true
	})
	return a
}

func lcfirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}
