	i := toInt(l.idx)
	if i < 0 {
		i += int64(len(s))
	}
	if i < 0 {
		in.warn(fmt.Sprintf("Illegal string offset %d", toInt(l.idx)))
		return
	}
	var c string
	switch x := v.(type) {
	case string:
		c = x
	default:
		c = in.toStr(v)
