cd /workspace/src && cat > expr.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"strings"
)

type UninitProp struct{}

var uninit = &UninitProp{}

// ---------- lvalues ----------

type lval interface {
	get(in *Interp) Value      // quiet read (no warnings), returns nil if missing
	set(in *Interp, v Value)
	ref(in *Interp) *Ref
	exists(in *Interp) bool
	unset(in *Interp)
}

type varLval struct {
	fr   *Frame
	name string
}

func (l *varLval) get(in *Interp) Value {
	if r, ok := l.fr.vars[l.name]; ok {
		return r.V
	}
	return nil
}
func (l *varLval) set(in *Interp, v Value) {
	if r, ok := l.fr.vars[l.name]; ok {
		r.set(v)
		return
	}
	r := &Ref{rc: 1}
	r.set(v)
	l.fr.vars[l.name] = r
	if l.fr.vars == nil {
		return
	}
	if in.globals == l.fr.vars {
		in.globalOrder = append(in.globalOrder, l.name)
	}
}
func (l *varLval) ref(in *Interp) *Ref {
	if r, ok := l.fr.vars[l.name]; ok {
		return r
	}
	r := &Ref{rc: 1}
	l.fr.vars[l.name] = r
	if in.globals == l.fr.vars {
		in.globalOrder = append(in.globalOrder, l.name)
	}
	return r
}
func (l *varLval) exists(in *Interp) bool {
	r, ok := l.fr.vars[l.name]
	return ok && r.V != nil
}
func (l *varLval) unset(in *Interp) {
	if r, ok := l.fr.vars[l.name]; ok {
		delete(l.fr.vars, l.name)
		r.release()
	}
}

type refLval struct{ r *Ref }

func (l *refLval) get(in *Interp) Value      { return l.r.V }
func (l *refLval) set(in *Interp, v Value)   { l.r.set(v) }
func (l *refLval) ref(in *Interp) *Ref       { return l.r }
func (l *refLval) exists(in *Interp) bool    { return l.r.V != nil }
func (l *refLval) unset(in *Interp)          { l.r.set(nil) }

type elemLval struct {
	arr *Array
	key Key
	base lval // for string offset writes and re-set
}

func (l *elemLval) get(in *Interp) Value {
	v, ok := l.arr.Get(l.key)
	if !ok {
		return nil
	}
	return deref(v)
}
func (l *elemLval) set(in *Interp, v Value) { l.arr.Set(l.key, v) }
func (l *elemLval) ref(in *Interp) *Ref     { return l.arr.GetRef(l.key) }
func (l *elemLval) exists(in *Interp) bool {
	v, ok := l.arr.Get(l.key)
	return ok && deref(v) != nil
}
func (l *elemLval) unset(in *Interp) { l.arr.Delete(l.key) }

type appendLval struct {
	arr *Array
	key *Key
}

func (l *appendLval) get(in *Interp) Value {
	if l.key != nil {
		v, _ := l.arr.Get(*l.key)
		return deref(v)
	}
	return nil
}
func (l *appendLval) set(in *Interp, v Value) {
	if l.key != nil {
		l.arr.Set(*l.key, v)
		return
	}
	k := IntKey(l.arr.nextFree)
	if !l.arr.Append(v) {
		in.throwError("Error", "Cannot add element to the array as the next element is already occupied")
	}
	l.key = &k
}
func (l *appendLval) ref(in *Interp) *Ref {
	if l.key == nil {
		k := IntKey(l.arr.nextFree)
		l.arr.Append(nil)
		l.key = &k
	}
	return l.arr.GetRef(*l.key)
}
func (l *appendLval) exists(in *Interp) bool { return false }
func (l *appendLval) unset(in *Interp)       {}

type propLval struct {
	obj  *Object
	name string
	fr   *Frame
}

func (l *propLval) get(in *Interp) Value {
	return in.getPropQuiet(l.obj, l.name, l.fr.class)
}
func (l *propLval) set(in *Interp, v Value) { in.setProp(l.obj, l.name, v, l.fr.class) }
func (l *propLval) ref(in *Interp) *Ref {
	in.checkPropWriteAccess(l.obj, l.name, l.fr.class)
	v, ok := l.obj.props.Get(StrKey(l.name))
	if !ok || v == uninit {
		if !ok && !l.obj.class.autoProps {
			if m := l.obj.class.findMethod("__get"); m != nil {
				// indirect modification of overloaded property
				in.notice(fmt.Sprintf("Indirect modification of overloaded property %s::$%s has no effect", l.obj.class.Name, l.name))
				r := &Ref{rc: 1}
				r.set(in.callMethod(l.obj, m, []Value{l.name}))
				return r
			}
		}
		if !ok {
			in.checkDynamicProp(l.obj, l.name)
		}
		l.obj.props.SetRaw(StrKey(l.name), nil)
	}
	return l.obj.props.GetRef(StrKey(l.name))
}
func (l *propLval) exists(in *Interp) bool {
	return in.issetProp(l.obj, l.name, l.fr.class)
}
func (l *propLval) unset(in *Interp) { in.unsetProp(l.obj, l.name, l.fr.class) }

type staticPropLval struct{ r *Ref; cls *Class; name string }

func (l *staticPropLval) get(in *Interp) Value    { return l.r.V }
func (l *staticPropLval) set(in *Interp, v Value) { l.r.set(v) }
func (l *staticPropLval) ref(in *Interp) *Ref     { return l.r }
func (l *staticPropLval) exists(in *Interp) bool  { return l.r.V != nil }
func (l *staticPropLval) unset(in *Interp) {
	in.throwError("Error", fmt.Sprintf("Attempt to unset static property %s::$%s", l.cls.Name, l.name))
}

// objOffsetLval: ArrayAccess object
type objOffsetLval struct {
	obj *Object
	key Value
}

func (l *objOffsetLval) get(in *Interp) Value {
	return in.callMethodByName(l.obj, "offsetGet", []Value{l.key})
}
func (l *objOffsetLval) set(in *Interp, v Value) {
	in.callMethodByName(l.obj, "offsetSet", []Value{l.key, v})
}
func (l *objOffsetLval) ref(in *Interp) *Ref {
	v := in.callMethodByName(l.obj, "offsetGet", []Value{l.key})
	if r, ok := v.(*Ref); ok {
		return r
	}
	in.notice(fmt.Sprintf("Indirect modification of overloaded element of %s has no effect", l.obj.class.Name))
	r := &Ref{rc: 1}
	r.set(v)
	return r
}
func (l *objOffsetLval) exists(in *Interp) bool {
	return toBool(in.callMethodByName(l.obj, "offsetExists", []Value{l.key}))
}
func (l *objOffsetLval) unset(in *Interp) {
	in.callMethodByName(l.obj, "offsetUnset", []Value{l.key})
}

// strOffsetLval: string offset write
type strOffsetLval struct {
	base lval
	idx  Value
}

func (l *strOffsetLval) get(in *Interp) Value {
	s, _ := l.base.get(in).(string)
	i := toInt(l.idx)
	if i < 0 {
		i += int64(len(s))
	}
	if i < 0 || i >= int64(len(s)) {
		return nil
	}
	return s[i : i+1]
}
func (l *strOffsetLval) set(in *Interp, v Value) {
	s, _ := l.base.get(in).(string)
	if _, isStr := l.idx.(string); isStr {
		if !isNumericStr(l.idx.(string)) {
			in.throwError("TypeError", fmt.Sprintf("Cannot access offset of type %s on string", "string"))
		}
	}
	i := toInt(l.idx)
	if i < 0 {
		i += int64(len(s))
	}
	if i < 0 {
		in.warn(fmt.Sprintf("Illegal string offset %d", toInt(l.idx)))
		return
	}
	var c string
	switch x := v.(type) {
	case string:
		c = x
	default:
		c = in.toStr(v)
	}
	if c == "" {
		in.throwError("Error", "Cannot assign an empty string to a string offset")
	}
	if len(c) > 1 {
		in.warn("Only the first byte will be assigned to the string offset")
	}
	b := []byte(s)
	for int64(len(b)) < i {
		b = append(b, ' ')
	}
	if i == int64(len(b)) {
		b = append(b, c[0])
	} else {
		b[i] = c[0]
	}
	l.base.set(in, string(b))
}
func (l *strOffsetLval) ref(in *Interp) *Ref {
	in.throwError("Error", "Cannot create references to/from string offsets")
	return nil
}
func (l *strOffsetLval) exists(in *Interp) bool { return l.get(in) != nil }
func (l *strOffsetLval) unset(in *Interp) {
	in.throwError("Error", "Cannot unset string offsets")
}

type nullLval struct{}

func (l *nullLval) get(in *Interp) Value      { return nil }
func (l *nullLval) set(in *Interp, v Value)   {}
func (l *nullLval) ref(in *Interp) *Ref       { return &Ref{rc: 1} }
func (l *nullLval) exists(in *Interp) bool    { return false }
func (l *nullLval) unset(in *Interp)          {}

func (in *Interp) varName(fr *Frame, e Expr) string {
	switch x := e.(type) {
	case *VarExpr:
		return x.Name
	case *VarVarExpr:
		return in.toStr(in.eval(fr, x.Name))
	}
	return ""
}

// lvalOf resolves an expression to an assignable location (for writes).
func (in *Interp) lvalOf(fr *Frame, e Expr) lval {
	switch x := e.(type) {
	case *VarExpr:
		if x.Name == "this" && fr.this != nil {
			in.throwError("Error", "Cannot re-assign $this")
		}
		if x.Name == "GLOBALS" {
			return &nullLval{}
		}
		return &varLval{fr: fr, name: x.Name}
	case *VarVarExpr:
		return &varLval{fr: fr, name: in.toStr(in.eval(fr, x.Name))}
	case *IndexExpr:
		fr.line = x.Line
		// $GLOBALS['x']
		if v, ok := x.Base.(*VarExpr); ok && v.Name == "GLOBALS" && x.Index != nil {
			name := in.toStr(in.eval(fr, x.Index))
			r, ok := in.globals[name]
			if !ok {
				r = &Ref{rc: 1}
				in.globals[name] = r
				in.globalOrder = append(in.globalOrder, name)
			}
			return &refLval{r: r}
		}
		base := in.lvalOf(fr, x.Base)
		cur := base.get(in)
		switch c := cur.(type) {
		case *Object:
			if x.Index == nil {
				if c.class.instanceOf("ArrayAccess") {
					return &objOffsetLval{obj: c, key: nil}
				}
				in.throwError("Error", fmt.Sprintf("Cannot use object of type %s as array", c.class.Name))
			}
			idx := in.eval(fr, x.Index)
			if c.class.instanceOf("ArrayAccess") {
				return &objOffsetLval{obj: c, key: idx}
			}
			in.throwError("Error", fmt.Sprintf("Cannot use object of type %s as array", c.class.Name))
		case string:
			if x.Index == nil {
				in.throwError("Error", "[] operator not supported for strings")
			}
			if c == "" {
				// empty string auto-vivifies to array (deprecated in 8.x? actually it's an Error since 7.1 for non-empty)
				arr := NewArray()
				base.set(in, arr)
				idx := in.eval(fr, x.Index)
				k, ok := normalizeKey(idx)
				if !ok {
					in.throwError("TypeError", "Illegal offset type")
				}
				return &elemLval{arr: arr, key: k, base: base}
			}
			idx := in.eval(fr, x.Index)
			return &strOffsetLval{base: base, idx: idx}
		case nil:
			arr := NewArray()
			base.set(in, arr)
			cur = arr
		case bool:
			if !c {
				in.deprecated("Automatic conversion of false to array is deprecated")
				arr := NewArray()
				base.set(in, arr)
				cur = arr
			} else {
				in.throwError("Error", "Cannot use a scalar value as an array")
			}
		case *Array:
			if c.rc > 1 {
				c = c.Clone()
				base.set(in, c)
			}
			cur = c
		default:
			in.throwError("Error", "Cannot use a scalar value as an array")
		}
		arr := cur.(*Array)
		if x.Index == nil {
			return &appendLval{arr: arr}
		}
		idx := in.eval(fr, x.Index)
		k, ok := normalizeKey(idx)
		if !ok {
			in.throwError("TypeError", fmt.Sprintf("Cannot access offset of type %s on array", typeName(idx)))
		}
		if _, isFloat := idx.(float64); isFloat {
			f := idx.(float64)
			if f != math.Trunc(f) || !floatFitsInt(f) {
				in.deprecated(fmt.Sprintf("Implicit conversion from float %s to int loses precision", formatFloatRepr(f)))
			}
		}
		return &elemLval{arr: arr, key: k, base: base}
	case *PropExpr:
		fr.line = x.Line
		objv := in.evalForPropWrite(fr, x.Obj)
		name := in.propName(fr, x.Name)
		obj, ok := objv.(*Object)
		if !ok {
			if objv == nil {
				in.throwError("Error", fmt.Sprintf("Attempt to assign property \"%s\" on null", name))
			}
			in.throwError("Error", fmt.Sprintf("Attempt to assign property \"%s\" on %s", name, typeName(objv)))
		}
		return &propLval{obj: obj, name: name, fr: fr}
	case *StaticPropExpr:
		fr.line = x.Line
		cls := in.resolveClassRef(fr, x.Class)
		name := in.propName(fr, x.Name)
		r, pi := cls.findStaticProp(name)
		if r == nil {
			in.throwError("Error", fmt.Sprintf("Access to undeclared static property %s::$%s", cls.Name, name))
		}
		in.checkStaticPropAccess(cls, pi, fr)
		return &staticPropLval{r: r, cls: cls, name: name}
	case *CallExpr, *MethodCallExpr, *StaticCallExpr:
		// function returning reference or array (temporary)
		v := in.eval(fr, e)
		if r, ok := v.(*Ref); ok {
			return &refLval{r: r}
		}
		r := &Ref{rc: 1}
		r.set(v)
		return &refLval{r: r}
	}
	// temporary value
	v := in.eval(fr, e)
	r := &Ref{rc: 1}
	r.set(v)
	return &refLval{r: r}
}

// evalForPropWrite evaluates the object expression of a property write, auto-creating stdClass is an Error in PHP 8
func (in *Interp) evalForPropWrite(fr *Frame, e Expr) Value {
	if isLvalue(e) {
		l := in.lvalOf(fr, e)
		cur := l.get(in)
		if cur == nil {
			if v, ok := e.(*VarExpr); ok {
				if _, exists := fr.vars[v.Name]; !exists {
					in.warn(fmt.Sprintf("Undefined variable $%s", v.Name))
				}
			}
		}
		return cur
	}
	return in.eval(fr, e)
}

func (in *Interp) propName(fr *Frame, e Expr) string {
	if s, ok := e.(*StringLit); ok {
		return s.V
	}
	return in.toStr(in.eval(fr, e))
}

func (in *Interp) assign(fr *Frame, target Expr, v Value) {
	switch t := target.(type) {
	case *VarExpr:
		if t.Name == "this" {
			in.throwError("Error", "Cannot re-assign $this")
		}
		if r, ok := fr.vars[t.Name]; ok {
			r.set(v)
			return
		}
		r := &Ref{rc: 1}
		r.set(v)
		fr.vars[t.Name] = r
		if fr.vars == in.globals {
			in.globalOrder = append(in.globalOrder, t.Name)
		}
		return
	case *ListExpr:
		in.destructure(fr, t.Items, v)
		return
	case *ArrayLit:
		in.destructure(fr, t.Items, v)
		return
	}
	l := in.lvalOf(fr, target)
	l.set(in, v)
}

func (in *Interp) assignVar(fr *Frame, name string, v Value) {
	if r, ok := fr.vars[name]; ok {
		r.set(v)
		return
	}
	r := &Ref{rc: 1}
	r.set(v)
	fr.vars[name] = r
	if fr.vars == in.globals {
		in.globalOrder = append(in.globalOrder, name)
	}
}

func (in *Interp) destructure(fr *Frame, items []ArrayItem, v Value) {
	arr, ok := v.(*Array)
	if !ok {
		if v == nil {
			// assigns null to all
			for _, it := range items {
				if it.Value != nil {
					if sub, ok := it.Value.(*ArrayLit); ok {
						in.destructure(fr, sub.Items, nil)
					} else if sub, ok := it.Value.(*ListExpr); ok {
						in.destructure(fr, sub.Items, nil)
					} else {
						in.assign(fr, it.Value, nil)
					}
				}
			}
			return
		}
		if o, ok := v.(*Object); ok && o.class.instanceOf("ArrayAccess") {
			idx := int64(0)
			for _, it := range items {
				if it.Value == nil {
					idx++
					continue
				}
				var key Value
				if it.Key != nil {
					key = in.eval(fr, it.Key)
				} else {
					key = idx
					idx++
				}
				val := in.callMethodByName(o, "offsetGet", []Value{key})
				in.assign(fr, it.Value, val)
			}
			return
		}
		// scalar: all null, no warning
		for _, it := range items {
			if it.Value != nil {
				in.assign(fr, it.Value, nil)
			}
		}
		return
	}
	idx := int64(0)
	for _, it := range items {
		if it.Value == nil {
			idx++
			continue
		}
		var k Key
		if it.Key != nil {
			kv := in.eval(fr, it.Key)
			var ok bool
			k, ok = normalizeKey(kv)
			if !ok {
				in.throwError("TypeError", "Illegal offset type")
			}
		} else {
			k = IntKey(idx)
			idx++
		}
		if it.ByRef {
			r := arr.GetRef(k)
			in.bindRef(fr, it.Value, r)
			continue
		}
		val, exists := arr.Get(k)
		if !exists {
			if k.IsStr {
				in.warn(fmt.Sprintf("Undefined array key \"%s\"", k.S))
			} else {
				in.warn(fmt.Sprintf("Undefined array key %d", k.I))
			}
		}
		val = deref(val)
		switch sub := it.Value.(type) {
		case *ArrayLit:
			in.destructure(fr, sub.Items, val)
		case *ListExpr:
			in.destructure(fr, sub.Items, val)
		default:
			in.assign(fr, it.Value, val)
		}
	}
}

// getRef returns a reference to the location denoted by e (creating it if needed)
func (in *Interp) getRef(fr *Frame, e Expr) *Ref {
	switch x := e.(type) {
	case *VarExpr:
		if x.Name == "this" && fr.this != nil {
			r := &Ref{rc: 1}
			r.set(fr.this)
			return r
		}
		if r, ok := fr.vars[x.Name]; ok {
			return r
		}
		r := &Ref{rc: 1}
		fr.vars[x.Name] = r
		if fr.vars == in.globals {
			in.globalOrder = append(in.globalOrder, x.Name)
		}
		return r
	}
	l := in.lvalOf(fr, e)
	return l.ref(in)
}

// bindRef makes target an alias of r
func (in *Interp) bindRef(fr *Frame, target Expr, r *Ref) {
	switch t := target.(type) {
	case *VarExpr:
		if old, ok := fr.vars[t.Name]; ok {
			if old == r {
				return
			}
			old.release()
		}
		r.rc++
		fr.vars[t.Name] = r
		if fr.vars == in.globals {
			found := false
			for _, n := range in.globalOrder {
				if n == t.Name {
					found = true
					break
				}
			}
			if !found {
				in.globalOrder = append(in.globalOrder, t.Name)
			}
		}
		return
	case *VarVarExpr:
		name := in.toStr(in.eval(fr, t.Name))
		if old, ok := fr.vars[name]; ok {
			old.release()
		}
		r.rc++
		fr.vars[name] = r
		return
	case *IndexExpr:
		base := in.lvalOf(fr, t.Base)
		cur := base.get(in)
		var arr *Array
		switch c := cur.(type) {
		case nil:
			arr = NewArray()
			base.set(in, arr)
		case *Array:
			if c.rc > 1 {
				c = c.Clone()
				base.set(in, c)
			}
			arr = c
		default:
			in.throwError("Error", "Cannot use a scalar value as an array")
		}
		if t.Index == nil {
			r.rc++
			arr.Append(r)
			return
		}
		k, ok := normalizeKey(in.eval(fr, t.Index))
		if !ok {
			in.throwError("TypeError", "Illegal offset type")
		}
		r.rc++
		arr.SetRaw(k, r)
		return
	case *PropExpr:
		objv := in.evalForPropWrite(fr, t.Obj)
		obj, ok := objv.(*Object)
		if !ok {
			in.throwError("Error", "Attempt to assign property on non-object")
		}
		name := in.propName(fr, t.Name)
		r.rc++
		obj.props.SetRaw(StrKey(name), r)
		return
	case *StaticPropExpr:
		cls := in.resolveClassRef(fr, t.Class)
		name := in.propName(fr, t.Name)
		for k := cls; k != nil; k = k.Parent {
			if _, ok := k.StaticProps[name]; ok {
				r.rc++
				k.StaticProps[name] = r
				return
			}
		}
		in.throwError("Error", fmt.Sprintf("Access to undeclared static property %s::$%s", cls.Name, name))
	case *ListExpr:
		in.destructure(fr, t.Items, r.V)
		return
	case *ArrayLit:
		in.destructure(fr, t.Items, r.V)
		return
	}
	in.throwError("Error", "Cannot assign reference to non referenceable value")
}

func (in *Interp) unset(fr *Frame, e Expr) {
	switch x := e.(type) {
	case *VarExpr:
		if x.Name == "this" {
			in.throwError("Error", "Cannot unset $this")
		}
		if r, ok := fr.vars[x.Name]; ok {
			delete(fr.vars, x.Name)
			r.release()
		}
		return
	case *VarVarExpr:
		name := in.toStr(in.eval(fr, x.Name))
		if r, ok := fr.vars[name]; ok {
			delete(fr.vars, name)
			r.release()
		}
		return
	case *IndexExpr:
		fr.line = x.Line
		if v, ok := x.Base.(*VarExpr); ok && v.Name == "GLOBALS" && x.Index != nil {
			name := in.toStr(in.eval(fr, x.Index))
			if r, ok := in.globals[name]; ok {
				delete(in.globals, name)
				r.release()
			}
			return
		}
		// evaluate base quietly; if not array, nothing
		baseV := in.evalQuiet(fr, x.Base)
		switch c := baseV.(type) {
		case *Array:
			l := in.lvalOf(fr, x.Base)
			cur := l.get(in).(*Array)
			if cur.rc > 1 {
				cur = cur.Clone()
				l.set(in, cur)
			}
			k, ok := normalizeKey(in.eval(fr, x.Index))
			if !ok {
				in.throwError("TypeError", "Illegal offset type in unset")
			}
			cur.Delete(k)
			_ = c
		case *Object:
			if c.class.instanceOf("ArrayAccess") {
				in.callMethodByName(c, "offsetUnset", []Value{in.eval(fr, x.Index)})
				return
			}
			in.throwError("Error", fmt.Sprintf("Cannot use object of type %s as array", c.class.Name))
		case string:
			in.throwError("Error", "Cannot unset string offsets")
		}
		return
	case *PropExpr:
		fr.line = x.Line
		objv := in.evalQuiet(fr, x.Obj)
		if obj, ok := objv.(*Object); ok {
			in.unsetProp(obj, in.propName(fr, x.Name), fr.class)
		}
		return
	case *StaticPropExpr:
		cls := in.resolveClassRef(fr, x.Class)
		in.throwError("Error", fmt.Sprintf("Attempt to unset static property %s::$%s", cls.Name, in.propName(fr, x.Name)))
	}
	in.fatal("Cannot unset expression")
}

// evalQuiet evaluates without undefined warnings (for isset/empty/unset)
func (in *Interp) evalQuiet(fr *Frame, e Expr) Value {
	switch x := e.(type) {
	case *VarExpr:
		if x.Name == "this" {
			return fr.this
		}
		if x.Name == "GLOBALS" {
			return in.globalsArray()
		}
		if r, ok := fr.vars[x.Name]; ok {
			return r.V
		}
		return nil
	case *VarVarExpr:
		name := in.toStr(in.eval(fr, x.Name))
		if r, ok := fr.vars[name]; ok {
			return r.V
		}
		return nil
	case *IndexExpr:
		base := in.evalQuiet(fr, x.Base)
		if x.Index == nil {
			in.throwError("Error", "Cannot use [] for reading")
		}
		switch b := base.(type) {
		case *Array:
			idx := in.eval(fr, x.Index)
			k, ok := normalizeKey(idx)
			if !ok {
				return nil
			}
			v, _ := b.Get(k)
			return deref(v)
		case string:
			idx := in.eval(fr, x.Index)
			var i int64
			switch ix := idx.(type) {
			case int64:
				i = ix
			case string:
				ni := parseNumeric(ix)
				if !ni.ok || !ni.whole || !ni.isInt {
					return nil
				}
				i = ni.i
			case float64:
				i = int64(ix)
			case bool:
				i = toInt(ix)
			default:
				return nil
			}
			if i < 0 {
				i += int64(len(b))
			}
			if i < 0 || i >= int64(len(b)) {
				return nil
			}
			return b[i : i+1]
		case *Object:
			idx := in.eval(fr, x.Index)
			if b.class.instanceOf("ArrayAccess") {
				if !toBool(in.callMethodByName(b, "offsetExists", []Value{idx})) {
					return nil
				}
				return in.callMethodByName(b, "offsetGet", []Value{idx})
			}
			in.throwError("Error", fmt.Sprintf("Cannot use object of type %s as array", b.class.Name))
		}
		return nil
	case *PropExpr:
		objv := in.evalQuiet(fr, x.Obj)
		obj, ok := objv.(*Object)
		if !ok {
			return nil
		}
		name := in.propName(fr, x.Name)
		if !in.issetProp(obj, name, fr.class) {
			return nil
		}
		return in.getProp2(obj, name, fr.class)
	case *StaticPropExpr:
		cls := in.resolveClassRefQuiet(fr, x.Class)
		if cls == nil {
			return nil
		}
		name := in.propName(fr, x.Name)
		r, _ := cls.findStaticProp(name)
		if r == nil {
			return nil
		}
		return r.V
	case *ClassConstExpr:
		cls := in.resolveClassRefQuiet(fr, x.Class)
		if cls == nil {
			return nil
		}
		return in.eval(fr, e)
	}
	return in.eval(fr, e)
}

func (in *Interp) isset(fr *Frame, e Expr) bool {
	switch x := e.(type) {
	case *PropExpr:
		objv := in.evalQuiet(fr, x.Obj)
		obj, ok := objv.(*Object)
		if !ok {
			return false
		}
		return in.issetProp(obj, in.propName(fr, x.Name), fr.class)
	case *IndexExpr:
		base := in.evalQuiet(fr, x.Base)
		if o, ok := base.(*Object); ok && o.class.instanceOf("ArrayAccess") {
			return toBool(in.callMethodByName(o, "offsetExists", []Value{in.eval(fr, x.Index)}))
		}
	}
	return in.evalQuiet(fr, e) != nil
}

func (in *Interp) globalsArray() *Array {
	a := NewArray()
	for _, name := range in.globalOrder {
		if r, ok := in.globals[name]; ok {
			a.SetStr(name, r.V)
		}
	}
	return a
}

// ---------- eval ----------

func (in *Interp) eval(fr *Frame, e Expr) Value {
	switch x := e.(type) {
	case *IntLit:
		return x.V
	case *StringLit:
		return x.V
	case *FloatLit:
		return x.V
	case *BoolLit:
		return x.V
	case *NullLit:
		return nil
	case *VarExpr:
		if r, ok := fr.vars[x.Name]; ok {
			return r.V
		}
		if x.Name == "this" {
			if fr.this != nil {
				return fr.this
			}
			if fr.vars == in.globals || fr.fn != nil {
				in.throwError("Error", "Using $this when not in object context")
			}
		}
		if x.Name == "GLOBALS" {
			return in.globalsArray()
		}
		fr.line = x.Line
		in.warn(fmt.Sprintf("Undefined variable $%s", x.Name))
		return nil
	case *VarVarExpr:
		name := in.toStr(in.eval(fr, x.Name))
		if r, ok := fr.vars[name]; ok {
			return r.V
		}
		if name == "this" && fr.this != nil {
			return fr.this
		}
		in.warn(fmt.Sprintf("Undefined variable $%s", name))
		return nil
	case *InterpString:
		var sb strings.Builder
		for _, p := range x.Parts {
			if s, ok := p.(*StringLit); ok {
				sb.WriteString(s.V)
			} else {
				sb.WriteString(in.toStr(in.eval(fr, p)))
			}
		}
		return sb.String()
	case *ArrayLit:
		return in.evalArrayLit(fr, x)
	case *IndexExpr:
		return in.evalIndex(fr, x)
	case *PropExpr:
		fr.line = x.Line
		objv := in.eval(fr, x.Obj)
		if objv == nil && x.NullSafe {
			return nil
		}
		name := in.propName(fr, x.Name)
		obj, ok := objv.(*Object)
		if !ok {
			in.warn(fmt.Sprintf("Attempt to read property \"%s\" on %s", name, typeName(objv)))
			return nil
		}
		return in.getProp2(obj, name, fr.class)
	case *StaticPropExpr:
		fr.line = x.Line
		cls := in.resolveClassRef(fr, x.Class)
		name := in.propName(fr, x.Name)
		r, pi := cls.findStaticProp(name)
		if r == nil {
			in.throwError("Error", fmt.Sprintf("Access to undeclared static property %s::$%s", cls.Name, name))
		}
		in.checkStaticPropAccess(cls, pi, fr)
		return r.V
	case *ClassConstExpr:
		fr.line = x.Line
		return in.evalClassConst(fr, x)
	case *ConstExpr:
		fr.line = x.Line
		return in.lookupConst(x.Name, x.Alt)
	case *MagicConstExpr:
		return in.magicConst(fr, x.Name)
	case *NameExpr:
		// bare name used as value (e.g. in instanceof handled elsewhere) -> constant lookup
		return in.lookupConst(x.Name, x.Alt)
	case *CallExpr:
		fr.line = x.Line
		return in.evalCall(fr, x)
	case *MethodCallExpr:
		fr.line = x.Line
		return in.evalMethodCall(fr, x)
	case *StaticCallExpr:
		fr.line = x.Line
		return in.evalStaticCall(fr, x)
	case *NewExpr:
		fr.line = x.Line
		return in.evalNew(fr, x)
	case *CloneExpr:
		fr.line = x.Line
		v := in.eval(fr, x.E)
		o, ok := v.(*Object)
		if !ok {
			in.throwError("Error", "__clone method called on non-object")
		}
		return in.cloneObject(o, fr)
	case *UnaryExpr:
		v := in.eval(fr, x.E)
		fr.line = x.Line
		switch x.Op {
		case "!":
			return !toBool(v)
		case "-":
			if i, ok := v.(int64); ok {
				if i == math.MinInt64 {
					return -float64(i)
				}
				return -i
			}
			if f, ok := v.(float64); ok {
				return -f
			}
			return in.arith("*", v, int64(-1))
		case "+":
			if _, ok := v.(int64); ok {
				return v
			}
			if _, ok := v.(float64); ok {
				return v
			}
			return in.arith("*", v, int64(1))
		case "~":
			switch n := v.(type) {
			case int64:
				return ^n
			case float64:
				return ^in.floatToIntChecked(n)
			case string:
				b := []byte(n)
				for i := range b {
					b[i] = ^b[i]
				}
				return string(b)
			default:
				in.throwError("TypeError", fmt.Sprintf("Cannot perform bitwise not on %s", typeName(v)))
			}
		}
	case *BinaryExpr:
		if x.Op == "??" {
			l := in.evalQuiet(fr, x.L)
			if l != nil {
				return l
			}
			return in.eval(fr, x.R)
		}
		l := in.eval(fr, x.L)
		r := in.eval(fr, x.R)
		fr.line = x.Line
		return in.binaryOp(x.Op, l, r)
	case *LogicalExpr:
		switch x.Op {
		case "&&", "and":
			if !toBool(in.eval(fr, x.L)) {
				return false
			}
			return toBool(in.eval(fr, x.R))
		case "||", "or":
			if toBool(in.eval(fr, x.L)) {
				return true
			}
			return toBool(in.eval(fr, x.R))
		case "xor":
			return toBool(in.eval(fr, x.L)) != toBool(in.eval(fr, x.R))
		}
	case *AssignExpr:
		fr.line = x.Line
		switch t := x.Target.(type) {
		case *VarExpr:
			v := in.eval(fr, x.Value)
			if t.Name == "this" {
				in.throwError("Error", "Cannot re-assign $this")
			}
			if r, ok := fr.vars[t.Name]; ok {
				r.set(v)
			} else {
				r := &Ref{rc: 1}
				r.set(v)
				fr.vars[t.Name] = r
				if fr.vars == in.globals {
					in.globalOrder = append(in.globalOrder, t.Name)
				}
			}
			return v
		case *ListExpr:
			v := in.eval(fr, x.Value)
			if arr, ok := v.(*Array); ok {
				arr.rc++
				defer func() { arr.rc--; if arr.rc <= 0 { in.addCandidate(arr) } }()
			}
			in.destructure(fr, t.Items, v)
			return v
		}
		// evaluate lvalue first then rhs? PHP evaluates RHS first for simple vars, but for array dims the container is resolved... We eval the rhs first.
		v := in.eval(fr, x.Value)
		l := in.lvalOf(fr, x.Target)
		l.set(in, v)
		return v
	case *AssignRefExpr:
		fr.line = x.Line
		// $a = &$b  or $a = &func()
		var r *Ref
		switch rhs := x.Value.(type) {
		case *NewExpr:
			r = &Ref{rc: 1}
			r.set(in.eval(fr, rhs))
		default:
			if isLvalue(x.Value) {
				r = in.getRef(fr, x.Value)
			} else {
				v := in.eval(fr, x.Value)
				if rr, ok := v.(*Ref); ok {
					r = rr
				} else {
					in.notice("Only variables should be assigned by reference")
					r = &Ref{rc: 1}
					r.set(v)
				}
			}
		}
		in.bindRef(fr, x.Target, r)
		return r.V
	case *CompoundAssignExpr:
		fr.line = x.Line
		if x.Op == "??" {
			cur := in.evalQuiet(fr, x.Target)
			if cur != nil {
				return cur
			}
			v := in.eval(fr, x.Value)
			in.assign(fr, x.Target, v)
			return v
		}
		l := in.lvalOf(fr, x.Target)
		cur := l.get(in)
		if cur == nil {
			if vl, ok := l.(*varLval); ok {
				if _, exists := fr.vars[vl.name]; !exists {
					in.warn(fmt.Sprintf("Undefined variable $%s", vl.name))
				}
			} else if el, ok := l.(*elemLval); ok {
				if !el.arr.Has(el.key) {
					if el.key.IsStr {
						in.warn(fmt.Sprintf("Undefined array key \"%s\"", el.key.S))
					} else {
						in.warn(fmt.Sprintf("Undefined array key %d", el.key.I))
					}
				}
			}
		}
		rhs := in.eval(fr, x.Value)
		var res Value
		if x.Op == "." {
			res = in.concat(cur, rhs)
		} else {
			res = in.binaryOp(x.Op, cur, rhs)
		}
		l.set(in, res)
		return res
	case *IncDecExpr:
		fr.line = x.Line
		l := in.lvalOf(fr, x.Target)
		cur := l.get(in)
		if cur == nil {
			if vl, ok := l.(*varLval); ok {
				if _, exists := fr.vars[vl.name]; !exists {
					in.warn(fmt.Sprintf("Undefined variable $%s", vl.name))
				}
			}
		}
		nv := in.incDec(cur, x.Inc)
		l.set(in, nv)
		if x.Prefix {
			return nv
		}
		return cur
	case *TernaryExpr:
		c := in.eval(fr, x.Cond)
		if x.Then == nil {
			if toBool(c) {
				return c
			}
			return in.eval(fr, x.Else)
		}
		if toBool(c) {
			return in.eval(fr, x.Then)
		}
		return in.eval(fr, x.Else)
	case *CastExpr:
		v := in.eval(fr, x.E)
		fr.line = x.Line
		return in.castTo(x.Type, v)
	case *IssetExpr:
		for _, v := range x.Vars {
			if !in.isset(fr, v) {
				return false
			}
		}
		return true
	case *EmptyExpr:
		return !toBool(in.evalQuiet(fr, x.E))
	case *ExitExpr:
		fr.line = x.Line
		code := 0
		if x.E != nil {
			v := in.eval(fr, x.E)
			if s, ok := v.(string); ok {
				in.echo(s)
			} else {
				code = int(toInt(v))
			}
		}
		panic(&ExitSignal{code: code})
	case *PrintExpr:
		v := in.eval(fr, x.E)
		in.echo(in.toStr(v))
		return int64(1)
	case *InstanceofExpr:
		v := in.eval(fr, x.E)
		var cls *Class
		switch c := x.Class.(type) {
		case *NameExpr:
			cls = in.resolveClassRefQuiet(fr, c)
			if cls == nil {
				return false
			}
		default:
			cv := in.eval(fr, c)
			switch cc := cv.(type) {
			case *Object:
				cls = cc.class
			case string:
				cls = in.lookupClass(cc)
				if cls == nil {
					return false
				}
			default:
				in.throwError("Error", "Class name must be a valid object or a string")
			}
		}
		o, ok := v.(*Object)
		if !ok {
			return false
		}
		return o.class.isSubclassOf(cls)
	case *ClosureExpr:
		return in.makeClosure(fr, x.Fn, x.Uses, x.Static, false)
	case *ArrowFnExpr:
		return in.makeClosure(fr, x.Fn, nil, x.Static, true)
	case *YieldExpr:
		fr.line = x.Line
		return in.evalYield(fr, x)
	case *YieldFromExpr:
		fr.line = x.Line
		return in.evalYieldFrom(fr, x)
	case *ThrowExpr:
		fr.line = x.Line
		in.doThrow(in.eval(fr, x.E))
		return nil
	case *MatchExpr:
		fr.line = x.Line
		subj := in.eval(fr, x.Subject)
		for _, arm := range x.Arms {
			if arm.Conds == nil {
				continue
			}
			for _, c := range arm.Conds {
				if strictEquals(subj, in.eval(fr, c)) {
					return in.eval(fr, arm.Body)
				}
			}
		}
		for _, arm := range x.Arms {
			if arm.Conds == nil {
				return in.eval(fr, arm.Body)
			}
		}
		in.throwError("UnhandledMatchError", "Unhandled match case "+in.matchRepr(subj))
	case *SilenceExpr:
		in.silenceDepth++
		defer func() { in.silenceDepth-- }()
		return in.eval(fr, x.E)
	case *IncludeExpr:
		fr.line = x.Line
		return in.evalInclude(fr, x)
	case *ListExpr:
		in.fatal("Cannot use list() outside of an assignment context")
	}
	panic(fmt.Sprintf("eval: unhandled expression %T", e))
}

func (in *Interp) matchRepr(v Value) string {
	switch x := v.(type) {
	case string:
		return phpQuoteString(x)
	case *Object:
		return "of type " + x.class.Name
	case *Array:
		return "of type array"
	case nil:
		return "NULL"
	case bool:
		if x {
			return "true"
		}
		return "false"
	case float64:
		return formatFloatRepr(x)
	}
	return toStr(v)
}

func phpQuoteString(s string) string {
	return "'" + strings.ReplaceAll(strings.ReplaceAll(s, "\\", "\\\\"), "'", "\\'") + "'"
}

func (in *Interp) evalArrayLit(fr *Frame, x *ArrayLit) Value {
	arr := NewArrayCap(len(x.Items))
	hasRefcounted := false
	for _, it := range x.Items {
		if it.Value == nil {
			in.fatal("Cannot use empty array elements in arrays")
		}
		if it.Spread {
			v := in.eval(fr, it.Value)
			switch s := v.(type) {
			case *Array:
				s.Each(func(k Key, val Value) bool {
					val = deref(val)
					if _, ok := val.(*Object); ok {
						hasRefcounted = true
					}
					if k.IsStr {
						arr.Set(k, val)
					} else {
						arr.Append(val)
					}
					return true
				})
			case *Object:
				in.iterate(s, func(k, val Value) bool {
					if ks, ok := k.(string); ok {
						arr.SetStr(ks, val)
					} else {
						arr.Append(val)
					}
					return true
				})
			default:
				in.throwError("Error", "Only arrays and Traversables can be unpacked")
			}
			continue
		}
		if it.ByRef {
			r := in.getRef(fr, it.Value)
			r.rc++
			if it.Key != nil {
				k, ok := normalizeKey(in.eval(fr, it.Key))
				if !ok {
					in.throwError("TypeError", "Illegal offset type")
				}
				arr.SetRaw(k, r)
			} else {
				arr.Append(r)
			}
			continue
		}
		if it.Key != nil {
			kv := in.eval(fr, it.Key)
			v := in.eval(fr, it.Value)
			switch v.(type) {
			case *Object, *Array:
				hasRefcounted = true
			}
			k, ok := normalizeKey(kv)
			if !ok {
				in.throwError("TypeError", fmt.Sprintf("Illegal offset type"))
			}
			if f, isF := kv.(float64); isF && (f != math.Trunc(f) || !floatFitsInt(f)) {
				in.deprecated(fmt.Sprintf("Implicit conversion from float %s to int loses precision", formatFloatRepr(f)))
			}
			arr.Set(k, v)
		} else {
			v := in.eval(fr, it.Value)
			switch v.(type) {
			case *Object, *Array:
				hasRefcounted = true
			}
			if !arr.Append(v) {
				in.throwError("Error", "Cannot add element to the array as the next element is already occupied")
			}
		}
	}
	if hasRefcounted {
		in.addCandidate(arr)
	}
	return arr
}

func (in *Interp) evalIndex(fr *Frame, x *IndexExpr) Value {
	if x.Index == nil {
		in.throwError("Error", "Cannot use [] for reading")
	}
	if v, ok := x.Base.(*VarExpr); ok && v.Name == "GLOBALS" {
		name := in.toStr(in.eval(fr, x.Index))
		if r, ok := in.globals[name]; ok {
			return r.V
		}
		in.warn(fmt.Sprintf("Undefined global variable $%s", name))
		return nil
	}
	base := in.eval(fr, x.Base)
	idx := in.eval(fr, x.Index)
	fr.line = x.Line
	return in.indexValue(base, idx, false)
}

// indexValue reads base[idx]
func (in *Interp) indexValue(base Value, idx Value, quiet bool) Value {
	switch b := base.(type) {
	case *Array:
		k, ok := normalizeKey(idx)
		if !ok {
			in.throwError("TypeError", fmt.Sprintf("Cannot access offset of type %s on array", typeName(idx)))
		}
		if f, isF := idx.(float64); isF && (f != math.Trunc(f) || !floatFitsInt(f)) && !quiet {
			in.deprecated(fmt.Sprintf("Implicit conversion from float %s to int loses precision", formatFloatRepr(f)))
		}
		v, exists := b.Get(k)
		if !exists {
			if !quiet {
				if k.IsStr {
					in.warn(fmt.Sprintf("Undefined array key \"%s\"", k.S))
				} else {
					in.warn(fmt.Sprintf("Undefined array key %d", k.I))
				}
			}
			return nil
		}
		return deref(v)
	case string:
		var i int64
		switch ix := idx.(type) {
		case int64:
			i = ix
		case string:
			ni := parseNumeric(ix)
			if !ni.ok || !ni.whole {
				in.throwError("TypeError", fmt.Sprintf("Cannot access offset of type %s on string", "string"))
			}
			if !ni.isInt {
				in.warn(fmt.Sprintf("String offset cast occurred"))
				i = int64(ni.f)
			} else {
				i = ni.i
			}
		case float64:
			in.warn("String offset cast occurred")
			i = int64(ix)
		case bool:
			in.warn("String offset cast occurred")
			i = toInt(ix)
		case nil:
			in.warn("String offset cast occurred")
			i = 0
		default:
			in.throwError("TypeError", fmt.Sprintf("Cannot access offset of type %s on string", typeName(idx)))
		}
		orig := i
		if i < 0 {
			i += int64(len(b))
		}
		if i < 0 || i >= int64(len(b)) {
			if !quiet {
				in.warn(fmt.Sprintf("Uninitialized string offset %d", orig))
			}
			return ""
		}
		return b[i : i+1]
	case *Object:
		if b.class.instanceOf("ArrayAccess") {
			return in.callMethodByName(b, "offsetGet", []Value{idx})
		}
		in.throwError("Error", fmt.Sprintf("Cannot use object of type %s as array", b.class.Name))
	case nil:
		if !quiet {
			in.warn("Trying to access array offset on null")
		}
		return nil
	default:
		if !quiet {
			in.warn(fmt.Sprintf("Trying to access array offset on %s", typeName(base)))
		}
		return nil
	}
	return nil
}

func (in *Interp) magicConst(fr *Frame, name string) Value {
	switch name {
	case "__file__":
		return fr.file
	case "__dir__":
		return dirOf(fr.file)
	case "__function__":
		if fr.fn != nil {
			if fr.closure != nil {
				return "{closure}"
			}
			return fr.fn.Name
		}
		return ""
	case "__class__":
		if fr.class != nil {
			return fr.class.Name
		}
		return ""
	case "__method__":
		if fr.fn != nil {
			if fr.closure != nil {
				return "{closure}"
			}
			if fr.fn.Method != nil && fr.fn.Method.Class != nil {
				return fr.fn.Method.Class.Name + "::" + fr.fn.Name
			}
			return fr.fn.Name
		}
		return ""
	case "__trait__":
		return ""
	case "__namespace__":
		return fr.namespace
	}
	return nil
}

// ---------- constants ----------

func (in *Interp) lookupConst(name string, alt string) Value {
	if v, ok := in.constants[name]; ok {
		return v
	}
	lname := strings.ToLower(name)
	switch lname {
	case "true":
		return true
	case "false":
		return false
	case "null":
		return nil
	}
	if alt != "" {
		if v, ok := in.constants[alt]; ok {
			return v
		}
		switch strings.ToLower(alt) {
		case "true":
			return true
		case "false":
			return false
		case "null":
			return nil
		}
		name = alt
	}
	// case-insensitive builtin constants? only true/false/null
	in.throwError("Error", fmt.Sprintf("Undefined constant \"%s\"", name))
	return nil
}

func (in *Interp) defineConst(name string, v Value) bool {
	if _, ok := in.constants[name]; ok {
		in.warn(fmt.Sprintf("Constant %s already defined", name))
		return false
	}
	in.constants[name] = v
	return true
}

func (in *Interp) evalClassConst(fr *Frame, x *ClassConstExpr) Value {
	name := x.Name
	if x.NameExpr != nil {
		name = in.toStr(in.eval(fr, x.NameExpr))
	}
	if name == "class" {
		switch c := x.Class.(type) {
		case *NameExpr:
			switch c.Name {
			case "self":
				if fr.class == nil {
					in.throwError("Error", "Cannot use \"self\" when no class scope is active")
				}
				return fr.class.Name
			case "static":
				if fr.staticClass == nil {
					in.throwError("Error", "Cannot use \"static\" when no class scope is active")
				}
				return fr.staticClass.Name
			case "parent":
				if fr.class == nil || fr.class.Parent == nil {
					in.throwError("Error", "Cannot use \"parent\" when current class scope has no parent")
				}
				return fr.class.Parent.Name
			}
			return c.Name
		default:
			v := in.eval(fr, c)
			if o, ok := v.(*Object); ok {
				return o.class.Name
			}
			in.throwError("TypeError", "Cannot use \"::class\" on "+typeName(v))
		}
	}
	cls := in.resolveClassRef(fr, x.Class)
	return in.classConstValue(cls, name, fr)
}

func (in *Interp) classConstValue(cls *Class, name string, fr *Frame) Value {
	// enum case?
	if cls.EnumCaseObjs != nil {
		if o, ok := cls.EnumCaseObjs[name]; ok {
			return o
		}
	}
	cc := cls.findConst(name)
	if cc == nil {
		in.throwError("Error", fmt.Sprintf("Undefined constant %s::%s", cls.Name, name))
	}
	if cc.Visibility == "private" && (fr == nil || fr.class != cc.Class) {
		in.throwError("Error", fmt.Sprintf("Cannot access private constant %s::%s", cls.Name, name))
	}
	if cc.Visibility == "protected" && (fr == nil || fr.class == nil || !(fr.class.isSubclassOf(cc.Class) || cc.Class.isSubclassOf(fr.class))) {
		in.throwError("Error", fmt.Sprintf("Cannot access protected constant %s::%s", cls.Name, name))
	}
	return in.resolveClassConst(cc)
}

func (in *Interp) resolveClassConst(cc *ClassConst) Value {
	if !cc.evaluated {
		if cc.evaluating {
			in.throwError("Error", fmt.Sprintf("Cannot declare self-referencing constant %s::%s", cc.Class.Name, cc.Name))
		}
		cc.evaluating = true
		fr := &Frame{vars: map[string]*Ref{}, class: cc.Class, staticClass: cc.Class, file: cc.Class.Decl.File, line: cc.Class.Decl.Line}
		if in.frame != nil {
			fr.line = in.frame.line
			fr.file = in.frame.file
		}
		cc.Value = in.eval(fr, cc.Expr)
		cc.evaluated = true
		cc.evaluating = false
	}
	return cc.Value
}

// ---------- class resolution ----------

func (in *Interp) resolveClassRef(fr *Frame, e Expr) *Class {
	c := in.resolveClassRefQuiet(fr, e)
	if c == nil {
		name := ""
		if n, ok := e.(*NameExpr); ok {
			name = n.Name
		} else {
			v := in.eval(fr, e)
			name = toStr(v)
		}
		in.throwError("Error", fmt.Sprintf("Class \"%s\" not found", name))
	}
	return c
}

func (in *Interp) resolveClassRefQuiet(fr *Frame, e Expr) *Class {
	switch c := e.(type) {
	case *NameExpr:
		switch c.Name {
		case "self":
			if fr.class == nil {
				in.throwError("Error", "Cannot use \"self\" when no class scope is active")
			}
			return fr.class
		case "static":
			if fr.staticClass == nil {
				if fr.class != nil {
					return fr.class
				}
				in.throwError("Error", "Cannot use \"static\" when no class scope is active")
			}
			return fr.staticClass
		case "parent":
			if fr.class == nil {
				in.throwError("Error", "Cannot use \"parent\" when no class scope is active")
			}
			if fr.class.Parent == nil {
				in.throwError("Error", "Cannot use \"parent\" when current class scope has no parent")
			}
			return fr.class.Parent
		}
		return in.lookupClass(c.Name)
	default:
		v := in.eval(fr, e)
		switch cv := v.(type) {
		case *Object:
			return cv.class
		case string:
			return in.lookupClass(cv)
		}
		in.throwError("Error", "Cannot use value of type "+typeName(v)+" as class name")
	}
	return nil
}

// lookupClass finds a class by name, triggering autoload if needed
func (in *Interp) lookupClass(name string) *Class {
	name = strings.TrimPrefix(name, "\\")
	lname := strings.ToLower(name)
	if c, ok := in.classes[lname]; ok {
		return c
	}
	if cd, ok := in.pendingClasses[lname]; ok {
		if in.classDepsReady(cd) || true {
			in.declareClass(cd, in.frame)
			if c, ok := in.classes[lname]; ok {
				return c
			}
		}
	}
	if len(in.autoloaders) > 0 {
		for _, al := range in.autoloaders {
			in.callValue(al, []Value{name})
			if c, ok := in.classes[lname]; ok {
				return c
			}
		}
	}
	return nil
}

// ---------- properties ----------

func (in *Interp) checkDynamicProp(obj *Object, name string) {
	if obj.class.autoProps {
		return
	}
	if obj.class.Decl != nil && obj.class.Decl.AllowDynamic {
		return
	}
	for c := obj.class; c != nil; c = c.Parent {
		if c.autoProps || (c.Decl != nil && c.Decl.AllowDynamic) {
			return
		}
	}
	in.deprecated(fmt.Sprintf("Creation of dynamic property %s::$%s is deprecated", obj.class.Name, name))
}

func (in *Interp) getPropQuiet(obj *Object, name string, scope *Class) Value {
	v, ok := obj.props.Get(StrKey(name))
	if ok && v != uninit && in.propAccessible(obj, name, scope) {
		return deref(v)
	}
	if m := obj.class.findMethod("__get"); m != nil && (!ok || !in.propAccessible(obj, name, scope)) {
		return in.callMethod(obj, m, []Value{name})
	}
	if ok && v != uninit {
		return deref(v)
	}
	return nil
}

func (in *Interp) getProp(obj *Object, name string) Value {
	v, ok := obj.props.Get(StrKey(name))
	if ok && v != uninit {
		return deref(v)
	}
	return nil
}

// getProp2 reads a property with full semantics (visibility, __get, warnings)
func (in *Interp) getProp2(obj *Object, name string, scope *Class) Value {
	v, ok := obj.props.Get(StrKey(name))
	if ok {
		if in.propAccessible(obj, name, scope) {
			if v == uninit {
				pi := obj.class.findProp(name)
				if pi != nil && pi.Decl != nil && pi.Decl.Hooks != nil {
					if g, ok := pi.Decl.Hooks["get"]; ok {
						return in.callHook(obj, pi, g, nil)
					}
				}
				if m := obj.class.findMethod("__get"); m != nil {
					return in.callMethod(obj, m, []Value{name})
				}
				in.throwError("Error", fmt.Sprintf("Typed property %s::$%s must not be accessed before initialization", pi.Class.Name, name))
			}
			pi := obj.class.findProp(name)
			if pi != nil && pi.Decl != nil && pi.Decl.Hooks != nil {
				if g, ok := pi.Decl.Hooks["get"]; ok {
					return in.callHook(obj, pi, g, nil)
				}
			}
			return deref(v)
		}
		if m := obj.class.findMethod("__get"); m != nil {
			return in.callMethod(obj, m, []Value{name})
		}
		pi := obj.class.findProp(name)
		in.throwError("Error", fmt.Sprintf("Cannot access %s property %s::$%s", pi.Visibility, obj.class.Name, name))
	}
	// hooks on virtual property
	if pi := obj.class.findProp(name); pi != nil && pi.Decl != nil && pi.Decl.Hooks != nil {
		if g, ok := pi.Decl.Hooks["get"]; ok {
			return in.callHook(obj, pi, g, nil)
		}
	}
	if m := obj.class.findMethod("__get"); m != nil {
		return in.callMethod(obj, m, []Value{name})
	}
	if obj.class.isEnum() {
		in.throwError("Error", fmt.Sprintf("Undefined property: %s::$%s", obj.class.Name, name))
	}
	in.warn(fmt.Sprintf("Undefined property: %s::$%s", obj.class.Name, name))
	return nil
}

func (in *Interp) callHook(obj *Object, pi *PropInfo, hook *FuncDecl, args []Value) Value {
	fn := &Function{Name: pi.Name, Decl: hook, Class: pi.Class}
	return in.callUserFunc(fn, args, obj, pi.Class, obj.class, nil, nil)
}

func (in *Interp) issetProp(obj *Object, name string, scope *Class) bool {
	v, ok := obj.props.Get(StrKey(name))
	if ok && v != uninit && in.propAccessible(obj, name, scope) {
		if pi := obj.class.findProp(name); pi != nil && pi.Decl != nil && pi.Decl.Hooks != nil {
			if g, ok := pi.Decl.Hooks["get"]; ok {
				return in.callHook(obj, pi, g, nil) != nil
			}
		}
		return deref(v) != nil
	}
	if pi := obj.class.findProp(name); pi != nil && pi.Decl != nil && pi.Decl.Hooks != nil && (!ok || v == uninit) {
		if g, ok := pi.Decl.Hooks["get"]; ok {
			return in.callHook(obj, pi, g, nil) != nil
		}
	}
	if m := obj.class.findMethod("__isset"); m != nil {
		if !toBool(in.callMethod(obj, m, []Value{name})) {
			return false
		}
		// PHP calls __get after __isset returns true to check for null
		if g := obj.class.findMethod("__get"); g != nil {
			return in.callMethod(obj, g, []Value{name}) != nil
		}
		return true
	}
	return false
}

func (in *Interp) checkPropWriteAccess(obj *Object, name string, scope *Class) {
	pi := obj.class.findProp(name)
	if pi == nil {
		return
	}
	if !in.propAccessible(obj, name, scope) {
		if m := obj.class.findMethod("__set"); m != nil {
			return
		}
		in.throwError("Error", fmt.Sprintf("Cannot modify %s property %s::$%s", pi.Visibility, obj.class.Name, name))
	}
}

func (in *Interp) setProp(obj *Object, name string, v Value, scope *Class) {
	pi := obj.class.findProp(name)
	cur, exists := obj.props.Get(StrKey(name))
	if pi != nil {
		if !in.propAccessible(obj, name, scope) {
			if m := obj.class.findMethod("__set"); m != nil {
				in.callMethod(obj, m, []Value{name, v})
				return
			}
			if pi.Readonly {
				in.throwError("Error", fmt.Sprintf("Cannot modify %s property %s::$%s", pi.Visibility, obj.class.Name, name))
			}
			in.throwError("Error", fmt.Sprintf("Cannot modify %s property %s::$%s", pi.Visibility, obj.class.Name, name))
		}
		if pi.Decl != nil && pi.Decl.Hooks != nil {
			if s, ok := pi.Decl.Hooks["set"]; ok {
				in.callHook(obj, pi, s, []Value{v})
				return
			}
			if _, ok := pi.Decl.Hooks["get"]; ok && !exists {
				in.throwError("Error", fmt.Sprintf("Property %s::$%s is read-only", obj.class.Name, name))
			}
		}
		if pi.Readonly {
			if exists && cur != uninit {
				in.throwError("Error", fmt.Sprintf("Cannot modify readonly property %s::$%s", obj.class.Name, name))
			}
			if scope != pi.Class {
				scopeName := "global scope"
				if scope != nil {
					scopeName = "scope " + scope.Name
				}
				in.throwError("Error", fmt.Sprintf("Cannot initialize readonly property %s::$%s from %s", obj.class.Name, name, scopeName))
			}
		}
		if pi.Type != nil {
			v = in.coercePropType(obj, pi, v)
		}
		if exists {
			if r, ok := cur.(*Ref); ok {
				r.set(v)
				return
			}
		}
		obj.props.Set(StrKey(name), v)
		return
	}
	if exists {
		obj.props.Set(StrKey(name), v)
		return
	}
	if m := obj.class.findMethod("__set"); m != nil {
		in.callMethod(obj, m, []Value{name, v})
		return
	}
	if obj.class.isEnum() {
		in.throwError("Error", fmt.Sprintf("Cannot create dynamic property %s::$%s", obj.class.Name, name))
	}
	if obj.class.Kind == "class" && obj.class.Readonly {
		in.throwError("Error", fmt.Sprintf("Cannot create dynamic property %s::$%s", obj.class.Name, name))
	}
	in.checkDynamicProp(obj, name)
	obj.props.Set(StrKey(name), v)
}

func (in *Interp) coercePropType(obj *Object, pi *PropInfo, v Value) Value {
	nv, ok := in.coerceType(pi.Type, v, pi.Class)
	if !ok {
		in.throwError("TypeError", fmt.Sprintf("Cannot assign %s to property %s::$%s of type %s", typeName(v), obj.class.Name, pi.Name, in.typeHintString(pi.Type)))
	}
	return nv
}

func (in *Interp) unsetProp(obj *Object, name string, scope *Class) {
	pi := obj.class.findProp(name)
	_, exists := obj.props.Get(StrKey(name))
	if pi != nil {
		if !in.propAccessible(obj, name, scope) {
			if m := obj.class.findMethod("__unset"); m != nil {
				in.callMethod(obj, m, []Value{name})
				return
			}
			in.throwError("Error", fmt.Sprintf("Cannot unset %s property %s::$%s", pi.Visibility, obj.class.Name, name))
		}
		if pi.Readonly {
			in.throwError("Error", fmt.Sprintf("Cannot unset readonly property %s::$%s", obj.class.Name, name))
		}
	}
	if !exists {
		if m := obj.class.findMethod("__unset"); m != nil {
			in.callMethod(obj, m, []Value{name})
		}
		return
	}
	obj.props.Delete(StrKey(name))
}

func (in *Interp) checkStaticPropAccess(cls *Class, pi *PropInfo, fr *Frame) {
	if pi == nil {
		return
	}
	switch pi.Visibility {
	case "private":
		if fr.class != pi.Class {
			in.throwError("Error", fmt.Sprintf("Cannot access private property %s::$%s", cls.Name, pi.Name))
		}
	case "protected":
		if fr.class == nil || !(fr.class.isSubclassOf(pi.Class) || pi.Class.isSubclassOf(fr.class)) {
			in.throwError("Error", fmt.Sprintf("Cannot access protected property %s::$%s", cls.Name, pi.Name))
		}
	}
}

// iterate over Traversable object or array
func (in *Interp) iterate(v Value, fn func(k, v Value) bool) {
	switch x := v.(type) {
	case *Array:
		x.Each(func(k Key, val Value) bool {
			return fn(k.Value(), deref(val))
		})
	case *Object:
		if g, ok := x.internal.(*Generator); ok {
			g.ensureStarted(in)
			for !g.finished {
				if !fn(g.curKey, g.curVal) {
					return
				}
				g.next(in)
			}
			return
		}
		if x.class.instanceOf("IteratorAggregate") {
			it := in.callMethodByName(x, "getIterator", nil)
			in.iterate(it, fn)
			return
		}
		if x.class.instanceOf("Iterator") {
			in.callMethodByName(x, "rewind", nil)
			for toBool(in.callMethodByName(x, "valid", nil)) {
				val := in.callMethodByName(x, "current", nil)
				k := in.callMethodByName(x, "key", nil)
				if !fn(k, val) {
					return
				}
				in.callMethodByName(x, "next", nil)
			}
			return
		}
		for _, kv := range in.visibleProps(x, nil) {
			if kv.v == uninit {
				continue
			}
			if !fn(kv.k, deref(kv.v)) {
				return
			}
		}
	}
}
