package main

import (
	"fmt"
	"strings"
)

// evalArgs evaluates call arguments for the given function (may be nil for unknown)
func (in *Interp) evalArgs(fr *Frame, fn *Function, args []Arg) ([]Value, map[string]Value) {
	var vals []Value
	var named map[string]Value
	for i, a := range args {
		if a.Spread {
			v := in.eval(fr, a.Expr)
			switch s := v.(type) {
			case *Array:
				s.Each(func(k Key, val Value) bool {
					if k.IsStr {
						if named == nil {
							named = map[string]Value{}
						}
						named[k.S] = deref(val)
					} else {
						if named != nil {
							in.throwError("Error", "Cannot use positional argument after named argument during unpacking")
						}
						vals = append(vals, deref(val))
					}
					return true
				})
			case *Object:
				in.iterate(s, func(k, val Value) bool {
					if ks, ok := k.(string); ok {
						if named == nil {
							named = map[string]Value{}
						}
						named[ks] = val
					} else {
						vals = append(vals, val)
					}
					return true
				})
			case nil:
				in.throwError("Error", "Only arrays and Traversables can be unpacked")
			default:
				in.throwError("Error", "Only arrays and Traversables can be unpacked")
			}
			continue
		}
		if a.Name != "" {
			if named == nil {
				named = map[string]Value{}
			}
			if _, dup := named[a.Name]; dup {
				in.throwError("Error", fmt.Sprintf("Named parameter $%s overwrites previous argument", a.Name))
			}
			// by-ref named param?
			if fn != nil {
				idx := in.paramIndex(fn, a.Name)
				if idx >= 0 && fn.isRefParam(idx) && isLvalue(a.Expr) {
					named[a.Name] = in.getRef(fr, a.Expr)
					continue
				}
			}
			named[a.Name] = in.eval(fr, a.Expr)
			continue
		}
		if named != nil {
			in.throwError("Error", "Cannot use positional argument after named argument")
		}
		idx := len(vals)
		_ = i
		if fn != nil && fn.isRefParam(idx) {
			if isLvalue(a.Expr) {
				vals = append(vals, in.getRef(fr, a.Expr))
			} else {
				v := in.eval(fr, a.Expr)
				if r, ok := v.(*Ref); ok {
					vals = append(vals, r)
				} else {
					if fn.Decl != nil {
						in.throwError("Error", fmt.Sprintf("%s(): Argument #%d%s could not be passed by reference", fn.Name, idx+1, in.paramNameFor(fn, idx)))
					}
					// natives: allow temporaries (PHP gives notice "Only variables should be passed by reference")
					if _, isCall := a.Expr.(*CallExpr); isCall {
						in.notice("Only variables should be passed by reference")
					} else if _, isCall := a.Expr.(*MethodCallExpr); isCall {
						in.notice("Only variables should be passed by reference")
					} else if _, isCall := a.Expr.(*StaticCallExpr); isCall {
						in.notice("Only variables should be passed by reference")
					} else {
						in.throwError("Error", fmt.Sprintf("%s(): Argument #%d%s could not be passed by reference", fn.Name, idx+1, in.paramNameFor(fn, idx)))
					}
					r := &Ref{rc: 1}
					r.set(v)
					vals = append(vals, r)
				}
			}
			continue
		}
		v := in.eval(fr, a.Expr)
		if r, ok := v.(*Ref); ok {
			v = r.V
		}
		vals = append(vals, v)
	}
	return vals, named
}

func (in *Interp) paramNameFor(fn *Function, idx int) string {
	if fn.Decl != nil && idx < len(fn.Decl.Params) {
		return " ($" + fn.Decl.Params[idx].Name + ")"
	}
	if idx < len(fn.ParamNames) {
		return " ($" + fn.ParamNames[idx] + ")"
	}
	return ""
}

func (in *Interp) paramIndex(fn *Function, name string) int {
	if fn.Decl != nil {
		for i, p := range fn.Decl.Params {
			if p.Name == name {
				return i
			}
		}
		return -1
	}
	for i, n := range fn.ParamNames {
		if n == name {
			return i
		}
	}
	return -1
}

// mergeNamed merges named args into positional according to fn's params
func (in *Interp) mergeNamed(fn *Function, vals []Value, named map[string]Value) []Value {
	if named == nil {
		return vals
	}
	var paramNames []string
	var variadicName string
	if fn.Decl != nil {
		for _, p := range fn.Decl.Params {
			if p.Variadic {
				variadicName = p.Name
				continue
			}
			paramNames = append(paramNames, p.Name)
		}
	} else {
		paramNames = fn.ParamNames
	}
	if paramNames == nil && variadicName == "" {
		// unknown parameter names: just append
		for _, v := range named {
			vals = append(vals, v)
		}
		return vals
	}
	result := make([]Value, len(vals), len(paramNames))
	copy(result, vals)
	used := map[string]bool{}
	for i, pn := range paramNames {
		if v, ok := named[pn]; ok {
			if i < len(vals) {
				in.throwError("Error", fmt.Sprintf("Named parameter $%s overwrites previous argument", pn))
			}
			for len(result) < i {
				result = append(result, missingArg{})
			}
			if len(result) == i {
				result = append(result, v)
			} else {
				result[i] = v
			}
			used[pn] = true
		}
	}
	for n, v := range named {
		if !used[n] {
			if variadicName != "" {
				// collected into variadic as string key
				result = append(result, namedExtra{name: n, v: v})
				continue
			}
			in.throwError("Error", fmt.Sprintf("Unknown named parameter $%s", n))
		}
	}
	return result
}

type missingArg struct{}
type namedExtra struct {
	name string
	v    Value
}

// ---------- calls ----------

func (in *Interp) evalCall(fr *Frame, x *CallExpr) Value {
	switch f := x.Fn.(type) {
	case *NameExpr:
		lname := strings.ToLower(f.Name)
		fn := in.functions[lname]
		if fn == nil && f.Alt != "" {
			fn = in.functions[strings.ToLower(f.Alt)]
			if fn != nil {
				lname = strings.ToLower(f.Alt)
			}
		}
		if fn == nil {
			// special compile-time-ish functions
			switch lname {
			case "compact", "extract", "get_defined_vars", "func_get_args", "func_num_args", "func_get_arg", "array_multisort":
			}
			name := f.Name
			if f.Alt != "" {
				name = f.Alt
			}
			in.throwError("Error", fmt.Sprintf("Call to undefined function %s()", name))
		}
		if x.IsCallableSyntax {
			return in.closureFromFunction(fn, nil, nil)
		}
		if fn.NativeCtx != nil {
			args, named := in.evalArgs(fr, fn, x.Args)
			args = in.mergeNamed(fn, args, named)
			return fn.NativeCtx(in, fr, args)
		}
		args, named := in.evalArgs(fr, fn, x.Args)
		if named != nil {
			args = in.mergeNamed(fn, args, named)
		}
		return in.callFunction(fn, args, nil, nil, nil, nil, fr, x.Line)
	default:
		callee := in.eval(fr, x.Fn)
		if x.IsCallableSyntax {
			return in.makeClosureFromCallable(callee, fr)
		}
		return in.callValueArgs(fr, callee, x.Args, x.Line)
	}
}

// callValueArgs calls a callable value with unevaluated args
func (in *Interp) callValueArgs(fr *Frame, callee Value, argExprs []Arg, line int) Value {
	fn, this, cls, static, closure := in.resolveCallable(callee, fr, true)
	if fn == nil {
		return nil
	}
	args, named := in.evalArgs(fr, fn, argExprs)
	if named != nil {
		args = in.mergeNamed(fn, args, named)
	}
	return in.callFunction(fn, args, this, cls, static, closure, fr, line)
}

// callValue calls a callable with already-evaluated args
func (in *Interp) callValue(callee Value, args []Value) Value {
	fr := in.frame
	fn, this, cls, static, closure := in.resolveCallable(callee, fr, true)
	if fn == nil {
		return nil
	}
	line := 0
	if fr != nil {
		line = fr.line
	}
	return in.callFunction(fn, args, this, cls, static, closure, fr, line)
}

// resolveCallable resolves a callable value. If throw, raises Error when not callable.
func (in *Interp) resolveCallable(callee Value, fr *Frame, throw bool) (*Function, *Object, *Class, *Class, *Closure) {
	callee = deref(callee)
	switch c := callee.(type) {
	case string:
		if idx := strings.Index(c, "::"); idx > 0 {
			clsName := c[:idx]
			mname := c[idx+2:]
			cls := in.resolveClassName(clsName, fr)
			if cls == nil {
				if throw {
					in.throwError("Error", fmt.Sprintf("Class \"%s\" not found", clsName))
				}
				return nil, nil, nil, nil, nil
			}
			m := cls.findMethod(strings.ToLower(mname))
			if m == nil {
				if throw {
					in.throwError("Error", fmt.Sprintf("Call to undefined method %s::%s()", cls.Name, mname))
				}
				return nil, nil, nil, nil, nil
			}
			var this *Object
			if !m.Static && fr != nil && fr.this != nil && fr.this.class.isSubclassOf(cls) {
				this = fr.this
			} else if !m.Static {
				if throw {
					in.throwError("Error", fmt.Sprintf("Non-static method %s::%s() cannot be called statically", cls.Name, m.Name))
				}
				return nil, nil, nil, nil, nil
			}
			return m.Fn, this, m.Class, cls, nil
		}
		fn := in.functions[strings.ToLower(strings.TrimPrefix(c, "\\"))]
		if fn == nil {
			if throw {
				in.throwError("Error", fmt.Sprintf("Call to undefined function %s()", c))
			}
			return nil, nil, nil, nil, nil
		}
		return fn, nil, nil, nil, nil
	case *Array:
		if c.Len() != 2 {
			if throw {
				in.throwError("Error", "Array callback must have exactly two elements")
			}
			return nil, nil, nil, nil, nil
		}
		first, ok1 := c.Get(IntKey(0))
		second, ok2 := c.Get(IntKey(1))
		if !ok1 || !ok2 {
			if throw {
				in.throwError("Error", "Array callback must have exactly two elements")
			}
			return nil, nil, nil, nil, nil
		}
		first = deref(first)
		mname, ok := deref(second).(string)
		if !ok {
			if throw {
				in.throwError("Error", "Array callback must have exactly two elements")
			}
			return nil, nil, nil, nil, nil
		}
		switch obj := first.(type) {
		case *Object:
			if strings.HasPrefix(mname, "parent::") {
				mname = mname[8:]
				m := obj.class.Parent.findMethod(strings.ToLower(mname))
				if m != nil {
					return m.Fn, obj, m.Class, obj.class, nil
				}
			}
			m := obj.class.findMethod(strings.ToLower(mname))
			if m == nil {
				if cl, ok := obj.internal.(*Closure); ok && strings.ToLower(mname) == "__invoke" {
					return cl.fn, cl.this, cl.scope, cl.static, cl
				}
				if cm := obj.class.findMethod("__call"); cm != nil {
					return in.magicCallFunction(obj, cm, mname), obj, cm.Class, obj.class, nil
				}
				if throw {
					in.throwError("Error", fmt.Sprintf("Call to undefined method %s::%s()", obj.class.Name, mname))
				}
				return nil, nil, nil, nil, nil
			}
			if m.Static {
				return m.Fn, nil, m.Class, obj.class, nil
			}
			return m.Fn, obj, m.Class, obj.class, nil
		case string:
			cls := in.resolveClassName(obj, fr)
			if cls == nil {
				if throw {
					in.throwError("Error", fmt.Sprintf("Class \"%s\" not found", obj))
				}
				return nil, nil, nil, nil, nil
			}
			if strings.HasPrefix(mname, "parent::") {
				mname = mname[8:]
				cls = cls.Parent
			}
			m := cls.findMethod(strings.ToLower(mname))
			if m == nil {
				if cm := cls.findMethod("__callstatic"); cm != nil {
					return in.magicCallStaticFunction(cls, cm, mname), nil, cm.Class, cls, nil
				}
				if throw {
					in.throwError("Error", fmt.Sprintf("Call to undefined method %s::%s()", cls.Name, mname))
				}
				return nil, nil, nil, nil, nil
			}
			var this *Object
			if !m.Static {
				if fr != nil && fr.this != nil && fr.this.class.isSubclassOf(cls) {
					this = fr.this
				} else {
					if throw {
						in.throwError("Error", fmt.Sprintf("Non-static method %s::%s() cannot be called statically", cls.Name, m.Name))
					}
					return nil, nil, nil, nil, nil
				}
			}
			return m.Fn, this, m.Class, cls, nil
		}
		if throw {
			in.throwError("Error", "Array callback must have exactly two elements")
		}
		return nil, nil, nil, nil, nil
	case *Object:
		if cl, ok := c.internal.(*Closure); ok {
			if cl.callable != nil {
				return in.resolveCallable(cl.callable, fr, throw)
			}
			return cl.fn, cl.this, cl.scope, cl.static, cl
		}
		if m := c.class.findMethod("__invoke"); m != nil {
			return m.Fn, c, m.Class, c.class, nil
		}
		if throw {
			in.throwError("Error", "Object of type "+c.class.Name+" is not callable")
		}
		return nil, nil, nil, nil, nil
	}
	if throw {
		in.throwError("Error", "Value not callable")
	}
	return nil, nil, nil, nil, nil
}

func (in *Interp) resolveClassName(name string, fr *Frame) *Class {
	switch strings.ToLower(name) {
	case "self":
		if fr != nil {
			return fr.class
		}
	case "static":
		if fr != nil {
			return fr.staticClass
		}
	case "parent":
		if fr != nil && fr.class != nil {
			return fr.class.Parent
		}
	}
	return in.lookupClass(name)
}

func (in *Interp) isCallable(v Value, fr *Frame) bool {
	v = deref(v)
	switch c := v.(type) {
	case string:
		if idx := strings.Index(c, "::"); idx > 0 {
			cls := in.lookupClass(c[:idx])
			if cls == nil {
				return false
			}
			return cls.findMethod(strings.ToLower(c[idx+2:])) != nil
		}
		return in.functions[strings.ToLower(strings.TrimPrefix(c, "\\"))] != nil
	case *Array:
		if c.Len() != 2 {
			return false
		}
		first, _ := c.Get(IntKey(0))
		second, _ := c.Get(IntKey(1))
		mname, ok := deref(second).(string)
		if !ok {
			return false
		}
		switch obj := deref(first).(type) {
		case *Object:
			if obj.class.findMethod(strings.ToLower(mname)) != nil {
				return true
			}
			return obj.class.findMethod("__call") != nil
		case string:
			cls := in.lookupClass(obj)
			if cls == nil {
				return false
			}
			if m := cls.findMethod(strings.ToLower(mname)); m != nil {
				return true
			}
			return cls.findMethod("__callstatic") != nil
		}
		return false
	case *Object:
		if _, ok := c.internal.(*Closure); ok {
			return true
		}
		return c.class.findMethod("__invoke") != nil
	}
	return false
}

// magicCallFunction wraps __call for a given method name
func (in *Interp) magicCallFunction(obj *Object, cm *Method, mname string) *Function {
	return &Function{Name: mname, Native: func(in *Interp, args []Value) Value {
		arr := NewArray()
		for _, a := range args {
			arr.Append(deref(a))
		}
		return in.callMethod(obj, cm, []Value{mname, arr})
	}, MaxArgs: -1}
}

func (in *Interp) magicCallStaticFunction(cls *Class, cm *Method, mname string) *Function {
	return &Function{Name: mname, Native: func(in *Interp, args []Value) Value {
		arr := NewArray()
		for _, a := range args {
			arr.Append(deref(a))
		}
		return in.callStaticMethod(cls, cm, []Value{mname, arr}, cls)
	}, MaxArgs: -1}
}

func (in *Interp) evalMethodCall(fr *Frame, x *MethodCallExpr) Value {
	objv := in.eval(fr, x.Obj)
	if objv == nil && x.NullSafe {
		return nil
	}
	var mname string
	var nameVal Value
	if s, ok := x.Name.(*StringLit); ok {
		mname = s.V
	} else {
		nameVal = in.eval(fr, x.Name)
		if s, ok := nameVal.(string); ok {
			mname = s
		} else {
			// $obj->$closure() ... PHP requires string method name
			in.throwError("Error", "Method name must be a string")
		}
	}
	obj, ok := objv.(*Object)
	if !ok {
		fr.line = x.Line
		in.throwError("Error", fmt.Sprintf("Call to a member function %s() on %s", mname, typeName(objv)))
	}
	lname := strings.ToLower(mname)
	m := obj.class.findMethod(lname)
	if m == nil {
		// Closure object special methods
		if cl, ok := obj.internal.(*Closure); ok {
			switch lname {
			case "__invoke":
				if x.IsCallableSyntax {
					return obj
				}
				return in.callValueArgs(fr, obj, x.Args, x.Line)
			case "call":
				args, _ := in.evalArgs(fr, nil, x.Args)
				if len(args) == 0 {
					in.throwError("ArgumentCountError", "Closure::call() expects at least 1 argument, 0 given")
				}
				newThis, _ := args[0].(*Object)
				var scope *Class
				if newThis != nil {
					scope = newThis.class
				}
				return in.callFunction(cl.fn, args[1:], newThis, scope, scope, &Closure{fn: cl.fn, bound: cl.bound, this: newThis, scope: scope, static: scope}, fr, x.Line)
			case "bindto":
				args, _ := in.evalArgs(fr, nil, x.Args)
				return in.closureBind(obj, args)
			case "bind":
				args, _ := in.evalArgs(fr, nil, x.Args)
				return in.closureBind(obj, args)
			}
		}
		if cm := obj.class.findMethod("__call"); cm != nil {
			if x.IsCallableSyntax {
				return in.closureFromFunction(in.magicCallFunction(obj, cm, mname), obj, obj.class)
			}
			args, _ := in.evalArgs(fr, nil, x.Args)
			arr := NewArray()
			for _, a := range args {
				arr.Append(deref(a))
			}
			return in.callMethod(obj, cm, []Value{mname, arr})
		}
		fr.line = x.Line
		in.throwError("Error", fmt.Sprintf("Call to undefined method %s::%s()", obj.class.Name, mname))
	}
	// visibility
	if m.Visibility != "public" && !in.methodAccessible(m, fr.class) {
		if cm := obj.class.findMethod("__call"); cm != nil {
			args, _ := in.evalArgs(fr, nil, x.Args)
			arr := NewArray()
			for _, a := range args {
				arr.Append(deref(a))
			}
			return in.callMethod(obj, cm, []Value{mname, arr})
		}
		fr.line = x.Line
		scope := "global scope"
		if fr.class != nil {
			scope = "scope " + fr.class.Name
		}
		in.throwError("Error", fmt.Sprintf("Call to %s method %s::%s() from %s", m.Visibility, obj.class.Name, m.Name, scope))
	}
	if x.IsCallableSyntax {
		if m.Static {
			return in.closureFromMethod(m, nil, obj.class)
		}
		return in.closureFromMethod(m, obj, obj.class)
	}
	args, named := in.evalArgs(fr, m.Fn, x.Args)
	if named != nil {
		args = in.mergeNamed(m.Fn, args, named)
	}
	if m.Static {
		return in.callFunction(m.Fn, args, nil, m.Class, obj.class, nil, fr, x.Line)
	}
	return in.callFunction(m.Fn, args, obj, m.Class, obj.class, nil, fr, x.Line)
}

func (in *Interp) methodAccessible(m *Method, scope *Class) bool {
	switch m.Visibility {
	case "public":
		return true
	case "protected":
		if scope == nil {
			return false
		}
		return scope.isSubclassOf(m.Class) || m.Class.isSubclassOf(scope) || (m.ProtoClass != nil && (scope.isSubclassOf(m.ProtoClass) || m.ProtoClass.isSubclassOf(scope)))
	case "private":
		return scope == m.Class
	}
	return true
}

func (in *Interp) evalStaticCall(fr *Frame, x *StaticCallExpr) Value {
	var cls *Class
	isParentOrSelf := false
	forwardStatic := false
	if n, ok := x.Class.(*NameExpr); ok {
		switch n.Name {
		case "parent", "self", "static":
			isParentOrSelf = true
			forwardStatic = true
		}
	}
	cls = in.resolveClassRef(fr, x.Class)
	var mname string
	if s, ok := x.Name.(*StringLit); ok {
		mname = s.V
	} else {
		nv := in.eval(fr, x.Name)
		s, ok := nv.(string)
		if !ok {
			in.throwError("Error", "Method name must be a string")
		}
		mname = s
	}
	lname := strings.ToLower(mname)
	m := cls.findMethod(lname)
	if m == nil {
		// closure static call? e.g. Closure::fromCallable
		if fr.this != nil && fr.this.class.isSubclassOf(cls) {
			if cm := cls.findMethod("__call"); cm != nil && isParentOrSelf {
				args, _ := in.evalArgs(fr, nil, x.Args)
				arr := NewArray()
				for _, a := range args {
					arr.Append(deref(a))
				}
				return in.callMethod(fr.this, cm, []Value{mname, arr})
			}
		}
		if cm := cls.findMethod("__callstatic"); cm != nil {
			if x.IsCallableSyntax {
				return in.closureFromFunction(in.magicCallStaticFunction(cls, cm, mname), nil, cls)
			}
			args, _ := in.evalArgs(fr, nil, x.Args)
			arr := NewArray()
			for _, a := range args {
				arr.Append(deref(a))
			}
			return in.callStaticMethod(cls, cm, []Value{mname, arr}, cls)
		}
		in.throwError("Error", fmt.Sprintf("Call to undefined method %s::%s()", cls.Name, mname))
	}
	if m.Visibility != "public" && !in.methodAccessible(m, fr.class) {
		scope := "global scope"
		if fr.class != nil {
			scope = "scope " + fr.class.Name
		}
		in.throwError("Error", fmt.Sprintf("Call to %s method %s::%s() from %s", m.Visibility, cls.Name, m.Name, scope))
	}
	if m.Abstract {
		in.throwError("Error", fmt.Sprintf("Cannot call abstract method %s::%s()", m.Class.Name, m.Name))
	}
	var this *Object
	staticCls := cls
	if !m.Static {
		if fr.this != nil && fr.this.class.isSubclassOf(cls) {
			this = fr.this
			staticCls = fr.this.class
		} else {
			in.throwError("Error", fmt.Sprintf("Non-static method %s::%s() cannot be called statically", cls.Name, m.Name))
		}
	} else if forwardStatic && fr.staticClass != nil {
		staticCls = fr.staticClass
	}
	if x.IsCallableSyntax {
		return in.closureFromMethod(m, this, staticCls)
	}
	args, named := in.evalArgs(fr, m.Fn, x.Args)
	if named != nil {
		args = in.mergeNamed(m.Fn, args, named)
	}
	return in.callFunction(m.Fn, args, this, m.Class, staticCls, nil, fr, x.Line)
}

// callMethod invokes a method on an object with evaluated args
func (in *Interp) callMethod(obj *Object, m *Method, args []Value) Value {
	line := 0
	if in.frame != nil {
		line = in.frame.line
	}
	if m.Static {
		return in.callFunction(m.Fn, args, nil, m.Class, obj.class, nil, in.frame, line)
	}
	return in.callFunction(m.Fn, args, obj, m.Class, obj.class, nil, in.frame, line)
}

func (in *Interp) callStaticMethod(cls *Class, m *Method, args []Value, staticCls *Class) Value {
	line := 0
	if in.frame != nil {
		line = in.frame.line
	}
	return in.callFunction(m.Fn, args, nil, m.Class, staticCls, nil, in.frame, line)
}

func (in *Interp) callMethodByName(obj *Object, name string, args []Value) Value {
	m := obj.class.findMethod(strings.ToLower(name))
	if m == nil {
		if cm := obj.class.findMethod("__call"); cm != nil {
			arr := NewArray()
			for _, a := range args {
				arr.Append(deref(a))
			}
			return in.callMethod(obj, cm, []Value{name, arr})
		}
		in.throwError("Error", fmt.Sprintf("Call to undefined method %s::%s()", obj.class.Name, name))
	}
	return in.callMethod(obj, m, args)
}

// callFunction is the central call dispatcher
func (in *Interp) callFunction(fn *Function, args []Value, this *Object, cls *Class, staticCls *Class, closure *Closure, caller *Frame, line int) Value {
	if fn.Native != nil || fn.NativeCtx != nil {
		return in.callNative(fn, args, this, cls, staticCls, caller, line)
	}
	return in.callUserFunc(fn, args, this, cls, staticCls, closure, caller)
}

func (in *Interp) callNative(fn *Function, args []Value, this *Object, cls *Class, staticCls *Class, caller *Frame, line int) Value {
	// arg count checks
	n := 0
	for _, a := range args {
		if _, ok := a.(missingArg); !ok {
			n++
		}
	}
	if fn.MinArgs > 0 && len(args) < fn.MinArgs {
		name := fn.Name
		if fn.Class != nil {
			name = fn.Class.Name + "::" + fn.Name
		}
		if fn.MaxArgs == fn.MinArgs {
			in.throwError("ArgumentCountError", fmt.Sprintf("%s() expects exactly %d argument%s, %d given", name, fn.MinArgs, plural(fn.MinArgs), len(args)))
		}
		in.throwError("ArgumentCountError", fmt.Sprintf("%s() expects at least %d argument%s, %d given", name, fn.MinArgs, plural(fn.MinArgs), len(args)))
	}
	if fn.MaxArgs >= 0 && len(args) > fn.MaxArgs {
		name := fn.Name
		if fn.Class != nil {
			name = fn.Class.Name + "::" + fn.Name
		}
		if fn.MaxArgs == fn.MinArgs {
			in.throwError("ArgumentCountError", fmt.Sprintf("%s() expects exactly %d argument%s, %d given", name, fn.MaxArgs, plural(fn.MaxArgs), len(args)))
		}
		in.throwError("ArgumentCountError", fmt.Sprintf("%s() expects at most %d argument%s, %d given", name, fn.MaxArgs, plural(fn.MaxArgs), len(args)))
	}
	// deref non-ref args
	for i := range args {
		if !fn.isRefParam(i) {
			if r, ok := args[i].(*Ref); ok {
				args[i] = r.V
			}
		}
	}
	fr := &Frame{vars: nil, this: this, class: cls, staticClass: staticCls, fn: fn, args: args, caller: caller, callLine: line, depth: in.depth + 1, funcName: fn.Name}
	if caller != nil {
		fr.file = caller.file
		fr.line = caller.line
	}
	if fn.Class != nil {
		fr.callClass = fn.Class.Name
		if this != nil {
			fr.callType = "->"
		} else {
			fr.callType = "::"
		}
	}
	prev := in.frame
	in.frame = fr
	in.traceStack = append(in.traceStack, fr)
	defer func() {
		in.frame = prev
		in.traceStack = in.traceStack[:len(in.traceStack)-1]
	}()
	if fn.NativeCtx != nil {
		return fn.NativeCtx(in, caller, args)
	}
	return fn.Native(in, args)
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

func (in *Interp) funcDisplayName(fn *Function, cls *Class) string {
	if fn.Decl != nil && fn.Decl.Name == "{closure}" {
		return "{closure}"
	}
	if cls != nil && fn.Method != nil {
		return cls.Name + "::" + fn.Name
	}
	if fn.Class != nil {
		return fn.Class.Name + "::" + fn.Name
	}
	return fn.Name
}

// callUserFunc executes a user-defined function
func (in *Interp) callUserFunc(fn *Function, args []Value, this *Object, cls *Class, staticCls *Class, closure *Closure, caller *Frame) Value {
	decl := fn.Decl
	if decl.Abstract || !decl.HasBody {
		in.throwError("Error", fmt.Sprintf("Cannot call abstract method %s::%s()", cls.Name, fn.Name))
	}
	fr := &Frame{vars: make(map[string]*Ref, len(decl.Params)+4), this: this, class: cls, staticClass: staticCls, fn: fn, args: args, caller: caller, file: decl.File, line: decl.Line, closure: closure, depth: in.depth + 1, namespace: decl.Namespace}
	if caller != nil {
		fr.callLine = caller.line
	}
	fr.funcName = fn.Name
	if closure != nil {
		fr.funcName = in.closureName(fn, closure)
	}
	if fn.Method != nil || cls != nil {
		if fn.Method != nil {
			fr.callClass = fn.Method.Class.Name
		} else if cls != nil {
			fr.callClass = cls.Name
		}
		if this != nil {
			fr.callType = "->"
		} else {
			fr.callType = "::"
		}
	}
	if closure != nil {
		fr.callClass = ""
		fr.callType = ""
	}
	if staticCls == nil && this != nil {
		fr.staticClass = this.class
	}
	// bind closure vars
	if closure != nil {
		for _, name := range closure.boundOrder {
			r := closure.bound[name]
			if closure.byRef != nil && closure.byRef[name] {
				r.rc++
				fr.vars[name] = r
			} else {
				nr := &Ref{rc: 1}
				nr.set(r.V)
				fr.vars[name] = nr
			}
		}
	}
	// bind params
	in.bindParams(fr, fn, args, caller)
	if decl.IsGenerator {
		return in.newGenerator(fr, fn)
	}
	prev := in.frame
	in.frame = fr
	in.depth++
	in.traceStack = append(in.traceStack, fr)
	defer func() {
		in.depth--
		in.frame = prev
		in.traceStack = in.traceStack[:len(in.traceStack)-1]
		// release locals
		for _, r := range fr.vars {
			r.release()
		}
		in.retagCandidates(in.depth)
	}()
	c := in.execStmts(fr, decl.Body)
	var ret Value
	if c == cReturn {
		ret = fr.retVal
	}
	if decl.ReturnType != nil {
		ret = in.coerceReturn(fn, fr, ret, c == cReturn)
	}
	if decl.ByRefReturn {
		return ret
	}
	if r, ok := ret.(*Ref); ok {
		return r.V
	}
	return ret
}

func (in *Interp) closureName(fn *Function, cl *Closure) string {
	decl := fn.Decl
	if cl.fromCallableName != "" {
		return cl.fromCallableName
	}
	if decl == nil {
		return "{closure}"
	}
	return "{closure:" + in.closureLocation(decl, cl) + "}"
}

func (in *Interp) closureLocation(decl *FuncDecl, cl *Closure) string {
	if cl.parentFunc != "" {
		return fmt.Sprintf("%s:%d", cl.parentFunc, decl.Line)
	}
	return fmt.Sprintf("%s:%d", decl.File, decl.Line)
}

// bindParams binds arguments to parameters in the new frame
func (in *Interp) bindParams(fr *Frame, fn *Function, args []Value, caller *Frame) {
	decl := fn.Decl
	params := decl.Params
	nargs := len(args)
	// count real args
	for i, p := range params {
		if p.Variadic {
			arr := NewArray()
			for j := i; j < nargs; j++ {
				a := args[j]
				if ne, ok := a.(namedExtra); ok {
					arr.SetStr(ne.name, in.coerceParamValue(fn, p, i, ne.v, caller))
					continue
				}
				if _, ok := a.(missingArg); ok {
					continue
				}
				if p.ByRef {
					if r, ok := a.(*Ref); ok {
						r.rc++
						arr.Append(r)
						continue
					}
				}
				arr.Append(in.coerceParamValue(fn, p, j, deref(a), caller))
			}
			r := &Ref{rc: 1}
			r.set(arr)
			fr.vars[p.Name] = r
			break
		}
		if i < nargs {
			a := args[i]
			if _, missing := a.(missingArg); !missing {
				if p.ByRef {
					if r, ok := a.(*Ref); ok {
						r.rc++
						fr.vars[p.Name] = r
						if p.Type != nil && r.V != nil {
							r.V = in.coerceParamValue(fn, p, i, r.V, caller)
						}
						continue
					}
					r := &Ref{rc: 1}
					r.set(in.coerceParamValue(fn, p, i, a, caller))
					fr.vars[p.Name] = r
					continue
				}
				v := deref(a)
				v = in.coerceParamValue(fn, p, i, v, caller)
				r := &Ref{rc: 1}
				r.set(v)
				fr.vars[p.Name] = r
				continue
			}
		}
		// missing: default or error
		if p.Default != nil {
			prev := in.frame
			in.frame = fr
			v := in.eval(fr, p.Default)
			in.frame = prev
			r := &Ref{rc: 1}
			r.set(v)
			fr.vars[p.Name] = r
			continue
		}
		// count required
		required := 0
		for _, q := range params {
			if q.Default == nil && !q.Variadic {
				required++
			}
		}
		name := in.funcDisplayName(fn, fr.class)
		if fr.closure != nil {
			name = fr.funcName
		} else if fn.Method != nil {
			name = fn.Method.Class.Name + "::" + fn.Name
		}
		passed := 0
		for _, a := range args {
			if _, ok := a.(missingArg); !ok {
				passed++
			}
		}
		exactly := "exactly"
		hasOptional := false
		for _, q := range params {
			if q.Default != nil || q.Variadic {
				hasOptional = true
			}
		}
		if hasOptional {
			exactly = "at least"
		}
		callerInfo := ""
		if caller != nil && caller.file != "" {
			callerInfo = fmt.Sprintf(" in %s on line %d", caller.file, caller.line)
		}
		if fn.Decl.Name == "{closure}" || fr.closure != nil {
			in.throwError("ArgumentCountError", fmt.Sprintf("Too few arguments to function %s(), %d passed%s and %s %d expected", name, passed, callerInfo, exactly, required))
		}
		in.throwError("ArgumentCountError", fmt.Sprintf("Too few arguments to function %s(), %d passed%s and %s %d expected", name, passed, callerInfo, exactly, required))
	}
	// promoted ctor params
	if fr.this != nil {
		for i, p := range params {
			if p.Promote != "" {
				r := fr.vars[p.Name]
				var v Value
				if r != nil {
					v = r.V
				}
				_ = i
				fr.this.props.Set(StrKey(p.Name), v)
			}
		}
	}
}

func (in *Interp) coerceParamValue(fn *Function, p *Param, idx int, v Value, caller *Frame) Value {
	if p.Type == nil {
		return v
	}
	nv, ok := in.coerceType(p.Type, v, fn.Class)
	if ok {
		return nv
	}
	if v == nil && p.Default != nil {
		if _, isNull := p.Default.(*NullLit); isNull {
			return nil
		}
	}
	name := in.funcDisplayName(fn, fn.Class)
	if fn.Method != nil {
		name = fn.Method.Class.Name + "::" + fn.Name
	}
	callerInfo := ""
	if caller != nil && caller.file != "" {
		callerInfo = fmt.Sprintf(", called in %s on line %d", caller.file, caller.line)
	}
	in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d ($%s) must be of type %s, %s given%s", name, idx+1, p.Name, in.typeHintString(p.Type), typeNameForError(v), callerInfo))
	return nil
}

func typeNameForError(v Value) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case *Object:
		return x.class.Name
	}
	return typeName(v)
}

func (in *Interp) coerceReturn(fn *Function, fr *Frame, ret Value, hadReturn bool) Value {
	th := fn.Decl.ReturnType
	if len(th.Names) == 1 {
		switch th.Names[0] {
		case "void":
			return nil
		case "never":
			in.throwError("TypeError", fmt.Sprintf("%s(): never-returning function must not implicitly return", in.funcDisplayName(fn, fr.class)))
		case "static":
			if o, ok := ret.(*Object); ok && fr.staticClass != nil && o.class.isSubclassOf(fr.staticClass) {
				return ret
			}
		case "self":
			if o, ok := ret.(*Object); ok && fr.class != nil && o.class.isSubclassOf(fr.class) {
				return ret
			}
		}
	}
	if fn.Decl.IsGenerator {
		return ret
	}
	if r, ok := ret.(*Ref); ok {
		ret = r.V
	}
	nv, ok := in.coerceType(th, ret, fr.class)
	if ok {
		return nv
	}
	name := in.funcDisplayName(fn, fr.class)
	if fn.Method != nil {
		name = fn.Method.Class.Name + "::" + fn.Name
	} else if fr.closure != nil {
		name = fr.funcName
	}
	if !hadReturn && ret == nil {
		in.throwError("TypeError", fmt.Sprintf("%s(): Return value must be of type %s, none returned", name, in.typeHintString(th)))
	}
	in.throwError("TypeError", fmt.Sprintf("%s(): Return value must be of type %s, %s returned", name, in.typeHintString(th), typeNameForError(ret)))
	return nil
}

func (in *Interp) typeHintString(th *TypeHint) string {
	var parts []string
	hasNull := false
	for _, n := range th.Names {
		if n == "null" {
			hasNull = true
			continue
		}
		parts = append(parts, in.displayTypeName(n))
	}
	if th.Nullable && !hasNull && len(parts) == 1 {
		return "?" + parts[0]
	}
	if hasNull || (th.Nullable && len(parts) > 1) {
		parts = append(parts, "null")
	}
	sep := "|"
	if th.Intersection {
		sep = "&"
	}
	return strings.Join(parts, sep)
}

func (in *Interp) displayTypeName(n string) string {
	switch n {
	case "int", "float", "string", "bool", "array", "callable", "iterable", "object", "mixed", "void", "null", "never", "false", "true", "self", "static", "parent":
		return n
	}
	if c := in.classes[strings.ToLower(n)]; c != nil {
		return c.Name
	}
	return n
}

// coerceType checks/coerces v against a type hint (non-strict mode). Returns (value, ok)
func (in *Interp) coerceType(th *TypeHint, v Value, selfCls *Class) (Value, bool) {
	if v == nil {
		if th.Nullable {
			return nil, true
		}
		for _, n := range th.Names {
			if n == "mixed" || n == "null" {
				return nil, true
			}
		}
		return nil, false
	}
	// exact matches first
	for _, n := range th.Names {
		if in.typeMatchesExact(n, v, selfCls) {
			return v, true
		}
	}
	if th.Intersection {
		// all must match (only class types)
		for _, n := range th.Names {
			if !in.typeMatchesExact(n, v, selfCls) {
				return nil, false
			}
		}
		return v, true
	}
	// scalar coercions (non-strict): order int, float, string, bool
	if _, isObj := v.(*Object); isObj {
		// object to string via __toString
		for _, n := range th.Names {
			if n == "string" {
				o := v.(*Object)
				if o.class.findMethod("__tostring") != nil {
					return in.objectToString(o), true
				}
			}
		}
		return nil, false
	}
	if _, isArr := v.(*Array); isArr {
		return nil, false
	}
	has := func(n string) bool {
		for _, t := range th.Names {
			if t == n {
				return true
			}
		}
		return false
	}
	switch x := v.(type) {
	case int64:
		if has("float") {
			return float64(x), true
		}
		if has("string") {
			return intToStr(x), true
		}
		if has("bool") {
			return x != 0, true
		}
	case float64:
		if has("int") {
			if x == float64(int64(x)) && floatFitsInt(x) {
				return int64(x), true
			}
			if floatFitsInt(x) && !has("string") {
				in.deprecated(fmt.Sprintf("Implicit conversion from float %s to int loses precision", formatFloatRepr(x)))
				return int64(x), true
			}
		}
		if has("string") {
			return in.toStr(x), true
		}
		if has("bool") {
			return x != 0, true
		}
	case string:
		ni := parseNumeric(x)
		if ni.ok && ni.whole {
			if has("int") && ni.isInt {
				return ni.i, true
			}
			if has("float") {
				return ni.f, true
			}
			if has("int") && !ni.isInt {
				if ni.f == float64(int64(ni.f)) {
					return int64(ni.f), true
				}
				in.deprecated(fmt.Sprintf("Implicit conversion from float-string \"%s\" to int loses precision", x))
				return int64(ni.f), true
			}
		} else if ni.ok && (has("int") || has("float")) && !has("bool") {
			// leading numeric: "123abc" -> TypeError in PHP 8? Actually allowed with warning for arithmetic, but for params: TypeError.
			return nil, false
		}
		if has("bool") {
			return x != "" && x != "0", true
		}
	case bool:
		if has("int") {
			if x {
				return int64(1), true
			}
			return int64(0), true
		}
		if has("float") {
			if x {
				return float64(1), true
			}
			return float64(0), true
		}
		if has("string") {
			if x {
				return "1", true
			}
			return "", true
		}
	}
	return nil, false
}

func (in *Interp) typeMatchesExact(n string, v Value, selfCls *Class) bool {
	switch n {
	case "mixed":
		return true
	case "int":
		_, ok := v.(int64)
		return ok
	case "float":
		_, ok := v.(float64)
		return ok
	case "string":
		_, ok := v.(string)
		return ok
	case "bool":
		_, ok := v.(bool)
		return ok
	case "true":
		b, ok := v.(bool)
		return ok && b
	case "false":
		b, ok := v.(bool)
		return ok && !b
	case "array":
		_, ok := v.(*Array)
		return ok
	case "null", "void":
		return v == nil
	case "object":
		_, ok := v.(*Object)
		return ok
	case "callable":
		return in.isCallable(v, in.frame)
	case "iterable":
		if _, ok := v.(*Array); ok {
			return true
		}
		if o, ok := v.(*Object); ok {
			return o.class.instanceOf("Traversable")
		}
		return false
	case "self", "static":
		o, ok := v.(*Object)
		if !ok {
			return false
		}
		if selfCls == nil {
			return true
		}
		return o.class.isSubclassOf(selfCls)
	case "parent":
		o, ok := v.(*Object)
		if !ok {
			return false
		}
		if selfCls == nil || selfCls.Parent == nil {
			return true
		}
		return o.class.isSubclassOf(selfCls.Parent)
	}
	o, ok := v.(*Object)
	if !ok {
		return false
	}
	if o.class.instanceOf(n) {
		return true
	}
	// Closure for callable-like class names
	return false
}

// ---------- closures ----------

func (in *Interp) makeClosure(fr *Frame, decl *FuncDecl, uses []ClosureUse, isStatic bool, arrow bool) Value {
	fn := &Function{Name: "{closure}", Decl: decl}
	cl := &Closure{fn: fn, bound: map[string]*Ref{}, scope: fr.class, static: fr.staticClass, isStatic: isStatic}
	if fr.fn != nil && fr.closure == nil {
		if fr.fn.Method != nil {
			cl.parentFunc = fr.fn.Method.Class.Name + "::" + fr.fn.Name + "()"
		} else if fr.class != nil && fr.fn.Class != nil {
			cl.parentFunc = fr.fn.Class.Name + "::" + fr.fn.Name + "()"
		} else {
			cl.parentFunc = fr.fn.Name + "()"
		}
	} else if fr.closure != nil {
		cl.parentFunc = fr.closure.parentFunc
		if cl.parentFunc == "" && fr.fn != nil {
			cl.parentFunc = ""
		}
	}
	if !isStatic && fr.this != nil {
		cl.this = fr.this
		fr.this.rc++
	}
	if arrow {
		// capture by value all variables used in body that exist in parent scope
		names := decl.freeVars()
		for _, name := range names {
			if r, ok := fr.vars[name]; ok {
				nr := &Ref{rc: 1}
				nr.set(r.V)
				cl.bound[name] = nr
				cl.boundOrder = append(cl.boundOrder, name)
			} else if name == "this" {
				continue
			}
		}
	} else {
		for _, u := range uses {
			if u.ByRef {
				r, ok := fr.vars[u.Name]
				if !ok {
					r = &Ref{rc: 1}
					fr.vars[u.Name] = r
				}
				r.rc++
				cl.bound[u.Name] = r
				if cl.byRef == nil {
					cl.byRef = map[string]bool{}
				}
				cl.byRef[u.Name] = true
			} else {
				r, ok := fr.vars[u.Name]
				nr := &Ref{rc: 1}
				if ok {
					nr.set(r.V)
				} else {
					in.warn(fmt.Sprintf("Undefined variable $%s", u.Name))
				}
				cl.bound[u.Name] = nr
			}
			cl.boundOrder = append(cl.boundOrder, u.Name)
		}
	}
	obj := in.newObject(in.classes["closure"])
	obj.internal = cl
	return obj
}

func (in *Interp) closureFromFunction(fn *Function, this *Object, scope *Class) Value {
	cl := &Closure{fn: fn, bound: map[string]*Ref{}, this: this, scope: scope, static: scope}
	if this != nil {
		this.rc++
	}
	obj := in.newObject(in.classes["closure"])
	obj.internal = cl
	return obj
}

func (in *Interp) closureFromMethod(m *Method, this *Object, static *Class) Value {
	cl := &Closure{fn: m.Fn, bound: map[string]*Ref{}, this: this, scope: m.Class, static: static, method: m}
	if this != nil {
		this.rc++
	}
	obj := in.newObject(in.classes["closure"])
	obj.internal = cl
	return obj
}

func (in *Interp) makeClosureFromCallable(callee Value, fr *Frame) Value {
	callee = deref(callee)
	if o, ok := callee.(*Object); ok {
		if _, isCl := o.internal.(*Closure); isCl {
			return o
		}
	}
	fn, this, cls, static, closure := in.resolveCallable(callee, fr, true)
	if closure != nil {
		obj := in.newObject(in.classes["closure"])
		obj.internal = closure
		return obj
	}
	if fn.Method != nil {
		return in.closureFromMethod(fn.Method, this, static)
	}
	if m := in.methodFor(fn, cls); m != nil {
		return in.closureFromMethod(m, this, static)
	}
	return in.closureFromFunction(fn, this, cls)
}

func (in *Interp) methodFor(fn *Function, cls *Class) *Method {
	if cls == nil {
		return nil
	}
	for _, m := range cls.Methods {
		if m.Fn == fn {
			return m
		}
	}
	return nil
}

func (in *Interp) closureBind(obj *Object, args []Value) Value {
	cl := obj.internal.(*Closure)
	var newThis *Object
	if len(args) > 0 {
		if o, ok := args[0].(*Object); ok {
			newThis = o
		}
	}
	scope := cl.scope
	if len(args) > 1 {
		switch s := args[1].(type) {
		case *Object:
			scope = s.class
		case string:
			if s != "static" {
				scope = in.lookupClass(s)
				if scope == nil {
					in.throwError("Error", fmt.Sprintf("Class \"%s\" not found", s))
				}
			}
		case nil:
			scope = nil
		}
	} else if newThis != nil && scope == nil {
		// keep scope
	}
	if cl.isStatic && newThis != nil {
		in.warn("Cannot bind an instance to a static closure")
		newThis = nil
	}
	ncl := &Closure{fn: cl.fn, bound: cl.bound, boundOrder: cl.boundOrder, byRef: cl.byRef, this: newThis, scope: scope, static: scope, isStatic: cl.isStatic, callable: cl.callable, method: cl.method, parentFunc: cl.parentFunc}
	if newThis != nil {
		ncl.static = newThis.class
		newThis.rc++
	}
	for _, r := range cl.bound {
		r.rc++
	}
	nobj := in.newObject(in.classes["closure"])
	nobj.internal = ncl
	return nobj
}

// freeVars computes variables referenced in an arrow function body
func (d *FuncDecl) freeVars() []string {
	if d.freeVarsCache != nil {
		return d.freeVarsCache
	}
	seen := map[string]bool{}
	for _, p := range d.Params {
		seen[p.Name] = true
	}
	var names []string
	var walkExpr func(e Expr)
	var walkStmt func(s Stmt)
	add := func(n string) {
		if !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	walkExpr = func(e Expr) {
		switch x := e.(type) {
		case nil:
		case *VarExpr:
			add(x.Name)
		case *VarVarExpr:
			walkExpr(x.Name)
		case *InterpString:
			for _, p := range x.Parts {
				walkExpr(p)
			}
		case *ArrayLit:
			for _, it := range x.Items {
				walkExpr(it.Key)
				walkExpr(it.Value)
			}
		case *ListExpr:
			for _, it := range x.Items {
				walkExpr(it.Key)
				walkExpr(it.Value)
			}
		case *IndexExpr:
			walkExpr(x.Base)
			walkExpr(x.Index)
		case *PropExpr:
			walkExpr(x.Obj)
			walkExpr(x.Name)
		case *StaticPropExpr:
			walkExpr(x.Class)
			walkExpr(x.Name)
		case *ClassConstExpr:
			walkExpr(x.Class)
		case *CallExpr:
			walkExpr(x.Fn)
			for _, a := range x.Args {
				walkExpr(a.Expr)
			}
		case *MethodCallExpr:
			walkExpr(x.Obj)
			walkExpr(x.Name)
			for _, a := range x.Args {
				walkExpr(a.Expr)
			}
		case *StaticCallExpr:
			walkExpr(x.Class)
			walkExpr(x.Name)
			for _, a := range x.Args {
				walkExpr(a.Expr)
			}
		case *NewExpr:
			walkExpr(x.Class)
			for _, a := range x.Args {
				walkExpr(a.Expr)
			}
		case *CloneExpr:
			walkExpr(x.E)
		case *UnaryExpr:
			walkExpr(x.E)
		case *BinaryExpr:
			walkExpr(x.L)
			walkExpr(x.R)
		case *LogicalExpr:
			walkExpr(x.L)
			walkExpr(x.R)
		case *AssignExpr:
			walkExpr(x.Target)
			walkExpr(x.Value)
		case *AssignRefExpr:
			walkExpr(x.Target)
			walkExpr(x.Value)
		case *CompoundAssignExpr:
			walkExpr(x.Target)
			walkExpr(x.Value)
		case *IncDecExpr:
			walkExpr(x.Target)
		case *TernaryExpr:
			walkExpr(x.Cond)
			walkExpr(x.Then)
			walkExpr(x.Else)
		case *CastExpr:
			walkExpr(x.E)
		case *IssetExpr:
			for _, v := range x.Vars {
				walkExpr(v)
			}
		case *EmptyExpr:
			walkExpr(x.E)
		case *ExitExpr:
			walkExpr(x.E)
		case *PrintExpr:
			walkExpr(x.E)
		case *InstanceofExpr:
			walkExpr(x.E)
			walkExpr(x.Class)
		case *ClosureExpr:
			for _, u := range x.Uses {
				add(u.Name)
			}
		case *ArrowFnExpr:
			for _, n := range x.Fn.freeVars() {
				add(n)
			}
		case *YieldExpr:
			walkExpr(x.Key)
			walkExpr(x.Value)
		case *YieldFromExpr:
			walkExpr(x.E)
		case *ThrowExpr:
			walkExpr(x.E)
		case *MatchExpr:
			walkExpr(x.Subject)
			for _, arm := range x.Arms {
				for _, c := range arm.Conds {
					walkExpr(c)
				}
				walkExpr(arm.Body)
			}
		case *SilenceExpr:
			walkExpr(x.E)
		case *IncludeExpr:
			walkExpr(x.E)
		}
	}
	walkStmt = func(s Stmt) {
		switch x := s.(type) {
		case *ExprStmt:
			walkExpr(x.E)
		case *ReturnStmt:
			walkExpr(x.E)
		case *EchoStmt:
			for _, e := range x.Exprs {
				walkExpr(e)
			}
		case *BlockStmt:
			for _, st := range x.Stmts {
				walkStmt(st)
			}
		}
	}
	for _, s := range d.Body {
		walkStmt(s)
	}
	d.freeVarsCache = names
	if names == nil {
		d.freeVarsCache = []string{}
	}
	return d.freeVarsCache
}
