cd /workspace/src && cat > class.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

func (in *Interp) declareClass(cd *ClassDecl, fr *Frame) *Class {
	lname := strings.ToLower(cd.Name)
	delete(in.pendingClasses, lname)
	c := &Class{Name: cd.Name, lname: lname, Kind: cd.Kind, Abstract: cd.Abstract, Final: cd.Final, Readonly: cd.Readonly, Decl: cd,
		Consts: map[string]*ClassConst{}, StaticProps: map[string]*Ref{}, StaticPropInfo: map[string]*PropInfo{}, PropMap: map[string]*PropInfo{}, Methods: map[string]*Method{}}
	if cd.Kind == "enum" {
		c.EnumBacking = cd.EnumBackingType
		c.EnumCaseObjs = map[string]*Object{}
	}
	// parent
	if cd.Parent != "" {
		p := in.lookupClass(cd.Parent)
		if p == nil {
			in.fatal(fmt.Sprintf("Class \"%s\" not found", cd.Parent))
		}
		if p.Kind == "interface" {
			in.fatal(fmt.Sprintf("Class %s cannot extend interface %s", cd.Name, p.Name))
		}
		if p.Kind == "trait" {
			in.fatal(fmt.Sprintf("Class %s cannot extend trait %s", cd.Name, p.Name))
		}
		if p.Final {
			in.fatal(fmt.Sprintf("Class %s cannot extend final class %s", cd.Name, p.Name))
		}
		c.Parent = p
		in.inheritFrom(c, p)
	}
	// interfaces
	for _, iname := range cd.Interfaces {
		ic := in.lookupClass(iname)
		if ic == nil {
			in.fatal(fmt.Sprintf("%s \"%s\" not found", map[bool]string{true: "Interface", false: "Class"}[cd.Kind != "class" || true], iname))
		}
		if ic.Kind != "interface" {
			in.fatal(fmt.Sprintf("%s cannot implement %s - it is not an interface", cd.Name, ic.Name))
		}
		in.addInterface(c, ic)
	}
	if cd.Kind == "enum" {
		in.addInterface(c, in.classes["unitenum"])
		if c.EnumBacking != "" {
			in.addInterface(c, in.classes["backedenum"])
		}
	}
	// register early (allows self-references in constant expressions)
	in.classes[lname] = c
	// traits
	for _, tu := range cd.Traits {
		for _, tname := range tu.Names {
			t := in.lookupClass(tname)
			if t == nil {
				in.fatal(fmt.Sprintf("Trait \"%s\" not found", tname))
			}
			if t.Kind != "trait" {
				in.fatal(fmt.Sprintf("%s cannot use %s - it is not a trait", cd.Name, t.Name))
			}
			in.useTrait(c, t, tu)
		}
	}
	// constants
	for _, cc := range cd.Consts {
		c.Consts[cc.Name] = &ClassConst{Name: cc.Name, Expr: cc.Value, Class: c, Visibility: cc.Visibility}
		c.ConstOrder = append(c.ConstOrder, cc.Name)
	}
	// properties
	for _, pd := range cd.Props {
		pi := &PropInfo{Name: pd.Name, Visibility: pd.Visibility, Class: c, Decl: pd, Static: pd.Static, Readonly: pd.Readonly, Type: pd.Type}
		if pd.Static {
			r := &Ref{rc: 1}
			c.StaticProps[pd.Name] = r
			c.StaticPropInfo[pd.Name] = pi
			c.StaticOrder = append(c.StaticOrder, pd.Name)
		} else {
			if existing, ok := c.PropMap[pd.Name]; ok {
				// override: replace in place
				for i, p := range c.Props {
					if p == existing {
						c.Props[i] = pi
					}
				}
			} else {
				c.Props = append(c.Props, pi)
			}
			c.PropMap[pd.Name] = pi
		}
	}
	// methods
	for _, md := range cd.Methods {
		in.addMethod(c, md, c)
	}
	// promoted constructor params become props
	if ctor := c.Methods["__construct"]; ctor != nil && ctor.Fn.Decl != nil && ctor.Class == c {
		for _, p := range ctor.Fn.Decl.Params {
			if p.Promote != "" {
				pi := &PropInfo{Name: p.Name, Visibility: p.Promote, Class: c, Readonly: p.PromoteReadonly || cd.Readonly, Type: p.Type, Decl: &PropDecl{Name: p.Name, Visibility: p.Promote, Type: p.Type}}
				if _, ok := c.PropMap[p.Name]; !ok {
					c.Props = append(c.Props, pi)
				}
				c.PropMap[p.Name] = pi
			}
		}
	}
	// abstract check
	if cd.Kind == "class" && !cd.Abstract {
		for _, mn := range c.MethodOrder {
			m := c.Methods[mn]
			if m.Abstract {
				in.frame.line = cd.Line
				in.fatal(fmt.Sprintf("Class %s contains 1 abstract method and must therefore be declared abstract or implement the remaining methods (%s::%s)", cd.Name, m.Class.Name, m.Name))
			}
		}
	}
	// enum cases
	if cd.Kind == "enum" {
		in.setupEnum(c, cd)
	}
	// initialize static props (lazily evaluated defaults) - evaluate now
	in.initStatics(c)
	return c
}

func (in *Interp) initStatics(c *Class) {
	if c.staticsInitialized {
		return
	}
	c.staticsInitialized = true
	for _, name := range c.StaticOrder {
		pi := c.StaticPropInfo[name]
		r := c.StaticProps[name]
		if pi.Decl != nil && pi.Decl.Default != nil {
			fr := &Frame{vars: map[string]*Ref{}, class: c, staticClass: c, file: c.Decl.File, line: pi.Decl.Line}
			if in.frame != nil {
				fr.line = in.frame.line
				fr.file = in.frame.file
			}
			r.set(in.eval(fr, pi.Decl.Default))
		} else if pi.Type != nil {
			r.V = uninit
		}
	}
}

func (in *Interp) inheritFrom(c *Class, p *Class) {
	// constants
	for _, n := range p.ConstOrder {
		c.Consts[n] = p.Consts[n]
		c.ConstOrder = append(c.ConstOrder, n)
	}
	// static props shared
	for _, n := range p.StaticOrder {
		c.StaticProps[n] = p.StaticProps[n]
		c.StaticPropInfo[n] = p.StaticPropInfo[n]
		c.StaticOrder = append(c.StaticOrder, n)
	}
	for _, pi := range p.Props {
		c.Props = append(c.Props, pi)
		c.PropMap[pi.Name] = pi
	}
	for _, mn := range p.MethodOrder {
		c.Methods[mn] = p.Methods[mn]
		c.MethodOrder = append(c.MethodOrder, mn)
	}
	for _, i := range p.Interfaces {
		in.addInterface(c, i)
	}
	c.autoProps = p.autoProps
	c.internalInit = p.internalInit
	c.isInternal = p.isInternal
}

func (in *Interp) addInterface(c *Class, ic *Class) {
	for _, e := range c.Interfaces {
		if e == ic {
			return
		}
	}
	c.Interfaces = append(c.Interfaces, ic)
	for _, sub := range ic.Interfaces {
		in.addInterface(c, sub)
	}
	// interface constants
	for _, n := range ic.ConstOrder {
		if _, ok := c.Consts[n]; !ok {
			c.Consts[n] = ic.Consts[n]
			c.ConstOrder = append(c.ConstOrder, n)
		}
	}
	// interface methods (abstract) - add if not present
	for _, mn := range ic.MethodOrder {
		if _, ok := c.Methods[mn]; !ok {
			c.Methods[mn] = ic.Methods[mn]
			c.MethodOrder = append(c.MethodOrder, mn)
		}
	}
}

func (in *Interp) addMethod(c *Class, md *FuncDecl, declClass *Class) *Method {
	lname := strings.ToLower(md.Name)
	m := &Method{Name: md.Name, Class: declClass, Static: md.Static, Abstract: md.Abstract || !md.HasBody, Final: md.Final, Visibility: md.Visibility}
	fn := &Function{Name: md.Name, Decl: md, Class: declClass, Method: m}
	m.Fn = fn
	if existing, ok := c.Methods[lname]; ok {
		if existing.Final && existing.Class != c && !existing.Abstract {
			in.fatal(fmt.Sprintf("Cannot override final method %s::%s()", existing.Class.Name, existing.Name))
		}
		c.Methods[lname] = m
	} else {
		c.Methods[lname] = m
		c.MethodOrder = append(c.MethodOrder, lname)
	}
	return m
}

func (in *Interp) useTrait(c *Class, t *Class, tu TraitUse) {
	// methods
	excluded := map[string]bool{}
	for _, r := range tu.Rules {
		if len(r.InsteadOf) > 0 {
			for _, other := range r.InsteadOf {
				if strings.EqualFold(other, t.Name) {
					excluded[strings.ToLower(r.Method)] = true
				}
			}
		}
	}
	for _, mn := range t.MethodOrder {
		tm := t.Methods[mn]
		if tm.Fn.Decl == nil {
			continue
		}
		if !excluded[mn] {
			// don't override methods defined in class itself
			if existing, ok := c.Methods[mn]; ok && existing.Class == c && !c.traitMethods[mn] {
				// class method wins
			} else {
				m := in.addMethod(c, tm.Fn.Decl, c)
				m.ProtoClass = t
				if c.traitMethods == nil {
					c.traitMethods = map[string]bool{}
				}
				c.traitMethods[mn] = true
			}
		}
		// aliases
		for _, r := range tu.Rules {
			if strings.EqualFold(r.Method, tm.Name) && (r.Trait == "" || strings.EqualFold(r.Trait, t.Name)) {
				if r.Alias != "" {
					alias := *tm.Fn.Decl
					alias.Name = r.Alias
					if r.Visibility != "" {
						alias.Visibility = r.Visibility
					}
					m := in.addMethod(c, &alias, c)
					m.ProtoClass = t
				} else if r.Visibility != "" {
					if m, ok := c.Methods[mn]; ok {
						m.Visibility = r.Visibility
					}
				}
			}
		}
	}
	// properties
	for _, pi := range t.Props {
		npi := *pi
		npi.Class = c
		if _, ok := c.PropMap[pi.Name]; !ok {
			c.Props = append(c.Props, &npi)
		}
		c.PropMap[pi.Name] = &npi
	}
	for _, n := range t.StaticOrder {
		pi := *t.StaticPropInfo[n]
		pi.Class = c
		r := &Ref{rc: 1}
		if pi.Decl != nil && pi.Decl.Default != nil {
			fr := &Frame{vars: map[string]*Ref{}, class: c, staticClass: c, file: c.Decl.File}
			r.set(in.eval(fr, pi.Decl.Default))
		}
		c.StaticProps[n] = r
		c.StaticPropInfo[n] = &pi
		c.StaticOrder = append(c.StaticOrder, n)
	}
	// constants
	for _, n := range t.ConstOrder {
		if _, ok := c.Consts[n]; !ok {
			cc := *t.Consts[n]
			cc.Class = c
			c.Consts[n] = &cc
			c.ConstOrder = append(c.ConstOrder, n)
		}
	}
	// nested traits already flattened into t
}

func (in *Interp) setupEnum(c *Class, cd *ClassDecl) {
	c.PropMap["name"] = &PropInfo{Name: "name", Visibility: "public", Class: c, Readonly: true}
	c.Props = append(c.Props, c.PropMap["name"])
	if c.EnumBacking != "" {
		c.PropMap["value"] = &PropInfo{Name: "value", Visibility: "public", Class: c, Readonly: true}
		c.Props = append(c.Props, c.PropMap["value"])
	}
	for _, ec := range cd.Cases {
		o := &Object{class: c, props: NewArray(), id: 0}
		o.rc = 1000000 // immortal
		o.props.SetStr("name", ec.Name)
		if c.EnumBacking != "" {
			if ec.Value == nil {
				in.fatal(fmt.Sprintf("Case %s of backed enum %s must have a value", ec.Name, c.Name))
			}
			fr := &Frame{vars: map[string]*Ref{}, class: c, staticClass: c, file: cd.File, line: ec.Line}
			v := in.eval(fr, ec.Value)
			o.props.SetStr("value", v)
		} else if ec.Value != nil {
			in.fatal(fmt.Sprintf("Case %s of non-backed enum %s must not have a value", ec.Name, c.Name))
		}
		c.EnumCaseObjs[ec.Name] = o
		c.EnumCases = append(c.EnumCases, ec.Name)
	}
	// cases(), from(), tryFrom()
	addNative := func(name string, static bool, f func(in *Interp, this *Object, args []Value) Value, min, max int) {
		lname := strings.ToLower(name)
		fn := &Function{Name: name, Class: c, MinArgs: min, MaxArgs: max}
		m := &Method{Name: name, Class: c, Static: static, Visibility: "public", Fn: fn}
		fn.Method = m
		fn.Native = func(in *Interp, args []Value) Value {
			return f(in, in.frame.this, args)
		}
		c.Methods[lname] = m
		c.MethodOrder = append(c.MethodOrder, lname)
	}
	addNative("cases", true, func(in *Interp, this *Object, args []Value) Value {
		arr := NewArray()
		for _, n := range c.EnumCases {
			arr.Append(c.EnumCaseObjs[n])
		}
		return arr
	}, 0, 0)
	if c.EnumBacking != "" {
		lookup := func(in *Interp, v Value, try bool) Value {
			v = deref(v)
			for _, n := range c.EnumCases {
				o := c.EnumCaseObjs[n]
				cv, _ := o.props.GetStr("value")
				if c.EnumBacking == "int" {
					if iv, ok := v.(int64); ok && cv == iv {
						return o
					}
					if s, ok := v.(string); ok {
						ni := parseNumeric(s)
						if ni.ok && ni.whole && ni.isInt && cv == ni.i {
							return o
						}
					}
					if f, ok := v.(float64); ok && float64(toInt(cv)) == f {
						return o
					}
				} else {
					if s, ok := v.(string); ok && cv == s {
						return o
					}
					if _, ok := v.(int64); ok && cv == toStr(v) {
						return o
					}
				}
			}
			if try {
				return nil
			}
			var repr string
			if s, ok := v.(string); ok {
				repr = "\"" + s + "\""
			} else {
				repr = toStr(v)
			}
			if c.EnumBacking == "int" {
				if _, ok := v.(string); ok {
					ni := parseNumeric(v.(string))
					if !ni.ok || !ni.whole {
						in.throwError("TypeError", fmt.Sprintf("%s::from(): Argument #1 ($value) must be of type int, string given", c.Name))
					}
				}
			} else {
				if _, ok := v.(string); !ok {
					if _, isInt := v.(int64); !isInt {
						in.throwError("TypeError", fmt.Sprintf("%s::from(): Argument #1 ($value) must be of type string, %s given", c.Name, typeName(v)))
					}
				}
			}
			in.throwError("ValueError", fmt.Sprintf("%s is not a valid backing value for enum %s", repr, c.Name))
			return nil
		}
		addNative("from", true, func(in *Interp, this *Object, args []Value) Value {
			return lookup(in, args[0], false)
		}, 1, 1)
		addNative("tryFrom", true, func(in *Interp, this *Object, args []Value) Value {
			return lookup(in, args[0], true)
		}, 1, 1)
	}
}

// ---------- instantiation ----------

func (in *Interp) evalNew(fr *Frame, x *NewExpr) Value {
	var cls *Class
	if x.Anon != nil {
		lname := strings.ToLower(x.Anon.Name)
		if c, ok := in.classes[lname]; ok {
			cls = c
		} else {
			cls = in.declareClass(x.Anon, fr)
			cls.Name = "class@anonymous"
			if x.Anon.Parent != "" {
				cls.Name = cls.Parent.Name + "@anonymous"
			} else if len(x.Anon.Interfaces) > 0 {
				cls.Name = cls.Interfaces[0].Name + "@anonymous"
			}
			cls.isAnon = true
		}
	} else {
		cls = in.resolveClassRef(fr, x.Class)
	}
	return in.instantiate(cls, fr, x.Args, nil)
}

func (in *Interp) instantiate(cls *Class, fr *Frame, argExprs []Arg, args []Value) *Object {
	if cls.Kind == "interface" {
		in.throwError("Error", fmt.Sprintf("Cannot instantiate interface %s", cls.Name))
	}
	if cls.Kind == "trait" {
		in.throwError("Error", fmt.Sprintf("Cannot instantiate trait %s", cls.Name))
	}
	if cls.Kind == "enum" {
		in.throwError("Error", fmt.Sprintf("Cannot instantiate enum %s", cls.Name))
	}
	if cls.Abstract {
		in.throwError("Error", fmt.Sprintf("Cannot instantiate abstract class %s", cls.Name))
	}
	obj := in.newObject(cls)
	in.initProps(obj, cls)
	if cls.internalInit != nil {
		cls.internalInit(in, obj)
	}
	ctor := cls.findMethod("__construct")
	if ctor != nil {
		if ctor.Visibility != "public" && !in.methodAccessible(ctor, fr.class) {
			scope := "global scope"
			if fr.class != nil {
				scope = "scope " + fr.class.Name
			}
			in.throwError("Error", fmt.Sprintf("Call to %s %s::__construct() from %s", ctor.Visibility, cls.Name, scope))
		}
		if argExprs != nil {
			var named map[string]Value
			args, named = in.evalArgs(fr, ctor.Fn, argExprs)
			if named != nil {
				args = in.mergeNamed(ctor.Fn, args, named)
			}
		}
		obj.rc++
		in.callFunction(ctor.Fn, args, obj, ctor.Class, cls, nil, fr, fr.line)
		obj.rc--
	} else if argExprs != nil {
		// evaluate args anyway for side effects
		in.evalArgs(fr, nil, argExprs)
	}
	return obj
}

func (in *Interp) initProps(obj *Object, cls *Class) {
	for _, pi := range cls.Props {
		if pi.Decl != nil && pi.Decl.Hooks != nil {
			if _, hasGet := pi.Decl.Hooks["get"]; hasGet && !pi.Decl.HasDefault {
				// virtual property
				continue
			}
		}
		if pi.Decl != nil && pi.Decl.HasDefault {
			fr := &Frame{vars: map[string]*Ref{}, class: pi.Class, staticClass: cls, file: pi.Class.Decl.File, line: pi.Decl.Line}
			if in.frame != nil {
				fr.line = in.frame.line
				fr.file = in.frame.file
			}
			v := in.eval(fr, pi.Decl.Default)
			obj.props.SetStr(pi.Name, v)
		} else if pi.Type != nil || pi.Readonly {
			obj.props.SetRaw(StrKey(pi.Name), uninit)
		} else if pi.Decl != nil && pi.Decl.Name != "" && !isPromoted(pi) {
			obj.props.SetStr(pi.Name, nil)
		} else if pi.Decl == nil {
			obj.props.SetStr(pi.Name, nil)
		} else {
			obj.props.SetRaw(StrKey(pi.Name), uninit)
		}
	}
}

func isPromoted(pi *PropInfo) bool {
	return pi.Decl != nil && pi.Decl.Line == 0 && !pi.Decl.HasDefault && pi.Decl.Type == nil && false
}

func (in *Interp) cloneObject(o *Object, fr *Frame) *Object {
	if o.class.isEnum() {
		in.throwError("Error", fmt.Sprintf("Trying to clone an uncloneable object of class %s", o.class.Name))
	}
	if _, ok := o.internal.(*Generator); ok {
		in.throwError("Error", "Trying to clone an uncloneable object of class Generator")
	}
	n := in.newObject(o.class)
	n.props = o.props.Clone()
	// derefence refs? PHP keeps references in cloned props
	switch st := o.internal.(type) {
	case *Array:
		cl := st.Clone()
		cl.rc++
		n.internal = cl
	case *Closure:
		n.internal = st
	case *SplStorage:
		n.internal = st.clone()
	case interface{ cloneInternal() interface{} }:
		n.internal = st.cloneInternal()
	default:
		n.internal = o.internal
	}
	if m := o.class.findMethod("__clone"); m != nil {
		if m.Visibility != "public" && !in.methodAccessible(m, fr.class) {
			in.throwError("Error", fmt.Sprintf("Call to %s %s::__clone() from %s", m.Visibility, o.class.Name, scopeName(fr.class)))
		}
		n.rc++
		in.callFunction(m.Fn, nil, n, m.Class, n.class, nil, fr, fr.line)
		n.rc--
	}
	return n
}

func scopeName(c *Class) string {
	if c == nil {
		return "global scope"
	}
	return "scope " + c.Name
}

// ---------- builtin class helpers ----------

type nativeMethod struct {
	name   string
	fn     func(in *Interp, this *Object, args []Value) Value
	min    int
	max    int
	static bool
	vis    string
	refArgs []int
	params []string
}

func (in *Interp) defineClass(name string, parent string, ifaces []string, methods []nativeMethod) *Class {
	c := &Class{Name: name, lname: strings.ToLower(name), Kind: "class", Consts: map[string]*ClassConst{}, StaticProps: map[string]*Ref{}, StaticPropInfo: map[string]*PropInfo{}, PropMap: map[string]*PropInfo{}, Methods: map[string]*Method{}, isInternal: true}
	c.Decl = &ClassDecl{Name: name, Kind: "class", File: "", AllowDynamic: false}
	if parent != "" {
		p := in.classes[strings.ToLower(parent)]
		c.Parent = p
		in.inheritFrom(c, p)
	}
	for _, i := range ifaces {
		in.addInterface(c, in.classes[strings.ToLower(i)])
	}
	for _, nm := range methods {
		in.addNativeMethod(c, nm)
	}
	in.classes[c.lname] = c
	return c
}

func (in *Interp) addNativeMethod(c *Class, nm nativeMethod) {
	lname := strings.ToLower(nm.name)
	vis := nm.vis
	if vis == "" {
		vis = "public"
	}
	fn := &Function{Name: nm.name, Class: c, MinArgs: nm.min, MaxArgs: nm.max, RefArgs: nm.refArgs, ParamNames: nm.params}
	m := &Method{Name: nm.name, Class: c, Static: nm.static, Visibility: vis, Fn: fn}
	fn.Method = m
	f := nm.fn
	fn.Native = func(in *Interp, args []Value) Value {
		return f(in, in.frame.this, args)
	}
	if _, ok := c.Methods[lname]; !ok {
		c.MethodOrder = append(c.MethodOrder, lname)
	}
	c.Methods[lname] = m
}

func (in *Interp) defineInterface(name string, parents []string, methods []string) *Class {
	c := &Class{Name: name, lname: strings.ToLower(name), Kind: "interface", Consts: map[string]*ClassConst{}, StaticProps: map[string]*Ref{}, StaticPropInfo: map[string]*PropInfo{}, PropMap: map[string]*PropInfo{}, Methods: map[string]*Method{}, isInternal: true}
	c.Decl = &ClassDecl{Name: name, Kind: "interface"}
	for _, p := range parents {
		in.addInterface(c, in.classes[strings.ToLower(p)])
	}
	for _, mn := range methods {
		lname := strings.ToLower(mn)
		fn := &Function{Name: mn, Class: c, Decl: &FuncDecl{Name: mn, Abstract: true, Visibility: "public"}}
		m := &Method{Name: mn, Class: c, Abstract: true, Visibility: "public", Fn: fn}
		fn.Method = m
		c.Methods[lname] = m
		c.MethodOrder = append(c.MethodOrder, lname)
	}
	in.classes[c.lname] = c
	return c
}

func (in *Interp) addProp(c *Class, name string, vis string, def Value) {
	pi := &PropInfo{Name: name, Visibility: vis, Class: c, Decl: &PropDecl{Name: name, Visibility: vis, HasDefault: true, Default: literalExpr(def)}}
	if _, ok := c.PropMap[name]; !ok {
		c.Props = append(c.Props, pi)
	}
	c.PropMap[name] = pi
}

func literalExpr(v Value) Expr {
	switch x := v.(type) {
	case nil:
		return &NullLit{}
	case bool:
		return &BoolLit{V: x}
	case int64:
		return &IntLit{V: x}
	case float64:
		return &FloatLit{V: x}
	case string:
		return &StringLit{V: x}
	case *Array:
		return &ArrayLit{}
	}
	return &NullLit{}
}

func (in *Interp) addConst(c *Class, name string, v Value) {
	c.Consts[name] = &ClassConst{Name: name, Value: v, Class: c, Visibility: "public", evaluated: true}
	c.ConstOrder = append(c.ConstOrder, name)
}
