func (in *Interp) fillExceptionLocation(o *Object) {
	fr := in.frame
	// skip native constructor frames: location is where `new` happened
	for fr != nil && fr.vars == nil && fr.caller != nil {
		fr = fr.caller
	}
	if fr != nil {
		o.props.SetStr("file", fr.file)
		o.props.SetStr("line", int64(fr.line))
	}
	o.props.SetStr("trace", in.buildTrace(fr, 0))
}

// buildTrace builds the backtrace array starting at frame fr (innermost)
func (in *Interp) buildTrace(fr *Frame, skip int) *Array {
	arr := NewArray()
	// walk traceStack from innermost
	stack := in.traceStack
	// find position of fr in stack
	start := len(stack) - 1
	for i := len(stack) - 1; i >= 0; i-- {
		if stack[i] == fr {
			start = i
			break
		}
	}
	for i := start; i >= 1; i-- {
		f := stack[i]
		if f.fn == nil && f.gen == nil {
			continue
		}
		if f.isInclude {
			e := NewArray()
			e.SetStr("file", f.caller.file)
			e.SetStr("line", int64(f.callLine))
			e.SetStr("function", f.funcName)
			arr.Append(e)
			continue
		}
		e := NewArray()
		if f.caller != nil && f.caller.file != "" {
			e.SetStr("file", f.caller.file)
			e.SetStr("line", int64(f.callLine))
		} else if f.gen != nil {
			// generator frames: use own file/line
		}
		e.SetStr("function", f.funcName)
		if f.callClass != "" {
			e.SetStr("class", f.callClass)
			e.SetStr("type", f.callType)
		}
		args := NewArray()
		for _, a := range f.args {
			if _, ok := a.(missingArg); ok {
				continue
			}
			args.Append(deref(a))
		}
		e.SetStr("args", args)
		arr.Append(e)
	}
	return arr
}

func (in *Interp) traceAsString(tv Value) string {
	var sb strings.Builder
	n := 0
	if arr, ok := tv.(*Array); ok {
		arr.Each(func(k Key, v Value) bool {
			e, ok := deref(v).(*Array)
			if !ok {
				return true
			}
			file, hasFile := e.GetStr("file")
			line, _ := e.GetStr("line")
			fn, _ := e.GetStr("function")
			cls, hasCls := e.GetStr("class")
			typ, _ := e.GetStr("type")
			args, _ := e.GetStr("args")
			sb.WriteString(fmt.Sprintf("#%d ", n))
			if hasFile {
				sb.WriteString(fmt.Sprintf("%s(%d): ", toStr(file), toInt(line)))
			} else {
				sb.WriteString("[internal function]: ")
			}
			if hasCls {
				sb.WriteString(toStr(cls) + toStr(typ))
			}
			sb.WriteString(toStr(fn) + "(")
			if aa, ok := deref(args).(*Array); ok {
				first := true
				aa.Each(func(_ Key, a Value) bool {
					if !first {
						sb.WriteString(", ")
					}
					first = false
					sb.WriteString(traceArgRepr(deref(a)))
					return true
				})
			}
			sb.WriteString(")\n")
			n++
			return true
		})
	}
	sb.WriteString(fmt.Sprintf("#%d {main}", n))
	return sb.String()
}

func traceArgRepr(v Value) string {
	switch x := v.(type) {
	case nil:
		return "NULL"
	case bool:
		if x {
			return "true"
		}
		return "false"
	case int64:
		return intToStr(x)
	case float64:
		return formatFloatRepr(x)
	case string:
		if len(x) > 15 {
			return "'" + x[:15] + "...'"
		}
		return "'" + x + "'"
	case *Array:
		return "Array"
	case *Object:
		return "Object(" + x.class.Name + ")"
	case *Resource:
		return "Resource id #" + intToStr(int64(x.id))
	}
	return "?"
}

func (in *Interp) throwableToString(ex *Object) string {
	var parts []string
	cur := ex
	seen := map[*Object]bool{}
	for cur != nil && !seen[cur] {
		seen[cur] = true
		msg := toStr(in.getProp(cur, "message"))
		file := toStr(in.getProp(cur, "file"))
		line := toInt(in.getProp(cur, "line"))
		var s string
		if msg != "" {
			s = fmt.Sprintf("%s: %s in %s:%d\nStack trace:\n%s", cur.class.Name, msg, file, line, in.traceAsString(in.getProp(cur, "trace")))
		} else {
			s = fmt.Sprintf("%s in %s:%d\nStack trace:\n%s", cur.class.Name, file, line, in.traceAsString(in.getProp(cur, "trace")))
		}
		parts = append(parts, s)
		prev, _ := in.getProp(cur, "previous").(*Object)
		cur = prev
	}
	// PHP prints previous first, then "Next ..."
	var sb strings.Builder
	for i := len(parts) - 1; i >= 0; i-- {
		if i != len(parts)-1 {
			sb.WriteString("\n\nNext ")
		}
		sb.WriteString(parts[i])
	}
	return sb.String()
}

// newException creates an exception object of the given class with message
func (in *Interp) newException(class string, msg string, code int64) *Object {
	cls := in.classes[strings.ToLower(class)]
	if cls == nil {
		cls = in.classes["exception"]
	}
	o := in.newObject(cls)
	in.initProps(o, cls)
	in.fillExceptionLocation(o)
	o.props.SetStr("message", msg)
	o.props.SetStr("code", code)
	return o
}

func (in *Interp) initMiscClasses() {
	// WeakMap (simplified: strong map keyed by object id)
	in.defineClass("WeakReference", "", nil, []nativeMethod{
		{name: "create", static: true, min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			o := in.newObject(in.classes["weakreference"])
			o.internal = args[0]
			return o
		}},
		{name: "get", fn: func(in *Interp, this *Object, args []Value) Value {
			if o, ok := this.internal.(*Object); ok && !o.freed {
				return o
			}
			return nil
		}},
	})
	wm := in.defineClass("WeakMap", "", []string{"ArrayAccess", "Countable", "IteratorAggregate"}, []nativeMethod{
		{name: "offsetExists", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*SplStorage)
			_, ok := st.get(args[0])
			return ok
		}},
		{name: "offsetGet", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*SplStorage)
			v, ok := st.get(args[0])
			if !ok {
				in.throwError("Error", fmt.Sprintf("Object %s#%d not contained in WeakMap", args[0].(*Object).class.Name, args[0].(*Object).id))
			}
			return v
		}},
		{name: "offsetSet", min: 2, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*SplStorage)
			o, ok := args[0].(*Object)
			if !ok {
				in.throwError("TypeError", "WeakMap key must be an object")
			}
			st.set(o, args[1])
			return nil
		}},
		{name: "offsetUnset", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*SplStorage)
			st.remove(args[0])
			return nil
		}},
		{name: "count", fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*SplStorage)
			return int64(len(st.order))
		}},
		{name: "getIterator", fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*SplStorage)
			// generator-like iterator over pairs: use ArrayIterator of values with object keys not possible; build Iterator object
			it := in.newObject(in.classes["arrayiterator"])
			arr := NewArray()
			for _, id := range st.order {
				e := st.items[id]
				arr.Append(e.data)
			}
			it.internal = arr
			arr.rc++
			return it
		}},
	})
	wm.internalInit = func(in *Interp, o *Object) {
		o.internal = newSplStorage()
	}
	wm.Final = true
}
