func newSplStorage() *SplStorage { return &SplStorage{items: map[int]*splEntry{}} }

func (s *SplStorage) get(k Value) (Value, bool) {
	o, ok := k.(*Object)
	if !ok {
		return nil, false
	}
	e, ok := s.items[o.id]
	if !ok {
		return nil, false
	}
	return e.data, true
}

func (s *SplStorage) set(o *Object, v Value) {
	if e, ok := s.items[o.id]; ok {
		e.data = v
		return
	}
	o.rc++
	s.items[o.id] = &splEntry{obj: o, data: v}
	s.order = append(s.order, o.id)
}

func (s *SplStorage) remove(k Value) {
	o, ok := k.(*Object)
	if !ok {
		return
	}
	if _, ok := s.items[o.id]; !ok {
		return
	}
	delete(s.items, o.id)
	for i, id := range s.order {
		if id == o.id {
			s.order = append(s.order[:i], s.order[i+1:]...)
			break
		}
	}
	decRef(o)
}

func (s *SplStorage) clone() *SplStorage {
	n := newSplStorage()
	for _, id := range s.order {
		e := s.items[id]
		n.set(e.obj, e.data)
