	sfa.internalInit = func(in *Interp, o *Object) { o.internal = &SplList{} }

	// ---- Heaps ----
	getHeap := func(o *Object) *SplHeapData {
		if h, ok := o.internal.(*SplHeapData); ok {
			return h
		}
		h := &SplHeapData{}
		o.internal = h
		return h
	}
	heapMethods := func(kind string) []nativeMethod {
		cmpFn := func(in *Interp, this *Object, a, b Value) int {
			// user compare if overridden
			if m := this.class.findMethod("compare"); m != nil && m.Fn.Native == nil {
				return int(toInt(in.callMethod(this, m, []Value{a, b})))
			}
			switch kind {
			case "min":
				return compareValues(b, a)
			case "max":
				return compareValues(a, b)
			case "pq":
				ha, hb := a.(*heapItem), b.(*heapItem)
				c := compareValues(ha.prio, hb.prio)
				if c == 0 {
					// FIFO for equal priority? PHP: undefined, but actual impl uses insertion order descending
					if ha.serial < hb.serial {
						return 1
					}
					return -1
				}
				return c
			}
			return 0
		}
		// items kept sorted descending by cmp (index 0 = top)
		insert := func(in *Interp, this *Object, v Value) {
			h := getHeap(this)
			// binary search for position
			i := sort.Search(len(h.items), func(i int) bool {
				return cmpFn(in, this, h.items[i], v) < 0
			})
			h.items = append(h.items, nil)
			copy(h.items[i+1:], h.items[i:])
			h.items[i] = v
		}
		top := func(in *Interp, this *Object) Value {
			h := getHeap(this)
			if len(h.items) == 0 {
				in.throwError("RuntimeException", "Can't peek at an empty heap")
			}
			return h.items[0]
		}
		extract := func(in *Interp, this *Object) Value {
			h := getHeap(this)
			if len(h.items) == 0 {
				in.throwError("RuntimeException", "Can't extract from an empty heap")
			}
			v := h.items[0]
			h.items = h.items[1:]
			return v
		}
		pqOut := func(in *Interp, this *Object, hi *heapItem) Value {
			h := getHeap(this)
			flags := h.serial >> 32 // reuse: store flags in high bits? simpler: props
			_ = flags
			f, _ := this.props.GetStr("\x00flags")
			fl := toInt(f)
			if fl == 0 {
				fl = 1
			}
			switch fl {
			case 1:
				return hi.v
			case 2:
				return hi.prio
			case 3:
				a := NewArray()
				a.SetStr("data", hi.v)
				a.SetStr("priority", hi.prio)
				return a
			}
			return hi.v
		}
		ms := []nativeMethod{
			{name: "count", fn: func(in *Interp, this *Object, args []Value) Value { return int64(len(getHeap(this).items)) }},
			{name: "isEmpty", fn: func(in *Interp, this *Object, args []Value) Value { return len(getHeap(this).items) == 0 }},
			{name: "rewind", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
			{name: "valid", fn: func(in *Interp, this *Object, args []Value) Value { return len(getHeap(this).items) > 0 }},
			{name: "key", fn: func(in *Interp, this *Object, args []Value) Value { return int64(len(getHeap(this).items) - 1) }},
			{name: "next", fn: func(in *Interp, this *Object, args []Value) Value {
				h := getHeap(this)
				if len(h.items) > 0 {
					v := h.items[0]
					h.items = h.items[1:]
					decRef(v)
				}
				return nil
			}},
			{name: "recoverFromCorruption", fn: func(in *Interp, this *Object, args []Value) Value { return true }},
			{name: "isCorrupted", fn: func(in *Interp, this *Object, args []Value) Value { return false }},
		}
		if kind == "pq" {
			ms = append(ms,
				nativeMethod{name: "insert", min: 2, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
					h := getHeap(this)
					h.serial++
					incRef(args[0])
					insert(in, this, &heapItem{v: args[0], prio: args[1], serial: h.serial})
					return true
				}},
				nativeMethod{name: "extract", fn: func(in *Interp, this *Object, args []Value) Value {
					hi := extract(in, this).(*heapItem)
					decRefNoFree(hi.v)
					return pqOut(in, this, hi)
				}},
				nativeMethod{name: "top", fn: func(in *Interp, this *Object, args []Value) Value {
					return pqOut(in, this, top(in, this).(*heapItem))
				}},
				nativeMethod{name: "current", fn: func(in *Interp, this *Object, args []Value) Value {
					h := getHeap(this)
					if len(h.items) == 0 {
						return nil
					}
					return pqOut(in, this, h.items[0].(*heapItem))
				}},
				nativeMethod{name: "setExtractFlags", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
					this.props.SetStr("\x00flags", toInt(args[0]))
					return nil
				}},
				nativeMethod{name: "getExtractFlags", fn: func(in *Interp, this *Object, args []Value) Value {
					f, ok := this.props.GetStr("\x00flags")
					if !ok {
						return int64(1)
					}
					return f
				}},
				nativeMethod{name: "compare", min: 2, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
					return int64(compareValues(args[0], args[1]))
				}},
				nativeMethod{name: "__debugInfo", fn: func(in *Interp, this *Object, args []Value) Value {
					h := getHeap(this)
					a := NewArray()
					f, ok := this.props.GetStr("\x00flags")
					if !ok {
						f = int64(1)
					}
					a.SetStr("\x00SplPriorityQueue\x00flags", f)
					a.SetStr("\x00SplPriorityQueue\x00isCorrupted", false)
					heap := NewArray()
					for _, it := range h.items {
						hi := it.(*heapItem)
						e := NewArray()
						e.SetStr("data", hi.v)
						e.SetStr("priority", hi.prio)
						heap.Append(e)
					}
					a.SetStr("\x00SplPriorityQueue\x00heap", heap)
					return a
				}},
			)
		} else {
			ms = append(ms,
				nativeMethod{name: "insert", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
					incRef(args[0])
					insert(in, this, args[0])
					return true
				}},
				nativeMethod{name: "extract", fn: func(in *Interp, this *Object, args []Value) Value {
					v := extract(in, this)
					decRefNoFree(v)
					return v
				}},
				nativeMethod{name: "top", fn: func(in *Interp, this *Object, args []Value) Value { return top(in, this) }},
				nativeMethod{name: "current", fn: func(in *Interp, this *Object, args []Value) Value {
					h := getHeap(this)
					if len(h.items) == 0 {
						return nil
					}
					return h.items[0]
				}},
				nativeMethod{name: "__debugInfo", fn: func(in *Interp, this *Object, args []Value) Value {
					h := getHeap(this)
					a := NewArray()
					a.SetStr("\x00SplHeap\x00flags", int64(0))
					a.SetStr("\x00SplHeap\x00isCorrupted", false)
					a.SetStr("\x00SplHeap\x00heap", NewListArray(h.items))
					return a
				}},
			)
			if kind == "min" {
				ms = append(ms, nativeMethod{name: "compare", min: 2, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
					return int64(compareValues(args[1], args[0]))
				}})
			} else {
				ms = append(ms, nativeMethod{name: "compare", min: 2, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
					return int64(compareValues(args[0], args[1]))
				}})
			}
		}
		return ms
	}
	heap := in.defineClass("SplHeap", "", []string{"Iterator", "Countable"}, heapMethods("max"))
	heap.Abstract = true
	heap.Methods["compare"].Abstract = true
	heap.internalInit = func(in *Interp, o *Object) { o.internal = &SplHeapData{} }
	minh := in.defineClass("SplMinHeap", "SplHeap", nil, heapMethods("min"))
	minh.internalInit = heap.internalInit
	maxh := in.defineClass("SplMaxHeap", "SplHeap", nil, heapMethods("max"))
	maxh.internalInit = heap.internalInit
	pq := in.defineClass("SplPriorityQueue", "", []string{"Iterator", "Countable"}, heapMethods("pq"))
	pq.internalInit = heap.internalInit
	in.addConst(pq, "EXTR_DATA", int64(1))
	in.addConst(pq, "EXTR_PRIORITY", int64(2))
	in.addConst(pq, "EXTR_BOTH", int64(3))

	// ---- SplTempFileObject / SplFileInfo minimal (skipped) ----
	in.initIteratorClasses()
}

func splObjectHash(o *Object) string {
	return fmt.Sprintf("%032x", o.id)
}
EOF
echo ok"}

