package main

import (
	"fmt"
	"sort"
)

// SplStorage: object -> data map used by SplObjectStorage / WeakMap
type splEntry struct {
	obj  *Object
	data Value
}

type SplStorage struct {
	items map[int]*splEntry
	order []int
	pos   int
}

func newSplStorage() *SplStorage { return &SplStorage{items: map[int]*splEntry{}} }

func (s *SplStorage) get(k Value) (Value, bool) {
	o, ok := k.(*Object)
	if !ok {
		return nil, false
	}
	e, ok := s.items[o.id]
	if !ok {
		return nil, false
	}
	return e.data, true
}

func (s *SplStorage) set(o *Object, v Value) {
	if e, ok := s.items[o.id]; ok {
		e.data = v
		return
	}
	o.rc++
	s.items[o.id] = &splEntry{obj: o, data: v}
	s.order = append(s.order, o.id)
}

func (s *SplStorage) remove(k Value) {
	o, ok := k.(*Object)
	if !ok {
		return
	}
	if _, ok := s.items[o.id]; !ok {
		return
	}
	delete(s.items, o.id)
	for i, id := range s.order {
		if id == o.id {
			s.order = append(s.order[:i], s.order[i+1:]...)
			break
		}
	}
	decRef(o)
}

func (s *SplStorage) clone() *SplStorage {
	n := newSplStorage()
	for _, id := range s.order {
		e := s.items[id]
		n.set(e.obj, e.data)
	}
	return n
}

// doubly linked list storage (slice based)
type SplList struct {
	items []Value
	flags int64
	pos   int
}

type SplHeapData struct {
	items []Value
	cmp   func(a, b Value) int
	serial int64
	max   bool
}

type heapItem struct {
	v      Value
	prio   Value
	serial int64
}

func (in *Interp) getStorage(o *Object) *Array {
	if a, ok := o.internal.(*Array); ok {
		return a
	}
	a := NewArray()
	a.rc++
	o.internal = a
	return a
}

func (in *Interp) initSplClasses() {
	// ---- ArrayObject / ArrayIterator ----
	arrayLike := func(name string) []nativeMethod {
		return []nativeMethod{
			{name: "__construct", max: 3, fn: func(in *Interp, this *Object, args []Value) Value {
				arr := NewArray()
				if len(args) > 0 {
					switch a := args[0].(type) {
					case *Array:
						arr = a.Clone()
					case *Object:
						if st, ok := a.internal.(*Array); ok {
							arr = st.Clone()
						} else {
							arr = in.objectToArray(a)
						}
					case nil:
					default:
						in.throwError("TypeError", fmt.Sprintf("%s::__construct(): Argument #1 ($array) must be of type array, %s given", name, typeName(args[0])))
					}
				}
				if old, ok := this.internal.(*Array); ok {
					decRef(old)
				}
				arr.rc++
				this.internal = arr
				if len(args) > 1 {
					this.props.SetStr("\x00flags", toInt(args[1]))
					this.props.Delete(StrKey("\x00flags"))
				}
				return nil
			}},
			{name: "offsetExists", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				k, ok := normalizeKey(args[0])
				if !ok {
					return false
				}
				return in.getStorage(this).Has(k)
			}},
			{name: "offsetGet", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				k, ok := normalizeKey(args[0])
				if !ok {
					return nil
				}
				v, exists := in.getStorage(this).Get(k)
				if !exists {
					if k.IsStr {
						in.warn(fmt.Sprintf("Undefined array key \"%s\"", k.S))
					} else {
						in.warn(fmt.Sprintf("Undefined array key %d", k.I))
					}
					return nil
				}
				return deref(v)
			}},
			{name: "offsetSet", min: 2, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
				st := in.getStorage(this)
				if args[0] == nil {
					st.Append(args[1])
					return nil
				}
				k, ok := normalizeKey(args[0])
				if !ok {
					in.throwError("TypeError", "Illegal offset type")
				}
				st.Set(k, args[1])
				return nil
			}},
			{name: "offsetUnset", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
