				return true
			}},
			{name: "uksort", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				in.sortArray(in.getStorage(this), "uksort", args)
				return true
			}},
			{name: "natsort", fn: func(in *Interp, this *Object, args []Value) Value {
				in.sortArray(in.getStorage(this), "natsort", args)
				return true
			}},
			{name: "natcasesort", fn: func(in *Interp, this *Object, args []Value) Value {
				in.sortArray(in.getStorage(this), "natcasesort", args)
				return true
			}},
			{name: "__serialize", fn: func(in *Interp, this *Object, args []Value) Value {
				a := NewArray()
				a.Append(int64(0))
				a.Append(in.getStorage(this).Clone())
				a.Append(NewArray())
				if name == "ArrayObject" {
					a.Append(nil)
				}
				return a
			}},
			{name: "__debugInfo", fn: func(in *Interp, this *Object, args []Value) Value {
				a := NewArray()
				a.SetStr("\x00"+name+"\x00storage", in.getStorage(this))
				return a
			}},
		}
	}
	ao := in.defineClass("ArrayObject", "", []string{"IteratorAggregate", "ArrayAccess", "Serializable", "Countable"}, arrayLike("ArrayObject"))
	in.addNativeMethod(ao, nativeMethod{name: "getIterator", fn: func(in *Interp, this *Object, args []Value) Value {
		it := in.newObject(in.classes["arrayiterator"])
