			return v
		}},
		{name: "offsetSet", min: 1, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*SplStorage)
			o, ok := args[0].(*Object)
			if !ok {
				in.throwError("TypeError", "SplObjectStorage::offsetSet(): Argument #1 ($object) must be of type object, "+typeName(args[0])+" given")
			}
