		a.SetStr("name", "{closure:"+in.closureLocation(fn.Decl, cl)+"}")
		a.SetStr("file", fn.Decl.File)
		a.SetStr("line", int64(fn.Decl.Line))
	} else {
		name := fn.Name
		if cl.method != nil {
			name = cl.method.Class.Name + "::" + fn.Name
		} else if fn.Class != nil {
			name = fn.Class.Name + "::" + fn.Name
		}
		a.SetStr("function", name)
	}
	if cl.this != nil {
		a.SetStr("this", cl.this)
	}
	if len(cl.boundOrder) > 0 {
		st := NewArray()
		for _, n := range cl.boundOrder {
			st.SetStr(n, cl.bound[n].V)
		}
		a.SetStr("static", st)
	}
	if fn.Decl != nil && len(fn.Decl.Params) > 0 {
		params := NewArray()
		for _, p := range fn.Decl.Params {
			key := "$" + p.Name
			if p.ByRef {
				key = "&$" + p.Name
			}
			if p.Default != nil || p.Variadic {
				params.SetStr(key, "<optional>")
			} else {
				params.SetStr(key, "<required>")
			}
		}
		a.SetStr("parameter", params)
	} else if fn.Decl == nil && len(fn.ParamNames) > 0 {
		params := NewArray()
		for i, p := range fn.ParamNames {
			if i < fn.MinArgs {
				params.SetStr("$"+p, "<required>")
			} else {
				params.SetStr("$"+p, "<optional>")
			}
		}
		a.SetStr("parameter", params)
