func (in *Interp) printR(v Value, indent int, sb *strings.Builder, seen map[interface{}]bool) {
	switch x := v.(type) {
	case *Array:
		if seen[x] {
			sb.WriteString("Array\n *RECURSION*")
			return
		}
		seen[x] = true
		pad := strings.Repeat(" ", indent)
		sb.WriteString("Array\n" + pad + "(\n")
		x.Each(func(k Key, val Value) bool {
			sb.WriteString(fmt.Sprintf("%s    [%s] => ", pad, k.String()))
			in.printR(deref(val), indent+8, sb, seen)
			sb.WriteString("\n")
			return true
		})
		sb.WriteString(pad + ")\n")
		delete(seen, x)
	case *Object:
		if seen[x] {
			sb.WriteString(x.class.Name + " Object\n *RECURSION*")
			return
		}
		seen[x] = true
		pad := strings.Repeat(" ", indent)
		if x.class.isEnum() {
			if x.class.EnumBacking != "" {
				sb.WriteString(x.class.Name + " Enum:" + x.class.EnumBacking + "\n" + pad + "(\n")
			} else {
				sb.WriteString(x.class.Name + " Enum\n" + pad + "(\n")
			}
		} else {
			sb.WriteString(x.class.Name + " Object\n" + pad + "(\n")
		}
		props, isDebug := in.debugProps(x)
		if cl, ok := x.internal.(*Closure); ok {
			props = in.closureDebugProps(x, cl)
			isDebug = true
		}
		props.Each(func(k Key, val Value) bool {
			if val == uninit {
				return true
			}
			name := k.String()
			if isDebug {
				n, vis, cls := splitMangled(name)
				switch vis {
				case "protected":
					sb.WriteString(fmt.Sprintf("%s    [%s:protected] => ", pad, n))
				case "private":
					sb.WriteString(fmt.Sprintf("%s    [%s:%s:private] => ", pad, n, cls))
				default:
					sb.WriteString(fmt.Sprintf("%s    [%s] => ", pad, n))
				}
			} else {
				pi := x.class.findProp(name)
				if pi == nil || pi.Visibility == "public" {
					sb.WriteString(fmt.Sprintf("%s    [%s] => ", pad, name))
				} else if pi.Visibility == "protected" {
					sb.WriteString(fmt.Sprintf("%s    [%s:protected] => ", pad, name))
				} else {
					sb.WriteString(fmt.Sprintf("%s    [%s:%s:private] => ", pad, name, pi.Class.Name))
				}
			}
			in.printR(deref(val), indent+8, sb, seen)
			sb.WriteString("\n")
			return true
		})
		sb.WriteString(pad + ")\n")
		delete(seen, x)
	case *Ref:
		in.printR(x.V, indent, sb, seen)
	default:
		sb.WriteString(in.toStr(v))
	}
}

func (in *Interp) varExport(v Value, indent int, sb *strings.Builder) {
	pad := strings.Repeat(" ", indent)
	switch x := v.(type) {
	case nil:
		sb.WriteString("NULL")
	case bool:
		if x {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
	case int64:
		if x == math.MinInt64 {
			sb.WriteString("-9223372036854775807-1")
		} else {
			sb.WriteString(intToStr(x))
		}
	case float64:
		s := formatFloatPrec(x, in.serializePrecision)
		if !strings.ContainsAny(s, ".EN") {
			s += ".0"
		}
		sb.WriteString(s)
	case string:
		sb.WriteString(exportString(x))
	case *Array:
		sb.WriteString("array (\n")
		x.Each(func(k Key, val Value) bool {
			if k.IsStr {
				sb.WriteString(fmt.Sprintf("%s  %s => ", pad, exportString(k.S)))
			} else {
				sb.WriteString(fmt.Sprintf("%s  %d => ", pad, k.I))
			}
			val = deref(val)
			switch val.(type) {
			case *Array, *Object:
				sb.WriteString("\n" + pad + "  ")
			}
			in.varExport(val, indent+2, sb)
			sb.WriteString(",\n")
			return true
		})
		sb.WriteString(pad + ")")
	case *Object:
		if x.class.isEnum() {
			sb.WriteString("\\" + x.class.Name + "::" + toStr(in.getProp(x, "name")))
			return
		}
		if x.class.lname == "stdclass" {
			sb.WriteString("(object) array(\n")
		} else {
			sb.WriteString("\\" + x.class.Name + "::__set_state(array(\n")
		}
		x.props.Each(func(k Key, val Value) bool {
			if val == uninit {
				return true
			}
			sb.WriteString(fmt.Sprintf("%s   %s => ", pad, exportString(k.String())))
			val = deref(val)
			switch val.(type) {
			case *Array, *Object:
				sb.WriteString("\n" + pad + "  ")
			}
			in.varExport(val, indent+2, sb)
			sb.WriteString(",\n")
			return true
		})
		if x.class.lname == "stdclass" {
			sb.WriteString(pad + ")")
		} else {
			sb.WriteString(pad + "))")
		}
	case *Resource:
		sb.WriteString("NULL")
	case *Ref:
		in.varExport(x.V, indent, sb)
	}
}

func exportString(s string) string {
	// PHP: single quotes, escape \ and '; NUL bytes become '' . "\0" . ''
	if strings.IndexByte(s, 0) >= 0 {
		parts := strings.Split(s, "\x00")
		var out []string
		for _, p := range parts {
			out = append(out, "'"+strings.ReplaceAll(strings.ReplaceAll(p, "\\", "\\\\"), "'", "\\'")+"'")
		}
		return strings.Join(out, " . \"\\0\" . ")
	}
	return "'" + strings.ReplaceAll(strings.ReplaceAll(s, "\\", "\\\\"), "'", "\\'") + "'"
}
