cd /workspace/src && cat > builtins_core.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"os"
	"sort"
	"strings"
	"time"
)

func (in *Interp) reg(name string, min, max int, fn NativeFn) *Function {
	f := &Function{Name: name, Native: fn, MinArgs: min, MaxArgs: max}
	in.functions[strings.ToLower(name)] = f
	return f
}

func (in *Interp) regRef(name string, min, max int, refArgs []int, fn NativeFn) *Function {
	f := in.reg(name, min, max, fn)
	f.RefArgs = refArgs
	return f
}

func (in *Interp) regCtx(name string, min, max int, fn func(in *Interp, fr *Frame, args []Value) Value) *Function {
	f := &Function{Name: name, NativeCtx: fn, MinArgs: min, MaxArgs: max}
	in.functions[strings.ToLower(name)] = f
	return f
}

func argOr(args []Value, i int, def Value) Value {
	if i < len(args) {
		if _, m := args[i].(missingArg); m {
			return def
		}
		return args[i]
	}
	return def
}

func hasArg(args []Value, i int) bool {
	if i >= len(args) {
		return false
	}
	_, m := args[i].(missingArg)
	return !m
}

func nowFloat() float64 {
	return float64(time.Now().UnixNano()) / 1e9
}

func (in *Interp) newResource(kind string, data interface{}) *Resource {
	r := &Resource{id: in.nextResID, kind: kind, data: data}
	in.nextResID++
	return r
}

// expectArray validates an array argument for a function
func (in *Interp) argArray(fname string, args []Value, i int) *Array {
	if i >= len(args) {
		in.throwError("ArgumentCountError", fmt.Sprintf("%s() expects at least %d arguments, %d given", fname, i+1, len(args)))
	}
	a, ok := deref(args[i]).(*Array)
	if !ok {
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type array, %s given", fname, i+1, in.argName(fname, i), typeNameForError(deref(args[i]))))
	}
	return a
}

var argNames = map[string][]string{}

func (in *Interp) argName(fname string, i int) string {
	if names, ok := argNames[strings.ToLower(fname)]; ok && i < len(names) {
		return " ($" + names[i] + ")"
	}
	return ""
}

func (in *Interp) argStr(fname string, args []Value, i int) string {
	v := deref(args[i])
	switch x := v.(type) {
	case string:
		return x
	case nil:
		in.deprecated(fmt.Sprintf("%s(): Passing null to parameter #%d%s of type string is deprecated", fname, i+1, in.argName(fname, i)))
		return ""
	case *Array:
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type string, array given", fname, i+1, in.argName(fname, i)))
	case *Object:
		if x.class.findMethod("__tostring") != nil {
			return in.objectToString(x)
		}
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type string, %s given", fname, i+1, in.argName(fname, i), x.class.Name))
	}
	return in.toStr(v)
}

func (in *Interp) argInt(fname string, args []Value, i int) int64 {
	v := deref(args[i])
	switch x := v.(type) {
	case int64:
		return x
	case float64:
		if !floatFitsInt(x) {
			in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type int, float given", fname, i+1, in.argName(fname, i)))
		}
		if x != math.Trunc(x) {
			in.deprecated(fmt.Sprintf("Implicit conversion from float %s to int loses precision", formatFloatRepr(x)))
		}
		return int64(x)
	case nil:
		in.deprecated(fmt.Sprintf("%s(): Passing null to parameter #%d%s of type int is deprecated", fname, i+1, in.argName(fname, i)))
		return 0
	case bool:
		return toInt(x)
	case string:
		ni := parseNumeric(x)
		if !ni.ok || !ni.whole {
			in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type int, string given", fname, i+1, in.argName(fname, i)))
		}
		if ni.isInt {
			return ni.i
		}
		if ni.f != math.Trunc(ni.f) {
			in.deprecated(fmt.Sprintf("Implicit conversion from float-string \"%s\" to int loses precision", x))
		}
		return int64(ni.f)
	case *Array:
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type int, array given", fname, i+1, in.argName(fname, i)))
	case *Object:
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type int, %s given", fname, i+1, in.argName(fname, i), x.class.Name))
	}
	return toInt(v)
}

func (in *Interp) argFloat(fname string, args []Value, i int) float64 {
	v := deref(args[i])
	switch x := v.(type) {
	case int64:
		return float64(x)
	case float64:
		return x
	case nil:
		in.deprecated(fmt.Sprintf("%s(): Passing null to parameter #%d%s of type float is deprecated", fname, i+1, in.argName(fname, i)))
		return 0
	case bool:
		return toFloat(x)
	case string:
		ni := parseNumeric(x)
		if !ni.ok || !ni.whole {
			in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type float, string given", fname, i+1, in.argName(fname, i)))
		}
		return ni.f
	case *Array:
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type float, array given", fname, i+1, in.argName(fname, i)))
	case *Object:
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type float, %s given", fname, i+1, in.argName(fname, i), x.class.Name))
	}
	return toFloat(v)
}

func (in *Interp) argBool(fname string, args []Value, i int) bool {
	v := deref(args[i])
	switch x := v.(type) {
	case *Array:
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type bool, array given", fname, i+1, in.argName(fname, i)))
	case *Object:
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type bool, %s given", fname, i+1, in.argName(fname, i), x.class.Name))
	}
	return toBool(v)
}

func (in *Interp) argCallable(fname string, args []Value, i int) Value {
	v := deref(args[i])
	if !in.isCallable(v, in.frame.caller) {
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be a valid callback, %s", fname, i+1, in.argName(fname, i), in.callableError(v)))
	}
	return v
}

func (in *Interp) callableError(v Value) string {
	switch x := v.(type) {
	case string:
		if idx := strings.Index(x, "::"); idx > 0 {
			if in.lookupClass(x[:idx]) == nil {
				return fmt.Sprintf("class \"%s\" not found", x[:idx])
			}
			return fmt.Sprintf("class %s does not have a method \"%s\"", in.lookupClass(x[:idx]).Name, x[idx+2:])
		}
		return fmt.Sprintf("function \"%s\" not found or invalid function name", x)
	case *Array:
		if x.Len() != 2 {
			return "array callback must have exactly two members"
		}
		first, _ := x.Get(IntKey(0))
		second, _ := x.Get(IntKey(1))
		if o, ok := deref(first).(*Object); ok {
			return fmt.Sprintf("class %s does not have a method \"%s\"", o.class.Name, toStr(deref(second)))
		}
		if s, ok := deref(first).(string); ok {
			if c := in.lookupClass(s); c != nil {
				return fmt.Sprintf("class %s does not have a method \"%s\"", c.Name, toStr(deref(second)))
			}
			return fmt.Sprintf("class \"%s\" not found", s)
		}
		return "first array member is not a valid class name or object"
	case *Object:
		return "no array or string given"
	}
	return "no array or string given"
}

