func (in *Interp) initCoreFunctions() {
	in.regCtx("func_get_args", 0, 0, func(in *Interp, fr *Frame, args []Value) Value {
		if fr == nil || fr.fn == nil {
			in.throwError("Error", "func_get_args() cannot be called from the global scope")
		}
		arr := NewArray()
		for _, a := range fr.args {
			if _, m := a.(missingArg); m {
				continue
			}
			arr.Append(deref(a))
		}
		return arr
	})
	in.regCtx("func_num_args", 0, 0, func(in *Interp, fr *Frame, args []Value) Value {
		if fr == nil || fr.fn == nil {
			in.throwError("Error", "func_num_args() must be called from a function context")
		}
		return int64(len(fr.args))
	})
	in.regCtx("func_get_arg", 1, 1, func(in *Interp, fr *Frame, args []Value) Value {
		i := toInt(args[0])
		if fr == nil || fr.fn == nil {
			in.throwError("Error", "func_get_arg() cannot be called from the global scope")
		}
		if i < 0 || int(i) >= len(fr.args) {
			in.throwError("ValueError", "func_get_arg(): Argument #1 ($position) must be less than the number of the arguments passed to the currently executed function")
		}
		return deref(fr.args[i])
	})
	in.regCtx("compact", 0, -1, func(in *Interp, fr *Frame, args []Value) Value {
		arr := NewArray()
		var add func(v Value)
		add = func(v Value) {
			switch x := deref(v).(type) {
			case string:
				if r, ok := fr.vars[x]; ok {
					arr.SetStr(x, r.V)
				} else if x == "this" && fr.this != nil {
					arr.SetStr(x, fr.this)
				} else {
					in.warn(fmt.Sprintf("compact(): Undefined variable $%s", x))
				}
			case *Array:
				x.Each(func(_ Key, val Value) bool {
					add(val)
					return true
				})
			}
		}
		for _, a := range args {
			add(a)
		}
		return arr
	})
	in.regCtx("extract", 1, 3, func(in *Interp, fr *Frame, args []Value) Value {
		arr, ok := deref(args[0]).(*Array)
		if !ok {
			in.throwError("TypeError", "extract(): Argument #1 ($array) must be of type array, "+typeName(deref(args[0]))+" given")
		}
		flags := int64(0)
		if len(args) > 1 {
			flags = toInt(args[1])
		}
		prefix := ""
		if len(args) > 2 {
			prefix = toStr(args[2])
		}
		n := 0
		arr.Each(func(k Key, v Value) bool {
			if !k.IsStr {
				if flags == 2 || flags == 3 { // EXTR_PREFIX_ALL / PREFIX_INVALID
					name := prefix + "_" + k.String()
					in.assignVar(fr, name, deref(v))
					n++
				}
				return true
			}
			name := k.S
			_, exists := fr.vars[name]
			switch flags {
			case 1: // EXTR_SKIP
				if exists {
					return true
				}
			case 2: // EXTR_PREFIX_SAME
				if exists {
					name = prefix + "_" + name
				}
			case 3: // EXTR_PREFIX_ALL
				name = prefix + "_" + name
			}
			if !isSimpleName(name) || name == "this" {
				return true
			}
			if flags == 256 { // EXTR_REFS
				in.bindRef(fr, &VarExpr{Name: name}, arr.GetRef(k))
			} else {
				in.assignVar(fr, name, deref(v))
			}
			n++
			return true
		})
		return int64(n)
	})
	in.regCtx("get_defined_vars", 0, 0, func(in *Interp, fr *Frame, args []Value) Value {
		arr := NewArray()
		if fr.vars == in.globals {
			for _, name := range in.globalOrder {
				if r, ok := in.globals[name]; ok {
					arr.SetStr(name, r.V)
				}
			}
			return arr
		}
		names := make([]string, 0, len(fr.vars))
		for n := range fr.vars {
			names = append(names, n)
		}
		// order: params first then others... approximate with declaration order unknown; use param order then sorted
		var ordered []string
		if fr.fn != nil && fr.fn.Decl != nil {
			for _, p := range fr.fn.Decl.Params {
				ordered = append(ordered, p.Name)
			}
		}
		seen := map[string]bool{}
		for _, n := range ordered {
			if _, ok := fr.vars[n]; ok {
				arr.SetStr(n, fr.vars[n].V)
				seen[n] = true
			}
		}
		sort.Strings(names)
		for _, n := range names {
			if !seen[n] {
				arr.SetStr(n, fr.vars[n].V)
			}
		}
		return arr
	})
