	in.reg("call_user_func_array", 2, 2, func(in *Interp, args []Value) Value {
		in.argCallable("call_user_func_array", args, 0)
		arr := in.argArray("call_user_func_array", args, 1)
		var pos []Value
		var named map[string]Value
		arr.Each(func(k Key, v Value) bool {
