func (in *Interp) applyIni(name, val string) {
	switch name {
	case "precision":
		in.precision = int(toInt(val))
	case "serialize_precision":
		in.serializePrecision = int(toInt(val))
	case "error_reporting":
		in.errorReporting = toInt(val)
	case "date.timezone":
		in.timezone = val
	}
}

func versionCompare(a, b string) int {
	canon := func(s string) []string {
		// insert '.' between transitions, replace -_+ with .
		var sb strings.Builder
		prev := byte(0)
		for i := 0; i < len(s); i++ {
			c := s[i]
			if c == '-' || c == '_' || c == '+' {
				c = '.'
			}
			if i > 0 && c != '.' && prev != '.' {
				pd := isDigit(prev)
				cd := isDigit(c)
				if pd != cd {
					sb.WriteByte('.')
				}
			}
			sb.WriteByte(c)
			prev = c
		}
		parts := strings.Split(sb.String(), ".")
		var out []string
		for _, p := range parts {
			if p != "" {
				out = append(out, p)
			}
		}
		return out
	}
	order := func(s string) int {
		switch {
		case strings.HasPrefix(s, "dev"):
			return 0
		case strings.HasPrefix(s, "alpha"), strings.HasPrefix(s, "a"):
			return 1
		case strings.HasPrefix(s, "beta"), strings.HasPrefix(s, "b"):
			return 2
		case strings.HasPrefix(s, "RC"), strings.HasPrefix(s, "rc"):
			return 3
		case s == "#":
			return 4
		case strings.HasPrefix(s, "pl"), strings.HasPrefix(s, "p"):
			return 5
		}
		return -1
	}
	pa, pb := canon(a), canon(b)
	n := len(pa)
	if len(pb) > n {
		n = len(pb)
	}
	for i := 0; i < n; i++ {
		var x, y string
		if i < len(pa) {
			x = pa[i]
		}
		if i < len(pb) {
			y = pb[i]
		}
		if x == "" && y == "" {
			continue
		}
		xd := x != "" && isDigit(x[0])
		yd := y != "" && isDigit(y[0])
		var c int
		switch {
		case x == "":
			if yd {
				c = -1
			} else {
				c = -cmpInt(int64(order(y)), 4)
				if order(y) < 4 {
					c = 1
				} else {
					c = -1
				}
			}
		case y == "":
			if xd {
				c = 1
			} else {
				if order(x) < 4 {
					c = -1
				} else {
					c = 1
				}
			}
		case xd && yd:
			c = cmpInt(toInt(x), toInt(y))
		case !xd && !yd:
			c = cmpInt(int64(order(x)), int64(order(y)))
		case xd:
			// number vs special: number is "#"
			c = cmpInt(4, int64(order(y)))
		default:
			c = cmpInt(int64(order(x)), 4)
		}
		if c != 0 {
			return c
		}
	}
	return 0
}

