func strToIntBase(s string, base int) int64 {
	s = strings.TrimSpace(s)
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	if base == 0 {
		if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
			base = 16
			s = s[2:]
		} else if strings.HasPrefix(s, "0b") || strings.HasPrefix(s, "0B") {
			base = 2
			s = s[2:]
		} else if strings.HasPrefix(s, "0o") || strings.HasPrefix(s, "0O") {
			base = 8
			s = s[2:]
		} else if strings.HasPrefix(s, "0") && len(s) > 1 {
			base = 8
			s = s[1:]
		} else {
			base = 10
		}
	} else if base == 16 {
		if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
			s = s[2:]
		}
	} else if base == 2 {
		if strings.HasPrefix(s, "0b") || strings.HasPrefix(s, "0B") {
			s = s[2:]
		}
	} else if base == 8 {
		if strings.HasPrefix(s, "0o") || strings.HasPrefix(s, "0O") {
			s = s[2:]
		}
	}
	var v int64
	overflow := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'z':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'Z':
			d = int(c-'A') + 10
		default:
			d = 99
		}
		if d >= base {
			break
		}
		nv := v*int64(base) + int64(d)
		if nv < v {
			overflow = true
			break
		}
		v = nv
	}
	if overflow {
		if neg {
			return math.MinInt64
		}
		return math.MaxInt64
	}
	if neg {
		return -v
	}
	return v
}

// ---------- serialize ----------

func (in *Interp) serialize(v Value, sb *strings.Builder) {
	switch x := v.(type) {
	case nil:
		sb.WriteString("N;")
	case bool:
		if x {
			sb.WriteString("b:1;")
		} else {
			sb.WriteString("b:0;")
		}
	case int64:
		sb.WriteString(fmt.Sprintf("i:%d;", x))
	case float64:
		sb.WriteString("d:" + formatFloatPrec(x, in.serializePrecision) + ";")
	case string:
		sb.WriteString(fmt.Sprintf("s:%d:\"%s\";", len(x), x))
	case *Array:
		sb.WriteString(fmt.Sprintf("a:%d:{", x.Len()))
		x.Each(func(k Key, val Value) bool {
			if k.IsStr {
				sb.WriteString(fmt.Sprintf("s:%d:\"%s\";", len(k.S), k.S))
			} else {
				sb.WriteString(fmt.Sprintf("i:%d;", k.I))
			}
			in.serialize(deref(val), sb)
			return true
		})
		sb.WriteString("}")
	case *Object:
		if x.class.isEnum() {
			name := toStr(in.getProp(x, "name"))
			s := x.class.Name + ":" + name
			sb.WriteString(fmt.Sprintf("E:%d:\"%s\";", len(s), s))
			return
		}
		if _, ok := x.internal.(*Closure); ok {
			in.throwError("Exception", "Serialization of 'Closure' is not allowed")
		}
		if m := x.class.findMethod("__serialize"); m != nil {
			r := in.callMethod(x, m, nil)
			arr, ok := r.(*Array)
			if !ok {
				in.throwError("TypeError", fmt.Sprintf("%s::__serialize() must return an array", x.class.Name))
			}
			sb.WriteString(fmt.Sprintf("O:%d:\"%s\":%d:{", len(x.class.Name), x.class.Name, arr.Len()))
			arr.Each(func(k Key, val Value) bool {
				if k.IsStr {
					sb.WriteString(fmt.Sprintf("s:%d:\"%s\";", len(k.S), k.S))
				} else {
					sb.WriteString(fmt.Sprintf("i:%d;", k.I))
				}
				in.serialize(deref(val), sb)
				return true
			})
			sb.WriteString("}")
			return
		}
		if x.class.instanceOf("Serializable") {
			if m := x.class.findMethod("serialize"); m != nil {
				r := in.callMethod(x, m, nil)
				s := toStr(r)
				sb.WriteString(fmt.Sprintf("C:%d:\"%s\":%d:{%s}", len(x.class.Name), x.class.Name, len(s), s))
				return
			}
		}
		var names []string
		if m := x.class.findMethod("__sleep"); m != nil {
			r := in.callMethod(x, m, nil)
			arr, ok := r.(*Array)
			if !ok {
				in.throwError("TypeError", fmt.Sprintf("%s::__sleep() should return an array only containing the names of instance-variables to serialize", x.class.Name))
			}
			for _, n := range arr.ValuesDeref() {
				names = append(names, toStr(n))
			}
		} else {
			x.props.Each(func(k Key, val Value) bool {
				if val != uninit {
					names = append(names, k.String())
				}
				return true
			})
		}
		sb.WriteString(fmt.Sprintf("O:%d:\"%s\":%d:{", len(x.class.Name), x.class.Name, len(names)))
		for _, n := range names {
			val, ok := x.props.Get(StrKey(n))
			if !ok {
				in.warn(fmt.Sprintf("serialize(): \"%s\" returned as member variable from __sleep() but does not exist", n))
				continue
			}
			key := n
			pi := x.class.findProp(n)
			if pi != nil {
				if pi.Visibility == "private" {
					key = "\x00" + pi.Class.Name + "\x00" + n
				} else if pi.Visibility == "protected" {
					key = "\x00*\x00" + n
				}
			}
			sb.WriteString(fmt.Sprintf("s:%d:\"%s\";", len(key), key))
			in.serialize(deref(val), sb)
		}
		sb.WriteString("}")
	default:
		sb.WriteString("i:0;")
	}
}

type unserializer struct {
	in  *Interp
	s   string
	pos int
}

func (u *unserializer) readUntil(c byte) (string, bool) {
	i := strings.IndexByte(u.s[u.pos:], c)
	if i < 0 {
		return "", false
	}
	r := u.s[u.pos : u.pos+i]
	u.pos += i + 1
	return r, true
}

func (u *unserializer) expect(c byte) bool {
	if u.pos < len(u.s) && u.s[u.pos] == c {
		u.pos++
		return true
	}
	return false
}

func (u *unserializer) parse() (Value, bool) {
	if u.pos >= len(u.s) {
		return nil, false
	}
	t := u.s[u.pos]
	switch t {
	case 'N':
		u.pos++
		if !u.expect(';') {
			return nil, false
		}
		return nil, true
	case 'b', 'i', 'd':
		u.pos++
		if !u.expect(':') {
			return nil, false
		}
		s, ok := u.readUntil(';')
		if !ok {
			return nil, false
		}
		switch t {
		case 'b':
			return s == "1", true
		case 'i':
			ni := parseNumeric(s)
			if !ni.ok {
				return nil, false
			}
			if ni.isInt {
				return ni.i, true
			}
			return ni.f, true
		case 'd':
			switch s {
			case "INF":
				return math.Inf(1), true
			case "-INF":
				return math.Inf(-1), true
			case "NAN":
				return math.NaN(), true
			}
			return toFloat(s), true
		}
	case 's':
		u.pos++
		if !u.expect(':') {
			return nil, false
		}
		ls, ok := u.readUntil(':')
		if !ok {
			return nil, false
		}
		n := int(toInt(ls))
		if !u.expect('"') || u.pos+n > len(u.s) {
			return nil, false
		}
		str := u.s[u.pos : u.pos+n]
		u.pos += n
		if !u.expect('"') || !u.expect(';') {
			return nil, false
		}
		return str, true
	case 'a':
		u.pos++
		if !u.expect(':') {
			return nil, false
		}
		ls, ok := u.readUntil(':')
		if !ok {
			return nil, false
		}
		n := int(toInt(ls))
		if !u.expect('{') {
			return nil, false
		}
		arr := NewArray()
		for i := 0; i < n; i++ {
			k, ok := u.parse()
			if !ok {
				return nil, false
			}
			v, ok := u.parse()
			if !ok {
				return nil, false
			}
			key, ok := normalizeKey(k)
			if !ok {
				return nil, false
			}
			arr.Set(key, v)
		}
		if !u.expect('}') {
			return nil, false
		}
		return arr, true
	case 'O', 'C':
		u.pos++
		if !u.expect(':') {
			return nil, false
		}
		ls, ok := u.readUntil(':')
		if !ok {
			return nil, false
		}
		n := int(toInt(ls))
		if !u.expect('"') || u.pos+n > len(u.s) {
			return nil, false
		}
		cname := u.s[u.pos : u.pos+n]
		u.pos += n
		if !u.expect('"') || !u.expect(':') {
			return nil, false
		}
		cs, ok := u.readUntil(':')
		if !ok {
			return nil, false
		}
		cnt := int(toInt(cs))
		if !u.expect('{') {
			return nil, false
		}
		cls := u.in.lookupClass(cname)
		if cls == nil {
			cls = u.in.classes["__php_incomplete_class"]
			if cls == nil {
				cls = u.in.defineClass("__PHP_Incomplete_Class", "", nil, nil)
				cls.autoProps = true
			}
		}
		if t == 'C' {
			data := u.s[u.pos : u.pos+cnt]
			u.pos += cnt
			if !u.expect('}') {
				return nil, false
			}
			obj := u.in.newObject(cls)
			u.in.initProps(obj, cls)
			if m := cls.findMethod("unserialize"); m != nil {
				u.in.callMethod(obj, m, []Value{data})
			}
			return obj, true
		}
		obj := u.in.newObject(cls)
		u.in.initProps(obj, cls)
		if cls.internalInit != nil {
			cls.internalInit(u.in, obj)
		}
		data := NewArray()
		for i := 0; i < cnt; i++ {
			k, ok := u.parse()
			if !ok {
				return nil, false
			}
			v, ok := u.parse()
			if !ok {
				return nil, false
			}
			key, _ := normalizeKey(k)
			data.Set(key, v)
		}
		if !u.expect('}') {
			return nil, false
		}
		if m := cls.findMethod("__unserialize"); m != nil {
			u.in.callMethod(obj, m, []Value{data})
		} else {
			data.Each(func(k Key, v Value) bool {
				name, _, _ := splitMangled(k.String())
				obj.props.SetStr(name, deref(v))
				return true
			})
			if m := cls.findMethod("__wakeup"); m != nil {
				u.in.callMethod(obj, m, nil)
			}
		}
		return obj, true
	case 'E':
		u.pos++
		if !u.expect(':') {
			return nil, false
		}
		ls, ok := u.readUntil(':')
		if !ok {
			return nil, false
		}
		n := int(toInt(ls))
		if !u.expect('"') || u.pos+n > len(u.s) {
			return nil, false
		}
		s := u.s[u.pos : u.pos+n]
		u.pos += n
		if !u.expect('"') || !u.expect(';') {
			return nil, false
		}
		idx := strings.Index(s, ":")
		if idx < 0 {
			return nil, false
		}
		cls := u.in.lookupClass(s[:idx])
		if cls == nil || !cls.isEnum() {
			return nil, false
		}
		o, ok := cls.EnumCaseObjs[s[idx+1:]]
		if !ok {
			return nil, false
		}
		return o, true
	}
	return nil, false
}
