	})
	in.regCtx("get_object_vars", 1, 1, func(in *Interp, fr *Frame, args []Value) Value {
		o, ok := args[0].(*Object)
		if !ok {
			in.throwError("TypeError", "get_object_vars(): Argument #1 ($object) must be of type object, "+typeName(args[0])+" given")
		}
		arr := NewArray()
		for _, kv := range in.visibleProps(o, fr.class) {
			if kv.v == uninit {
				continue
			}
			if i, isInt := isIntKeyString(kv.k); isInt {
				arr.SetInt(i, deref(kv.v))
			} else {
				arr.SetStr(kv.k, deref(kv.v))
			}
		}
		return arr
	})
	in.regCtx("get_class_vars", 1, 1, func(in *Interp, fr *Frame, args []Value) Value {
		cls := in.lookupClass(toStr(args[0]))
		if cls == nil {
			return false
		}
		arr := NewArray()
		for _, pi := range cls.Props {
			if pi.Visibility != "public" && !(fr.class != nil && (fr.class == pi.Class || fr.class.isSubclassOf(pi.Class))) {
				continue
			}
			var v Value
			if pi.Decl != nil && pi.Decl.HasDefault {
				v = in.eval(&Frame{vars: map[string]*Ref{}, class: pi.Class, staticClass: cls, file: fr.file}, pi.Decl.Default)
			} else if pi.Type != nil {
				continue
			}
			arr.SetStr(pi.Name, v)
		}
		for _, n := range cls.StaticOrder {
			pi := cls.StaticPropInfo[n]
			if pi.Visibility != "public" && !(fr.class != nil && (fr.class == pi.Class || fr.class.isSubclassOf(pi.Class))) {
				continue
			}
			arr.SetStr(n, cls.StaticProps[n].V)
		}
		return arr
	})
	in.regCtx("get_class_methods", 1, 1, func(in *Interp, fr *Frame, args []Value) Value {
		var cls *Class
		switch x := args[0].(type) {
		case *Object:
			cls = x.class
		case string:
			cls = in.lookupClass(x)
		}
		if cls == nil {
			in.throwError("TypeError", "get_class_methods(): Argument #1 ($object_or_class) must be an object or a valid class name, "+typeName(args[0])+" given")
		}
		arr := NewArray()
		for _, mn := range cls.MethodOrder {
			m := cls.Methods[mn]
			if m.Visibility == "public" || in.methodAccessible(m, fr.class) {
				arr.Append(m.Name)
			}
		}
		return arr
	})
	in.reg("method_exists", 2, 2, func(in *Interp, args []Value) Value {
		var cls *Class
		switch x := args[0].(type) {
		case *Object:
			cls = x.class
		case string:
			cls = in.lookupClass(x)
		default:
			in.throwError("TypeError", "method_exists(): Argument #1 ($object_or_class) must be of type object|string, "+typeName(args[0])+" given")
		}
		if cls == nil {
			return false
		}
		if cls.lname == "closure" && strings.ToLower(toStr(args[1])) == "__invoke" {
			return true
		}
		return cls.findMethod(strings.ToLower(toStr(args[1]))) != nil
	})
	in.reg("property_exists", 2, 2, func(in *Interp, args []Value) Value {
		name := toStr(args[1])
		switch x := args[0].(type) {
		case *Object:
			if x.class.findProp(name) != nil {
				return true
			}
			if _, ok := x.class.StaticProps[name]; ok {
				return true
			}
			_, ok := x.props.Get(StrKey(name))
			return ok
		case string:
			cls := in.lookupClass(x)
			if cls == nil {
				return false
			}
			if cls.findProp(name) != nil {
				return true
			}
			_, ok := cls.findStaticProp(name)
			return ok != nil
		}
		in.throwError("TypeError", "property_exists(): Argument #1 ($object_or_class) must be of type object|string, "+typeName(args[0])+" given")
		return false
	})
	in.reg("class_exists", 1, 2, func(in *Interp, args []Value) Value {
		name := toStr(args[0])
		var c *Class
		if len(args) > 1 && !toBool(args[1]) {
			c = in.classes[strings.ToLower(strings.TrimPrefix(name, "\\"))]
		} else {
			c = in.lookupClass(name)
		}
		return c != nil && c.Kind == "class"
	})
	in.reg("interface_exists", 1, 2, func(in *Interp, args []Value) Value {
		c := in.lookupClass(toStr(args[0]))
		return c != nil && c.Kind == "interface"
	})
	in.reg("trait_exists", 1, 2, func(in *Interp, args []Value) Value {
		c := in.lookupClass(toStr(args[0]))
		return c != nil && c.Kind == "trait"
	})
	in.reg("enum_exists", 1, 2, func(in *Interp, args []Value) Value {
		c := in.lookupClass(toStr(args[0]))
		return c != nil && c.Kind == "enum"
	})
	in.reg("get_declared_classes", 0, 0, func(in *Interp, args []Value) Value {
		arr := NewArray()
		names := []string{}
		for _, c := range in.classes {
			if c.Kind == "class" {
				names = append(names, c.Name)
			}
		}
		sort.Strings(names)
		for _, n := range names {
			arr.Append(n)
		}
		return arr
	})
	in.reg("get_declared_interfaces", 0, 0, func(in *Interp, args []Value) Value {
		arr := NewArray()
		for _, c := range in.classes {
			if c.Kind == "interface" {
				arr.Append(c.Name)
			}
		}
		return arr
	})
	in.reg("is_a", 2, 3, func(in *Interp, args []Value) Value {
		allowStr := len(args) > 2 && toBool(args[2])
		var cls *Class
		switch x := args[0].(type) {
		case *Object:
			cls = x.class
		case string:
			if !allowStr {
				return false
			}
			cls = in.lookupClass(x)
		}
		if cls == nil {
			return false
		}
		target := in.lookupClass(toStr(args[1]))
		if target == nil {
			return false
		}
		return cls.isSubclassOf(target)
	})
	in.reg("is_subclass_of", 2, 3, func(in *Interp, args []Value) Value {
		var cls *Class
		switch x := args[0].(type) {
		case *Object:
			cls = x.class
		case string:
			cls = in.lookupClass(x)
		}
		if cls == nil {
			return false
		}
		target := in.lookupClass(toStr(args[1]))
		if target == nil || target == cls {
			return false
		}
		return cls.isSubclassOf(target)
	})
	in.reg("class_implements", 1, 2, func(in *Interp, args []Value) Value {
		var cls *Class
		switch x := args[0].(type) {
		case *Object:
			cls = x.class
		case string:
			cls = in.lookupClass(x)
		}
		if cls == nil {
			in.warn("class_implements(): Class " + toStr(args[0]) + " does not exist and could not be loaded")
			return false
		}
		arr := NewArray()
		for _, i := range cls.Interfaces {
			arr.SetStr(i.Name, i.Name)
		}
		return arr
	})
	in.reg("class_parents", 1, 2, func(in *Interp, args []Value) Value {
		var cls *Class
		switch x := args[0].(type) {
		case *Object:
			cls = x.class
		case string:
			cls = in.lookupClass(x)
		}
