	})
	in.reg("class_uses", 1, 2, func(in *Interp, args []Value) Value {
		var cls *Class
		switch x := args[0].(type) {
		case *Object:
			cls = x.class
		case string:
			cls = in.lookupClass(x)
		}
		if cls == nil {
			return false
		}
		arr := NewArray()
		if cls.Decl != nil {
			for _, tu := range cls.Decl.Traits {
				for _, n := range tu.Names {
					if t := in.lookupClass(n); t != nil {
						arr.SetStr(t.Name, t.Name)
					}
				}
			}
		}
		return arr
	})
	in.reg("class_alias", 2, 3, func(in *Interp, args []Value) Value {
