package main

import (
	"strings"
)

func (in *Interp) initOutputFunctions() {
	in.reg("ob_start", 0, 3, func(in *Interp, args []Value) Value {
		ob := &OutBuffer{name: "default output handler"}
		if len(args) > 0 && args[0] != nil {
			ob.callback = args[0]
			ob.name = "Closure::__invoke"
			if s, ok := args[0].(string); ok {
				ob.name = s
			}
		}
		in.out.stack = append(in.out.stack, ob)
		return true
	})
	in.reg("ob_get_clean", 0, 0, func(in *Interp, args []Value) Value {
		if len(in.out.stack) == 0 {
			return false
		}
		ob := in.out.stack[len(in.out.stack)-1]
		in.out.stack = in.out.stack[:len(in.out.stack)-1]
		return ob.buf.String()
	})
	in.reg("ob_get_contents", 0, 0, func(in *Interp, args []Value) Value {
		if len(in.out.stack) == 0 {
			return false
		}
		return in.out.stack[len(in.out.stack)-1].buf.String()
	})
	in.reg("ob_get_length", 0, 0, func(in *Interp, args []Value) Value {
		if len(in.out.stack) == 0 {
			return false
		}
		return int64(in.out.stack[len(in.out.stack)-1].buf.Len())
	})
	in.reg("ob_get_level", 0, 0, func(in *Interp, args []Value) Value {
		return int64(len(in.out.stack))
	})
	flushTop := func(in *Interp, keep bool) bool {
		if len(in.out.stack) == 0 {
			return false
		}
		ob := in.out.stack[len(in.out.stack)-1]
		s := ob.buf.String()
		if ob.callback != nil {
			r := in.callValue(ob.callback, []Value{s, int64(8)})
			if r != false {
				s = in.toStr(r)
			}
		}
		if !keep {
			in.out.stack = in.out.stack[:len(in.out.stack)-1]
		} else {
			ob.buf.Reset()
		}
		in.out.Write(s)
		return true
	}
	in.reg("ob_end_flush", 0, 0, func(in *Interp, args []Value) Value {
		if len(in.out.stack) == 0 {
			in.notice("ob_end_flush(): Failed to delete and flush buffer. No buffer to delete or flush")
			return false
		}
		return flushTop(in, false)
	})
	in.reg("ob_flush", 0, 0, func(in *Interp, args []Value) Value {
		if len(in.out.stack) == 0 {
			in.notice("ob_flush(): Failed to flush buffer. No buffer to flush")
			return false
		}
		return flushTop(in, true)
	})
	in.reg("ob_get_flush", 0, 0, func(in *Interp, args []Value) Value {
		if len(in.out.stack) == 0 {
			return false
		}
		s := in.out.stack[len(in.out.stack)-1].buf.String()
		flushTop(in, false)
		return s
	})
	in.reg("ob_end_clean", 0, 0, func(in *Interp, args []Value) Value {
		if len(in.out.stack) == 0 {
			in.notice("ob_end_clean(): Failed to delete buffer. No buffer to delete")
			return false
		}
		in.out.stack = in.out.stack[:len(in.out.stack)-1]
		return true
	})
	in.reg("ob_clean", 0, 0, func(in *Interp, args []Value) Value {
		if len(in.out.stack) == 0 {
			in.notice("ob_clean(): Failed to delete buffer. No buffer to delete")
			return false
		}
		in.out.stack[len(in.out.stack)-1].buf.Reset()
		return true
	})
	in.reg("ob_list_handlers", 0, 0, func(in *Interp, args []Value) Value {
		arr := NewArray()
		for _, ob := range in.out.stack {
			arr.Append(ob.name)
		}
		return arr
	})
	in.reg("ob_get_status", 0, 1, func(in *Interp, args []Value) Value {
		arr := NewArray()
		if len(in.out.stack) == 0 {
			return arr
		}
		ob := in.out.stack[len(in.out.stack)-1]
		arr.SetStr("name", ob.name)
		arr.SetStr("type", int64(0))
		arr.SetStr("flags", int64(112))
		arr.SetStr("level", int64(len(in.out.stack)-1))
		arr.SetStr("chunk_size", int64(0))
		arr.SetStr("buffer_size", int64(16384))
		arr.SetStr("buffer_used", int64(ob.buf.Len()))
		return arr
	})
	in.reg("output_add_rewrite_var", 2, 2, func(in *Interp, args []Value) Value { return true })
	in.reg("output_reset_rewrite_vars", 0, 0, func(in *Interp, args []Value) Value { return true })
	_ = strings.ToLower
}

// flushAllBuffers at shutdown
func (in *Interp) flushAllBuffers() {
	for len(in.out.stack) > 0 {
		ob := in.out.stack[len(in.out.stack)-1]
		s := ob.buf.String()
		if ob.callback != nil {
			r := in.callValue(ob.callback, []Value{s, int64(8)})
			if r != false {
				s = in.toStr(r)
			}
		}
		in.out.stack = in.out.stack[:len(in.out.stack)-1]
		in.out.Write(s)
	}
}
EOF
echo ok"}

