// MT19937 as implemented by PHP (mt_rand)
type MtRand struct {
	state [624]uint32
	index int
	seeded bool
}

func (m *MtRand) seed(s uint32) {
	m.state[0] = s
	for i := 1; i < 624; i++ {
		m.state[i] = 1812433253*(m.state[i-1]^(m.state[i-1]>>30)) + uint32(i)
	}
	m.reload()
	m.seeded = true
}

func (m *MtRand) reload() {
	const N, M = 624, 397
	twist := func(mm, u, v uint32) uint32 {
		mix := (u & 0x80000000) | (v & 0x7fffffff)
		r := mm ^ (mix >> 1)
		if v&1 == 1 {
			r ^= 0x9908b0df
		}
		return r
	}
	var i int
	for i = 0; i < N-M; i++ {
		m.state[i] = twist(m.state[i+M], m.state[i], m.state[i+1])
	}
	for ; i < N-1; i++ {
		m.state[i] = twist(m.state[i+M-N], m.state[i], m.state[i+1])
	}
	m.state[N-1] = twist(m.state[M-1], m.state[N-1], m.state[0])
	m.index = 0
}

func (m *MtRand) next32() uint32 {
	if m.index >= 624 {
		m.reload()
	}
	s1 := m.state[m.index]
	m.index++
	s1 ^= s1 >> 11
	s1 ^= (s1 << 7) & 0x9d2c5680
	s1 ^= (s1 << 15) & 0xefc60000
	return s1 ^ (s1 >> 18)
}

func (m *MtRand) nextInt() int64 {
	return int64(m.next32() >> 1)
}

// range using PHP's algorithm (uniform random via rejection sampling)
func (m *MtRand) rangeInt(min, max int64) int64 {
	umax := uint64(max) - uint64(min)
	if umax == 0 {
		return min
	}
	var result uint64
	if umax > math.MaxUint32 {
		// 64-bit
		result = uint64(m.next32())<<32 | uint64(m.next32())
		if umax == math.MaxUint64 {
			return min + int64(result)
		}
		umax++
		if umax&(umax-1) != 0 {
			limit := math.MaxUint64 - (math.MaxUint64 % umax) - 1
			for result > limit {
				result = uint64(m.next32())<<32 | uint64(m.next32())
			}
		}
		return min + int64(result%umax)
	}
	r32 := uint32(m.next32())
	um := uint32(umax)
	if um == math.MaxUint32 {
		return min + int64(r32)
	}
	um++
	if um&(um-1) != 0 {
		limit := uint32(math.MaxUint32 - (math.MaxUint32 % uint64(um)) - 1)
		for r32 > limit {
			r32 = m.next32()
		}
	}
	return min + int64(r32%um)
}

func (in *Interp) mt() *MtRand {
	if in.mtRand == nil {
		in.mtRand = &MtRand{}
	}
	if !in.mtRand.seeded {
		var b [4]byte
		crand.Read(b[:])
		in.mtRand.seed(binary.LittleEndian.Uint32(b[:]) ^ uint32(time.Now().UnixNano()))
	}
	return in.mtRand
}

func phpRound(value float64, places int) float64 {
	if math.IsNaN(value) || math.IsInf(value, 0) {
		return value
	}
	f1 := math.Pow(10, float64(abs(places)))
	var tmp float64
	if places >= 0 {
		tmp = value * f1
	} else {
		tmp = value / f1
	}
	// pre-rounding to the precision if the magnitude is correct
	if math.Abs(tmp) >= 1e15 {
		return value
	}
	// round half away from zero with check using string repr (PHP's approach: php_round_helper with pre-rounding)
	rounded := math.Round(tmp)
	// correct for cases like 1.005 * 100 = 100.49999999999999
	if math.Abs(tmp-rounded) == 0.5 {
		// exact half
	} else {
		// use higher precision check
		s := strconv.FormatFloat(tmp, 'f', -1, 64)
		_ = s
		diff := math.Abs(tmp - math.Trunc(tmp))
		if math.Abs(diff-0.5) < 1e-9*math.Max(1, math.Abs(tmp)) {
			// treat as half: round away from zero
			if tmp > 0 {
				rounded = math.Trunc(tmp) + 1
			} else {
				rounded = math.Trunc(tmp) - 1
			}
		}
	}
	if places >= 0 {
		tmp = rounded / f1
	} else {
		tmp = rounded * f1
	}
	if math.IsInf(tmp, 0) || math.IsNaN(tmp) {
		return value
	}
	// use string conversion to get a cleaner representation
	if places > 0 && places < 15 {
		s := strconv.FormatFloat(tmp, 'f', places, 64)
		r, err := strconv.ParseFloat(s, 64)
		if err == nil {
			return r
		}
	}
	return tmp
}

