func roundMode(v float64, mode int64) float64 {
	switch mode {
	case 1: // half up (away from zero)
		if v >= 0 {
			return math.Floor(v + 0.5)
		}
		return math.Ceil(v - 0.5)
	case 2: // half down (toward zero)
		if v >= 0 {
			return math.Ceil(v - 0.5)
		}
		return math.Floor(v + 0.5)
	case 3: // half even
		return math.RoundToEven(v)
	case 4: // half odd
		r := math.RoundToEven(v)
		if math.Abs(v-math.Trunc(v)) == 0.5 {
			if int64(r)%2 == 0 {
				if v > 0 {
					r = r - 1
				} else {
					r = r + 1
				}
				// r is even; need odd: pick the other neighbor
				fl := math.Floor(v)
				ce := math.Ceil(v)
				if int64(fl)%2 != 0 {
					return fl
				}
				return ce
			}
		}
		return r
	case 5:
		return math.Ceil(v)
	case 6:
		return math.Floor(v)
	case 7:
		return math.Trunc(v)
	case 8:
		if v >= 0 {
			return math.Ceil(v)
		}
		return math.Floor(v)
	}
	return math.Round(v)
}

func digitVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'z':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'Z':
		return int(c-'A') + 10
	}
	return -1
}

func baseToDec(in *Interp, s string, base int) Value {
	var n int64
	var f float64
	useFloat := false
	invalid := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		d := digitVal(c)
		if d < 0 || d >= base {
			// allow prefixes 0x, 0b, 0o
			if i == 1 && s[0] == '0' && ((base == 16 && (c == 'x' || c == 'X')) || (base == 2 && (c == 'b' || c == 'B')) || (base == 8 && (c == 'o' || c == 'O'))) {
				continue
			}
			invalid = true
			continue
		}
		if !useFloat {
			nn := n*int64(base) + int64(d)
			if nn/int64(base) != n || nn < 0 {
				useFloat = true
				f = float64(n)*float64(base) + float64(d)
			} else {
				n = nn
			}
		} else {
			f = f*float64(base) + float64(d)
		}
	}
	if invalid {
		in.deprecated("Invalid characters passed for attempted conversion, these have been ignored")
	}
	if useFloat {
		return f
	}
	return n
}

func numberFormat(num float64, dec int, dp, ts string) string {
	if dec < 0 {
		dec = 0
	}
	num = phpRound(num, dec)
	neg := num < 0
	if neg {
		num = -num
	}
	s := strconv.FormatFloat(num, 'f', dec, 64)
	intPart := s
	frac := ""
	if i := strings.IndexByte(s, '.'); i >= 0 {
		intPart = s[:i]
		frac = s[i+1:]
	}
	var sb strings.Builder
	for i, c := range intPart {
		if i > 0 && (len(intPart)-i)%3 == 0 {
			sb.WriteString(ts)
		}
		sb.WriteRune(c)
	}
	res := sb.String()
	if dec > 0 {
		res += dp + frac
	}
	if neg && strings.Trim(strings.TrimLeft(res, "0"+ts), dp+"0") != "" {
		res = "-" + res
	} else if neg {
		// -0 => "-0"
		allZero := true
		for _, c := range s {
			if c != '0' && c != '.' {
				allZero = false
			}
		}
		if !allZero {
			res = "-" + res
		} else {
			res = "-" + res
		}
	}
	return res
}

func (in *Interp) minmax(name string, args []Value, dir int) Value {
	var vals []Value
	if len(args) == 1 {
		arr, ok := args[0].(*Array)
		if !ok {
			in.throwError("TypeError", fmt.Sprintf("%s(): Argument #1 ($value) must be of type array, %s given", name, typeName(args[0])))
		}
		if arr.Len() == 0 {
			in.throwError("ValueError", fmt.Sprintf("%s(): Argument #1 ($value) must contain at least one element", name))
		}
		vals = arr.ValuesDeref()
	} else {
		vals = args
	}
	best := vals[0]
	for _, v := range vals[1:] {
		c := compareValues(v, best)
		if dir > 0 && c > 0 {
			best = v
		} else if dir < 0 && c < 0 {
			best = v
		}
	}
	return best
}
