func phpToUpper(s string) string {
	b := []byte(s)
	for i, c := range b {
		if c >= 'a' && c <= 'z' {
			b[i] = c - 32
		}
	}
	return string(b)
}

func phpUcfirst(s string) string {
	if s == "" {
		return s
	}
	if s[0] >= 'a' && s[0] <= 'z' {
		return string(s[0]-32) + s[1:]
	}
	return s
}

func phpLcfirst(s string) string {
	if s == "" {
		return s
	}
	if s[0] >= 'A' && s[0] <= 'Z' {
		return string(s[0]+32) + s[1:]
	}
	return s
}

func phpTrim(s string, chars string, mode int) string {
	set := makeCharSet(chars)
	start, end := 0, len(s)
	if mode&1 != 0 {
		for start < end && set[s[start]] {
			start++
		}
	}
	if mode&2 != 0 {
		for end > start && set[s[end-1]] {
			end--
		}
	}
	return s[start:end]
}

func makeCharSet(chars string) [256]bool {
	var set [256]bool
	for i := 0; i < len(chars); i++ {
		c := chars[i]
		if i+3 < len(chars) && chars[i+1] == '.' && chars[i+2] == '.' {
			end := chars[i+3]
			for x := int(c); x <= int(end); x++ {
				set[x] = true
			}
			i += 3
			continue
		}
		set[c] = true
	}
	return set
}

