		if p < len(s) {
			p++
		}
		in.strtokPos = p
		return res
	})
	in.reg("ucwords", 1, 2, in.functions["ucwords"].Native)
	in.reg("vsprintf", 2, 2, in.functions["vsprintf"].Native)
	in.reg("nl2br", 1, 2, in.functions["nl2br"].Native)
	in.reg("array_flip", 1, 1, nil)
	delete(in.functions, "array_flip")
	in.reg("strval", 1, 1, in.functions["strval"].Native)
	in.reg("iconv", 3, 3, func(in *Interp, args []Value) Value { return toStr(args[2]) })
	delete(in.functions, "iconv")
	in.reg("crypt", 1, 2, func(in *Interp, args []Value) Value { return "" })
	delete(in.functions, "crypt")
	in.reg("str_word_count", 1, 3, in.functions["str_word_count"].Native)
	in.reg("ucfirst", 1, 1, in.functions["ucfirst"].Native)
	in.reg("dechex", 1, 1, in.functions["dechex"].Native)
	in.reg("escapeshellarg", 1, 1, func(in *Interp, args []Value) Value {
		return "'" + strings.ReplaceAll(toStr(args[0]), "'", "'\\''") + "'"
	})
	in.reg("escapeshellcmd", 1, 1, func(in *Interp, args []Value) Value {
		s := toStr(args[0])
		var sb strings.Builder
		for i := 0; i < len(s); i++ {
			if strings.IndexByte("#&;`|*?~<>^()[]{}$\\\x0A\xFF\"'", s[i]) >= 0 {
				sb.WriteByte('\\')
			}
			sb.WriteByte(s[i])
		}
		return sb.String()
	})
	in.reg("array_key_first", 1, 1, nil)
	delete(in.functions, "array_key_first")
	_ = unicode.IsLetter
	_ = url.QueryEscape
