func applyStartLen(s string, args []Value, i int) string {
	if len(args) > i && args[i] != nil {
		start := toInt(args[i])
		if start < 0 {
			start += int64(len(s))
			if start < 0 {
				start = 0
			}
		}
		if start > int64(len(s)) {
			return ""
		}
		s = s[start:]
		if len(args) > i+1 && args[i+1] != nil {
			l := toInt(args[i+1])
			if l < 0 {
				l += int64(len(s))
				if l < 0 {
					l = 0
				}
			}
			if l < int64(len(s)) {
				s = s[:l]
			}
		}
	}
	return s
}

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func strrposImpl(in *Interp, name string, h, n string, off int64) Value {
	if off >= 0 {
		if off > int64(len(h)) {
			in.throwError("ValueError", name+"(): Argument #3 ($offset) must be contained in argument #1 ($haystack)")
		}
		i := strings.LastIndex(h[off:], n)
		if i < 0 {
			return false
		}
		return int64(i) + off
	}
	if -off > int64(len(h)) {
		in.throwError("ValueError", name+"(): Argument #3 ($offset) must be contained in argument #1 ($haystack)")
	}
	// negative offset: search starts that many chars from end
	end := int64(len(h)) + off + int64(len(n))
	if end > int64(len(h)) {
		end = int64(len(h))
	}
	if end < 0 {
		return false
	}
	i := strings.LastIndex(h[:end], n)
	if i < 0 {
		return false
	}
	return int64(i)
}

func phpSubstr(s string, start int64, length *int64) string {
	n := int64(len(s))
	if start < 0 {
		start += n
		if start < 0 {
			start = 0
		}
	}
	if start > n {
		return ""
	}
	end := n
	if length != nil {
		l := *length
		if l < 0 {
			end = n + l
			if end < start {
				return ""
			}
		} else {
			end = start + l
			if end > n {
				end = n
			}
		}
	}
	return s[start:end]
}

func (in *Interp) strReplace(args []Value, ci bool) Value {
	count := int64(0)
	replaceOne := func(subject string) string {
		doReplace := func(s, search, rep string) string {
			if search == "" {
				return s
			}
			if !ci {
				c := strings.Count(s, search)
				count += int64(c)
				return strings.ReplaceAll(s, search, rep)
			}
			ls := phpToLower(s)
			lsearch := phpToLower(search)
			var sb strings.Builder
			i := 0
			for {
				j := strings.Index(ls[i:], lsearch)
				if j < 0 {
					sb.WriteString(s[i:])
					break
				}
				sb.WriteString(s[i : i+j])
				sb.WriteString(rep)
				count++
				i += j + len(search)
			}
			return sb.String()
		}
		if sa, ok := args[0].(*Array); ok {
			searches := sa.ValuesDeref()
			var reps []Value
			repIsArr := false
			if ra, ok := args[1].(*Array); ok {
				reps = ra.ValuesDeref()
				repIsArr = true
			}
			for i, s := range searches {
				rep := ""
				if repIsArr {
					if i < len(reps) {
						rep = in.toStr(reps[i])
					}
				} else {
					rep = in.toStr(args[1])
				}
				subject = doReplace(subject, in.toStr(s), rep)
			}
			return subject
		}
		if _, ok := args[1].(*Array); ok {
			in.throwError("TypeError", "str_replace(): Argument #2 ($replace) must be of type string when argument #1 ($search) is a string")
		}
		return doReplace(subject, in.toStr(args[0]), in.toStr(args[1]))
	}
	var result Value
	if subj, ok := args[2].(*Array); ok {
		out := NewArray()
		subj.Each(func(k Key, v Value) bool {
			v = deref(v)
			if _, isArr := v.(*Array); isArr {
				out.Set(k, v)
				return true
			}
			out.Set(k, replaceOne(in.toStr(v)))
			return true
		})
		result = out
	} else {
		result = replaceOne(in.toStr(args[2]))
	}
	if len(args) > 3 {
		if r, ok := args[3].(*Ref); ok {
			r.set(count)
		}
	}
	return result
}

func strtrArray(s string, arr *Array, in *Interp) string {
	type pair struct{ from, to string }
	var pairs []pair
	maxLen := 0
	minLen := math.MaxInt32
	arr.Each(func(k Key, v Value) bool {
		from := k.String()
		if from == "" {
			return true
		}
		pairs = append(pairs, pair{from, in.toStr(deref(v))})
		if len(from) > maxLen {
			maxLen = len(from)
		}
		if len(from) < minLen {
			minLen = len(from)
		}
		return true
	})
	if len(pairs) == 0 {
		return s
	}
	m := map[string]string{}
	for _, p := range pairs {
		m[p.from] = p.to
	}
	var sb strings.Builder
	i := 0
	for i < len(s) {
		matched := false
		for l := maxLen; l >= minLen; l-- {
			if i+l > len(s) {
				continue
			}
			if to, ok := m[s[i:i+l]]; ok {
				sb.WriteString(to)
				i += l
				matched = true
				break
			}
		}
		if !matched {
			sb.WriteByte(s[i])
			i++
		}
	}
	return sb.String()
}

func htmlSpecialChars(s string, flags int64, double bool) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '&':
			if !double {
				// check if already an entity
				if j := strings.IndexByte(s[i:], ';'); j > 1 && j < 12 {
					ent := s[i+1 : i+j]
					if isValidEntityName(ent) {
						sb.WriteByte('&')
						continue
					}
				}
			}
			sb.WriteString("&amp;")
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '"':
			if flags&2 != 0 {
				sb.WriteString("&quot;")
			} else {
				sb.WriteByte(c)
			}
		case '\'':
			if flags&1 != 0 {
				if flags&48 == 48 || flags&16 != 0 || flags&32 != 0 {
					sb.WriteString("&#039;")
				} else {
					sb.WriteString("&#039;")
				}
			} else {
				sb.WriteByte(c)
			}
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

func isValidEntityName(ent string) bool {
	if ent == "" {
		return false
	}
	if ent[0] == '#' {
		if len(ent) > 1 && (ent[1] == 'x' || ent[1] == 'X') {
			for i := 2; i < len(ent); i++ {
				if !isHex(ent[i]) {
					return false
				}
			}
			return len(ent) > 2
		}
		for i := 1; i < len(ent); i++ {
			if !isDigit(ent[i]) {
				return false
			}
		}
		return len(ent) > 1
	}
	for i := 0; i < len(ent); i++ {
		if !isIdentChar(ent[i]) {
			return false
		}
	}
	return true
}

