	delete(in.functions, "array_map")
	in.reg("str_increment", 1, 1, func(in *Interp, args []Value) Value {
		s := in.argStr("str_increment", args, 0)
		if s == "" {
			in.throwError("ValueError", "str_increment(): Argument #1 ($string) cannot be empty")
		}
		for i := 0; i < len(s); i++ {
			c := s[i]
			if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) {
				in.throwError("ValueError", "str_increment(): Argument #1 ($string) must be composed only of alphanumeric ASCII characters")
			}
		}
		return strIncrement(s, in)
	})
	in.reg("str_decrement", 1, 1, func(in *Interp, args []Value) Value {
		s := in.argStr("str_decrement", args, 0)
		if s == "" {
			in.throwError("ValueError", "str_decrement(): Argument #1 ($string) cannot be empty")
		}
		b := []byte(s)
		i := len(b) - 1
		for i >= 0 {
			c := b[i]
			switch {
			case c == 'a':
				b[i] = 'z'
				i--
			case c == 'A':
				b[i] = 'Z'
				i--
			case c == '0':
				b[i] = '9'
				i--
			default:
				b[i] = c - 1
				return string(b)
			}
		}
		in.throwError("ValueError", "str_decrement(): Argument #1 ($string) \""+s+"\" is out of decrement range")
		return nil
	})
	in.reg("mb_strlen", 1, 2, func(in *Interp, args []Value) Value { return int64(utf8.RuneCountInString(toStr(args[0]))) })
	in.reg("mb_strtoupper", 1, 2, func(in *Interp, args []Value) Value { return strings.ToUpper(toStr(args[0])) })
