	delete(in.functions, "convert_uuencode")
	in.reg("strtok", 1, 2, func(in *Interp, args []Value) Value {
		var token string
		if len(args) == 2 {
			in.strtokStr = in.argStr("strtok", args, 0)
			in.strtokPos = 0
			token = in.argStr("strtok", args, 1)
		} else {
			token = in.argStr("strtok", args, 0)
		}
		set := makeCharSet(token)
		s := in.strtokStr
		p := in.strtokPos
		for p < len(s) && set[s[p]] {
			p++
		}
		if p >= len(s) {
			in.strtokPos = p
			return false
		}
		start := p
		for p < len(s) && !set[s[p]] {
			p++
		}
		res := s[start:p]
		if p < len(s) {
			p++
		}
		in.strtokPos = p
		return res
	})
	in.reg("ucwords", 1, 2, in.functions["ucwords"].Native)
	in.reg("vsprintf", 2, 2, in.functions["vsprintf"].Native)
