var htmlEntityReverse map[string]rune

func htmlEntities(s string, flags int64, double bool) string {
	s = htmlSpecialChars(s, flags, double)
	var sb strings.Builder
	for _, r := range s {
		if name, ok := htmlEntityTable[r]; ok {
			sb.WriteString("&" + name + ";")
		} else {
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

func htmlEntityDecode(s string, flags int64) string {
	if htmlEntityReverse == nil {
		htmlEntityReverse = map[string]rune{}
		for r, n := range htmlEntityTable {
			htmlEntityReverse[n] = r
		}
	}
	var sb strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == '&' {
			j := strings.IndexByte(s[i:], ';')
			if j > 1 && j < 12 {
				ent := s[i+1 : i+j]
				if ent[0] == '#' {
					var code int64
					var err error
					if len(ent) > 1 && (ent[1] == 'x' || ent[1] == 'X') {
						code, err = strconv.ParseInt(ent[2:], 16, 32)
					} else {
						code, err = strconv.ParseInt(ent[1:], 10, 32)
					}
					if err == nil && code > 0 && code <= 0x10FFFF {
						if code == 39 && flags&1 == 0 {
							sb.WriteString(s[i : i+j+1])
						} else if code == 34 && flags&2 == 0 {
							sb.WriteString(s[i : i+j+1])
						} else {
							sb.WriteRune(rune(code))
						}
						i += j + 1
						continue
					}
				} else {
					switch ent {
					case "amp":
						sb.WriteByte('&')
						i += j + 1
						continue
					case "lt":
						sb.WriteByte('<')
						i += j + 1
						continue
					case "gt":
						sb.WriteByte('>')
						i += j + 1
						continue
					case "quot":
						if flags&2 != 0 {
							sb.WriteByte('"')
							i += j + 1
							continue
						}
					case "apos":
						if flags&1 != 0 && flags&48 != 0 {
							sb.WriteByte('\'')
							i += j + 1
							continue
						}
					default:
						if r, ok := htmlEntityReverse[ent]; ok {
							sb.WriteRune(r)
							i += j + 1
							continue
						}
					}
				}
			}
		}
		sb.WriteByte(s[i])
		i++
	}
	return sb.String()
}

func stripTags(s string) string {
	var sb strings.Builder
	depth := 0
	inQuote := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if depth == 0 {
			if c == '<' {
				// check for valid tag start
				if i+1 < len(s) && (isIdentStart(s[i+1]) || s[i+1] == '/' || s[i+1] == '!' || s[i+1] == '?') {
					depth = 1
					continue
				}
				if i+1 < len(s) && s[i+1] == ' ' {
					sb.WriteByte(c)
					continue
				}
				depth = 1
				continue
			}
			sb.WriteByte(c)
			continue
		}
		if inQuote != 0 {
			if c == inQuote {
				inQuote = 0
			}
			continue
		}
		switch c {
		case '"', '\'':
			inQuote = c
		case '<':
			depth++
		case '>':
			depth--
		}
	}
	return sb.String()
}

func wordwrap(s string, width int, brk string, cut bool) string {
	if s == "" {
		return ""
	}
	// PHP algorithm
	var sb strings.Builder
	lastStart, lastSpace := 0, 0
	current := 0
	for current = 0; current < len(s); current++ {
		c := s[current]
		if c == brk[0] && current+len(brk) <= len(s) && s[current:current+len(brk)] == brk {
			sb.WriteString(s[lastStart : current+len(brk)])
			current += len(brk) - 1
			lastStart = current + 1
			lastSpace = lastStart
		} else if c == ' ' {
			if current-lastStart >= width {
				sb.WriteString(s[lastStart:current])
				sb.WriteString(brk)
				lastStart = current + 1
			}
			lastSpace = current
		} else if current-lastStart >= width && cut && lastStart >= lastSpace {
			sb.WriteString(s[lastStart:current])
			sb.WriteString(brk)
			lastStart = current
			lastSpace = current
		} else if current-lastStart >= width && lastStart < lastSpace {
			sb.WriteString(s[lastStart:lastSpace])
			sb.WriteString(brk)
			lastStart = lastSpace + 1
			lastSpace = lastStart
		}
	}
	if lastStart != current {
		sb.WriteString(s[lastStart:current])
	}
	return sb.String()
}

func similarText(a, b string) int {
	if len(a) == 0 || len(b) == 0 {
		return 0
	}
	max, pos1, pos2 := 0, 0, 0
	for i := 0; i < len(a); i++ {
		for j := 0; j < len(b); j++ {
			k := 0
			for i+k < len(a) && j+k < len(b) && a[i+k] == b[j+k] {
				k++
			}
			if k > max {
				max, pos1, pos2 = k, i, j
			}
		}
	}
	if max == 0 {
		return 0
	}
	return max + similarText(a[:pos1], b[:pos2]) + similarText(a[pos1+max:], b[pos2+max:])
}

func levenshtein(a, b string, ci, cr, cd int) int {
	if len(a) == 0 {
		return len(b) * ci
	}
	if len(b) == 0 {
		return len(a) * cd
	}
	p1 := make([]int, len(b)+1)
	p2 := make([]int, len(b)+1)
	for j := 0; j <= len(b); j++ {
		p1[j] = j * ci
	}
	for i := 0; i < len(a); i++ {
		p2[0] = p1[0] + cd
		for j := 0; j < len(b); j++ {
			c0 := p1[j]
			if a[i] != b[j] {
				c0 += cr
			}
			c1 := p1[j+1] + cd
			if c1 < c0 {
				c0 = c1
			}
			c2 := p2[j] + ci
			if c2 < c0 {
				c0 = c2
			}
			p2[j+1] = c0
		}
		p1, p2 = p2, p1
	}
	return p1[len(b)]
}

func soundex(s string) string {
	codes := map[byte]byte{'B': '1', 'F': '1', 'P': '1', 'V': '1', 'C': '2', 'G': '2', 'J': '2', 'K': '2', 'Q': '2', 'S': '2', 'X': '2', 'Z': '2', 'D': '3', 'T': '3', 'L': '4', 'M': '5', 'N': '5', 'R': '6'}
	s = phpToUpper(s)
	var out []byte
	var last byte
	for i := 0; i < len(s) && len(out) < 4; i++ {
		c := s[i]
		if c < 'A' || c > 'Z' {
			continue
		}
		code, ok := codes[c]
		if len(out) == 0 {
			out = append(out, c)
			if ok {
				last = code
			} else {
				last = 0
			}
			continue
		}
		if !ok {
			if c != 'H' && c != 'W' {
				last = 0
			}
			continue
		}
		if code != last {
			out = append(out, code)
		}
		last = code
	}
	if len(out) == 0 {
		return ""
	}
	for len(out) < 4 {
		out = append(out, '0')
	}
	return string(out)
}

func metaphone(s string) string {
	// simplified metaphone
	s = phpToUpper(s)
	var letters []byte
	for i := 0; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' {
			letters = append(letters, s[i])
		}
	}
	if len(letters) == 0 {
		return ""
	}
	w := string(letters)
	isVowel := func(c byte) bool { return strings.IndexByte("AEIOU", c) >= 0 }
	at := func(i int) byte {
		if i < 0 || i >= len(w) {
			return 0
		}
		return w[i]
	}
	var out strings.Builder
	i := 0
	// initial exceptions
	switch {
	case strings.HasPrefix(w, "AE"), strings.HasPrefix(w, "GN"), strings.HasPrefix(w, "KN"), strings.HasPrefix(w, "PN"), strings.HasPrefix(w, "WR"):
		i = 1
	case w[0] == 'X':
		out.WriteByte('S')
		i = 1
	case strings.HasPrefix(w, "WH"):
		out.WriteByte('W')
		i = 2
	}
	for ; i < len(w); i++ {
		c := w[i]
		if c == at(i-1) && c != 'C' {
			continue
		}
		switch c {
		case 'A', 'E', 'I', 'O', 'U':
			if i == 0 {
				out.WriteByte(c)
			}
		case 'B':
			if !(i == len(w)-1 && at(i-1) == 'M') {
				out.WriteByte('B')
			}
		case 'C':
			if at(i+1) == 'I' && at(i+2) == 'A' {
				out.WriteByte('X')
			} else if at(i+1) == 'H' {
				if i == 0 && !isVowel(at(i+2)) {
					out.WriteByte('K')
				} else {
					out.WriteByte('X')
				}
				i++
			} else if at(i+1) == 'I' || at(i+1) == 'E' || at(i+1) == 'Y' {
				if at(i-1) != 'S' {
					out.WriteByte('S')
				}
			} else {
				out.WriteByte('K')
			}
		case 'D':
			if at(i+1) == 'G' && (at(i+2) == 'E' || at(i+2) == 'Y' || at(i+2) == 'I') {
				out.WriteByte('J')
				i += 2
			} else {
				out.WriteByte('T')
			}
		case 'G':
			if at(i+1) == 'H' && !(i+2 >= len(w) || isVowel(at(i+2))) {
				continue
			}
			if at(i+1) == 'N' && (i+2 == len(w) || (at(i+2) == 'E' && at(i+3) == 'D' && i+4 == len(w))) {
				continue
			}
			if at(i-1) == 'D' && (at(i+1) == 'E' || at(i+1) == 'Y' || at(i+1) == 'I') {
				continue
			}
			if at(i+1) == 'I' || at(i+1) == 'E' || at(i+1) == 'Y' {
				out.WriteByte('J')
			} else {
				out.WriteByte('K')
			}
		case 'H':
			if isVowel(at(i+1)) && strings.IndexByte("CSPTG", at(i-1)) < 0 {
				out.WriteByte('H')
			}
		case 'K':
			if at(i-1) != 'C' {
				out.WriteByte('K')
			}
		case 'P':
			if at(i+1) == 'H' {
				out.WriteByte('F')
				i++
			} else {
				out.WriteByte('P')
			}
		case 'Q':
			out.WriteByte('K')
		case 'S':
			if at(i+1) == 'H' {
				out.WriteByte('X')
				i++
			} else if at(i+1) == 'I' && (at(i+2) == 'O' || at(i+2) == 'A') {
				out.WriteByte('X')
			} else {
				out.WriteByte('S')
			}
		case 'T':
			if at(i+1) == 'I' && (at(i+2) == 'O' || at(i+2) == 'A') {
				out.WriteByte('X')
			} else if at(i+1) == 'H' {
				out.WriteByte('0')
				i++
			} else if !(at(i+1) == 'C' && at(i+2) == 'H') {
				out.WriteByte('T')
			}
		case 'V':
			out.WriteByte('F')
		case 'W', 'Y':
			if isVowel(at(i + 1)) {
				out.WriteByte(c)
			}
		case 'X':
			out.WriteString("KS")
		case 'Z':
			out.WriteByte('S')
		default:
			out.WriteByte(c)
		}
	}
	return out.String()
}

func strnatcmp(a, b string, ci bool) int {
	if ci {
		a, b = phpToLower(a), phpToLower(b)
	}
	i, j := 0, 0
	for {
		// skip leading spaces
		for i < len(a) && isWS(a[i]) {
			i++
		}
		for j < len(b) && isWS(b[j]) {
			j++
		}
		if i >= len(a) || j >= len(b) {
			break
		}
		ca, cb := a[i], b[j]
		if isDigit(ca) && isDigit(cb) {
			// compare numbers
			if ca == '0' || cb == '0' {
				// fractional compare (left aligned)
				for {
					if i >= len(a) || !isDigit(a[i]) {
						if j < len(b) && isDigit(b[j]) {
							return -1
						}
						break
					}
					if j >= len(b) || !isDigit(b[j]) {
						return 1
					}
					if a[i] < b[j] {
						return -1
					}
					if a[i] > b[j] {
						return 1
					}
					i++
					j++
				}
				continue
			}
			// right aligned
			bias := 0
			for {
				ad := i < len(a) && isDigit(a[i])
				bd := j < len(b) && isDigit(b[j])
				if !ad && !bd {
					break
				}
				if !ad {
					return -1
				}
				if !bd {
					return 1
				}
				if bias == 0 {
					if a[i] < b[j] {
						bias = -1
					} else if a[i] > b[j] {
						bias = 1
					}
				}
				i++
				j++
			}
			if bias != 0 {
				return bias
			}
			continue
		}
		if ca < cb {
			return -1
		}
		if ca > cb {
			return 1
		}
		i++
		j++
	}
	if i < len(a) {
		return 1
	}
	if j < len(b) {
		return -1
	}
	return 0
}

func ctypeCheck(v Value, f func(byte) bool) bool {
	var s string
	switch x := v.(type) {
	case string:
		s = x
	case int64:
		if x >= -128 && x <= 255 {
			if x < 0 {
				x += 256
			}
			return f(byte(x))
		}
		s = intToStr(x)
	default:
		return false
	}
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if !f(s[i]) {
			return false
		}
	}
	return true
}

func urlEncode(s string, raw bool) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' {
			sb.WriteByte(c)
		} else if c == '~' && raw {
			sb.WriteByte(c)
		} else if c == ' ' && !raw {
			sb.WriteByte('+')
		} else {
			sb.WriteString(fmt.Sprintf("%%%02X", c))
		}
	}
	return sb.String()
}

func urlDecode(s string, plus bool) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '+' && plus {
			sb.WriteByte(' ')
		} else if c == '%' && i+2 < len(s) && isHex(s[i+1]) && isHex(s[i+2]) {
			sb.WriteByte(byte(hexVal(s[i+1])*16 + hexVal(s[i+2])))
			i += 2
		} else {
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

func parseQueryString(s string) *Array {
	arr := NewArray()
	if s == "" {
		return arr
	}
	for _, part := range strings.Split(s, "&") {
		if part == "" {
			continue
		}
		var k, v string
		if i := strings.IndexByte(part, '='); i >= 0 {
			k, v = urlDecode(part[:i], true), urlDecode(part[i+1:], true)
		} else {
			k = urlDecode(part, true)
		}
		// handle brackets
		if bi := strings.IndexByte(k, '['); bi > 0 {
			base := k[:bi]
			rest := k[bi:]
			var keys []string
			for len(rest) > 0 && rest[0] == '[' {
				e := strings.IndexByte(rest, ']')
				if e < 0 {
					break
				}
				keys = append(keys, rest[1:e])
				rest = rest[e+1:]
			}
			cur := arr
			bk, _ := normalizeKey(base)
			for idx, sub := range keys {
				var next *Array
				existing, ok := cur.Get(bk)
				if ok {
					next, _ = existing.(*Array)
				}
				if next == nil {
					next = NewArray()
					cur.Set(bk, next)
				}
				cur = next
				if idx == len(keys)-1 {
					if sub == "" {
						cur.Append(v)
					} else {
						sk, _ := normalizeKey(sub)
						cur.Set(sk, v)
					}
				} else {
					if sub == "" {
						bk = IntKey(cur.nextFree)
					} else {
						bk, _ = normalizeKey(sub)
					}
				}
			}
			continue
		}
		k = strings.ReplaceAll(strings.ReplaceAll(k, ".", "_"), " ", "_")
		kk, _ := normalizeKey(k)
		arr.Set(kk, v)
	}
	return arr
}

func (in *Interp) parseUrl(s string, args []Value) Value {
	comp := int64(-1)
	if len(args) > 1 {
		comp = toInt(args[1])
	}
	res := NewArray()
	rest := s
	// scheme
	if i := strings.Index(rest, "://"); i > 0 && isSchemeName(rest[:i]) {
		res.SetStr("scheme", rest[:i])
		rest = rest[i+3:]
		// authority
		end := len(rest)
		for j := 0; j < len(rest); j++ {
			if rest[j] == '/' || rest[j] == '?' || rest[j] == '#' {
				end = j
				break
			}
		}
		auth := rest[:end]
		rest = rest[end:]
		if at := strings.LastIndexByte(auth, '@'); at >= 0 {
			ui := auth[:at]
			auth = auth[at+1:]
			if c := strings.IndexByte(ui, ':'); c >= 0 {
				res.SetStr("user", ui[:c])
				res.SetStr("pass", ui[c+1:])
			} else {
				res.SetStr("user", ui)
			}
		}
		host := auth
		if strings.HasPrefix(host, "[") {
			if e := strings.IndexByte(host, ']'); e >= 0 {
				res.SetStr("host", host[:e+1])
				if e+1 < len(host) && host[e+1] == ':' {
					p, err := strconv.Atoi(host[e+2:])
					if err != nil {
						return false
					}
					res.SetStr("port", int64(p))
				}
			}
		} else if c := strings.LastIndexByte(host, ':'); c >= 0 {
			if host[c+1:] != "" {
				p, err := strconv.Atoi(host[c+1:])
				if err != nil || p > 65535 || p < 0 {
					return false
				}
				res.SetStr("host", host[:c])
				res.SetStr("port", int64(p))
			} else {
				res.SetStr("host", host[:c])
			}
		} else if host != "" {
			res.SetStr("host", host)
		}
	} else if i := strings.IndexByte(rest, ':'); i > 0 && isSchemeName(rest[:i]) && !(i+1 < len(rest) && isDigit(rest[i+1]) && !strings.Contains(rest[i+1:], "/")) {
		res.SetStr("scheme", rest[:i])
		rest = rest[i+1:]
	} else if strings.HasPrefix(rest, "//") {
		rest = rest[2:]
		end := len(rest)
		for j := 0; j < len(rest); j++ {
			if rest[j] == '/' || rest[j] == '?' || rest[j] == '#' {
				end = j
				break
			}
		}
		res.SetStr("host", rest[:end])
		rest = rest[end:]
	}
	if h := strings.IndexByte(rest, '#'); h >= 0 {
		res.SetStr("fragment", rest[h+1:])
		rest = rest[:h]
	}
	if q := strings.IndexByte(rest, '?'); q >= 0 {
		res.SetStr("query", rest[q+1:])
		rest = rest[:q]
	}
	if rest != "" {
		res.SetStr("path", rest)
	}
	// reorder keys
	ordered := NewArray()
	for _, k := range []string{"scheme", "host", "port", "user", "pass", "path", "query", "fragment"} {
		if v, ok := res.GetStr(k); ok {
			ordered.SetStr(k, v)
		}
	}
	if comp >= 0 {
		names := []string{"scheme", "host", "port", "user", "pass", "path", "query", "fragment"}
		if int(comp) < len(names) {
			v, ok := ordered.GetStr(names[comp])
			if !ok {
				return nil
			}
			return v
		}
		in.throwError("ValueError", "parse_url(): Argument #2 ($component) must be a valid URL component identifier, "+intToStr(comp)+" given")
	}
	return ordered
}

func isSchemeName(s string) bool {
	if s == "" || !((s[0] >= 'a' && s[0] <= 'z') || (s[0] >= 'A' && s[0] <= 'Z')) {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || isDigit(c) || c == '+' || c == '-' || c == '.') {
			return false
		}
	}
	return true
}

func sscanf(s, format string) []Value {
	var out []Value
	si := 0
	fi := 0
	failed := false
	for fi < len(format) {
		fc := format[fi]
		if isWS(fc) {
			for si < len(s) && isWS(s[si]) {
				si++
			}
			fi++
			continue
		}
		if fc != '%' {
			if si < len(s) && s[si] == fc {
				si++
				fi++
				continue
			}
			failed = true
			break
		}
		fi++
		if fi >= len(format) {
			break
		}
		if format[fi] == '%' {
			if si < len(s) && s[si] == '%' {
				si++
			}
			fi++
			continue
		}
		suppress := false
		if format[fi] == '*' {
			suppress = true
			fi++
		}
		width := 0
		for fi < len(format) && isDigit(format[fi]) {
			width = width*10 + int(format[fi]-'0')
			fi++
		}
		if fi < len(format) && (format[fi] == 'l' || format[fi] == 'h' || format[fi] == 'L') {
			fi++
		}
		if fi >= len(format) {
			break
		}
		conv := format[fi]
		fi++
		if conv != 'c' && conv != '[' {
			for si < len(s) && isWS(s[si]) {
				si++
			}
		}
		if si >= len(s) && !failed {
			failed = true
		}
		var val Value
		switch conv {
		case 'd', 'i', 'u':
			start := si
			if si < len(s) && (s[si] == '-' || s[si] == '+') {
				si++
			}
			for si < len(s) && isDigit(s[si]) && (width == 0 || si-start < width) {
				si++
			}
			if si == start || (si == start+1 && !isDigit(s[start])) {
				failed = true
				si = start
				break
			}
			n, _ := strconv.ParseInt(s[start:si], 10, 64)
			val = n
		case 'x', 'X':
			start := si
			for si < len(s) && isHex(s[si]) && (width == 0 || si-start < width) {
				si++
			}
			if si == start {
				failed = true
				break
			}
			n, _ := strconv.ParseInt(s[start:si], 16, 64)
			val = n
		case 'o':
			start := si
			for si < len(s) && s[si] >= '0' && s[si] <= '7' && (width == 0 || si-start < width) {
				si++
			}
			if si == start {
				failed = true
				break
			}
			n, _ := strconv.ParseInt(s[start:si], 8, 64)
			val = n
		case 'f', 'e', 'g', 'E':
			start := si
			for si < len(s) && (isDigit(s[si]) || s[si] == '.' || s[si] == '-' || s[si] == '+' || s[si] == 'e' || s[si] == 'E') && (width == 0 || si-start < width) {
				si++
			}
			if si == start {
				failed = true
				break
			}
			f, _ := strconv.ParseFloat(s[start:si], 64)
			val = f
		case 's':
			start := si
			for si < len(s) && !isWS(s[si]) && (width == 0 || si-start < width) {
				si++
			}
			if si == start {
				failed = true
				break
			}
			val = s[start:si]
		case 'c':
			if width == 0 {
				width = 1
			}
			if si+width > len(s) {
				failed = true
				break
			}
			val = s[si : si+width]
			si += width
		case '[':
			// char set
			neg := false
			if fi < len(format) && format[fi] == '^' {
				neg = true
				fi++
			}
			setStart := fi
			if fi < len(format) && format[fi] == ']' {
				fi++
			}
			for fi < len(format) && format[fi] != ']' {
				fi++
			}
			set := makeCharSet(format[setStart:fi])
			fi++
			start := si
			for si < len(s) && set[s[si]] != neg && (width == 0 || si-start < width) {
				si++
			}
			if si == start {
				failed = true
				break
			}
			val = s[start:si]
		}
		if failed {
			if !suppress {
				out = append(out, nil)
			}
			// remaining conversions get null
			for fi < len(format) {
				if format[fi] == '%' && fi+1 < len(format) && format[fi+1] != '%' && format[fi+1] != '*' {
					out = append(out, nil)
				}
				fi++
			}
			break
		}
		if !suppress {
			out = append(out, val)
		}
	}
	if len(out) == 0 && failed {
		return nil
	}
	return out
}
