		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #%d%s must be of type array, %s given", fname, i+1, in.argName(fname, i), typeNameForError(r.V)))
	}
	if arr.rc > 1 {
		arr = arr.Clone()
		r.set(arr)
	}
	return r, arr
}

type sortItem struct {
	k Key
	v Value
}

// sortArray performs the various PHP sorts in place on arr
func (in *Interp) sortArray(arr *Array, kind string, args []Value) {
	items := make([]sortItem, 0, arr.Len())
	arr.Each(func(k Key, v Value) bool {
		items = append(items, sortItem{k, v})
		return true
	})
	flags := int64(0)
	var cb Value
	switch kind {
	case "usort", "uasort", "uksort":
		if len(args) > 0 {
			cb = args[0]
		}
	default:
		if len(args) > 0 && args[0] != nil {
			flags = toInt(args[0])
		}
	}
	cmpVals := func(a, b Value) int {
		return in.sortCompare(a, b, flags)
	}
	var less func(i, j int) bool
	switch kind {
	case "sort", "asort":
		less = func(i, j int) bool { return cmpVals(deref(items[i].v), deref(items[j].v)) < 0 }
	case "rsort", "arsort":
		less = func(i, j int) bool { return cmpVals(deref(items[j].v), deref(items[i].v)) < 0 }
	case "ksort":
		less = func(i, j int) bool { return cmpVals(items[i].k.Value(), items[j].k.Value()) < 0 }
	case "krsort":
		less = func(i, j int) bool { return cmpVals(items[j].k.Value(), items[i].k.Value()) < 0 }
	case "usort", "uasort":
		less = func(i, j int) bool {
			r := in.callValue(cb, []Value{deref(items[i].v), deref(items[j].v)})
			return in.cbResult(r) < 0
		}
	case "uksort":
		less = func(i, j int) bool {
			r := in.callValue(cb, []Value{items[i].k.Value(), items[j].k.Value()})
			return in.cbResult(r) < 0
		}
	case "natsort":
		less = func(i, j int) bool { return strnatcmp(toStr(deref(items[i].v)), toStr(deref(items[j].v)), false) < 0 }
	case "natcasesort":
		less = func(i, j int) bool { return strnatcmp(toStr(deref(items[i].v)), toStr(deref(items[j].v)), true) < 0 }
	}
	sort.SliceStable(items, less)
	// rebuild
	arr.entries = arr.entries[:0]
	arr.index = nil
	arr.nDeleted = 0
	arr.nextFree = 0
	arr.pos = 0
	renumber := kind == "sort" || kind == "rsort" || kind == "usort"
	for i, it := range items {
		var k Key
		if renumber {
			k = IntKey(int64(i))
		} else {
			k = it.k
		}
		if arr.index == nil && !(k.IsStr == false && k.I == int64(len(arr.entries))) {
			arr.buildIndex()
		}
		if arr.index != nil {
			arr.index[k] = len(arr.entries)
		}
		arr.entries = append(arr.entries, entry{k: k, v: it.v})
		if !k.IsStr && k.I >= arr.nextFree {
			arr.nextFree = k.I + 1
		}
	}
}

func (in *Interp) cbResult(r Value) int {
	switch x := r.(type) {
	case int64:
		if x < 0 {
			return -1
		}
		if x > 0 {
			return 1
		}
		return 0
	case bool:
		if x {
			return 1
		}
		return 0
	case float64:
		if x < 0 {
			return -1
		}
		if x > 0 {
			return 1
		}
		return 0
	}
	return int(toInt(r))
}

func (in *Interp) sortCompare(a, b Value, flags int64) int {
	base := flags &^ 8
	caseInsensitive := flags&8 != 0
	switch base {
	case 1: // SORT_NUMERIC
		return cmpFloat(toFloat(a), toFloat(b))
	case 2: // SORT_STRING
		sa, sb := in.toStr(a), in.toStr(b)
		if caseInsensitive {
			sa, sb = phpToLower(sa), phpToLower(sb)
		}
		return cmpStr(sa, sb)
	case 6: // SORT_NATURAL
		return strnatcmp(in.toStr(a), in.toStr(b), caseInsensitive)
	case 5:
		return cmpStr(in.toStr(a), in.toStr(b))
	}
	return compareValues(a, b)
}

func (in *Interp) initArrayFunctions() {
	in.reg("count", 1, 2, func(in *Interp, args []Value) Value {
		mode := int64(0)
		if len(args) > 1 {
			mode = toInt(args[1])
		}
		switch x := args[0].(type) {
		case *Array:
