func (in *Interp) ptrArray(name string, args []Value) *Array {
	v := args[0]
	if r, ok := v.(*Ref); ok {
		v = r.V
	}
	switch x := v.(type) {
	case *Array:
		return x
	case *Object:
		if st, ok := x.internal.(*Array); ok {
			return st
		}
		return x.props
	}
	in.throwError("TypeError", fmt.Sprintf("%s(): Argument #1 ($array) must be of type array, %s given", name, typeName(v)))
	return nil
}

func countRecursive(a *Array) int {
	n := a.Len()
	a.Each(func(k Key, v Value) bool {
		if sub, ok := deref(v).(*Array); ok {
			n += countRecursive(sub)
		}
		return true
	})
	return n
}

func mergeRecursive(dst *Array, src *Array) {
	src.Each(func(k Key, v Value) bool {
		v = deref(v)
		if k.IsStr {
			if existing, ok := dst.Get(k); ok {
				existing = deref(existing)
				ea, eIsArr := existing.(*Array)
				va, vIsArr := v.(*Array)
				var merged *Array
				if eIsArr {
					merged = ea.Clone()
				} else {
					merged = NewArray()
					merged.Append(existing)
				}
				if vIsArr {
					mergeRecursive(merged, va)
				} else {
					merged.Append(v)
				}
				dst.Set(k, merged)
			} else {
				dst.Set(k, v)
			}
		} else {
			dst.Append(v)
		}
		return true
	})
}

func replaceRecursive(dst *Array, src *Array) {
	src.Each(func(k Key, v Value) bool {
		v = deref(v)
		if va, ok := v.(*Array); ok {
			if existing, ok := dst.Get(k); ok {
				if ea, ok := deref(existing).(*Array); ok {
					merged := ea.Clone()
					replaceRecursive(merged, va)
					dst.Set(k, merged)
					return true
				}
			}
		}
		dst.Set(k, v)
		return true
	})
}

func (in *Interp) arrayDiffIntersect(name string, args []Value, diff bool, byKey bool, byBoth bool, valCb Value, keyCb Value) Value {
	first := in.argArray(name, args, 0)
	others := make([]*Array, 0, len(args)-1)
	for i := 1; i < len(args); i++ {
		others = append(others, in.argArray(name, args, i))
	}
	valEq := func(a, b Value) bool {
		if valCb != nil {
			return toInt(in.callValue(valCb, []Value{a, b})) == 0
		}
		return in.toStr(a) == in.toStr(b)
	}
	keyEq := func(a, b Key) bool {
		if keyCb != nil {
			return toInt(in.callValue(keyCb, []Value{a.Value(), b.Value()})) == 0
		}
		return a == b
	}
	out := NewArray()
	first.Each(func(k Key, v Value) bool {
		v = deref(v)
		inAll := true
		inAny := false
		for _, o := range others {
			found := false
			if byKey && !byBoth && keyCb == nil {
				found = o.Has(k)
			} else if byBoth && keyCb == nil {
				if ov, ok := o.Get(k); ok {
					found = valEq(v, deref(ov))
				}
			} else {
				o.Each(func(ok Key, ov Value) bool {
					ov = deref(ov)
					match := true
					if byKey {
						match = keyEq(k, ok)
					}
					if match && (!byKey || byBoth) {
						match = valEq(v, ov)
					}
					if match {
						found = true
						return false
					}
					return true
				})
			}
			if found {
				inAny = true
			} else {
				inAll = false
			}
		}
		if diff {
			if !inAny {
				out.Set(k, v)
			}
		} else {
			if inAll {
				out.Set(k, v)
			}
		}
		return true
	})
	return out
}

func (in *Interp) rangeFn(args []Value) Value {
	start, end := args[0], args[1]
	var step Value = int64(1)
	if len(args) > 2 {
		step = args[2]
	}
	out := NewArray()
	// string ranges
	ss, sIsStr := start.(string)
	es, eIsStr := end.(string)
	if sIsStr && eIsStr && len(ss) >= 1 && len(es) >= 1 && !isNumericStr(ss) && !isNumericStr(es) {
		st := toInt(step)
		if st < 0 {
			st = -st
		}
		if st == 0 {
			in.throwError("ValueError", "range(): Argument #3 ($step) cannot be 0")
		}
		a, b := int64(ss[0]), int64(es[0])
		if a <= b {
			for c := a; c <= b; c += st {
				out.Append(string([]byte{byte(c)}))
			}
		} else {
			for c := a; c >= b; c -= st {
				out.Append(string([]byte{byte(c)}))
			}
		}
		return out
	}
	// numeric
	toNum := func(v Value) Value {
		switch x := v.(type) {
		case int64:
			return x
		case float64:
			return x
		case string:
			if x == "" {
				return int64(0)
			}
			ni := parseNumeric(x)
			if ni.ok {
				if ni.isInt {
					return ni.i
				}
				return ni.f
			}
			return int64(0)
		}
		return toInt(v)
	}
	s, e, st := toNum(start), toNum(end), toNum(step)
	_, sf := s.(float64)
	_, ef := e.(float64)
	stf, stIsF := st.(float64)
	isFloat := sf || ef || (stIsF && stf != float64(int64(stf)))
	if isFloat {
		fs, fe := toFloat(s), toFloat(e)
		fst := toFloat(st)
		if fst < 0 {
			fst = -fst
		}
		if fst == 0 {
			in.throwError("ValueError", "range(): Argument #3 ($step) cannot be 0")
		}
		if fs <= fe {
			n := int64((fe-fs)/fst + 1e-9)
			for i := int64(0); i <= n; i++ {
				out.Append(fs + float64(i)*fst)
			}
		} else {
			n := int64((fs-fe)/fst + 1e-9)
			for i := int64(0); i <= n; i++ {
				out.Append(fs - float64(i)*fst)
			}
		}
		return out
	}
	is, ie, ist := toInt(s), toInt(e), toInt(st)
	if ist < 0 {
		ist = -ist
	}
	if ist == 0 {
		in.throwError("ValueError", "range(): Argument #3 ($step) cannot be 0")
	}
	if is <= ie {
		if (ie-is)/ist > 100000000 {
			in.throwError("ValueError", "The supplied range exceeds the maximum array size")
		}
		for i := is; i <= ie; i += ist {
			out.Append(i)
			if i > ie-ist {
				break
			}
		}
	} else {
		for i := is; i >= ie; i -= ist {
			out.Append(i)
			if i < ie+ist {
				break
			}
		}
	}
	return out
}

func (in *Interp) arrayMultisort(args []Value) Value {
	// collect arrays and their flags
	type col struct {
		ref   *Ref
		arr   *Array
		order int64
		flags int64
	}
	var cols []col
	for _, a := range args {
		if r, ok := a.(*Ref); ok {
			if arr, ok := r.V.(*Array); ok {
				if arr.rc > 1 {
					arr = arr.Clone()
					r.set(arr)
				}
				cols = append(cols, col{ref: r, arr: arr, order: 4, flags: 0})
				continue
			}
			a = r.V
		}
		if len(cols) == 0 {
			in.throwError("TypeError", "array_multisort(): Argument #1 ($array) must be an array or a sort flag")
		}
		f := toInt(a)
		if f == 3 || f == 4 {
			cols[len(cols)-1].order = f
		} else {
			cols[len(cols)-1].flags = f
		}
	}
	if len(cols) == 0 {
		return false
	}
	n := cols[0].arr.Len()
	for _, c := range cols {
		if c.arr.Len() != n {
			in.throwError("ValueError", "Array sizes are inconsistent")
		}
	}
	vals := make([][]Value, len(cols))
	keys := make([][]Key, len(cols))
	for i, c := range cols {
		vals[i] = c.arr.Values()
		keys[i] = c.arr.Keys()
	}
	idx := make([]int, n)
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool {
		for ci, c := range cols {
			r := in.sortCompare(deref(vals[ci][idx[a]]), deref(vals[ci][idx[b]]), c.flags)
			if c.order == 3 {
				r = -r
			}
			if r != 0 {
				return r < 0
			}
		}
		return false
	})
	for ci, c := range cols {
		na := NewArray()
		for _, i := range idx {
			k := keys[ci][i]
			if k.IsStr {
				na.SetRaw(k, vals[ci][i])
			} else {
				na.Append(vals[ci][i])
			}
		}
		c.ref.set(na)
	}
	return true
}
