			}
		}
		dec := &jsonDecoder{in: in, s: s, assoc: assoc, flags: flags, maxDepth: depth}
		v, err := dec.decode()
		in.jsonLastError = err
		if err != 0 {
			if flags&JSON_THROW_ON_ERROR != 0 {
				in.jsonLastError = 0
				ex := in.newException("JsonException", jsonErrorMsgs[err], int64(err))
				panic(&ThrowSignal{obj: ex})
			}
			return nil
		}
		return v
	})
	in.reg("json_last_error", 0, 0, func(in *Interp, args []Value) Value { return int64(in.jsonLastError) })
	in.reg("json_last_error_msg", 0, 0, func(in *Interp, args []Value) Value { return jsonErrorMsgs[in.jsonLastError] })
	in.reg("json_validate", 1, 3, func(in *Interp, args []Value) Value {
		dec := &jsonDecoder{in: in, s: toStr(args[0]), assoc: true, maxDepth: 512}
		_, err := dec.decode()
		in.jsonLastError = err
		return err == 0
	})
}

func (e *jsonEncoder) encode(v Value, sb *strings.Builder, indent int) {
	v = deref(v)
	switch x := v.(type) {
	case nil:
		sb.WriteString("null")
	case bool:
		if x {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
	case int64:
		sb.WriteString(strconv.FormatInt(x, 10))
	case float64:
		if math.IsNaN(x) || math.IsInf(x, 0) {
			e.err = 7
			sb.WriteString("0")
			return
		}
		s := formatFloatPrec(x, e.in.serializePrecision)
		s = strings.Replace(s, "E", "e", 1)
		if e.flags&JSON_PRESERVE_ZERO_FRACTION != 0 && !strings.ContainsAny(s, ".e") {
			s += ".0"
		}
		sb.WriteString(s)
	case string:
		e.encodeString(x, sb)
	case *Array:
		if e.seen[x] {
			e.err = 6
			sb.WriteString("null")
			return
		}
		if indent/1 >= e.maxDepth {
			e.err = 1
		}
		e.seen[x] = true
		defer delete(e.seen, x)
		if x.IsList() && e.flags&JSON_FORCE_OBJECT == 0 {
			if x.Len() == 0 {
				sb.WriteString("[]")
				return
			}
			sb.WriteByte('[')
			first := true
			x.Each(func(k Key, val Value) bool {
				if !first {
					sb.WriteByte(',')
				}
				first = false
				e.newline(sb, indent+1)
				e.encode(val, sb, indent+1)
				return true
			})
			e.newline(sb, indent)
			sb.WriteByte(']')
			return
		}
		if x.Len() == 0 {
			sb.WriteString("{}")
			return
		}
		sb.WriteByte('{')
		first := true
		x.Each(func(k Key, val Value) bool {
			if !first {
				sb.WriteByte(',')
			}
			first = false
			e.newline(sb, indent+1)
			e.encodeString(k.String(), sb)
			sb.WriteByte(':')
			if e.flags&JSON_PRETTY_PRINT != 0 {
				sb.WriteByte(' ')
			}
			e.encode(val, sb, indent+1)
			return true
		})
		e.newline(sb, indent)
		sb.WriteByte('}')
	case *Object:
		if e.seen[x] {
			e.err = 6
			sb.WriteString("null")
			return
		}
		if x.class.instanceOf("JsonSerializable") {
			r := e.in.callMethodByName(x, "jsonSerialize", nil)
			e.seen[x] = true
			e.encode(r, sb, indent)
			delete(e.seen, x)
			return
		}
		if x.class.isEnum() {
			if x.class.EnumBacking == "" {
				e.err = 8
				sb.WriteString("0")
				return
			}
			e.encode(e.in.getProp(x, "value"), sb, indent)
			return
		}
		if _, ok := x.internal.(*Closure); ok {
			e.err = 8
			sb.WriteString("0")
			return
		}
		if x.class.instanceOf("DateTimeInterface") {
			// encode as date props
		}
		e.seen[x] = true
		defer delete(e.seen, x)
		props := e.in.visibleProps(x, nil)
		var items []kv
		for _, p := range props {
			if p.v == uninit {
				continue
			}
			items = append(items, p)
		}
		if len(items) == 0 {
			sb.WriteString("{}")
			return
		}
		sb.WriteByte('{')
		for i, p := range items {
			if i > 0 {
				sb.WriteByte(',')
			}
			e.newline(sb, indent+1)
			e.encodeString(p.k, sb)
			sb.WriteByte(':')
			if e.flags&JSON_PRETTY_PRINT != 0 {
				sb.WriteByte(' ')
			}
			e.encode(p.v, sb, indent+1)
		}
		e.newline(sb, indent)
		sb.WriteByte('}')
	default:
		e.err = 8
		sb.WriteString("null")
	}
}

func (e *jsonEncoder) newline(sb *strings.Builder, indent int) {
	if e.flags&JSON_PRETTY_PRINT != 0 {
		sb.WriteByte('\n')
		sb.WriteString(strings.Repeat("    ", indent))
	}
}

func (e *jsonEncoder) encodeString(s string, sb *strings.Builder) {
	if e.flags&JSON_NUMERIC_CHECK != 0 {
		ni := parseNumeric(s)
		if ni.ok && ni.whole {
			if ni.isInt {
				sb.WriteString(strconv.FormatInt(ni.i, 10))
			} else {
				e.encode(ni.f, sb, 0)
			}
			return
		}
	}
	if !utf8.ValidString(s) {
		if e.flags&JSON_INVALID_UTF8_SUBSTITUTE != 0 {
			s = strings.ToValidUTF8(s, "\ufffd")
		} else if e.flags&JSON_INVALID_UTF8_IGNORE != 0 {
			s = strings.ToValidUTF8(s, "")
		} else {
			e.err = 5
			sb.WriteString("null")
			return
		}
	}
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			if e.flags&JSON_HEX_QUOT != 0 {
				sb.WriteString("\\u0022")
			} else {
				sb.WriteString("\\\"")
			}
		case '\\':
			sb.WriteString("\\\\")
		case '/':
			if e.flags&JSON_UNESCAPED_SLASHES != 0 {
				sb.WriteByte('/')
			} else {
				sb.WriteString("\\/")
			}
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\b':
			sb.WriteString("\\b")
		case '\f':
			sb.WriteString("\\f")
		case '<':
			if e.flags&JSON_HEX_TAG != 0 {
				sb.WriteString("\\u003C")
			} else {
				sb.WriteByte('<')
			}
		case '>':
			if e.flags&JSON_HEX_TAG != 0 {
				sb.WriteString("\\u003E")
			} else {
				sb.WriteByte('>')
			}
		case '&':
			if e.flags&JSON_HEX_AMP != 0 {
				sb.WriteString("\\u0026")
			} else {
				sb.WriteByte('&')
			}
		case '\'':
			if e.flags&JSON_HEX_APOS != 0 {
				sb.WriteString("\\u0027")
			} else {
				sb.WriteByte('\'')
			}
		default:
			if r < 0x20 {
				sb.WriteString(fmt.Sprintf("\\u%04x", r))
			} else if r > 127 {
				if e.flags&JSON_UNESCAPED_UNICODE != 0 && !((r == 0x2028 || r == 0x2029) && e.flags&JSON_UNESCAPED_LINE_TERMINATORS == 0) {
					sb.WriteRune(r)
				} else if r >= 0x10000 {
					r -= 0x10000
					sb.WriteString(fmt.Sprintf("\\u%04x\\u%04x", 0xD800+(r>>10), 0xDC00+(r&0x3FF)))
				} else {
					sb.WriteString(fmt.Sprintf("\\u%04x", r))
				}
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
}

type jsonDecoder struct {
	in       *Interp
	s        string
	pos      int
	assoc    bool
	flags    int64
	maxDepth int
	depth    int
}

func (d *jsonDecoder) decode() (Value, int) {
	d.skipWS()
	if d.pos >= len(d.s) {
		return nil, 4
	}
	v, err := d.value()
	if err != 0 {
		return nil, err
	}
	d.skipWS()
	if d.pos < len(d.s) {
		return nil, 4
	}
	return v, 0
}

func (d *jsonDecoder) skipWS() {
	for d.pos < len(d.s) && (d.s[d.pos] == ' ' || d.s[d.pos] == '\t' || d.s[d.pos] == '\n' || d.s[d.pos] == '\r') {
		d.pos++
	}
}

func (d *jsonDecoder) value() (Value, int) {
	d.skipWS()
	if d.pos >= len(d.s) {
		return nil, 4
	}
	c := d.s[d.pos]
	switch {
	case c == '{':
		d.depth++
		if d.depth > d.maxDepth {
			return nil, 1
		}
		defer func() { d.depth-- }()
		d.pos++
		var arr *Array
		var obj *Object
		if d.assoc {
			arr = NewArray()
		} else {
			obj = d.in.newObject(d.in.classes["stdclass"])
		}
		d.skipWS()
		if d.pos < len(d.s) && d.s[d.pos] == '}' {
			d.pos++
			if d.assoc {
				return arr, 0
			}
			return obj, 0
		}
		for {
			d.skipWS()
			if d.pos >= len(d.s) || d.s[d.pos] != '"' {
				return nil, 4
			}
			k, err := d.str()
			if err != 0 {
				return nil, err
			}
			d.skipWS()
			if d.pos >= len(d.s) || d.s[d.pos] != ':' {
				return nil, 4
			}
			d.pos++
			v, err := d.value()
			if err != 0 {
				return nil, err
			}
			if d.assoc {
				key, _ := normalizeKey(k)
				arr.Set(key, v)
			} else {
				if k == "" && false {
					return nil, 9
				}
				if len(k) > 0 && k[0] == 0 {
					return nil, 9
				}
				obj.props.SetStr(k, v)
			}
			d.skipWS()
			if d.pos >= len(d.s) {
				return nil, 4
			}
			if d.s[d.pos] == ',' {
				d.pos++
				continue
			}
			if d.s[d.pos] == '}' {
				d.pos++
				break
			}
			return nil, 4
		}
		if d.assoc {
			return arr, 0
		}
		return obj, 0
	case c == '[':
		d.depth++
		if d.depth > d.maxDepth {
			return nil, 1
		}
		defer func() { d.depth-- }()
		d.pos++
		arr := NewArray()
		d.skipWS()
		if d.pos < len(d.s) && d.s[d.pos] == ']' {
			d.pos++
			return arr, 0
		}
		for {
			v, err := d.value()
			if err != 0 {
				return nil, err
			}
			arr.Append(v)
			d.skipWS()
			if d.pos >= len(d.s) {
				return nil, 4
			}
			if d.s[d.pos] == ',' {
				d.pos++
				continue
			}
			if d.s[d.pos] == ']' {
				d.pos++
				break
			}
			return nil, 4
		}
		return arr, 0
	case c == '"':
		s, err := d.str()
		if err != 0 {
			return nil, err
		}
		return s, 0
	case c == 't':
		if strings.HasPrefix(d.s[d.pos:], "true") {
			d.pos += 4
			return true, 0
		}
		return nil, 4
	case c == 'f':
		if strings.HasPrefix(d.s[d.pos:], "false") {
			d.pos += 5
			return false, 0
		}
		return nil, 4
	case c == 'n':
		if strings.HasPrefix(d.s[d.pos:], "null") {
			d.pos += 4
			return nil, 0
		}
		return nil, 4
	case c == '-' || isDigit(c):
		start := d.pos
		if c == '-' {
			d.pos++
		}
		if d.pos >= len(d.s) || !isDigit(d.s[d.pos]) {
			return nil, 4
		}
		if d.s[d.pos] == '0' {
			d.pos++
			if d.pos < len(d.s) && isDigit(d.s[d.pos]) {
				return nil, 4
			}
		} else {
			for d.pos < len(d.s) && isDigit(d.s[d.pos]) {
				d.pos++
			}
		}
		isFloat := false
		if d.pos < len(d.s) && d.s[d.pos] == '.' {
			isFloat = true
			d.pos++
			if d.pos >= len(d.s) || !isDigit(d.s[d.pos]) {
				return nil, 4
			}
			for d.pos < len(d.s) && isDigit(d.s[d.pos]) {
				d.pos++
			}
		}
		if d.pos < len(d.s) && (d.s[d.pos] == 'e' || d.s[d.pos] == 'E') {
			isFloat = true
			d.pos++
			if d.pos < len(d.s) && (d.s[d.pos] == '+' || d.s[d.pos] == '-') {
				d.pos++
			}
			if d.pos >= len(d.s) || !isDigit(d.s[d.pos]) {
				return nil, 4
			}
			for d.pos < len(d.s) && isDigit(d.s[d.pos]) {
				d.pos++
			}
		}
		numStr := d.s[start:d.pos]
		if !isFloat {
			i, err := strconv.ParseInt(numStr, 10, 64)
			if err == nil {
				return i, 0
			}
			if d.flags&JSON_BIGINT_AS_STRING != 0 {
				return numStr, 0
			}
		}
		f, _ := strconv.ParseFloat(numStr, 64)
		return f, 0
	}
	return nil, 4
}

func (d *jsonDecoder) str() (string, int) {
	d.pos++ // opening quote
	var sb strings.Builder
	for d.pos < len(d.s) {
		c := d.s[d.pos]
		if c == '"' {
			d.pos++
			s := sb.String()
			if !utf8.ValidString(s) {
				if d.flags&JSON_INVALID_UTF8_IGNORE != 0 {
					return strings.ToValidUTF8(s, ""), 0
				}
				if d.flags&JSON_INVALID_UTF8_SUBSTITUTE != 0 {
					return strings.ToValidUTF8(s, "\ufffd"), 0
				}
				return "", 5
			}
			return s, 0
		}
		if c < 0x20 {
			return "", 3
		}
		if c == '\\' {
			d.pos++
			if d.pos >= len(d.s) {
				return "", 4
			}
			esc := d.s[d.pos]
			d.pos++
			switch esc {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case '/':
				sb.WriteByte('/')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case 'u':
				if d.pos+4 > len(d.s) {
					return "", 4
				}
				cp, err := strconv.ParseUint(d.s[d.pos:d.pos+4], 16, 32)
				if err != nil {
					return "", 4
				}
				d.pos += 4
				if cp >= 0xD800 && cp <= 0xDBFF {
					// surrogate pair
					if d.pos+6 <= len(d.s) && d.s[d.pos] == '\\' && d.s[d.pos+1] == 'u' {
						lo, err := strconv.ParseUint(d.s[d.pos+2:d.pos+6], 16, 32)
						if err == nil && lo >= 0xDC00 && lo <= 0xDFFF {
							d.pos += 6
							r := rune(((cp - 0xD800) << 10) + (lo - 0xDC00) + 0x10000)
							sb.WriteRune(r)
							continue
						}
					}
					return "", 10
				}
				if cp >= 0xDC00 && cp <= 0xDFFF {
					return "", 10
				}
				sb.WriteRune(rune(cp))
			default:
				return "", 4
			}
			continue
		}
		sb.WriteByte(c)
		d.pos++
	}
	return "", 4
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > builtins_json.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

const (
	JSON_HEX_TAG                 = 1
	JSON_HEX_AMP                 = 2
	JSON_HEX_APOS                = 4
	JSON_HEX_QUOT                = 8
	JSON_FORCE_OBJECT            = 16
	JSON_NUMERIC_CHECK           = 32
	JSON_UNESCAPED_SLASHES       = 64
	JSON_PRETTY_PRINT            = 128
	JSON_UNESCAPED_UNICODE       = 256
	JSON_PARTIAL_OUTPUT_ON_ERROR = 512
	JSON_PRESERVE_ZERO_FRACTION  = 1024
	JSON_UNESCAPED_LINE_TERMINATORS = 2048
	JSON_OBJECT_AS_ARRAY         = 1
	JSON_BIGINT_AS_STRING        = 2
	JSON_INVALID_UTF8_IGNORE     = 1048576
	JSON_INVALID_UTF8_SUBSTITUTE = 2097152
	JSON_THROW_ON_ERROR          = 4194304
)

var jsonErrorMsgs = map[int]string{
	0:  "No error",
	1:  "Maximum stack depth exceeded",
	2:  "State mismatch (invalid or malformed JSON)",
	3:  "Control character error, possibly incorrectly encoded",
	4:  "Syntax error",
	5:  "Malformed UTF-8 characters, possibly incorrectly encoded",
	6:  "Recursion detected",
	7:  "Inf and NaN cannot be JSON encoded",
	8:  "Type is not supported",
	9:  "The decoded property name is invalid",
	10: "Single unpaired UTF-16 surrogate in unicode escape",
}

type jsonEncoder struct {
	in    *Interp
	flags int64
	depth int
	maxDepth int
	err   int
	seen  map[interface{}]bool
}

func (in *Interp) initJsonFunctions() {
	in.reg("json_encode", 1, 3, func(in *Interp, args []Value) Value {
		flags := int64(0)
		if len(args) > 1 {
			flags = toInt(args[1])
		}
		depth := 512
		if len(args) > 2 {
			depth = int(toInt(args[2]))
		}
		enc := &jsonEncoder{in: in, flags: flags, maxDepth: depth, seen: map[interface{}]bool{}}
		var sb strings.Builder
		enc.encode(args[0], &sb, 0)
		in.jsonLastError = enc.err
		if enc.err != 0 {
			if flags&JSON_THROW_ON_ERROR != 0 {
				in.jsonLastError = 0
				ex := in.newException("JsonException", jsonErrorMsgs[enc.err], int64(enc.err))
				panic(&ThrowSignal{obj: ex})
			}
			if flags&JSON_PARTIAL_OUTPUT_ON_ERROR != 0 {
				return sb.String()
			}
			return false
		}
		return sb.String()
	})
	in.reg("json_decode", 1, 4, func(in *Interp, args []Value) Value {
		s := in.argStr("json_decode", args, 0)
		assoc := false
		flags := int64(0)
		depth := 512
		if len(args) > 3 {
			flags = toInt(args[3])
		}
		if len(args) > 1 {
			if args[1] == nil {
				assoc = flags&JSON_OBJECT_AS_ARRAY != 0
			} else {
				assoc = toBool(args[1])
			}
		} else {
			assoc = flags&JSON_OBJECT_AS_ARRAY != 0
		}
		if len(args) > 2 {
			depth = int(toInt(args[2]))
			if depth <= 0 {
				in.throwError("ValueError", "json_decode(): Argument #3 ($depth) must be greater than 0")
			}
		}
		dec := &jsonDecoder{in: in, s: s, assoc: assoc, flags: flags, maxDepth: depth}
		v, err := dec.decode()
		in.jsonLastError = err
		if err != 0 {
			if flags&JSON_THROW_ON_ERROR != 0 {
				in.jsonLastError = 0
				ex := in.newException("JsonException", jsonErrorMsgs[err], int64(err))
				panic(&ThrowSignal{obj: ex})
			}
			return nil
		}
		return v
	})
	in.reg("json_last_error", 0, 0, func(in *Interp, args []Value) Value { return int64(in.jsonLastError) })
	in.reg("json_last_error_msg", 0, 0, func(in *Interp, args []Value) Value { return jsonErrorMsgs[in.jsonLastError] })
	in.reg("json_validate", 1, 3, func(in *Interp, args []Value) Value {
		dec := &jsonDecoder{in: in, s: toStr(args[0]), assoc: true, maxDepth: 512}
		_, err := dec.decode()
		in.jsonLastError = err
		return err == 0
	})
}

func (e *jsonEncoder) encode(v Value, sb *strings.Builder, indent int) {
	v = deref(v)
	switch x := v.(type) {
	case nil:
		sb.WriteString("null")
	case bool:
		if x {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
	case int64:
		sb.WriteString(strconv.FormatInt(x, 10))
	case float64:
		if math.IsNaN(x) || math.IsInf(x, 0) {
			e.err = 7
			sb.WriteString("0")
			return
		}
		s := formatFloatPrec(x, e.in.serializePrecision)
		s = strings.Replace(s, "E", "e", 1)
		if e.flags&JSON_PRESERVE_ZERO_FRACTION != 0 && !strings.ContainsAny(s, ".e") {
			s += ".0"
		}
		sb.WriteString(s)
	case string:
		e.encodeString(x, sb)
	case *Array:
		if e.seen[x] {
			e.err = 6
			sb.WriteString("null")
			return
		}
		if indent/1 >= e.maxDepth {
			e.err = 1
		}
		e.seen[x] = true
		defer delete(e.seen, x)
		if x.IsList() && e.flags&JSON_FORCE_OBJECT == 0 {
			if x.Len() == 0 {
				sb.WriteString("[]")
				return
			}
			sb.WriteByte('[')
			first := true
			x.Each(func(k Key, val Value) bool {
				if !first {
					sb.WriteByte(',')
				}
				first = false
