func (e *jsonEncoder) newline(sb *strings.Builder, indent int) {
	if e.flags&JSON_PRETTY_PRINT != 0 {
		sb.WriteByte('\n')
		sb.WriteString(strings.Repeat("    ", indent))
	}
}

func (e *jsonEncoder) encodeString(s string, sb *strings.Builder) {
	if e.flags&JSON_NUMERIC_CHECK != 0 {
		ni := parseNumeric(s)
		if ni.ok && ni.whole {
			if ni.isInt {
				sb.WriteString(strconv.FormatInt(ni.i, 10))
			} else {
				e.encode(ni.f, sb, 0)
			}
			return
		}
	}
	if !utf8.ValidString(s) {
		if e.flags&JSON_INVALID_UTF8_SUBSTITUTE != 0 {
			s = strings.ToValidUTF8(s, "\ufffd")
		} else if e.flags&JSON_INVALID_UTF8_IGNORE != 0 {
			s = strings.ToValidUTF8(s, "")
		} else {
			e.err = 5
			sb.WriteString("null")
			return
		}
	}
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			if e.flags&JSON_HEX_QUOT != 0 {
				sb.WriteString("\\u0022")
			} else {
				sb.WriteString("\\\"")
			}
		case '\\':
			sb.WriteString("\\\\")
		case '/':
			if e.flags&JSON_UNESCAPED_SLASHES != 0 {
				sb.WriteByte('/')
			} else {
				sb.WriteString("\\/")
			}
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\b':
			sb.WriteString("\\b")
		case '\f':
			sb.WriteString("\\f")
		case '<':
			if e.flags&JSON_HEX_TAG != 0 {
				sb.WriteString("\\u003C")
			} else {
				sb.WriteByte('<')
			}
		case '>':
			if e.flags&JSON_HEX_TAG != 0 {
				sb.WriteString("\\u003E")
			} else {
				sb.WriteByte('>')
			}
		case '&':
			if e.flags&JSON_HEX_AMP != 0 {
				sb.WriteString("\\u0026")
			} else {
				sb.WriteByte('&')
			}
		case '\'':
			if e.flags&JSON_HEX_APOS != 0 {
				sb.WriteString("\\u0027")
			} else {
				sb.WriteByte('\'')
			}
		default:
			if r < 0x20 {
				sb.WriteString(fmt.Sprintf("\\u%04x", r))
			} else if r > 127 {
				if e.flags&JSON_UNESCAPED_UNICODE != 0 && !((r == 0x2028 || r == 0x2029) && e.flags&JSON_UNESCAPED_LINE_TERMINATORS == 0) {
