			if err == nil {
				return i, 0
			}
			if d.flags&JSON_BIGINT_AS_STRING != 0 {
				return numStr, 0
			}
		}
		f, _ := strconv.ParseFloat(numStr, 64)
		return f, 0
	}
	return nil, 4
}

func (d *jsonDecoder) str() (string, int) {
	d.pos++ // opening quote
	var sb strings.Builder
	for d.pos < len(d.s) {
		c := d.s[d.pos]
		if c == '"' {
			d.pos++
			s := sb.String()
			if !utf8.ValidString(s) {
				if d.flags&JSON_INVALID_UTF8_IGNORE != 0 {
					return strings.ToValidUTF8(s, ""), 0
				}
				if d.flags&JSON_INVALID_UTF8_SUBSTITUTE != 0 {
					return strings.ToValidUTF8(s, "\ufffd"), 0
				}
				return "", 5
			}
			return s, 0
		}
		if c < 0x20 {
			return "", 3
		}
		if c == '\\' {
			d.pos++
			if d.pos >= len(d.s) {
				return "", 4
			}
			esc := d.s[d.pos]
			d.pos++
			switch esc {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case '/':
				sb.WriteByte('/')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
