					return "", 10
				}
				if cp >= 0xDC00 && cp <= 0xDFFF {
					return "", 10
				}
				sb.WriteRune(rune(cp))
			default:
				return "", 4
			}
			continue
		}
		sb.WriteByte(c)
		d.pos++
	}
	return "", 4
}
