// A backtracking regex engine supporting a practical subset of PCRE.

type reNodeKind int

const (
	rnLit reNodeKind = iota
	rnAny
	rnClass
	rnStart // ^
	rnEnd   // $
	rnStrStart // \A
	rnStrEnd   // \z
	rnStrEndNL // \Z
	rnWordB
	rnNotWordB
	rnGroup
	rnAlt
	rnConcat
	rnRepeat
	rnBackref
	rnLookahead
	rnNegLookahead
	rnLookbehind
	rnNegLookbehind
	rnAtomic
	rnEmpty
	rnRecurse
	rnCond
	rnKeep // \K
	rnFail
)

type reClassItem struct {
	lo, hi rune
}

type reNode struct {
	kind     reNodeKind
	r        rune   // literal
	ci       bool   // case-insensitive
	dotall   bool
	multiline bool
	items    []reClassItem
	negate   bool
	classFns []func(rune) bool
	children []*reNode
	min, max int // repeat; max -1 = inf
	greedy   bool
	possessive bool
	group    int // capture index (0 = non-capturing)
	name     string
	backref  int
	backrefName string
	condGroup int
}

type Regex struct {
	root      *reNode
	ngroups   int
	names     map[string]int
	nameList  []string // index -> name
	utf8      bool
	anchored  bool
	dollarEnd bool
	ungreedy  bool
	pattern   string
	groupNodes map[int]*reNode
}

type reParser struct {
	src   string
	pos   int
	ci    bool
	multi bool
	dotall bool
	ext   bool
	ungreedy bool
	utf8  bool
	ngroups int
	names map[string]int
	nameList []string
	groupNodes map[int]*reNode
	noAutoCapture bool
}

type reError struct{ msg string }

func (e *reError) Error() string { return e.msg }

func compileRegex(pattern string, flags string) (*Regex, error) {
	p := &reParser{src: pattern, names: map[string]int{}, groupNodes: map[int]*reNode{}}
	re := &Regex{pattern: pattern}
	for _, f := range flags {
		switch f {
		case 'i':
			p.ci = true
		case 'm':
			p.multi = true
		case 's':
			p.dotall = true
		case 'x':
			p.ext = true
		case 'u':
			p.utf8 = true
			re.utf8 = true
		case 'U':
			p.ungreedy = true
		case 'D':
			re.dollarEnd = true
		case 'A':
			re.anchored = true
		case 'n':
			p.noAutoCapture = true
		}
	}
	root, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.src) {
		if p.src[p.pos] == ')' {
			return nil, &reError{"unmatched closing parenthesis"}
		}
		return nil, &reError{"syntax error"}
	}
	re.root = root
	re.ngroups = p.ngroups
	re.names = p.names
	re.nameList = p.nameList
	re.groupNodes = p.groupNodes
	return re, nil
}

func (p *reParser) peek() byte {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}

func (p *reParser) eof() bool { return p.pos >= len(p.src) }

func (p *reParser) parseAlt() (*reNode, error) {
	var alts []*reNode
	for {
		c, err := p.parseConcat()
		if err != nil {
			return nil, err
		}
		alts = append(alts, c)
		if p.peek() == '|' {
			p.pos++
			continue
		}
		break
	}
	if len(alts) == 1 {
		return alts[0], nil
	}
	return &reNode{kind: rnAlt, children: alts}, nil
}

func (p *reParser) parseConcat() (*reNode, error) {
	var items []*reNode
	for !p.eof() {
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom, err := p.parseAtom()
		if err != nil {
			return nil, err
		}
		if atom == nil {
			continue
		}
		atom, err = p.parseQuantifier(atom)
		if err != nil {
			return nil, err
		}
		items = append(items, atom)
	}
	if len(items) == 1 {
		return items[0], nil
	}
	if len(items) == 0 {
		return &reNode{kind: rnEmpty}, nil
	}
	return &reNode{kind: rnConcat, children: items}, nil
}

func (p *reParser) parseQuantifier(atom *reNode) (*reNode, error) {
	for !p.eof() {
		if p.ext {
			p.skipExt()
			if p.eof() {
				break
			}
		}
		c := p.peek()
		min, max := -1, -1
		switch c {
		case '*':
			min, max = 0, -1
			p.pos++
		case '+':
			min, max = 1, -1
			p.pos++
		case '?':
			min, max = 0, 1
			p.pos++
		case '{':
			// {n}, {n,}, {n,m}, {,m}
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return atom, nil
			}
			body := p.src[p.pos+1 : p.pos+end]
			var ok bool
			min, max, ok = parseBraces(body)
			if !ok {
				return atom, nil
			}
			p.pos += end + 1
