			return atom, nil
		}
		greedy := !p.ungreedy
		possessive := false
		if p.peek() == '?' {
			greedy = !greedy
			p.pos++
		} else if p.peek() == '+' {
			possessive = true
			p.pos++
		}
		if atom.kind == rnRepeat && false {
			return nil, &reError{"nothing to repeat"}
		}
		atom = &reNode{kind: rnRepeat, children: []*reNode{atom}, min: min, max: max, greedy: greedy, possessive: possessive}
	}
	return atom, nil
}

func parseBraces(body string) (int, int, bool) {
	if body == "" {
		return 0, 0, false
	}
	parts := strings.SplitN(body, ",", 2)
	var min, max int
	if parts[0] == "" {
		if len(parts) == 1 {
			return 0, 0, false
		}
		min = 0
	} else {
		n, err := strconv.Atoi(parts[0])
		if err != nil {
			return 0, 0, false
		}
		min = n
	}
	if len(parts) == 1 {
		return min, min, true
	}
	if parts[1] == "" {
		return min, -1, true
	}
	n, err := strconv.Atoi(parts[1])
	if err != nil {
		return 0, 0, false
	}
	return min, n, true
}

func (p *reParser) skipExt() {
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.pos++
			continue
		}
		if c == '#' {
			for !p.eof() && p.peek() != '\n' {
				p.pos++
			}
			continue
		}
		break
	}
