func (p *reParser) nextRune() rune {
	if p.utf8 {
		r, size := utf8.DecodeRuneInString(p.src[p.pos:])
		p.pos += size
		return r
	}
	c := p.src[p.pos]
	p.pos++
	return rune(c)
}

func (p *reParser) lit(r rune) *reNode {
	return &reNode{kind: rnLit, r: r, ci: p.ci}
}

func (p *reParser) parseAtom() (*reNode, error) {
	if p.ext {
		p.skipExt()
		if p.eof() {
			return nil, nil
		}
		c := p.peek()
		if c == '|' || c == ')' {
			return nil, nil
		}
