	c := p.peek()
	switch c {
	case '(':
		return p.parseGroup()
	case '[':
		return p.parseClass()
	case '.':
		p.pos++
		return &reNode{kind: rnAny, dotall: p.dotall}, nil
	case '^':
		p.pos++
		return &reNode{kind: rnStart, multiline: p.multi}, nil
	case '$':
		p.pos++
		return &reNode{kind: rnEnd, multiline: p.multi}, nil
	case '\\':
		return p.parseEscape()
	case '*', '+', '?':
		return nil, &reError{"quantifier does not follow a repeatable item"}
	}
	r := p.nextRune()
	return p.lit(r), nil
}

func (p *reParser) parseGroup() (*reNode, error) {
	p.pos++ // (
	node := &reNode{kind: rnGroup}
	if p.peek() == '?' {
		p.pos++
		c := p.peek()
		switch {
		case c == ':':
			p.pos++
		case c == '>':
			p.pos++
			node.kind = rnAtomic
		case c == '=':
			p.pos++
			node.kind = rnLookahead
		case c == '!':
			p.pos++
			node.kind = rnNegLookahead
		case c == '<' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '=':
			p.pos += 2
			node.kind = rnLookbehind
		case c == '<' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '!':
			p.pos += 2
			node.kind = rnNegLookbehind
		case c == 'P' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '<', c == '<', c == '\'':
			// named group
			if c == 'P' {
				p.pos++
			}
			closer := byte('>')
			if p.peek() == '\'' {
				closer = '\''
			}
			p.pos++
			end := strings.IndexByte(p.src[p.pos:], closer)
			if end < 0 {
				return nil, &reError{"syntax error in subpattern name (missing terminator?)"}
			}
			name := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			p.ngroups++
			node.group = p.ngroups
			node.name = name
			p.names[name] = node.group
			for len(p.nameList) <= node.group {
				p.nameList = append(p.nameList, "")
			}
			p.nameList[node.group] = name
		case c == 'P' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '=':
			// (?P=name) backreference
			p.pos += 2
			end := strings.IndexByte(p.src[p.pos:], ')')
			if end < 0 {
				return nil, &reError{"syntax error"}
			}
			name := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			return &reNode{kind: rnBackref, backrefName: name, ci: p.ci}, nil
		case c == 'P' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '>':
			p.pos += 2
			end := strings.IndexByte(p.src[p.pos:], ')')
			name := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			return &reNode{kind: rnRecurse, backrefName: name}, nil
		case c == 'R' || isDigit(c):
			end := strings.IndexByte(p.src[p.pos:], ')')
			if end < 0 {
				return nil, &reError{"syntax error"}
			}
			ref := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			n := 0
			if ref != "R" {
				n, _ = strconv.Atoi(ref)
			}
			return &reNode{kind: rnRecurse, backref: n}, nil
		case c == '#':
			// comment
			end := strings.IndexByte(p.src[p.pos:], ')')
			if end < 0 {
				return nil, &reError{"missing ) after (?# comment"}
			}
			p.pos += end + 1
			return nil, nil
		case c == '(':
			// conditional (?(1)yes|no)
			p.pos++
			end := strings.IndexByte(p.src[p.pos:], ')')
			if end < 0 {
				return nil, &reError{"syntax error"}
			}
			ref := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			node.kind = rnCond
			if n, err := strconv.Atoi(ref); err == nil {
				node.condGroup = n
			} else {
				ref = strings.Trim(ref, "<>'")
				node.backrefName = ref
			}
			body, err := p.parseAlt()
			if err != nil {
				return nil, err
			}
			if p.peek() != ')' {
				return nil, &reError{"missing closing parenthesis"}
			}
			p.pos++
			if body.kind == rnAlt {
				node.children = body.children
			} else {
				node.children = []*reNode{body}
			}
			return node, nil
		default:
			// inline flags (?i) (?i-m) (?i:...)
			saveCi, saveMulti, saveDot, saveExt, saveUng := p.ci, p.multi, p.dotall, p.ext, p.ungreedy
			on := true
			for !p.eof() {
				f := p.peek()
				if f == ')' || f == ':' {
					break
				}
				p.pos++
				switch f {
				case '-':
					on = false
				case 'i':
					p.ci = on
				case 'm':
					p.multi = on
				case 's':
					p.dotall = on
				case 'x':
					p.ext = on
				case 'U':
					p.ungreedy = on
				case 'J', 'u', 'n':
				default:
					return nil, &reError{fmt.Sprintf("unrecognized character after (? or (?-")}
				}
			}
			if p.eof() {
				return nil, &reError{"missing )"}
			}
			if p.peek() == ')' {
				p.pos++
				// flags apply to rest of enclosing group
				return nil, nil
			}
			p.pos++ // ':'
			body, err := p.parseAlt()
			if err != nil {
				return nil, err
			}
			if p.peek() != ')' {
				return nil, &reError{"missing closing parenthesis"}
			}
			p.pos++
			p.ci, p.multi, p.dotall, p.ext, p.ungreedy = saveCi, saveMulti, saveDot, saveExt, saveUng
			node.children = []*reNode{body}
			return node, nil
		}
	} else if !p.noAutoCapture {
		p.ngroups++
		node.group = p.ngroups
	}
	saveCi, saveMulti, saveDot, saveExt, saveUng := p.ci, p.multi, p.dotall, p.ext, p.ungreedy
	body, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	p.ci, p.multi, p.dotall, p.ext, p.ungreedy = saveCi, saveMulti, saveDot, saveExt, saveUng
	if p.peek() != ')' {
		return nil, &reError{"missing closing parenthesis"}
	}
	p.pos++
	node.children = []*reNode{body}
	if node.group > 0 {
		p.groupNodes[node.group] = node
	}
	return node, nil
}

func (p *reParser) parseEscape() (*reNode, error) {
	p.pos++ // backslash
	if p.eof() {
		return nil, &reError{"\\ at end of pattern"}
	}
	c := p.src[p.pos]
	p.pos++
	switch c {
	case 'd':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isDigitR}}, nil
	case 'D':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isDigitR}, negate: true}, nil
	case 'w':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isWordR}}, nil
	case 'W':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isWordR}, negate: true}, nil
	case 's':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isSpaceR}}, nil
	case 'S':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isSpaceR}, negate: true}, nil
	case 'h':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isHSpaceR}}, nil
	case 'H':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isHSpaceR}, negate: true}, nil
	case 'v':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isVSpaceR}}, nil
	case 'V':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isVSpaceR}, negate: true}, nil
	case 'R':
		// newline sequence: \r\n | \n | \r | \v | \f
		alt := &reNode{kind: rnAlt, children: []*reNode{
			{kind: rnConcat, children: []*reNode{{kind: rnLit, r: '\r'}, {kind: rnLit, r: '\n'}}},
			{kind: rnClass, items: []reClassItem{{'\n', '\r'}, {'\v', '\f'}, {0x85, 0x85}, {0x2028, 0x2029}}},
		}}
		return &reNode{kind: rnAtomic, children: []*reNode{alt}}, nil
	case 'N':
		return &reNode{kind: rnClass, items: []reClassItem{{'\n', '\n'}}, negate: true}, nil
	case 'b':
		return &reNode{kind: rnWordB}, nil
	case 'B':
		return &reNode{kind: rnNotWordB}, nil
	case 'A':
		return &reNode{kind: rnStrStart}, nil
	case 'z':
		return &reNode{kind: rnStrEnd}, nil
	case 'Z':
		return &reNode{kind: rnStrEndNL}, nil
	case 'G':
		return &reNode{kind: rnStrStart}, nil
	case 'K':
		return &reNode{kind: rnKeep}, nil
	case 'Q':
		end := strings.Index(p.src[p.pos:], "\\E")
		var lit string
		if end < 0 {
			lit = p.src[p.pos:]
			p.pos = len(p.src)
		} else {
			lit = p.src[p.pos : p.pos+end]
			p.pos += end + 2
		}
		var nodes []*reNode
		for _, r := range lit {
			nodes = append(nodes, p.lit(r))
		}
		if len(nodes) == 0 {
			return nil, nil
		}
		return &reNode{kind: rnConcat, children: nodes}, nil
	case 'E':
		return nil, nil
	case 'k':
		// \k<name> \k'name' \k{name}
		if p.eof() {
			return nil, &reError{"syntax error"}
		}
		open := p.peek()
		closer := byte('>')
		switch open {
		case '<':
			closer = '>'
		case '\'':
			closer = '\''
		case '{':
			closer = '}'
		default:
			return nil, &reError{"\\k is not followed by a name"}
		}
		p.pos++
		end := strings.IndexByte(p.src[p.pos:], closer)
		if end < 0 {
			return nil, &reError{"syntax error"}
		}
		name := p.src[p.pos : p.pos+end]
		p.pos += end + 1
		return &reNode{kind: rnBackref, backrefName: name, ci: p.ci}, nil
	case 'g':
		// \g{n} \g{-n} \gn
		var ref string
		if p.peek() == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return nil, &reError{"syntax error"}
			}
			ref = p.src[p.pos+1 : p.pos+end]
			p.pos += end + 1
		} else {
			start := p.pos
			if p.peek() == '-' {
				p.pos++
			}
			for !p.eof() && isDigit(p.peek()) {
				p.pos++
			}
			ref = p.src[start:p.pos]
		}
		n, err := strconv.Atoi(ref)
		if err != nil {
			return &reNode{kind: rnBackref, backrefName: ref, ci: p.ci}, nil
		}
		if n < 0 {
			n = p.ngroups + 1 + n
		}
		return &reNode{kind: rnBackref, backref: n, ci: p.ci}, nil
	case 'p', 'P':
		neg := c == 'P'
		var name string
		if p.peek() == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return nil, &reError{"malformed \\P or \\p sequence"}
			}
			name = p.src[p.pos+1 : p.pos+end]
			p.pos += end + 1
		} else if !p.eof() {
			name = string(p.src[p.pos])
			p.pos++
		}
		if strings.HasPrefix(name, "^") {
			neg = !neg
			name = name[1:]
		}
		fn := unicodePropFn(name)
		if fn == nil {
			return nil, &reError{"unknown property name after \\P or \\p"}
		}
		return &reNode{kind: rnClass, classFns: []func(rune) bool{fn}, negate: neg}, nil
	case 'X':
		// extended grapheme: approximate as any char + combining marks
		return &reNode{kind: rnConcat, children: []*reNode{
			{kind: rnAny, dotall: true},
			{kind: rnRepeat, min: 0, max: -1, greedy: true, children: []*reNode{{kind: rnClass, classFns: []func(rune) bool{func(r rune) bool { return unicode.Is(unicode.M, r) }}}}},
		}}, nil
	}
	if isDigit(c) && c != '0' {
		// backreference \1..\99
		n := int(c - '0')
		for !p.eof() && isDigit(p.peek()) && n*10+int(p.peek()-'0') <= p.ngroups {
			n = n*10 + int(p.peek()-'0')
			p.pos++
		}
		return &reNode{kind: rnBackref, backref: n, ci: p.ci}, nil
	}
	r, err := p.escapeChar(c)
	if err != nil {
		return nil, err
	}
	return p.lit(r), nil
}

// escapeChar handles single-char escapes (shared with classes)
func (p *reParser) escapeChar(c byte) (rune, error) {
	switch c {
	case 'n':
		return '\n', nil
	case 'r':
		return '\r', nil
	case 't':
		return '\t', nil
	case 'f':
		return '\f', nil
	case 'e':
		return 27, nil
	case 'a':
		return 7, nil
	case '0':
		// octal
		v := 0
		cnt := 0
		for !p.eof() && cnt < 2 && p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + int(p.peek()-'0')
			p.pos++
			cnt++
		}
		return rune(v), nil
	case 'x':
		if p.peek() == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return 0, &reError{"syntax error"}
			}
			v, err := strconv.ParseUint(p.src[p.pos+1:p.pos+end], 16, 32)
			if err != nil {
				return 0, &reError{"syntax error"}
			}
			p.pos += end + 1
			return rune(v), nil
		}
		v := 0
		cnt := 0
		for !p.eof() && cnt < 2 && isHex(p.peek()) {
			v = v*16 + hexVal(p.peek())
			p.pos++
			cnt++
		}
		return rune(v), nil
	case 'c':
		if p.eof() {
			return 0, &reError{"\\c at end of pattern"}
		}
		ch := p.src[p.pos]
		p.pos++
		return rune(phpToUpper(string(ch))[0] ^ 0x40), nil
	}
	if c >= 0x80 && p.utf8 {
		// multibyte literal after backslash
		p.pos--
		r := p.nextRune()
		return r, nil
	}
	return rune(c), nil
}

func (p *reParser) parseClass() (*reNode, error) {
	p.pos++ // [
	node := &reNode{kind: rnClass, ci: p.ci}
	if p.peek() == '^' {
		node.negate = true
		p.pos++
	}
	first := true
	for {
		if p.eof() {
			return nil, &reError{"missing terminating ] for character class"}
		}
		c := p.peek()
		if c == ']' && !first {
			p.pos++
			break
		}
		first = false
		var lo rune
		isSet := false
		if c == '[' && p.pos+1 < len(p.src) && p.src[p.pos+1] == ':' {
			end := strings.Index(p.src[p.pos:], ":]")
			if end > 0 {
				name := p.src[p.pos+2 : p.pos+end]
				neg := false
				if strings.HasPrefix(name, "^") {
					neg = true
					name = name[1:]
				}
				fn := posixClassFn(name)
				if fn == nil {
					return nil, &reError{"unknown POSIX class name"}
				}
				if neg {
					f := fn
					fn = func(r rune) bool { return !f(r) }
				}
				node.classFns = append(node.classFns, fn)
				p.pos += end + 2
				isSet = true
			}
		}
		if isSet {
			continue
		}
		if c == '\\' {
			p.pos++
			if p.eof() {
				return nil, &reError{"\\ at end of pattern"}
			}
			e := p.src[p.pos]
			p.pos++
			switch e {
			case 'd':
				node.classFns = append(node.classFns, isDigitR)
				continue
			case 'D':
				node.classFns = append(node.classFns, func(r rune) bool { return !isDigitR(r) })
				continue
			case 'w':
				node.classFns = append(node.classFns, isWordR)
				continue
			case 'W':
				node.classFns = append(node.classFns, func(r rune) bool { return !isWordR(r) })
				continue
			case 's':
				node.classFns = append(node.classFns, isSpaceR)
				continue
			case 'S':
				node.classFns = append(node.classFns, func(r rune) bool { return !isSpaceR(r) })
				continue
			case 'h':
				node.classFns = append(node.classFns, isHSpaceR)
				continue
			case 'v':
				node.classFns = append(node.classFns, isVSpaceR)
				continue
			case 'p', 'P':
				neg := e == 'P'
				var name string
				if p.peek() == '{' {
					end := strings.IndexByte(p.src[p.pos:], '}')
					if end < 0 {
						return nil, &reError{"malformed \\P or \\p sequence"}
					}
					name = p.src[p.pos+1 : p.pos+end]
					p.pos += end + 1
				} else {
					name = string(p.src[p.pos])
					p.pos++
				}
				if strings.HasPrefix(name, "^") {
					neg = !neg
					name = name[1:]
				}
				fn := unicodePropFn(name)
				if fn == nil {
					return nil, &reError{"unknown property name after \\P or \\p"}
				}
				if neg {
					f := fn
					fn = func(r rune) bool { return !f(r) }
				}
				node.classFns = append(node.classFns, fn)
				continue
			case 'b':
				lo = 8
			default:
				r, err := p.escapeChar(e)
				if err != nil {
					return nil, err
				}
				lo = r
			}
		} else {
			lo = p.nextRune()
		}
		// range?
		if p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			var hi rune
			if p.peek() == '\\' {
				p.pos++
				e := p.src[p.pos]
				p.pos++
				r, err := p.escapeChar(e)
				if err != nil {
					return nil, err
				}
				hi = r
			} else {
				hi = p.nextRune()
			}
			if hi < lo {
				return nil, &reError{"range out of order in character class"}
			}
			node.items = append(node.items, reClassItem{lo, hi})
			continue
		}
		node.items = append(node.items, reClassItem{lo, lo})
	}
	return node, nil
}

func isDigitR(r rune) bool { return r >= '0' && r <= '9' }
func isWordR(r rune) bool {
	return r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')
}
func isSpaceR(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\f' || r == '\v'
}
func isHSpaceR(r rune) bool { return r == ' ' || r == '\t' || r == 0xA0 }
func isVSpaceR(r rune) bool { return r == '\n' || r == '\r' || r == '\f' || r == '\v' || r == 0x85 }

func posixClassFn(name string) func(rune) bool {
	switch name {
	case "alpha":
		return func(r rune) bool { return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') }
	case "digit":
		return isDigitR
	case "alnum":
		return func(r rune) bool { return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') }
	case "space":
		return isSpaceR
	case "upper":
		return func(r rune) bool { return r >= 'A' && r <= 'Z' }
	case "lower":
		return func(r rune) bool { return r >= 'a' && r <= 'z' }
	case "punct":
		return func(r rune) bool { return r > 32 && r < 127 && !isWordR(r) || r == '_' && false }
	case "xdigit":
		return func(r rune) bool { return r < 128 && isHex(byte(r)) }
	case "word":
		return isWordR
	case "blank":
		return func(r rune) bool { return r == ' ' || r == '\t' }
	case "cntrl":
		return func(r rune) bool { return r < 32 || r == 127 }
	case "print":
		return func(r rune) bool { return r >= 32 && r < 127 }
	case "graph":
		return func(r rune) bool { return r > 32 && r < 127 }
	case "ascii":
		return func(r rune) bool { return r < 128 }
	}
	return nil
}

func unicodePropFn(name string) func(rune) bool {
	switch name {
	case "L", "Letter":
		return unicode.IsLetter
	case "Lu":
		return unicode.IsUpper
	case "Ll":
		return unicode.IsLower
	case "Lt":
		return unicode.IsTitle
	case "Lm":
		return func(r rune) bool { return unicode.Is(unicode.Lm, r) }
	case "Lo":
		return func(r rune) bool { return unicode.Is(unicode.Lo, r) }
	case "N":
		return unicode.IsNumber
	case "Nd":
		return unicode.IsDigit
	case "Nl":
		return func(r rune) bool { return unicode.Is(unicode.Nl, r) }
	case "No":
		return func(r rune) bool { return unicode.Is(unicode.No, r) }
	case "P":
		return unicode.IsPunct
	case "S":
		return unicode.IsSymbol
	case "Sm":
		return func(r rune) bool { return unicode.Is(unicode.Sm, r) }
	case "Sc":
		return func(r rune) bool { return unicode.Is(unicode.Sc, r) }
	case "Z":
		return func(r rune) bool { return unicode.Is(unicode.Z, r) }
	case "Zs":
		return func(r rune) bool { return unicode.Is(unicode.Zs, r) }
	case "M":
		return unicode.IsMark
	case "Mn":
		return func(r rune) bool { return unicode.Is(unicode.Mn, r) }
	case "C":
		return unicode.IsControl
	case "Cc":
		return func(r rune) bool { return unicode.Is(unicode.Cc, r) }
	case "Xan":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.IsNumber(r) }
	case "Xwd":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.IsNumber(r) || r == '_' }
	case "Xsp", "Xps":
		return unicode.IsSpace
	case "Any":
		return func(r rune) bool { return true }
	}
	if strings.HasPrefix(name, "Is") {
		name = name[2:]
	}
	if tbl, ok := unicode.Scripts[name]; ok {
		return func(r rune) bool { return unicode.Is(tbl, r) }
	}
	if tbl, ok := unicode.Categories[name]; ok {
		return func(r rune) bool { return unicode.Is(tbl, r) }
	}
	return nil
}

// ---------- matcher ----------

type reMatcher struct {
	re      *Regex
	s       string
	caps    []int // 2*(ngroups+1)
	steps   int
	limit   int
	keepStart int
	hitLimit bool
	recDepth int
}

func (re *Regex) newMatcher(s string) *reMatcher {
	m := &reMatcher{re: re, s: s, caps: make([]int, 2*(re.ngroups+1)), limit: 10000000}
	return m
}

func (m *reMatcher) resetCaps() {
	for i := range m.caps {
		m.caps[i] = -1
	}
}

// matchAt tries to match starting exactly at pos. Returns end or -1.
func (m *reMatcher) matchAt(pos int) bool {
	m.resetCaps()
	m.keepStart = -1
	end := -1
	ok := m.match(m.re.root, pos, func(p int) bool {
		end = p
		return true
	})
	if ok {
		start := pos
		if m.keepStart >= 0 {
			start = m.keepStart
		}
		m.caps[0] = start
		m.caps[1] = end
	}
	return ok
}

// find searches for a match starting at or after pos. Returns true if found; caps set.
func (m *reMatcher) find(pos int) bool {
	for p := pos; p <= len(m.s); {
		if m.matchAt(p) {
			return true
		}
		if m.re.anchored {
			return false
		}
		if m.hitLimit {
			return false
		}
		if p >= len(m.s) {
			break
		}
		if m.re.utf8 {
			_, size := utf8.DecodeRuneInString(m.s[p:])
			p += size
		} else {
			p++
		}
	}
	return false
}

func (m *reMatcher) decode(pos int) (rune, int) {
	if pos >= len(m.s) {
		return -1, 0
	}
	if m.re.utf8 {
		r, size := utf8.DecodeRuneInString(m.s[pos:])
		return r, size
	}
	return rune(m.s[pos]), 1
}

func (m *reMatcher) decodeBack(pos int) (rune, int) {
	if pos <= 0 {
		return -1, 0
	}
	if m.re.utf8 {
		r, size := utf8.DecodeLastRuneInString(m.s[:pos])
		return r, size
	}
	return rune(m.s[pos-1]), 1
}

func foldRune(r rune) rune {
	if r < 128 {
		if r >= 'A' && r <= 'Z' {
			return r + 32
		}
		return r
	}
	return unicode.ToLower(r)
}

func (n *reNode) classMatch(r rune) bool {
	matched := false
	for _, it := range n.items {
		if r >= it.lo && r <= it.hi {
			matched = true
			break
		}
	}
	if !matched && n.ci {
		fr := foldRune(r)
		ur := unicode.ToUpper(r)
		for _, it := range n.items {
			if (fr >= it.lo && fr <= it.hi) || (ur >= it.lo && ur <= it.hi) {
				matched = true
				break
			}
		}
	}
	if !matched {
		for _, fn := range n.classFns {
			if fn(r) {
				matched = true
				break
			}
		}
	}
	if n.negate {
		return !matched
	}
	return matched
}

func (m *reMatcher) isWordAt(pos int) bool {
	if pos < 0 || pos >= len(m.s) {
		return false
	}
	r, _ := m.decode(pos)
	return isWordR(r)
}

func (m *reMatcher) isWordBefore(pos int) bool {
	if pos <= 0 {
		return false
	}
	r, _ := m.decodeBack(pos)
	return isWordR(r)
}

func (m *reMatcher) match(n *reNode, pos int, k func(int) bool) bool {
	m.steps++
	if m.steps > m.limit {
		m.hitLimit = true
		return false
	}
	switch n.kind {
	case rnEmpty:
		return k(pos)
	case rnLit:
		r, size := m.decode(pos)
		if size == 0 {
			return false
		}
		if r == n.r || (n.ci && foldRune(r) == foldRune(n.r)) {
			return k(pos + size)
		}
		return false
	case rnAny:
		r, size := m.decode(pos)
		if size == 0 {
			return false
		}
		if !n.dotall && r == '\n' {
			return false
		}
		return k(pos + size)
	case rnClass:
		r, size := m.decode(pos)
		if size == 0 {
			return false
		}
		if n.classMatch(r) {
			return k(pos + size)
		}
		return false
	case rnStart:
		if pos == 0 || (n.multiline && m.s[pos-1] == '\n') {
			return k(pos)
		}
		return false
	case rnEnd:
		if pos == len(m.s) {
			return k(pos)
		}
		if !m.re.dollarEnd && pos == len(m.s)-1 && m.s[pos] == '\n' {
			return k(pos)
		}
		if n.multiline && m.s[pos] == '\n' {
			return k(pos)
		}
		return false
	case rnStrStart:
		if pos == 0 {
			return k(pos)
		}
		return false
	case rnStrEnd:
		if pos == len(m.s) {
			return k(pos)
		}
		return false
	case rnStrEndNL:
		if pos == len(m.s) || (pos == len(m.s)-1 && m.s[pos] == '\n') {
			return k(pos)
		}
		return false
	case rnWordB:
		if m.isWordBefore(pos) != m.isWordAt(pos) {
			return k(pos)
		}
		return false
	case rnNotWordB:
		if m.isWordBefore(pos) == m.isWordAt(pos) {
			return k(pos)
		}
		return false
	case rnKeep:
		m.keepStart = pos
		return k(pos)
	case rnFail:
		return false
	case rnConcat:
		return m.matchSeq(n.children, 0, pos, k)
	case rnAlt:
		for _, c := range n.children {
			if m.match(c, pos, k) {
				return true
			}
		}
		return false
	case rnGroup:
		if n.group == 0 {
			return m.match(n.children[0], pos, k)
		}
		oldS, oldE := m.caps[2*n.group], m.caps[2*n.group+1]
		ok := m.match(n.children[0], pos, func(e int) bool {
			ps, pe := m.caps[2*n.group], m.caps[2*n.group+1]
			m.caps[2*n.group] = pos
			m.caps[2*n.group+1] = e
			if k(e) {
				return true
			}
			m.caps[2*n.group] = ps
			m.caps[2*n.group+1] = pe
			return false
		})
		if !ok {
			m.caps[2*n.group] = oldS
			m.caps[2*n.group+1] = oldE
		}
		return ok
	case rnAtomic:
		end := -1
		saved := append([]int(nil), m.caps...)
		if !m.match(n.children[0], pos, func(e int) bool { end = e; return true }) {
			copy(m.caps, saved)
			return false
		}
		if k(end) {
			return true
		}
		copy(m.caps, saved)
		return false
	case rnLookahead:
		saved := append([]int(nil), m.caps...)
		if m.match(n.children[0], pos, func(e int) bool { return true }) {
			if k(pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		return false
	case rnNegLookahead:
		saved := append([]int(nil), m.caps...)
		if m.match(n.children[0], pos, func(e int) bool { return true }) {
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		return k(pos)
	case rnLookbehind, rnNegLookbehind:
		// try all start positions before pos such that sub-match ends exactly at pos
		found := false
		saved := append([]int(nil), m.caps...)
		for start := pos; start >= 0; start-- {
			if m.match(n.children[0], start, func(e int) bool { return e == pos }) {
				found = true
				break
			}
			if m.re.utf8 && start > 0 && !utf8.RuneStart(m.s[start-1]) {
				// step to rune boundary handled by loop
			}
		}
		if n.kind == rnLookbehind {
			if found {
				if k(pos) {
					return true
				}
				copy(m.caps, saved)
				return false
			}
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		if found {
			return false
		}
		return k(pos)
	case rnBackref:
		g := n.backref
		if n.backrefName != "" {
			gi, ok := m.re.names[n.backrefName]
			if !ok {
				return false
			}
			g = gi
		}
		if g > m.re.ngroups || g < 1 {
			return false
		}
		s, e := m.caps[2*g], m.caps[2*g+1]
		if s < 0 || e < 0 {
			// unset group fails to match in PCRE (unless JS compat)
			return false
		}
		sub := m.s[s:e]
		if pos+len(sub) > len(m.s) {
			return false
		}
		cand := m.s[pos : pos+len(sub)]
		if cand == sub || (n.ci && strings.EqualFold(cand, sub)) {
			return k(pos + len(sub))
		}
		return false
	case rnRepeat:
		return m.matchRepeat(n, pos, 0, k)
	case rnRecurse:
		m.recDepth++
		if m.recDepth > 200 {
			m.recDepth--
			return false
		}
		var target *reNode
		if n.backrefName != "" {
			target = m.re.groupNodes[m.re.names[n.backrefName]]
		} else if n.backref == 0 {
			target = m.re.root
		} else {
			target = m.re.groupNodes[n.backref]
		}
		if target == nil {
			m.recDepth--
			return false
		}
		saved := append([]int(nil), m.caps...)
		var body *reNode = target
		if target.kind == rnGroup {
			body = target.children[0]
		}
		ok := m.match(body, pos, func(e int) bool {
			copy(m.caps, saved)
			return k(e)
		})
		m.recDepth--
		if !ok {
			copy(m.caps, saved)
		}
		return ok
	case rnCond:
		g := n.condGroup
		if n.backrefName != "" {
			g = m.re.names[n.backrefName]
		}
		set := g > 0 && g <= m.re.ngroups && m.caps[2*g] >= 0
		if set {
			return m.match(n.children[0], pos, k)
		}
		if len(n.children) > 1 {
			return m.match(n.children[1], pos, k)
		}
		return k(pos)
	}
	return false
}

func (m *reMatcher) matchSeq(nodes []*reNode, i int, pos int, k func(int) bool) bool {
	if i == len(nodes) {
		return k(pos)
	}
	return m.match(nodes[i], pos, func(p int) bool {
		return m.matchSeq(nodes, i+1, p, k)
	})
}

func (m *reMatcher) matchRepeat(n *reNode, pos int, count int, k func(int) bool) bool {
	child := n.children[0]
	if n.possessive {
		// match greedily as many as possible without backtracking
		cur := pos
		cnt := 0
		for n.max < 0 || cnt < n.max {
			next := -1
			if !m.match(child, cur, func(e int) bool { next = e; return true }) {
				break
			}
			if next == cur {
				break
			}
			cur = next
			cnt++
		}
		if cnt < n.min {
			return false
		}
		return k(cur)
	}
	// fast path for simple single-char children with greedy matching
	if n.greedy && (child.kind == rnLit || child.kind == rnAny || child.kind == rnClass) {
		// collect positions
		positions := []int{pos}
		cur := pos
		for n.max < 0 || len(positions)-1 < n.max {
			next := -1
			if !m.match(child, cur, func(e int) bool { next = e; return true }) {
				break
			}
			cur = next
			positions = append(positions, cur)
		}
		for i := len(positions) - 1; i >= n.min; i-- {
			if k(positions[i]) {
				return true
			}
			m.steps++
			if m.steps > m.limit {
				m.hitLimit = true
				return false
			}
		}
		return false
	}
	if count < n.min {
		return m.match(child, pos, func(p int) bool {
			if p == pos && count+1 >= n.min {
				// zero-width iteration: avoid infinite loop
				return m.matchRepeat(n, p, n.min, k)
			}
			return m.matchRepeat(n, p, count+1, k)
		})
	}
	if n.max >= 0 && count >= n.max {
		return k(pos)
	}
	if n.greedy {
		if m.match(child, pos, func(p int) bool {
			if p == pos {
				return false // zero-width: stop iterating
			}
			return m.matchRepeat(n, p, count+1, k)
		}) {
			return true
		}
		return k(pos)
	}
	// lazy
	if k(pos) {
		return true
	}
	return m.match(child, pos, func(p int) bool {
		if p == pos {
			return false
		}
		return m.matchRepeat(n, p, count+1, k)
	})
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > regex.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// A backtracking regex engine supporting a practical subset of PCRE.

type reNodeKind int

const (
	rnLit reNodeKind = iota
	rnAny
	rnClass
	rnStart // ^
	rnEnd   // $
	rnStrStart // \A
	rnStrEnd   // \z
	rnStrEndNL // \Z
	rnWordB
	rnNotWordB
	rnGroup
	rnAlt
	rnConcat
	rnRepeat
	rnBackref
	rnLookahead
	rnNegLookahead
	rnLookbehind
	rnNegLookbehind
	rnAtomic
	rnEmpty
	rnRecurse
	rnCond
	rnKeep // \K
	rnFail
)

type reClassItem struct {
	lo, hi rune
}

type reNode struct {
	kind     reNodeKind
	r        rune   // literal
	ci       bool   // case-insensitive
	dotall   bool
	multiline bool
	items    []reClassItem
	negate   bool
	classFns []func(rune) bool
	children []*reNode
	min, max int // repeat; max -1 = inf
	greedy   bool
	possessive bool
	group    int // capture index (0 = non-capturing)
	name     string
	backref  int
	backrefName string
	condGroup int
}

type Regex struct {
	root      *reNode
	ngroups   int
	names     map[string]int
	nameList  []string // index -> name
	utf8      bool
	anchored  bool
	dollarEnd bool
	ungreedy  bool
	pattern   string
	groupNodes map[int]*reNode
}

type reParser struct {
	src   string
	pos   int
	ci    bool
	multi bool
	dotall bool
	ext   bool
	ungreedy bool
	utf8  bool
	ngroups int
	names map[string]int
	nameList []string
	groupNodes map[int]*reNode
	noAutoCapture bool
}

type reError struct{ msg string }

func (e *reError) Error() string { return e.msg }

func compileRegex(pattern string, flags string) (*Regex, error) {
	p := &reParser{src: pattern, names: map[string]int{}, groupNodes: map[int]*reNode{}}
	re := &Regex{pattern: pattern}
	for _, f := range flags {
		switch f {
		case 'i':
			p.ci = true
		case 'm':
			p.multi = true
		case 's':
			p.dotall = true
		case 'x':
			p.ext = true
		case 'u':
			p.utf8 = true
			re.utf8 = true
		case 'U':
			p.ungreedy = true
		case 'D':
			re.dollarEnd = true
		case 'A':
			re.anchored = true
		case 'n':
			p.noAutoCapture = true
		}
	}
	root, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.src) {
		if p.src[p.pos] == ')' {
			return nil, &reError{"unmatched closing parenthesis"}
		}
		return nil, &reError{"syntax error"}
	}
	re.root = root
	re.ngroups = p.ngroups
	re.names = p.names
	re.nameList = p.nameList
	re.groupNodes = p.groupNodes
	return re, nil
}

func (p *reParser) peek() byte {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}

func (p *reParser) eof() bool { return p.pos >= len(p.src) }

func (p *reParser) parseAlt() (*reNode, error) {
	var alts []*reNode
	for {
		c, err := p.parseConcat()
		if err != nil {
			return nil, err
		}
		alts = append(alts, c)
		if p.peek() == '|' {
			p.pos++
			continue
		}
		break
	}
	if len(alts) == 1 {
		return alts[0], nil
	}
	return &reNode{kind: rnAlt, children: alts}, nil
}

func (p *reParser) parseConcat() (*reNode, error) {
	var items []*reNode
	for !p.eof() {
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom, err := p.parseAtom()
		if err != nil {
			return nil, err
		}
		if atom == nil {
			continue
		}
		atom, err = p.parseQuantifier(atom)
		if err != nil {
			return nil, err
		}
		items = append(items, atom)
	}
	if len(items) == 1 {
		return items[0], nil
	}
	if len(items) == 0 {
		return &reNode{kind: rnEmpty}, nil
	}
	return &reNode{kind: rnConcat, children: items}, nil
}

func (p *reParser) parseQuantifier(atom *reNode) (*reNode, error) {
	for !p.eof() {
		if p.ext {
			p.skipExt()
			if p.eof() {
				break
			}
		}
		c := p.peek()
		min, max := -1, -1
		switch c {
		case '*':
			min, max = 0, -1
			p.pos++
		case '+':
			min, max = 1, -1
			p.pos++
		case '?':
			min, max = 0, 1
			p.pos++
		case '{':
			// {n}, {n,}, {n,m}, {,m}
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return atom, nil
			}
			body := p.src[p.pos+1 : p.pos+end]
			var ok bool
			min, max, ok = parseBraces(body)
			if !ok {
				return atom, nil
			}
			p.pos += end + 1
		default:
			return atom, nil
		}
		greedy := !p.ungreedy
		possessive := false
		if p.peek() == '?' {
			greedy = !greedy
			p.pos++
		} else if p.peek() == '+' {
			possessive = true
			p.pos++
		}
		if atom.kind == rnRepeat && false {
			return nil, &reError{"nothing to repeat"}
		}
		atom = &reNode{kind: rnRepeat, children: []*reNode{atom}, min: min, max: max, greedy: greedy, possessive: possessive}
	}
	return atom, nil
}

func parseBraces(body string) (int, int, bool) {
	if body == "" {
		return 0, 0, false
	}
	parts := strings.SplitN(body, ",", 2)
	var min, max int
	if parts[0] == "" {
		if len(parts) == 1 {
			return 0, 0, false
		}
		min = 0
	} else {
		n, err := strconv.Atoi(parts[0])
		if err != nil {
			return 0, 0, false
		}
		min = n
	}
	if len(parts) == 1 {
		return min, min, true
	}
	if parts[1] == "" {
		return min, -1, true
	}
	n, err := strconv.Atoi(parts[1])
	if err != nil {
		return 0, 0, false
	}
	return min, n, true
}

func (p *reParser) skipExt() {
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.pos++
			continue
		}
		if c == '#' {
			for !p.eof() && p.peek() != '\n' {
				p.pos++
			}
			continue
		}
		break
	}
}

func (p *reParser) nextRune() rune {
	if p.utf8 {
		r, size := utf8.DecodeRuneInString(p.src[p.pos:])
		p.pos += size
		return r
	}
	c := p.src[p.pos]
	p.pos++
	return rune(c)
}

func (p *reParser) lit(r rune) *reNode {
	return &reNode{kind: rnLit, r: r, ci: p.ci}
}

func (p *reParser) parseAtom() (*reNode, error) {
	if p.ext {
		p.skipExt()
		if p.eof() {
			return nil, nil
		}
		c := p.peek()
		if c == '|' || c == ')' {
			return nil, nil
		}
	}
	c := p.peek()
	switch c {
	case '(':
		return p.parseGroup()
	case '[':
		return p.parseClass()
	case '.':
		p.pos++
		return &reNode{kind: rnAny, dotall: p.dotall}, nil
	case '^':
		p.pos++
		return &reNode{kind: rnStart, multiline: p.multi}, nil
	case '$':
		p.pos++
		return &reNode{kind: rnEnd, multiline: p.multi}, nil
	case '\\':
		return p.parseEscape()
	case '*', '+', '?':
		return nil, &reError{"quantifier does not follow a repeatable item"}
	}
	r := p.nextRune()
	return p.lit(r), nil
}

func (p *reParser) parseGroup() (*reNode, error) {
	p.pos++ // (
	node := &reNode{kind: rnGroup}
	if p.peek() == '?' {
		p.pos++
		c := p.peek()
		switch {
		case c == ':':
			p.pos++
		case c == '>':
			p.pos++
			node.kind = rnAtomic
		case c == '=':
			p.pos++
			node.kind = rnLookahead
		case c == '!':
			p.pos++
			node.kind = rnNegLookahead
		case c == '<' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '=':
			p.pos += 2
			node.kind = rnLookbehind
		case c == '<' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '!':
			p.pos += 2
			node.kind = rnNegLookbehind
		case c == 'P' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '<', c == '<', c == '\'':
			// named group
			if c == 'P' {
				p.pos++
			}
			closer := byte('>')
			if p.peek() == '\'' {
				closer = '\''
			}
			p.pos++
			end := strings.IndexByte(p.src[p.pos:], closer)
			if end < 0 {
				return nil, &reError{"syntax error in subpattern name (missing terminator?)"}
			}
			name := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			p.ngroups++
			node.group = p.ngroups
			node.name = name
			p.names[name] = node.group
			for len(p.nameList) <= node.group {
				p.nameList = append(p.nameList, "")
			}
			p.nameList[node.group] = name
		case c == 'P' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '=':
			// (?P=name) backreference
			p.pos += 2
			end := strings.IndexByte(p.src[p.pos:], ')')
			if end < 0 {
				return nil, &reError{"syntax error"}
			}
			name := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			return &reNode{kind: rnBackref, backrefName: name, ci: p.ci}, nil
		case c == 'P' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '>':
			p.pos += 2
			end := strings.IndexByte(p.src[p.pos:], ')')
			name := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			return &reNode{kind: rnRecurse, backrefName: name}, nil
		case c == 'R' || isDigit(c):
			end := strings.IndexByte(p.src[p.pos:], ')')
			if end < 0 {
				return nil, &reError{"syntax error"}
			}
			ref := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			n := 0
			if ref != "R" {
				n, _ = strconv.Atoi(ref)
			}
			return &reNode{kind: rnRecurse, backref: n}, nil
		case c == '#':
			// comment
			end := strings.IndexByte(p.src[p.pos:], ')')
			if end < 0 {
				return nil, &reError{"missing ) after (?# comment"}
			}
			p.pos += end + 1
			return nil, nil
		case c == '(':
			// conditional (?(1)yes|no)
			p.pos++
			end := strings.IndexByte(p.src[p.pos:], ')')
			if end < 0 {
				return nil, &reError{"syntax error"}
			}
			ref := p.src[p.pos : p.pos+end]
			p.pos += end + 1
			node.kind = rnCond
			if n, err := strconv.Atoi(ref); err == nil {
				node.condGroup = n
			} else {
				ref = strings.Trim(ref, "<>'")
				node.backrefName = ref
			}
			body, err := p.parseAlt()
			if err != nil {
				return nil, err
			}
			if p.peek() != ')' {
				return nil, &reError{"missing closing parenthesis"}
			}
			p.pos++
			if body.kind == rnAlt {
				node.children = body.children
			} else {
				node.children = []*reNode{body}
			}
			return node, nil
		default:
			// inline flags (?i) (?i-m) (?i:...)
			saveCi, saveMulti, saveDot, saveExt, saveUng := p.ci, p.multi, p.dotall, p.ext, p.ungreedy
			on := true
			for !p.eof() {
				f := p.peek()
				if f == ')' || f == ':' {
					break
				}
				p.pos++
				switch f {
				case '-':
					on = false
				case 'i':
					p.ci = on
				case 'm':
					p.multi = on
				case 's':
					p.dotall = on
				case 'x':
					p.ext = on
				case 'U':
					p.ungreedy = on
				case 'J', 'u', 'n':
				default:
					return nil, &reError{fmt.Sprintf("unrecognized character after (? or (?-")}
				}
			}
			if p.eof() {
				return nil, &reError{"missing )"}
			}
			if p.peek() == ')' {
				p.pos++
				// flags apply to rest of enclosing group
				return nil, nil
			}
			p.pos++ // ':'
			body, err := p.parseAlt()
			if err != nil {
				return nil, err
			}
			if p.peek() != ')' {
				return nil, &reError{"missing closing parenthesis"}
			}
			p.pos++
			p.ci, p.multi, p.dotall, p.ext, p.ungreedy = saveCi, saveMulti, saveDot, saveExt, saveUng
			node.children = []*reNode{body}
			return node, nil
		}
	} else if !p.noAutoCapture {
		p.ngroups++
		node.group = p.ngroups
	}
	saveCi, saveMulti, saveDot, saveExt, saveUng := p.ci, p.multi, p.dotall, p.ext, p.ungreedy
	body, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	p.ci, p.multi, p.dotall, p.ext, p.ungreedy = saveCi, saveMulti, saveDot, saveExt, saveUng
	if p.peek() != ')' {
		return nil, &reError{"missing closing parenthesis"}
	}
	p.pos++
	node.children = []*reNode{body}
	if node.group > 0 {
		p.groupNodes[node.group] = node
	}
	return node, nil
}

func (p *reParser) parseEscape() (*reNode, error) {
	p.pos++ // backslash
	if p.eof() {
		return nil, &reError{"\\ at end of pattern"}
	}
	c := p.src[p.pos]
	p.pos++
	switch c {
	case 'd':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isDigitR}}, nil
	case 'D':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isDigitR}, negate: true}, nil
	case 'w':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isWordR}}, nil
	case 'W':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isWordR}, negate: true}, nil
	case 's':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isSpaceR}}, nil
	case 'S':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isSpaceR}, negate: true}, nil
	case 'h':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isHSpaceR}}, nil
	case 'H':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isHSpaceR}, negate: true}, nil
	case 'v':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isVSpaceR}}, nil
	case 'V':
		return &reNode{kind: rnClass, classFns: []func(rune) bool{isVSpaceR}, negate: true}, nil
	case 'R':
		// newline sequence: \r\n | \n | \r | \v | \f
		alt := &reNode{kind: rnAlt, children: []*reNode{
			{kind: rnConcat, children: []*reNode{{kind: rnLit, r: '\r'}, {kind: rnLit, r: '\n'}}},
			{kind: rnClass, items: []reClassItem{{'\n', '\r'}, {'\v', '\f'}, {0x85, 0x85}, {0x2028, 0x2029}}},
		}}
		return &reNode{kind: rnAtomic, children: []*reNode{alt}}, nil
	case 'N':
		return &reNode{kind: rnClass, items: []reClassItem{{'\n', '\n'}}, negate: true}, nil
	case 'b':
		return &reNode{kind: rnWordB}, nil
	case 'B':
		return &reNode{kind: rnNotWordB}, nil
	case 'A':
		return &reNode{kind: rnStrStart}, nil
	case 'z':
		return &reNode{kind: rnStrEnd}, nil
	case 'Z':
		return &reNode{kind: rnStrEndNL}, nil
	case 'G':
		return &reNode{kind: rnStrStart}, nil
	case 'K':
		return &reNode{kind: rnKeep}, nil
	case 'Q':
		end := strings.Index(p.src[p.pos:], "\\E")
		var lit string
		if end < 0 {
			lit = p.src[p.pos:]
			p.pos = len(p.src)
		} else {
			lit = p.src[p.pos : p.pos+end]
			p.pos += end + 2
		}
		var nodes []*reNode
		for _, r := range lit {
			nodes = append(nodes, p.lit(r))
		}
		if len(nodes) == 0 {
			return nil, nil
		}
		return &reNode{kind: rnConcat, children: nodes}, nil
	case 'E':
		return nil, nil
	case 'k':
		// \k<name> \k'name' \k{name}
		if p.eof() {
			return nil, &reError{"syntax error"}
		}
		open := p.peek()
		closer := byte('>')
		switch open {
		case '<':
			closer = '>'
		case '\'':
			closer = '\''
		case '{':
			closer = '}'
		default:
			return nil, &reError{"\\k is not followed by a name"}
		}
		p.pos++
		end := strings.IndexByte(p.src[p.pos:], closer)
		if end < 0 {
			return nil, &reError{"syntax error"}
		}
		name := p.src[p.pos : p.pos+end]
		p.pos += end + 1
		return &reNode{kind: rnBackref, backrefName: name, ci: p.ci}, nil
	case 'g':
		// \g{n} \g{-n} \gn
		var ref string
		if p.peek() == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return nil, &reError{"syntax error"}
			}
			ref = p.src[p.pos+1 : p.pos+end]
			p.pos += end + 1
		} else {
			start := p.pos
			if p.peek() == '-' {
				p.pos++
			}
			for !p.eof() && isDigit(p.peek()) {
				p.pos++
			}
			ref = p.src[start:p.pos]
		}
		n, err := strconv.Atoi(ref)
		if err != nil {
			return &reNode{kind: rnBackref, backrefName: ref, ci: p.ci}, nil
		}
		if n < 0 {
			n = p.ngroups + 1 + n
		}
		return &reNode{kind: rnBackref, backref: n, ci: p.ci}, nil
	case 'p', 'P':
		neg := c == 'P'
		var name string
		if p.peek() == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return nil, &reError{"malformed \\P or \\p sequence"}
			}
			name = p.src[p.pos+1 : p.pos+end]
			p.pos += end + 1
		} else if !p.eof() {
			name = string(p.src[p.pos])
			p.pos++
		}
		if strings.HasPrefix(name, "^") {
			neg = !neg
			name = name[1:]
		}
		fn := unicodePropFn(name)
		if fn == nil {
			return nil, &reError{"unknown property name after \\P or \\p"}
		}
		return &reNode{kind: rnClass, classFns: []func(rune) bool{fn}, negate: neg}, nil
	case 'X':
		// extended grapheme: approximate as any char + combining marks
		return &reNode{kind: rnConcat, children: []*reNode{
			{kind: rnAny, dotall: true},
			{kind: rnRepeat, min: 0, max: -1, greedy: true, children: []*reNode{{kind: rnClass, classFns: []func(rune) bool{func(r rune) bool { return unicode.Is(unicode.M, r) }}}}},
		}}, nil
	}
	if isDigit(c) && c != '0' {
		// backreference \1..\99
		n := int(c - '0')
		for !p.eof() && isDigit(p.peek()) && n*10+int(p.peek()-'0') <= p.ngroups {
			n = n*10 + int(p.peek()-'0')
			p.pos++
		}
		return &reNode{kind: rnBackref, backref: n, ci: p.ci}, nil
	}
	r, err := p.escapeChar(c)
	if err != nil {
		return nil, err
	}
	return p.lit(r), nil
}

// escapeChar handles single-char escapes (shared with classes)
func (p *reParser) escapeChar(c byte) (rune, error) {
	switch c {
	case 'n':
		return '\n', nil
	case 'r':
		return '\r', nil
	case 't':
		return '\t', nil
	case 'f':
		return '\f', nil
	case 'e':
		return 27, nil
	case 'a':
		return 7, nil
	case '0':
		// octal
		v := 0
		cnt := 0
		for !p.eof() && cnt < 2 && p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + int(p.peek()-'0')
			p.pos++
			cnt++
		}
		return rune(v), nil
	case 'x':
		if p.peek() == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return 0, &reError{"syntax error"}
			}
			v, err := strconv.ParseUint(p.src[p.pos+1:p.pos+end], 16, 32)
			if err != nil {
				return 0, &reError{"syntax error"}
			}
			p.pos += end + 1
			return rune(v), nil
		}
		v := 0
		cnt := 0
		for !p.eof() && cnt < 2 && isHex(p.peek()) {
			v = v*16 + hexVal(p.peek())
			p.pos++
			cnt++
		}
		return rune(v), nil
	case 'c':
		if p.eof() {
			return 0, &reError{"\\c at end of pattern"}
		}
		ch := p.src[p.pos]
		p.pos++
		return rune(phpToUpper(string(ch))[0] ^ 0x40), nil
	}
	if c >= 0x80 && p.utf8 {
		// multibyte literal after backslash
		p.pos--
		r := p.nextRune()
		return r, nil
	}
	return rune(c), nil
}

func (p *reParser) parseClass() (*reNode, error) {
	p.pos++ // [
	node := &reNode{kind: rnClass, ci: p.ci}
	if p.peek() == '^' {
		node.negate = true
		p.pos++
	}
	first := true
	for {
		if p.eof() {
			return nil, &reError{"missing terminating ] for character class"}
		}
		c := p.peek()
		if c == ']' && !first {
			p.pos++
			break
		}
		first = false
		var lo rune
		isSet := false
		if c == '[' && p.pos+1 < len(p.src) && p.src[p.pos+1] == ':' {
			end := strings.Index(p.src[p.pos:], ":]")
			if end > 0 {
				name := p.src[p.pos+2 : p.pos+end]
				neg := false
				if strings.HasPrefix(name, "^") {
					neg = true
					name = name[1:]
				}
				fn := posixClassFn(name)
				if fn == nil {
					return nil, &reError{"unknown POSIX class name"}
				}
				if neg {
					f := fn
					fn = func(r rune) bool { return !f(r) }
				}
				node.classFns = append(node.classFns, fn)
				p.pos += end + 2
				isSet = true
			}
		}
		if isSet {
			continue
		}
		if c == '\\' {
			p.pos++
			if p.eof() {
				return nil, &reError{"\\ at end of pattern"}
			}
			e := p.src[p.pos]
			p.pos++
			switch e {
			case 'd':
				node.classFns = append(node.classFns, isDigitR)
				continue
			case 'D':
				node.classFns = append(node.classFns, func(r rune) bool { return !isDigitR(r) })
				continue
			case 'w':
				node.classFns = append(node.classFns, isWordR)
				continue
			case 'W':
				node.classFns = append(node.classFns, func(r rune) bool { return !isWordR(r) })
				continue
			case 's':
				node.classFns = append(node.classFns, isSpaceR)
				continue
			case 'S':
				node.classFns = append(node.classFns, func(r rune) bool { return !isSpaceR(r) })
				continue
			case 'h':
				node.classFns = append(node.classFns, isHSpaceR)
				continue
			case 'v':
				node.classFns = append(node.classFns, isVSpaceR)
				continue
			case 'p', 'P':
				neg := e == 'P'
				var name string
				if p.peek() == '{' {
					end := strings.IndexByte(p.src[p.pos:], '}')
					if end < 0 {
						return nil, &reError{"malformed \\P or \\p sequence"}
					}
					name = p.src[p.pos+1 : p.pos+end]
					p.pos += end + 1
				} else {
					name = string(p.src[p.pos])
					p.pos++
				}
				if strings.HasPrefix(name, "^") {
					neg = !neg
					name = name[1:]
				}
				fn := unicodePropFn(name)
				if fn == nil {
					return nil, &reError{"unknown property name after \\P or \\p"}
				}
				if neg {
					f := fn
					fn = func(r rune) bool { return !f(r) }
				}
				node.classFns = append(node.classFns, fn)
				continue
			case 'b':
				lo = 8
			default:
				r, err := p.escapeChar(e)
				if err != nil {
					return nil, err
				}
				lo = r
			}
		} else {
			lo = p.nextRune()
		}
		// range?
		if p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			var hi rune
			if p.peek() == '\\' {
				p.pos++
				e := p.src[p.pos]
				p.pos++
				r, err := p.escapeChar(e)
				if err != nil {
					return nil, err
				}
				hi = r
			} else {
				hi = p.nextRune()
			}
			if hi < lo {
				return nil, &reError{"range out of order in character class"}
			}
			node.items = append(node.items, reClassItem{lo, hi})
			continue
		}
		node.items = append(node.items, reClassItem{lo, lo})
	}
	return node, nil
}

func isDigitR(r rune) bool { return r >= '0' && r <= '9' }
func isWordR(r rune) bool {
	return r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')
}
func isSpaceR(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\f' || r == '\v'
}
func isHSpaceR(r rune) bool { return r == ' ' || r == '\t' || r == 0xA0 }
func isVSpaceR(r rune) bool { return r == '\n' || r == '\r' || r == '\f' || r == '\v' || r == 0x85 }

func posixClassFn(name string) func(rune) bool {
	switch name {
	case "alpha":
		return func(r rune) bool { return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') }
	case "digit":
		return isDigitR
	case "alnum":
		return func(r rune) bool { return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') }
	case "space":
		return isSpaceR
	case "upper":
		return func(r rune) bool { return r >= 'A' && r <= 'Z' }
	case "lower":
		return func(r rune) bool { return r >= 'a' && r <= 'z' }
	case "punct":
		return func(r rune) bool { return r > 32 && r < 127 && !isWordR(r) || r == '_' && false }
	case "xdigit":
		return func(r rune) bool { return r < 128 && isHex(byte(r)) }
	case "word":
		return isWordR
	case "blank":
		return func(r rune) bool { return r == ' ' || r == '\t' }
	case "cntrl":
		return func(r rune) bool { return r < 32 || r == 127 }
	case "print":
		return func(r rune) bool { return r >= 32 && r < 127 }
	case "graph":
		return func(r rune) bool { return r > 32 && r < 127 }
	case "ascii":
		return func(r rune) bool { return r < 128 }
	}
	return nil
}

func unicodePropFn(name string) func(rune) bool {
	switch name {
	case "L", "Letter":
		return unicode.IsLetter
	case "Lu":
		return unicode.IsUpper
	case "Ll":
		return unicode.IsLower
	case "Lt":
		return unicode.IsTitle
	case "Lm":
		return func(r rune) bool { return unicode.Is(unicode.Lm, r) }
	case "Lo":
		return func(r rune) bool { return unicode.Is(unicode.Lo, r) }
	case "N":
		return unicode.IsNumber
	case "Nd":
		return unicode.IsDigit
	case "Nl":
		return func(r rune) bool { return unicode.Is(unicode.Nl, r) }
	case "No":
		return func(r rune) bool { return unicode.Is(unicode.No, r) }
	case "P":
		return unicode.IsPunct
	case "S":
		return unicode.IsSymbol
	case "Sm":
		return func(r rune) bool { return unicode.Is(unicode.Sm, r) }
	case "Sc":
		return func(r rune) bool { return unicode.Is(unicode.Sc, r) }
	case "Z":
		return func(r rune) bool { return unicode.Is(unicode.Z, r) }
	case "Zs":
		return func(r rune) bool { return unicode.Is(unicode.Zs, r) }
	case "M":
		return unicode.IsMark
	case "Mn":
		return func(r rune) bool { return unicode.Is(unicode.Mn, r) }
	case "C":
		return unicode.IsControl
	case "Cc":
		return func(r rune) bool { return unicode.Is(unicode.Cc, r) }
	case "Xan":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.IsNumber(r) }
	case "Xwd":
		return func(r rune) bool { return unicode.IsLetter(r) || unicode.IsNumber(r) || r == '_' }
	case "Xsp", "Xps":
		return unicode.IsSpace
	case "Any":
		return func(r rune) bool { return true }
	}
	if strings.HasPrefix(name, "Is") {
		name = name[2:]
	}
	if tbl, ok := unicode.Scripts[name]; ok {
		return func(r rune) bool { return unicode.Is(tbl, r) }
	}
	if tbl, ok := unicode.Categories[name]; ok {
		return func(r rune) bool { return unicode.Is(tbl, r) }
	}
	return nil
}

// ---------- matcher ----------

type reMatcher struct {
	re      *Regex
	s       string
	caps    []int // 2*(ngroups+1)
	steps   int
	limit   int
	keepStart int
	hitLimit bool
	recDepth int
}

func (re *Regex) newMatcher(s string) *reMatcher {
	m := &reMatcher{re: re, s: s, caps: make([]int, 2*(re.ngroups+1)), limit: 10000000}
	return m
}

func (m *reMatcher) resetCaps() {
	for i := range m.caps {
		m.caps[i] = -1
	}
}

// matchAt tries to match starting exactly at pos. Returns end or -1.
func (m *reMatcher) matchAt(pos int) bool {
	m.resetCaps()
	m.keepStart = -1
	end := -1
	ok := m.match(m.re.root, pos, func(p int) bool {
		end = p
		return true
	})
	if ok {
		start := pos
		if m.keepStart >= 0 {
			start = m.keepStart
		}
		m.caps[0] = start
		m.caps[1] = end
	}
	return ok
}

// find searches for a match starting at or after pos. Returns true if found; caps set.
func (m *reMatcher) find(pos int) bool {
	for p := pos; p <= len(m.s); {
		if m.matchAt(p) {
			return true
		}
		if m.re.anchored {
			return false
		}
		if m.hitLimit {
			return false
		}
		if p >= len(m.s) {
			break
		}
		if m.re.utf8 {
			_, size := utf8.DecodeRuneInString(m.s[p:])
			p += size
		} else {
			p++
		}
	}
	return false
}

func (m *reMatcher) decode(pos int) (rune, int) {
	if pos >= len(m.s) {
		return -1, 0
	}
	if m.re.utf8 {
		r, size := utf8.DecodeRuneInString(m.s[pos:])
		return r, size
	}
	return rune(m.s[pos]), 1
}

func (m *reMatcher) decodeBack(pos int) (rune, int) {
	if pos <= 0 {
		return -1, 0
	}
	if m.re.utf8 {
		r, size := utf8.DecodeLastRuneInString(m.s[:pos])
		return r, size
	}
	return rune(m.s[pos-1]), 1
}

func foldRune(r rune) rune {
	if r < 128 {
		if r >= 'A' && r <= 'Z' {
			return r + 32
		}
		return r
	}
	return unicode.ToLower(r)
}

func (n *reNode) classMatch(r rune) bool {
	matched := false
	for _, it := range n.items {
		if r >= it.lo && r <= it.hi {
			matched = true
			break
		}
	}
	if !matched && n.ci {
		fr := foldRune(r)
		ur := unicode.ToUpper(r)
		for _, it := range n.items {
			if (fr >= it.lo && fr <= it.hi) || (ur >= it.lo && ur <= it.hi) {
				matched = true
				break
			}
		}
	}
	if !matched {
		for _, fn := range n.classFns {
			if fn(r) {
				matched = true
				break
			}
		}
	}
	if n.negate {
		return !matched
	}
	return matched
}

func (m *reMatcher) isWordAt(pos int) bool {
	if pos < 0 || pos >= len(m.s) {
		return false
	}
	r, _ := m.decode(pos)
	return isWordR(r)
}

func (m *reMatcher) isWordBefore(pos int) bool {
	if pos <= 0 {
		return false
	}
	r, _ := m.decodeBack(pos)
	return isWordR(r)
}

func (m *reMatcher) match(n *reNode, pos int, k func(int) bool) bool {
	m.steps++
	if m.steps > m.limit {
		m.hitLimit = true
		return false
	}
	switch n.kind {
	case rnEmpty:
		return k(pos)
	case rnLit:
		r, size := m.decode(pos)
		if size == 0 {
			return false
		}
		if r == n.r || (n.ci && foldRune(r) == foldRune(n.r)) {
			return k(pos + size)
		}
		return false
	case rnAny:
		r, size := m.decode(pos)
		if size == 0 {
			return false
		}
		if !n.dotall && r == '\n' {
			return false
		}
		return k(pos + size)
	case rnClass:
		r, size := m.decode(pos)
		if size == 0 {
			return false
		}
		if n.classMatch(r) {
			return k(pos + size)
		}
		return false
	case rnStart:
		if pos == 0 || (n.multiline && m.s[pos-1] == '\n') {
			return k(pos)
		}
		return false
	case rnEnd:
		if pos == len(m.s) {
			return k(pos)
		}
		if !m.re.dollarEnd && pos == len(m.s)-1 && m.s[pos] == '\n' {
			return k(pos)
		}
		if n.multiline && m.s[pos] == '\n' {
			return k(pos)
		}
		return false
	case rnStrStart:
		if pos == 0 {
			return k(pos)
		}
		return false
	case rnStrEnd:
		if pos == len(m.s) {
			return k(pos)
		}
		return false
	case rnStrEndNL:
		if pos == len(m.s) || (pos == len(m.s)-1 && m.s[pos] == '\n') {
			return k(pos)
		}
		return false
	case rnWordB:
		if m.isWordBefore(pos) != m.isWordAt(pos) {
			return k(pos)
		}
		return false
	case rnNotWordB:
		if m.isWordBefore(pos) == m.isWordAt(pos) {
			return k(pos)
		}
		return false
	case rnKeep:
		m.keepStart = pos
		return k(pos)
	case rnFail:
		return false
	case rnConcat:
		return m.matchSeq(n.children, 0, pos, k)
	case rnAlt:
		for _, c := range n.children {
			if m.match(c, pos, k) {
				return true
			}
		}
		return false
	case rnGroup:
		if n.group == 0 {
			return m.match(n.children[0], pos, k)
		}
		oldS, oldE := m.caps[2*n.group], m.caps[2*n.group+1]
		ok := m.match(n.children[0], pos, func(e int) bool {
			ps, pe := m.caps[2*n.group], m.caps[2*n.group+1]
			m.caps[2*n.group] = pos
			m.caps[2*n.group+1] = e
			if k(e) {
				return true
			}
			m.caps[2*n.group] = ps
			m.caps[2*n.group+1] = pe
			return false
		})
		if !ok {
			m.caps[2*n.group] = oldS
			m.caps[2*n.group+1] = oldE
		}
		return ok
	case rnAtomic:
		end := -1
		saved := append([]int(nil), m.caps...)
		if !m.match(n.children[0], pos, func(e int) bool { end = e; return true }) {
			copy(m.caps, saved)
			return false
		}
		if k(end) {
			return true
		}
		copy(m.caps, saved)
		return false
	case rnLookahead:
		saved := append([]int(nil), m.caps...)
		if m.match(n.children[0], pos, func(e int) bool { return true }) {
			if k(pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		return false
	case rnNegLookahead:
		saved := append([]int(nil), m.caps...)
		if m.match(n.children[0], pos, func(e int) bool { return true }) {
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		return k(pos)
	case rnLookbehind, rnNegLookbehind:
		// try all start positions before pos such that sub-match ends exactly at pos
		found := false
		saved := append([]int(nil), m.caps...)
		for start := pos; start >= 0; start-- {
			if m.match(n.children[0], start, func(e int) bool { return e == pos }) {
				found = true
				break
			}
			if m.re.utf8 && start > 0 && !utf8.RuneStart(m.s[start-1]) {
				// step to rune boundary handled by loop
			}
		}
		if n.kind == rnLookbehind {
			if found {
				if k(pos) {
					return true
				}
				copy(m.caps, saved)
				return false
			}
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		if found {
			return false
		}
		return k(pos)
	case rnBackref:
		g := n.backref
		if n.backrefName != "" {
			gi, ok := m.re.names[n.backrefName]
			if !ok {
				return false
			}
			g = gi
		}
		if g > m.re.ngroups || g < 1 {
			return false
		}
		s, e := m.caps[2*g], m.caps[2*g+1]
		if s < 0 || e < 0 {
			// unset group fails to match in PCRE (unless JS compat)
			return false
		}
		sub := m.s[s:e]
		if pos+len(sub) > len(m.s) {
			return false
		}
		cand := m.s[pos : pos+len(sub)]
		if cand == sub || (n.ci && strings.EqualFold(cand, sub)) {
			return k(pos + len(sub))
		}
		return false
	case rnRepeat:
		return m.matchRepeat(n, pos, 0, k)
	case rnRecurse:
		m.recDepth++
		if m.recDepth > 200 {
			m.recDepth--
			return false
		}
		var target *reNode
		if n.backrefName != "" {
			target = m.re.groupNodes[m.re.names[n.backrefName]]
		} else if n.backref == 0 {
			target = m.re.root
		} else {
			target = m.re.groupNodes[n.backref]
		}
		if target == nil {
			m.recDepth--
			return false
		}
		saved := append([]int(nil), m.caps...)
		var body *reNode = target
		if target.kind == rnGroup {
			body = target.children[0]
		}
		ok := m.match(body, pos, func(e int) bool {
			copy(m.caps, saved)
			return k(e)
		})
		m.recDepth--
		if !ok {
			copy(m.caps, saved)
		}
		return ok
	case rnCond:
		g := n.condGroup
		if n.backrefName != "" {
			g = m.re.names[n.backrefName]
		}
		set := g > 0 && g <= m.re.ngroups && m.caps[2*g] >= 0
		if set {
			return m.match(n.children[0], pos, k)
		}
		if len(n.children) > 1 {
			return m.match(n.children[1], pos, k)
		}
		return k(pos)
	}
	return false
}

func (m *reMatcher) matchSeq(nodes []*reNode, i int, pos int, k func(int) bool) bool {
	if i == len(nodes) {
		return k(pos)
	}
	return m.match(nodes[i], pos, func(p int) bool {
		return m.matchSeq(nodes, i+1, p, k)
	})
}

func (m *reMatcher) matchRepeat(n *reNode, pos int, count int, k func(int) bool) bool {
	child := n.children[0]
	if n.possessive {
		// match greedily as many as possible without backtracking
		cur := pos
		cnt := 0
		for n.max < 0 || cnt < n.max {
			next := -1
			if !m.match(child, cur, func(e int) bool { next = e; return true }) {
				break
			}
			if next == cur {
				break
			}
			cur = next
			cnt++
		}
		if cnt < n.min {
			return false
		}
		return k(cur)
	}
	// fast path for simple single-char children with greedy matching
	if n.greedy && (child.kind == rnLit || child.kind == rnAny || child.kind == rnClass) {
		// collect positions
		positions := []int{pos}
		cur := pos
		for n.max < 0 || len(positions)-1 < n.max {
			next := -1
			if !m.match(child, cur, func(e int) bool { next = e; return true }) {
				break
			}
			cur = next
			positions = append(positions, cur)
		}
		for i := len(positions) - 1; i >= n.min; i-- {
			if k(positions[i]) {
				return true
			}
			m.steps++
			if m.steps > m.limit {
				m.hitLimit = true
				return false
			}
		}
		return false
	}
	if count < n.min {
		return m.match(child, pos, func(p int) bool {
			if p == pos && count+1 >= n.min {
				// zero-width iteration: avoid infinite loop
				return m.matchRepeat(n, p, n.min, k)
			}
			return m.matchRepeat(n, p, count+1, k)
		})
	}
	if n.max >= 0 && count >= n.max {
		return k(pos)
	}
	if n.greedy {
		if m.match(child, pos, func(p int) bool {
			if p == pos {
				return false // zero-width: stop iterating
			}
			return m.matchRepeat(n, p, count+1, k)
		}) {
			return true
		}
		return k(pos)
	}
	// lazy
	if k(pos) {
		return true
	}
	return m.match(child, pos, func(p int) bool {
		if p == pos {
			return false
		}
		return m.matchRepeat(n, p, count+1, k)
	})
}
