	re, err := compileRegex(body, mods)
	if err != nil {
		msg := "Compilation failed: " + err.Error() + " at offset " + strconv.Itoa(len(body))
		in.warn(fname + "(): " + msg)
		regexCache[pattern] = &compiledRe{err: msg}
		return nil
	}
	regexCache[pattern] = &compiledRe{re: re}
	return re
}

