	})
	in.regRef("preg_replace_callback_array", 2, 5, []int{3}, func(in *Interp, args []Value) Value {
		pats := in.argArray("preg_replace_callback_array", args, 0)
		subject := args[1]
		limit := int64(-1)
		if len(args) > 2 && args[2] != nil {
			limit = toInt(args[2])
		}
		total := int64(0)
		flags := int64(0)
		if len(args) > 4 {
			flags = toInt(args[4])
		}
		in.pregCbFlags = flags
