			return false
		}
		s := in.argStr("preg_split", args, 1)
		limit := int64(-1)
		if len(args) > 2 && args[2] != nil {
			limit = toInt(args[2])
		}
		if limit == 0 {
			limit = -1
		}
		flags := int64(0)
		if len(args) > 3 {
			flags = toInt(args[3])
