					}
				}
			}
			last = me
			if me == ms {
				pos = advancePos(s, me, re.utf8)
			} else {
				pos = me
			}
		}
		if !(noEmpty && last >= len(s)) || (!noEmpty) {
			add(s[last:], last)
		}
