	in.reg("preg_last_error_msg", 0, 0, func(in *Interp, args []Value) Value {
		switch in.pregLastError {
		case 0:
			return "No error"
		case 1:
			return "Internal error"
		case 2:
			return "Backtrack limit exhausted"
		case 3:
			return "Recursion limit exhausted"
		case 4:
			return "Malformed UTF-8 characters, possibly incorrectly encoded"
		case 5:
			return "The offset did not correspond to the beginning of a valid UTF-8 code point"
		case 6:
			return "JIT stack limit exhausted"
		}
		return "Unknown error"
	})
}

func decodeRuneAt(s string, pos int) (rune, int) {
	if pos >= len(s) {
		return -1, 0
	}
	c := s[pos]
	if c < 0x80 {
		return rune(c), 1
	}
	size := 1
	switch {
	case c&0xE0 == 0xC0:
		size = 2
	case c&0xF0 == 0xE0:
		size = 3
	case c&0xF8 == 0xF0:
		size = 4
	}
	if pos+size > len(s) {
		size = len(s) - pos
	}
	return 0, size
}

func advancePos(s string, pos int, utf bool) int {
	if pos >= len(s) {
		return len(s) + 1
	}
	if utf {
		_, size := decodeRuneAt(s, pos)
		return pos + size
	}
	return pos + 1
}

// expandReplacement handles $1, \1, ${1} references
func expandReplacement(rep string, m *reMatcher, s string) string {
	var sb strings.Builder
	for i := 0; i < len(rep); i++ {
		c := rep[i]
		if (c == '$' || c == '\\') && i+1 < len(rep) {
			j := i + 1
			brace := false
			if c == '$' && rep[j] == '{' {
				brace = true
				j++
			}
			start := j
			for j < len(rep) && isDigit(rep[j]) && j-start < 2 {
				j++
			}
			if j > start && (!brace || (j < len(rep) && rep[j] == '}')) {
				n, _ := strconv.Atoi(rep[start:j])
				if brace {
					j++
				}
				if n <= m.re.ngroups {
					gs, ge := m.caps[2*n], m.caps[2*n+1]
					if gs >= 0 {
						sb.WriteString(s[gs:ge])
					}
				}
				i = j - 1
				continue
			}
			if c == '\\' && rep[i+1] == '\\' {
				sb.WriteByte('\\')
				i++
				continue
			}
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

func (in *Interp) pregReplace(fname string, args []Value, cb Value) Value {
	limit := int64(-1)
	if len(args) > 3 && args[3] != nil {
		limit = toInt(args[3])
	}
	total := int64(0)
	isFilter := fname == "preg_filter"
	var patterns []string
	var reps []Value
	repIsArr := false
	if pa, ok := args[0].(*Array); ok {
		for _, v := range pa.ValuesDeref() {
			patterns = append(patterns, in.toStr(v))
		}
		if cb == nil {
			if ra, ok := args[1].(*Array); ok {
				reps = ra.ValuesDeref()
				repIsArr = true
			} else {
				reps = []Value{args[1]}
			}
		}
	} else {
		patterns = []string{in.toStr(args[0])}
		if cb == nil {
			if _, ok := args[1].(*Array); ok {
				in.throwError("TypeError", fname+"(): Argument #1 ($pattern) must be of type array when argument #2 ($replacement) is an array, string given")
			}
			reps = []Value{args[1]}
		}
	}
	doSubject := func(subject string) (string, bool) {
		matchedAny := false
		for pi, pat := range patterns {
			re := in.compilePattern(fname, pat)
			if re == nil {
				return "", false
			}
			var rep string
			if cb == nil {
				if repIsArr {
					if pi < len(reps) {
						rep = in.toStr(reps[pi])
					}
				} else {
					rep = in.toStr(reps[0])
				}
			}
			m := re.newMatcher(subject)
			var sb strings.Builder
			last := 0
			pos := 0
			n := int64(0)
			for pos <= len(subject) && (limit < 0 || n < limit) {
				if !m.find(pos) {
					break
				}
				ms, me := m.caps[0], m.caps[1]
				sb.WriteString(subject[last:ms])
				if cb != nil {
					matches := in.buildMatchArray(re, m, subject, in.pregCbFlags, true)
					r := in.callValue(cb, []Value{matches})
					sb.WriteString(in.toStr(r))
				} else {
					sb.WriteString(expandReplacement(rep, m, subject))
				}
				n++
				last = me
				if me == ms {
					if ms < len(subject) {
						next := advancePos(subject, ms, re.utf8)
						sb.WriteString(subject[ms:next])
						last = next
					}
					pos = advancePos(subject, ms, re.utf8)
				} else {
					pos = me
				}
			}
			if m.hitLimit {
				in.pregLastError = 2
				return "", false
			}
			if last <= len(subject) {
				sb.WriteString(subject[last:])
			}
			if n > 0 {
				matchedAny = true
			}
			total += n
			subject = sb.String()
		}
		return subject, matchedAny
	}
	in.pregLastError = 0
	var result Value
	if sa, ok := args[2].(*Array); ok {
		out := NewArray()
		sa.Each(func(k Key, v Value) bool {
			r, matched := doSubject(in.toStr(deref(v)))
			if isFilter && !matched {
				return true
			}
			out.Set(k, r)
			return true
		})
		result = out
	} else {
		r, matched := doSubject(in.toStr(args[2]))
		if in.pregLastError != 0 {
			result = nil
		} else if isFilter && !matched {
			result = nil
		} else {
			result = r
		}
	}
	if len(args) > 4 {
		if r, ok := args[4].(*Ref); ok {
			r.set(total)
		}
	}
	return result
}
