package main

import (
	"fmt"
	"strconv"
	"strings"
)

type compiledRe struct {
	re  *Regex
	err string
}

var regexCache = map[string]*compiledRe{}

// parsePattern splits delimiters/modifiers and compiles
func (in *Interp) compilePattern(fname string, pattern string) *Regex {
	if c, ok := regexCache[pattern]; ok {
		if c.err != "" {
			in.warn(fname + "(): " + c.err)
			return nil
		}
		return c.re
	}
	p := strings.TrimLeft(pattern, " \t\n\r\f\v")
	if p == "" {
		in.warn(fname + "(): Empty regular expression")
		regexCache[pattern] = &compiledRe{err: "Empty regular expression"}
		return nil
	}
	delim := p[0]
	if isIdentChar(delim) || delim == '\\' {
		msg := "Delimiter must not be alphanumeric, backslash, or NUL"
		in.warn(fname + "(): " + msg)
		regexCache[pattern] = &compiledRe{err: msg}
		return nil
	}
	endDelim := delim
	switch delim {
	case '(':
		endDelim = ')'
	case '[':
		endDelim = ']'
	case '{':
		endDelim = '}'
	case '<':
		endDelim = '>'
	}
	// find closing delimiter (not escaped)
	body := ""
	mods := ""
	found := false
	if endDelim == delim {
		for i := 1; i < len(p); i++ {
			if p[i] == '\\' {
				i++
				continue
			}
			if p[i] == delim {
				body = p[1:i]
				mods = p[i+1:]
				found = true
				break
			}
		}
	} else {
		depth := 1
		for i := 1; i < len(p); i++ {
			if p[i] == '\\' {
				i++
				continue
			}
			if p[i] == delim {
				depth++
			} else if p[i] == endDelim {
				depth--
				if depth == 0 {
					body = p[1:i]
					mods = p[i+1:]
					found = true
					break
				}
			}
		}
	}
	if !found {
		msg := fmt.Sprintf("No ending delimiter '%c' found", delim)
		if endDelim != delim {
			msg = fmt.Sprintf("No ending matching delimiter '%c' found", endDelim)
		}
		in.warn(fname + "(): " + msg)
		regexCache[pattern] = &compiledRe{err: msg}
		return nil
	}
	for _, c := range mods {
		switch c {
		case 'i', 'm', 's', 'x', 'u', 'U', 'D', 'A', 'J', 'n', 'S', 'X':
		case '\n', ' ', '\r':
		case 'e':
			msg := "The /e modifier is no longer supported, use preg_replace_callback instead"
			in.warn(fname + "(): " + msg)
			regexCache[pattern] = &compiledRe{err: msg}
			return nil
		default:
			msg := fmt.Sprintf("Unknown modifier '%c'", c)
			in.warn(fname + "(): " + msg)
			regexCache[pattern] = &compiledRe{err: msg}
			return nil
		}
	}
	re, err := compileRegex(body, mods)
	if err != nil {
		msg := "Compilation failed: " + err.Error() + " at offset " + strconv.Itoa(len(body))
		in.warn(fname + "(): " + msg)
		regexCache[pattern] = &compiledRe{err: msg}
		return nil
	}
	regexCache[pattern] = &compiledRe{re: re}
	return re
}

func (in *Interp) buildMatchArray(re *Regex, m *reMatcher, s string, flags int64, trimTrailing bool) *Array {
	arr := NewArray()
	offsetCapture := flags&256 != 0
	unmatchedNull := flags&512 != 0
	last := re.ngroups
	if trimTrailing && !unmatchedNull {
		for last > 0 && m.caps[2*last] < 0 {
			last--
		}
	}
	for g := 0; g <= last; g++ {
		var v Value
		s0, e0 := m.caps[2*g], m.caps[2*g+1]
		if s0 < 0 {
			if unmatchedNull {
				v = nil
			} else {
				v = ""
			}
			if offsetCapture {
				pair := NewArray()
				pair.Append(v)
				pair.Append(int64(-1))
				v = pair
			}
		} else {
			v = s[s0:e0]
			if offsetCapture {
				pair := NewArray()
				pair.Append(v)
				pair.Append(int64(s0))
				v = pair
			}
		}
		if g < len(re.nameList) && re.nameList[g] != "" {
			arr.SetStr(re.nameList[g], v)
		}
		arr.SetInt(int64(g), v)
	}
	return arr
}

