				matchedAny = true
			}
			total += n
			subject = sb.String()
		}
		return subject, matchedAny
	}
	in.pregLastError = 0
	var result Value
	if sa, ok := args[2].(*Array); ok {
		out := NewArray()
		sa.Each(func(k Key, v Value) bool {
			r, matched := doSubject(in.toStr(deref(v)))
			if isFilter && !matched {
				return true
			}
			out.Set(k, r)
			return true
		})
		result = out
	} else {
		r, matched := doSubject(in.toStr(args[2]))
		if in.pregLastError != 0 {
			result = nil
		} else if isFilter && !matched {
			result = nil
		} else {
			result = r
		}
	}
	if len(args) > 4 {
		if r, ok := args[4].(*Ref); ok {
			r.set(total)
		}
	}
	return result
}
