			}
			s.eof = true
		}
		return line, true
	case "memory", "temp":
		if s.pos >= len(s.buf) {
			s.eof = true
			return "", false
		}
		i := s.pos
		for i < len(s.buf) && s.buf[i] != '\n' {
			i++
