func (s *Stream) read(in *Interp, n int) string {
	switch s.kind {
	case "stdin":
		buf := make([]byte, n)
		k, err := io.ReadFull(s.reader, buf)
		if err != nil {
			s.eof = true
		}
		return string(buf[:k])
	case "memory", "temp":
		if s.pos >= len(s.buf) {
			s.eof = true
			return ""
		}
		end := s.pos + n
		if end >= len(s.buf) {
			end = len(s.buf)
		}
		r := string(s.buf[s.pos:end])
		s.pos = end
		return r
	case "file":
		if s.reader == nil {
			s.reader = bufio.NewReader(s.file)
		}
		buf := make([]byte, n)
		k, err := io.ReadFull(s.reader, buf)
		if err != nil {
