func osErrMsg(err error) string {
	if os.IsNotExist(err) {
		return "No such file or directory"
	}
	if os.IsPermission(err) {
		return "Permission denied"
	}
	if os.IsExist(err) {
		return "File exists"
	}
	s := err.Error()
	if i := strings.LastIndex(s, ": "); i >= 0 {
		s = s[i+2:]
	}
	if s == "not a directory" {
		return "Not a directory"
	}
	if s == "directory not empty" {
		return "Directory not empty"
	}
	if s == "is a directory" {
		return "Is a directory"
	}
	return s
}

func phpBasename(p string, suffix string) string {
	p = strings.TrimRight(p, "/")
	if p == "" {
		return ""
	}
	if i := strings.LastIndexByte(p, '/'); i >= 0 {
		p = p[i+1:]
	}
	if suffix != "" && strings.HasSuffix(p, suffix) && p != suffix {
		p = p[:len(p)-len(suffix)]
	}
	return p
}

func phpDirname(p string) string {
	if p == "" {
		return ""
	}
	if !strings.Contains(p, "/") {
		return "."
	}
	trimmed := strings.TrimRight(p, "/")
	if trimmed == "" {
		return "/"
	}
	i := strings.LastIndexByte(trimmed, '/')
	if i < 0 {
		return "."
	}
	d := strings.TrimRight(trimmed[:i], "/")
	if d == "" {
		return "/"
	}
	return d
}

func expandBraces(p string) []string {
	i := strings.IndexByte(p, '{')
	if i < 0 {
		return []string{p}
	}
	depth := 0
	j := i
	for ; j < len(p); j++ {
		if p[j] == '{' {
			depth++
		} else if p[j] == '}' {
			depth--
			if depth == 0 {
				break
			}
		}
	}
	if j >= len(p) {
		return []string{p}
	}
	inner := p[i+1 : j]
	var parts []string
	depth = 0
	start := 0
	for k := 0; k < len(inner); k++ {
		switch inner[k] {
		case '{':
			depth++
		case '}':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, inner[start:k])
				start = k + 1
			}
		}
	}
	parts = append(parts, inner[start:])
	var out []string
	for _, part := range parts {
		out = append(out, expandBraces(p[:i]+part+p[j+1:])...)
	}
	return out
}

func csvLine(in *Interp, arr *Array, sep, enc, esc string) string {
	var parts []string
	arr.Each(func(k Key, v Value) bool {
		s := in.toStr(deref(v))
		needQuote := strings.ContainsAny(s, sep+enc+"\n\r\t ") || (esc != "" && strings.Contains(s, esc))
		if needQuote {
			var sb strings.Builder
			sb.WriteString(enc)
			escaped := false
			for i := 0; i < len(s); i++ {
				c := s[i]
				if esc != "" && c == esc[0] && esc != enc {
					escaped = true
					sb.WriteByte(c)
					continue
				}
				if c == enc[0] && !escaped {
					sb.WriteString(enc)
				}
				escaped = false
				sb.WriteByte(c)
			}
			sb.WriteString(enc)
			parts = append(parts, sb.String())
		} else {
			parts = append(parts, s)
		}
		return true
	})
	return strings.Join(parts, sep)
}

func parseCsvLine(line string, sep, enc, esc string) *Array {
	arr := NewArray()
	var field strings.Builder
	i := 0
	n := len(line)
	sepc := sep[0]
	var encc byte
	if enc != "" {
		encc = enc[0]
	}
	for i <= n {
		// skip leading whitespace? PHP keeps it unless quoted
		if i < n && encc != 0 && line[i] == encc {
			// quoted field
			i++
			for i < n {
				c := line[i]
				if esc != "" && c == esc[0] && esc != enc && i+1 < n {
					field.WriteByte(c)
					field.WriteByte(line[i+1])
					i += 2
					continue
				}
				if c == encc {
					if i+1 < n && line[i+1] == encc {
						field.WriteByte(encc)
						i += 2
						continue
					}
					i++
					break
				}
				field.WriteByte(c)
				i++
			}
			// consume until separator
			for i < n && line[i] != sepc {
				field.WriteByte(line[i])
				i++
			}
		} else {
			for i < n && line[i] != sepc {
				field.WriteByte(line[i])
				i++
			}
		}
		arr.Append(field.String())
		field.Reset()
		if i < n && line[i] == sepc {
			i++
			if i == n {
				arr.Append("")
				break
			}
			continue
		}
		break
	}
	return arr
}
