	file   *os.File
	reader *bufio.Reader
	buf    []byte // memory stream
	pos    int
	eof    bool
	mode   string
	path   string
	dir    []string // for directory handles
	dirPos int
	writer *bufio.Writer
}

func (in *Interp) getStream(v Value, fname string) *Stream {
	r, ok := v.(*Resource)
	if !ok {
		in.throwError("TypeError", fmt.Sprintf("%s(): Argument #1 ($stream) must be of type resource, %s given", fname, typeName(v)))
	}
	if r.closed {
		in.throwError("TypeError", fmt.Sprintf("%s(): supplied resource is not a valid stream resource", fname))
	}
	s, ok := r.data.(*Stream)
	if !ok {
		in.throwError("TypeError", fmt.Sprintf("%s(): supplied resource is not a valid stream resource", fname))
	}
	return s
}

func (in *Interp) streamWrite(v Value, data string) int {
	s := in.getStream(v, "fwrite")
	return s.write(in, data)
}

func (s *Stream) write(in *Interp, data string) int {
	switch s.kind {
	case "stdout", "output":
		in.echo(data)
		return len(data)
	case "stderr":
		in.out.Flush()
		os.Stderr.WriteString(data)
		return len(data)
	case "memory", "temp":
		if strings.Contains(s.mode, "a") {
			s.pos = len(s.buf)
		}
		for len(s.buf) < s.pos {
			s.buf = append(s.buf, 0)
		}
		s.buf = append(s.buf[:s.pos], append([]byte(data), s.buf[min(len(s.buf), s.pos+len(data)):]...)...)
		s.pos += len(data)
		return len(data)
	case "file":
		if s.file == nil {
			return 0
		}
		n, _ := s.file.WriteString(data)
		return n
	}
	return 0
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (s *Stream) readLine(in *Interp) (string, bool) {
	switch s.kind {
	case "stdin":
		line, err := s.reader.ReadString('\n')
		if err != nil {
			if line == "" {
				s.eof = true
				return "", false
			}
			s.eof = true
		}
		return line, true
	case "memory", "temp":
		if s.pos >= len(s.buf) {
			s.eof = true
			return "", false
		}
		i := s.pos
		for i < len(s.buf) && s.buf[i] != '\n' {
			i++
		}
		if i < len(s.buf) {
			i++
		}
		line := string(s.buf[s.pos:i])
		s.pos = i
		return line, true
	case "file":
		if s.reader == nil {
			s.reader = bufio.NewReader(s.file)
		}
		line, err := s.reader.ReadString('\n')
		if err != nil {
			if line == "" {
				s.eof = true
				return "", false
			}
			s.eof = true
		}
		return line, true
	}
	return "", false
}

func (s *Stream) read(in *Interp, n int) string {
	switch s.kind {
	case "stdin":
		buf := make([]byte, n)
		k, err := io.ReadFull(s.reader, buf)
		if err != nil {
			s.eof = true
		}
		return string(buf[:k])
	case "memory", "temp":
		if s.pos >= len(s.buf) {
			s.eof = true
			return ""
		}
		end := s.pos + n
		if end >= len(s.buf) {
			end = len(s.buf)
		}
		r := string(s.buf[s.pos:end])
		s.pos = end
		return r
	case "file":
		if s.reader == nil {
			s.reader = bufio.NewReader(s.file)
		}
		buf := make([]byte, n)
		k, err := io.ReadFull(s.reader, buf)
		if err != nil {
			s.eof = true
		}
		return string(buf[:k])
	}
	return ""
}

func (s *Stream) readAll(in *Interp) string {
	switch s.kind {
	case "stdin":
		b, _ := io.ReadAll(s.reader)
		s.eof = true
		return string(b)
	case "memory", "temp":
		if s.pos >= len(s.buf) {
			s.eof = true
			return ""
		}
		r := string(s.buf[s.pos:])
		s.pos = len(s.buf)
		s.eof = true
		return r
	case "file":
		if s.reader == nil {
			s.reader = bufio.NewReader(s.file)
		}
		b, _ := io.ReadAll(s.reader)
		s.eof = true
		return string(b)
	}
	return ""
}

func (s *Stream) isEOF() bool {
	switch s.kind {
	case "memory", "temp":
		return s.pos >= len(s.buf) && s.eof
	case "file":
		if s.eof {
			return true
		}
		if s.reader == nil {
			s.reader = bufio.NewReader(s.file)
		}
		_, err := s.reader.Peek(1)
		if err != nil {
			s.eof = true
			return true
		}
		return false
	case "stdin":
		if s.eof {
			return true
		}
		_, err := s.reader.Peek(1)
		if err != nil {
			s.eof = true
			return true
		}
		return false
	}
	return s.eof
}

func (in *Interp) resolvePath(p string) string {
	if filepath.IsAbs(p) {
