	tzOffset      *int
	err           bool
	resetTime     bool
	tsSet         bool
	ts            int64
}

var monthMap = map[string]int{
	"jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3, "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6,
	"jul": 7, "july": 7, "aug": 8, "august": 8, "sep": 9, "sept": 9, "september": 9, "oct": 10, "october": 10, "nov": 11, "november": 11, "dec": 12, "december": 12,
}

var weekdayMap = map[string]int{
	"sun": 0, "sunday": 0, "mon": 1, "monday": 1, "tue": 2, "tues": 2, "tuesday": 2, "wed": 3, "wednesday": 3, "thu": 4, "thur": 4, "thurs": 4, "thursday": 4, "fri": 5, "friday": 5, "sat": 6, "saturday": 6,
}

var relUnits = map[string]string{
	"sec": "s", "secs": "s", "second": "s", "seconds": "s",
	"min": "i", "mins": "i", "minute": "i", "minutes": "i",
	"hour": "h", "hours": "h",
	"day": "d", "days": "d",
	"week": "w", "weeks": "w",
	"fortnight": "f", "fortnights": "f",
	"month": "m", "months": "m",
	"year": "y", "years": "y",
	"weekday": "wd", "weekdays": "wd",
	"usec": "us", "usecs": "us", "microsecond": "us", "microseconds": "us",
	"msec": "ms", "msecs": "ms", "millisecond": "ms", "milliseconds": "ms",
	"sat": "", "saturday": "",
}

var relWords = map[string]int{"last": -1, "previous": -1, "this": 0, "next": 1, "first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6, "seventh": 7, "eighth": 8, "ninth": 9, "tenth": 10, "eleventh": 11, "twelfth": 12}

func (p *dateParser) skipSpace() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t' || p.s[p.pos] == ',' || p.s[p.pos] == '\n') {
		p.pos++
	}
}

func (p *dateParser) peekWord() string {
	i := p.pos
	for i < len(p.s) && ((p.s[i] >= 'a' && p.s[i] <= 'z') || (p.s[i] >= 'A' && p.s[i] <= 'Z')) {
		i++
	}
	return strings.ToLower(p.s[p.pos:i])
}

func (p *dateParser) readWord() string {
	w := p.peekWord()
	p.pos += len(w)
	return w
}

func (p *dateParser) readNum() (int, int, bool) {
	i := p.pos
	for i < len(p.s) && isDigit(p.s[i]) {
		i++
	}
	if i == p.pos {
		return 0, 0, false
	}
	n, _ := strconv.Atoi(p.s[p.pos:i])
	l := i - p.pos
	p.pos = i
	return n, l, true
}

func (p *dateParser) peekNumLen() int {
	i := p.pos
	for i < len(p.s) && isDigit(p.s[i]) {
		i++
	}
	return i - p.pos
}

func (p *dateParser) setTime(h, mi, s int) {
	p.h, p.mi, p.sec = h, mi, s
	p.ns = 0
	p.haveTime = true
	p.timeSet = true
}

func (p *dateParser) parseTimeAfterNum(h int) bool {
	// expects ':' consumed next
	if p.pos < len(p.s) && p.s[p.pos] == ':' {
		p.pos++
		mi, l, ok := p.readNum()
		if !ok || l > 2 {
			p.err = true
			return false
		}
		sec := 0
		if p.pos < len(p.s) && p.s[p.pos] == ':' {
			p.pos++
			s2, _, ok := p.readNum()
			if !ok {
				p.err = true
				return false
			}
			sec = s2
			if p.pos < len(p.s) && (p.s[p.pos] == '.' || p.s[p.pos] == ',') {
				p.pos++
				start := p.pos
				frac, l, ok := p.readNum()
				if ok {
					_ = start
					for l < 9 {
						frac *= 10
						l++
					}
					for l > 9 {
						frac /= 10
						l--
					}
					p.ns = frac
				}
			}
		}
		p.setTime(h, mi, sec)
		p.parseMeridian()
		p.parseTZ()
		return true
	}
	return false
}

func (p *dateParser) parseMeridian() {
	save := p.pos
	p.skipSpace()
	w := p.peekWord()
	w = strings.ReplaceAll(w, ".", "")
	if w == "am" || w == "pm" || w == "a" || w == "p" {
		p.pos += len(w)
		if p.pos < len(p.s) && p.s[p.pos] == '.' {
			p.pos++
			if p.pos < len(p.s) && (p.s[p.pos] == 'm' || p.s[p.pos] == 'M') {
				p.pos++
				if p.pos < len(p.s) && p.s[p.pos] == '.' {
					p.pos++
				}
			}
		}
		if w[0] == 'p' && p.h < 12 {
			p.h += 12
		} else if w[0] == 'a' && p.h == 12 {
			p.h = 0
		}
		return
	}
	p.pos = save
}

func (p *dateParser) parseTZ() {
	save := p.pos
	p.skipSpace()
	if p.pos >= len(p.s) {
		return
	}
	c := p.s[p.pos]
	if c == 'Z' || c == 'z' {
		if p.pos+1 >= len(p.s) || !isIdentChar(p.s[p.pos+1]) {
			p.pos++
			off := 0
			p.tzOffset = &off
			return
		}
	}
	if c == '+' || c == '-' {
		sign := 1
		if c == '-' {
			sign = -1
		}
		i := p.pos + 1
		j := i
		for j < len(p.s) && isDigit(p.s[j]) {
			j++
		}
		digits := p.s[i:j]
		var h, m int
		switch len(digits) {
		case 1, 2:
			h, _ = strconv.Atoi(digits)
			if j < len(p.s) && p.s[j] == ':' {
				k := j + 1
				for k < len(p.s) && isDigit(p.s[k]) {
					k++
				}
				m, _ = strconv.Atoi(p.s[j+1 : k])
				j = k
			}
		case 3:
			h, _ = strconv.Atoi(digits[:1])
			m, _ = strconv.Atoi(digits[1:])
		case 4:
			h, _ = strconv.Atoi(digits[:2])
			m, _ = strconv.Atoi(digits[2:])
		default:
			p.pos = save
			return
		}
		off := sign * (h*3600 + m*60)
		p.tzOffset = &off
		p.pos = j
		return
	}
	// named timezone like UTC, GMT, EST or Europe/Paris
	i := p.pos
	for i < len(p.s) && (isIdentChar(p.s[i]) || p.s[i] == '/') {
		i++
	}
	name := p.s[p.pos:i]
	if name == "" {
		p.pos = save
		return
	}
	upper := strings.ToUpper(name)
	abbrs := map[string]int{"UTC": 0, "GMT": 0, "Z": 0, "EST": -5 * 3600, "EDT": -4 * 3600, "CST": -6 * 3600, "CDT": -5 * 3600, "MST": -7 * 3600, "MDT": -6 * 3600, "PST": -8 * 3600, "PDT": -7 * 3600, "CET": 3600, "CEST": 7200, "BST": 3600, "JST": 9 * 3600, "IST": 19800, "EET": 7200, "WET": 0, "AEST": 36000, "MSK": 10800}
	if off, ok := abbrs[upper]; ok {
		if upper == "UTC" || upper == "GMT" {
			p.tzSet = time.UTC
		} else {
			p.tzOffset = &off
		}
		p.pos = i
		return
	}
	if strings.Contains(name, "/") {
		if l, err := time.LoadLocation(name); err == nil {
			p.tzSet = l
			p.pos = i
			return
		}
	}
	p.pos = save
}

func (p *dateParser) parse() bool {
	p.weekdayRel = -1
	for {
		p.skipSpace()
		if p.pos >= len(p.s) {
			break
		}
		if p.err {
			return false
		}
		c := p.s[p.pos]
		switch {
		case c == '@':
			p.pos++
			neg := false
			if p.pos < len(p.s) && p.s[p.pos] == '-' {
				neg = true
				p.pos++
			}
			n, _, ok := p.readNum()
			if !ok {
				return false
			}
			ts := int64(n)
			if p.pos < len(p.s) && p.s[p.pos] == '.' {
				p.pos++
				frac, l, ok := p.readNum()
				if ok {
					for l < 9 {
						frac *= 10
						l++
					}
					p.ns = frac
				}
			}
			if neg {
				ts = -ts
			}
			p.tsSet = true
			p.ts = ts
			p.tzSet = time.UTC
		case isDigit(c):
			if !p.parseNumeric() {
				return false
			}
		case c == '+' || c == '-':
			sign := 1
			if c == '-' {
				sign = -1
			}
			p.pos++
			p.skipSpace()
			n, _, ok := p.readNum()
			if !ok {
				return false
			}
			p.skipSpace()
			unit := p.readWord()
			if !p.applyRel(sign*n, unit) {
				return false
			}
		case (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'):
			if !p.parseWord() {
				return false
			}
		case c == '.' || c == '/':
			p.pos++
		default:
			return false
		}
	}
	return !p.err
}

func (p *dateParser) applyRel(n int, unit string) bool {
	u, ok := relUnits[unit]
	if !ok {
		if wd, ok := weekdayMap[unit]; ok {
			// "+1 monday" etc: treat like "next monday" n times
			p.weekdayRel = wd
			p.weekdayDir = n
			return true
		}
		return false
	}
	switch u {
	case "s":
		p.relS += n
	case "i":
		p.relMi += n
	case "h":
		p.relH += n
	case "d":
		p.relDays += n
	case "w":
		p.relDays += 7 * n
	case "f":
		p.relDays += 14 * n
	case "m":
		p.relMonths += n
	case "y":
		p.relYears += n
	case "wd":
		p.relWeekdays += n
	case "us":
		p.ns += n * 1000
	case "ms":
		p.ns += n * 1000000
	}
	return true
}

func (p *dateParser) parseNumeric() bool {
	start := p.pos
	n, l, _ := p.readNum()
	// time hh:mm
	if p.pos < len(p.s) && p.s[p.pos] == ':' && l <= 2 {
		return p.parseTimeAfterNum(n)
	}
	// ISO date yyyy-mm-dd
	if l == 4 && p.pos < len(p.s) && (p.s[p.pos] == '-' || p.s[p.pos] == '/') {
		sep := p.s[p.pos]
		p.pos++
		m, ml, ok := p.readNum()
		if !ok {
			return false
		}
		if p.pos < len(p.s) && p.s[p.pos] == sep {
			p.pos++
			d, _, ok := p.readNum()
			if !ok {
				return false
			}
			p.y, p.m, p.d = n, m, d
			p.haveDate = true
		} else {
			// yyyy-mm
			p.y, p.m, p.d = n, m, 1
			p.haveDate = true
			_ = ml
		}
		// optional T time
		if p.pos < len(p.s) && (p.s[p.pos] == 'T' || p.s[p.pos] == 't') {
			p.pos++
			h, hl, ok := p.readNum()
			if !ok || hl > 2 {
				return false
			}
			if !p.parseTimeAfterNum(h) {
				// time like T10
				p.setTime(h, 0, 0)
			}
		}
		return true
	}
	// yyyymmdd compact
	if l == 8 && !(p.pos < len(p.s) && p.s[p.pos] == ':') {
		p.y, p.m, p.d = n/10000, (n/100)%100, n%100
		p.haveDate = true
		if p.pos < len(p.s) && (p.s[p.pos] == 'T' || p.s[p.pos] == 't') {
			p.pos++
			h, _, _ := p.readNum()
			p.parseTimeAfterNum(h)
		}
		return true
	}
	// mm/dd/yyyy or mm/dd
	if (l == 1 || l == 2) && p.pos < len(p.s) && p.s[p.pos] == '/' {
		p.pos++
		d, _, ok := p.readNum()
		if !ok {
			return false
		}
		p.m, p.d = n, d
		p.haveDate = true
		if p.pos < len(p.s) && p.s[p.pos] == '/' {
			p.pos++
			y, yl, ok := p.readNum()
			if !ok {
				return false
			}
			if yl <= 2 {
				if y < 70 {
					y += 2000
				} else {
					y += 1900
				}
			}
			p.y = y
		} else {
			p.y = p.base.Year()
		}
		return true
	}
	// dd-mm-yyyy or dd.mm.yyyy or dd-Mon-yyyy
	if (l == 1 || l == 2) && p.pos < len(p.s) && (p.s[p.pos] == '-' || p.s[p.pos] == '.') {
		sep := p.s[p.pos]
		save := p.pos
		p.pos++
		if p.pos < len(p.s) && isDigit(p.s[p.pos]) {
			m, _, _ := p.readNum()
			if p.pos < len(p.s) && p.s[p.pos] == sep {
				p.pos++
				y, yl, ok := p.readNum()
				if !ok {
					return false
				}
				if yl <= 2 {
					if y < 70 {
						y += 2000
					} else {
						y += 1900
					}
				}
				p.y, p.m, p.d = y, m, n
				p.haveDate = true
				return true
			}
			if sep == '.' {
				// hh.mm time? treat as time
				p.setTime(n, m, 0)
				return true
			}
			p.pos = save
			return false
		}
		w := p.readWord()
		if mo, ok := monthMap[w]; ok {
			p.m, p.d = mo, n
			p.haveDate = true
			if p.pos < len(p.s) && p.s[p.pos] == sep {
				p.pos++
				y, yl, ok := p.readNum()
				if ok {
					if yl <= 2 {
						if y < 70 {
							y += 2000
						} else {
							y += 1900
						}
					}
					p.y = y
				}
			} else {
				p.y = p.base.Year()
			}
			return true
		}
		p.pos = save
		return false
	}
	// "15 January 2020" / "15 Jan"
	save := p.pos
	p.skipSpace()
	w := p.peekWord()
	if mo, ok := monthMap[w]; ok && l <= 2 {
		p.pos += len(w)
		p.d, p.m = n, mo
		p.haveDate = true
		p.y = p.base.Year()
		save2 := p.pos
		p.skipSpace()
		if p.pos < len(p.s) && isDigit(p.s[p.pos]) {
			y, yl, _ := p.readNum()
			if p.pos < len(p.s) && p.s[p.pos] == ':' {
				// it's a time
				p.pos = save2
				return true
			}
			if yl == 4 {
				p.y = y
			} else if yl <= 2 {
				if y < 70 {
					y += 2000
				} else {
					y += 1900
				}
				p.y = y
			}
		} else {
			p.pos = save2
		}
		return true
	}
	// number followed by unit: "3 days"
	if u, ok := relUnits[w]; ok && u != "" {
		p.pos += len(w)
		return p.applyRel(n, w)
	}
	if _, ok := weekdayMap[w]; ok {
		p.pos += len(w)
		return p.applyRel(n, w)
	}
	// am/pm time like "3pm"
	if (w == "am" || w == "pm") && l <= 2 {
		p.setTime(n, 0, 0)
		p.parseMeridian()
		return true
	}
	p.pos = save
	// 4-digit year alone
	if l == 4 {
		p.y = n
		p.haveDate = true
		if p.m == 0 {
			p.m = int(p.base.Month())
			p.d = p.base.Day()
		}
		return true
	}
	// hhmm? unsupported
	_ = start
	return false
}

func (p *dateParser) parseWord() bool {
	w := p.readWord()
	switch w {
	case "now":
		return true
	case "today", "midnight":
		p.setTime(0, 0, 0)
		return true
	case "noon":
		p.setTime(12, 0, 0)
		return true
	case "tomorrow":
		p.relDays++
		p.setTime(0, 0, 0)
		return true
	case "yesterday":
		p.relDays--
		p.setTime(0, 0, 0)
		return true
	case "ago":
		p.relDays, p.relMonths, p.relYears = -p.relDays, -p.relMonths, -p.relYears
		p.relH, p.relMi, p.relS = -p.relH, -p.relMi, -p.relS
		p.relWeekdays = -p.relWeekdays
		return true
	case "t":
		// ISO T separator
		return true
	case "of":
		return true
	case "at", "on", "the", "and":
		return true
	}
	if mo, ok := monthMap[w]; ok {
		p.m = mo
		p.haveDate = true
		p.skipSpace()
		if p.pos < len(p.s) && isDigit(p.s[p.pos]) {
			n, l, _ := p.readNum()
			if p.pos < len(p.s) && p.s[p.pos] == ':' {
				// time follows; month only
				p.d = 1
				p.y = p.base.Year()
				return p.parseTimeAfterNum(n)
			}
			if l == 4 {
				p.y = n
				p.d = 1
			} else {
				p.d = n
				// ordinal suffix
				sw := p.peekWord()
				if sw == "st" || sw == "nd" || sw == "rd" || sw == "th" {
					p.pos += len(sw)
				}
				p.y = p.base.Year()
				save := p.pos
				p.skipSpace()
				if p.pos < len(p.s) && isDigit(p.s[p.pos]) {
					y, yl, _ := p.readNum()
					if p.pos < len(p.s) && p.s[p.pos] == ':' {
						p.pos = save
					} else if yl == 4 {
						p.y = y
					} else {
						p.pos = save
					}
				} else {
					p.pos = save
				}
			}
		} else {
			p.d = 1
			p.y = p.base.Year()
		}
		return true
	}
	if wd, ok := weekdayMap[w]; ok {
		p.weekdayRel = wd
		p.weekdayDir = 0
		if !p.timeSet {
			p.setTime(0, 0, 0)
		}
		return true
	}
	if n, ok := relWords[w]; ok {
		p.skipSpace()
		next := p.peekWord()
		if next == "day" {
			save := p.pos
			p.pos += len(next)
			p.skipSpace()
			if p.peekWord() == "of" {
				p.pos += 2
				if w == "first" {
					p.firstLastOf = 1
				} else if w == "last" {
					p.firstLastOf = 2
				} else {
					return false
				}
				if !p.timeSet {
					p.setTime(0, 0, 0)
				}
				// followed by "next month" etc or a month name
				return true
			}
			p.pos = save
		}
		if wd, ok := weekdayMap[next]; ok {
			p.pos += len(next)
			p.weekdayRel = wd
			if w == "this" {
				p.weekdayDir = 0
			} else {
				p.weekdayDir = n
			}
			if !p.timeSet {
				p.setTime(0, 0, 0)
			}
			return true
		}
		if u, ok := relUnits[next]; ok && u != "" {
			p.pos += len(next)
			if w == "this" {
				return true
			}
			return p.applyRel(n, next)
		}
		return false
	}
	if u, ok := relUnits[w]; ok && u != "" {
		// bare unit e.g. "week" => +1? PHP: "week" alone invalid? treat as 1
		return p.applyRel(1, w)
	}
	// timezone name
	p.pos -= len(w)
	save := p.pos
	p.parseTZ()
	if p.pos == save {
		return false
	}
	return true
}

func (in *Interp) strtotime(s string, base time.Time) (time.Time, bool) {
	s = strings.TrimSpace(s)
	p := &dateParser{s: s, base: base, loc: base.Location()}
	if s == "" {
		return base, false
	}
	if !p.parse() {
		return base, false
	}
	loc := base.Location()
	if p.tzSet != nil {
		loc = p.tzSet
	} else if p.tzOffset != nil {
		loc = time.FixedZone(tzOffsetName(*p.tzOffset), *p.tzOffset)
	}
	if p.tsSet {
		t := time.Unix(p.ts, int64(p.ns)).In(loc)
		t = t.AddDate(p.relYears, p.relMonths, p.relDays)
		t = t.Add(time.Duration(p.relH)*time.Hour + time.Duration(p.relMi)*time.Minute + time.Duration(p.relS)*time.Second)
		if p.tzSet == nil && p.tzOffset == nil {
			t = t.In(base.Location())
		}
		return t, true
	}
	b := base.In(loc)
	y, m, d := b.Year(), int(b.Month()), b.Day()
	h, mi, sec, ns := b.Hour(), b.Minute(), b.Second(), b.Nanosecond()
	if p.haveDate {
		if p.y != 0 || p.m != 0 {
			y = p.y
			if p.y == 0 {
				y = b.Year()
			}
		}
		if p.m != 0 {
			m = p.m
		}
		if p.d != 0 {
			d = p.d
		}
		if !p.timeSet {
			h, mi, sec, ns = 0, 0, 0, 0
		}
	}
	if p.timeSet {
		h, mi, sec, ns = p.h, p.mi, p.sec, p.ns
	}
	// relative months/years applied first (PHP: y/m/d relative then h/i/s)
	y += p.relYears
	m += p.relMonths
	if p.firstLastOf != 0 {
		// normalize month then set day
		t := time.Date(y, time.Month(m), 1, h, mi, sec, ns, loc)
		if p.firstLastOf == 1 {
			d = 1
		} else {
			d = daysInMonth(t.Year(), int(t.Month()))
		}
		y, m = t.Year(), int(t.Month())
	}
	d += p.relDays
	t := time.Date(y, time.Month(m), d, h, mi, sec, ns, loc)
	if p.weekdayRel >= 0 {
		cur := int(t.Weekday())
		diff := p.weekdayRel - cur
		switch {
		case p.weekdayDir == 0:
			if diff < 0 {
				diff += 7
			}
		case p.weekdayDir > 0:
			if diff <= 0 {
				diff += 7
			}
			diff += 7 * (p.weekdayDir - 1)
		case p.weekdayDir < 0:
			if diff >= 0 {
				diff -= 7
			}
			diff += 7 * (p.weekdayDir + 1)
		}
		t = t.AddDate(0, 0, diff)
	}
	if p.relWeekdays != 0 {
		n := p.relWeekdays
		step := 1
		if n < 0 {
			step = -1
			n = -n
		}
		for n > 0 {
			t = t.AddDate(0, 0, step)
			if t.Weekday() != time.Saturday && t.Weekday() != time.Sunday {
				n--
			}
		}
	}
	t = t.Add(time.Duration(p.relH)*time.Hour + time.Duration(p.relMi)*time.Minute + time.Duration(p.relS)*time.Second)
	if p.tzSet == nil && p.tzOffset == nil {
		return t, true
	}
	return t, true
}

func tzOffsetName(off int) string {
	sign := "+"
	if off < 0 {
		sign = "-"
		off = -off
	}
	return fmt.Sprintf("%s%02d:%02d", sign, off/3600, (off%3600)/60)
}

func (in *Interp) initDateFunctions() {
	in.reg("time", 0, 0, func(in *Interp, args []Value) Value { return time.Now().Unix() })
	in.reg("date", 1, 2, func(in *Interp, args []Value) Value {
		t := time.Now().In(in.loc())
		if len(args) > 1 && args[1] != nil {
			t = time.Unix(toInt(args[1]), 0).In(in.loc())
		}
		return phpDate(in.argStr("date", args, 0), t)
	})
	in.reg("gmdate", 1, 2, func(in *Interp, args []Value) Value {
		t := time.Now().UTC()
		if len(args) > 1 && args[1] != nil {
			t = time.Unix(toInt(args[1]), 0).UTC()
		}
		return phpDate(in.argStr("gmdate", args, 0), t)
	})
	in.reg("idate", 1, 2, func(in *Interp, args []Value) Value {
		t := time.Now().In(in.loc())
		if len(args) > 1 && args[1] != nil {
			t = time.Unix(toInt(args[1]), 0).In(in.loc())
		}
		f := in.argStr("idate", args, 0)
		if len(f) != 1 {
			in.throwError("ValueError", "idate(): Argument #1 ($format) must be one character")
		}
		switch f[0] {
		case 'B', 'd', 'h', 'H', 'i', 'I', 'L', 'm', 's', 't', 'U', 'w', 'W', 'y', 'Y', 'z', 'Z', 'N', 'o':
			return toInt(phpDate(f, t))
		}
		in.throwError("ValueError", "idate(): Argument #1 ($format) must be a valid date format character")
		return nil
	})
	mk := func(name string, utc bool) {
		in.reg(name, 0, 6, func(in *Interp, args []Value) Value {
			loc := in.loc()
			if utc {
				loc = time.UTC
			}
			now := time.Now().In(loc)
			vals := []int{now.Hour(), now.Minute(), now.Second(), int(now.Month()), now.Day(), now.Year()}
			for i := 0; i < len(args) && i < 6; i++ {
				if args[i] != nil {
					vals[i] = int(in.argInt(name, args, i))
				}
			}
			y := vals[5]
			if len(args) > 5 && args[5] != nil {
				if y >= 0 && y < 70 {
					y += 2000
				} else if y >= 70 && y <= 100 {
					y += 1900
				}
			}
			t := time.Date(y, time.Month(vals[3]), vals[4], vals[0], vals[1], vals[2], 0, loc)
			return t.Unix()
		})
	}
	mk("mktime", false)
	mk("gmmktime", true)
	in.reg("checkdate", 3, 3, func(in *Interp, args []Value) Value {
		m, d, y := in.argInt("checkdate", args, 0), in.argInt("checkdate", args, 1), in.argInt("checkdate", args, 2)
		if m < 1 || m > 12 || d < 1 || y < 1 || y > 32767 {
			return false
		}
		return d <= int64(daysInMonth(int(y), int(m)))
	})
	in.reg("strtotime", 1, 2, func(in *Interp, args []Value) Value {
		base := time.Now().In(in.loc())
		if len(args) > 1 && args[1] != nil {
			base = time.Unix(toInt(args[1]), 0).In(in.loc())
		}
		t, ok := in.strtotime(in.argStr("strtotime", args, 0), base)
		if !ok {
			return false
		}
		return t.Unix()
	})
	in.reg("date_default_timezone_set", 1, 1, func(in *Interp, args []Value) Value {
		tz := in.argStr("date_default_timezone_set", args, 0)
		if _, err := time.LoadLocation(tz); err != nil {
			in.notice(fmt.Sprintf("date_default_timezone_set(): Timezone ID '%s' is invalid", tz))
			return false
		}
		in.timezone = tz
		in.ini["date.timezone"] = tz
		return true
	})
	in.reg("date_default_timezone_get", 0, 0, func(in *Interp, args []Value) Value { return in.timezone })
	in.reg("getdate", 0, 1, func(in *Interp, args []Value) Value {
		t := time.Now().In(in.loc())
		if len(args) > 0 && args[0] != nil {
			t = time.Unix(toInt(args[0]), 0).In(in.loc())
		}
		a := NewArray()
		a.SetStr("seconds", int64(t.Second()))
		a.SetStr("minutes", int64(t.Minute()))
		a.SetStr("hours", int64(t.Hour()))
		a.SetStr("mday", int64(t.Day()))
		a.SetStr("wday", int64(t.Weekday()))
		a.SetStr("mon", int64(t.Month()))
		a.SetStr("year", int64(t.Year()))
		a.SetStr("yday", int64(t.YearDay()-1))
		a.SetStr("weekday", weekdayNames[t.Weekday()])
		a.SetStr("month", monthNames[t.Month()-1])
		a.SetInt(0, t.Unix())
		return a
	})
	in.reg("localtime", 0, 2, func(in *Interp, args []Value) Value {
		t := time.Now().In(in.loc())
		if len(args) > 0 && args[0] != nil {
			t = time.Unix(toInt(args[0]), 0).In(in.loc())
		}
		assoc := len(args) > 1 && toBool(args[1])
		vals := []int64{int64(t.Second()), int64(t.Minute()), int64(t.Hour()), int64(t.Day()), int64(t.Month()) - 1, int64(t.Year() - 1900), int64(t.Weekday()), int64(t.YearDay() - 1), 0}
		if t.IsDST() {
			vals[8] = 1
		}
		names := []string{"tm_sec", "tm_min", "tm_hour", "tm_mday", "tm_mon", "tm_year", "tm_wday", "tm_yday", "tm_isdst"}
		a := NewArray()
		for i, v := range vals {
			if assoc {
				a.SetStr(names[i], v)
			} else {
				a.Append(v)
			}
		}
		return a
	})
	in.reg("date_parse", 1, 1, func(in *Interp, args []Value) Value {
		s := toStr(args[0])
		base := time.Date(0, 1, 1, 0, 0, 0, 0, time.UTC)
		p := &dateParser{s: s, base: base, loc: time.UTC}
		p.weekdayRel = -1
		ok := p.parse()
		a := NewArray()
		set := func(k string, v int, have bool) {
			if have {
				a.SetStr(k, int64(v))
			} else {
				a.SetStr(k, false)
			}
		}
		set("year", p.y, p.haveDate && p.y != 0)
		set("month", p.m, p.haveDate && p.m != 0)
		set("day", p.d, p.haveDate && p.d != 0)
		set("hour", p.h, p.timeSet)
		set("minute", p.mi, p.timeSet)
		set("second", p.sec, p.timeSet)
		if p.timeSet {
			a.SetStr("fraction", float64(p.ns)/1e9)
		} else {
			a.SetStr("fraction", false)
		}
		if ok {
			a.SetStr("warning_count", int64(0))
			a.SetStr("warnings", NewArray())
			a.SetStr("error_count", int64(0))
			a.SetStr("errors", NewArray())
		} else {
			a.SetStr("warning_count", int64(0))
			a.SetStr("warnings", NewArray())
			a.SetStr("error_count", int64(1))
			errs := NewArray()
			errs.SetInt(int64(p.pos), "Unexpected character")
			a.SetStr("errors", errs)
		}
		a.SetStr("is_localtime", p.tzSet != nil || p.tzOffset != nil)
		if p.relDays != 0 || p.relMonths != 0 || p.relYears != 0 || p.relH != 0 || p.relMi != 0 || p.relS != 0 {
			rel := NewArray()
			rel.SetStr("year", int64(p.relYears))
			rel.SetStr("month", int64(p.relMonths))
			rel.SetStr("day", int64(p.relDays))
			rel.SetStr("hour", int64(p.relH))
			rel.SetStr("minute", int64(p.relMi))
			rel.SetStr("second", int64(p.relS))
			a.SetStr("relative", rel)
		}
		return a
	})
	in.reg("timezone_identifiers_list", 0, 2, func(in *Interp, args []Value) Value {
		return NewListArray([]Value{"UTC", "Europe/London", "Europe/Paris", "Europe/Berlin", "America/New_York", "America/Chicago", "America/Los_Angeles", "Asia/Tokyo", "Australia/Sydney"})
	})
	in.reg("hrtime", 0, 1, in.functions["hrtime"].Native)
	in.reg("strftime", 1, 2, func(in *Interp, args []Value) Value {
		in.deprecated("Function strftime() is deprecated since 8.1, use IntlDateFormatter::format() instead")
		t := time.Now().In(in.loc())
		if len(args) > 1 && args[1] != nil {
			t = time.Unix(toInt(args[1]), 0).In(in.loc())
		}
		return strftime(toStr(args[0]), t)
	})
	in.reg("gmstrftime", 1, 2, func(in *Interp, args []Value) Value {
		in.deprecated("Function gmstrftime() is deprecated since 8.1, use IntlDateFormatter::format() instead")
		t := time.Now().UTC()
		if len(args) > 1 && args[1] != nil {
			t = time.Unix(toInt(args[1]), 0).UTC()
		}
		return strftime(toStr(args[0]), t)
	})
}

func strftime(f string, t time.Time) string {
	var sb strings.Builder
	for i := 0; i < len(f); i++ {
		if f[i] != '%' || i+1 >= len(f) {
			sb.WriteByte(f[i])
			continue
		}
		i++
		switch f[i] {
		case 'a':
			sb.WriteString(weekdayNames[t.Weekday()][:3])
		case 'A':
			sb.WriteString(weekdayNames[t.Weekday()])
		case 'd':
			sb.WriteString(fmt.Sprintf("%02d", t.Day()))
		case 'e':
			sb.WriteString(fmt.Sprintf("%2d", t.Day()))
		case 'j':
			sb.WriteString(fmt.Sprintf("%03d", t.YearDay()))
		case 'u':
			wd := int(t.Weekday())
			if wd == 0 {
				wd = 7
			}
			sb.WriteString(strconv.Itoa(wd))
		case 'w':
			sb.WriteString(strconv.Itoa(int(t.Weekday())))
		case 'b', 'h':
			sb.WriteString(monthNames[t.Month()-1][:3])
		case 'B':
			sb.WriteString(monthNames[t.Month()-1])
		case 'm':
			sb.WriteString(fmt.Sprintf("%02d", int(t.Month())))
		case 'y':
			sb.WriteString(fmt.Sprintf("%02d", t.Year()%100))
		case 'Y':
			sb.WriteString(strconv.Itoa(t.Year()))
		case 'H':
			sb.WriteString(fmt.Sprintf("%02d", t.Hour()))
		case 'I':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			sb.WriteString(fmt.Sprintf("%02d", h))
		case 'l':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			sb.WriteString(fmt.Sprintf("%2d", h))
		case 'M':
			sb.WriteString(fmt.Sprintf("%02d", t.Minute()))
		case 'S':
			sb.WriteString(fmt.Sprintf("%02d", t.Second()))
		case 'p':
			if t.Hour() < 12 {
				sb.WriteString("AM")
			} else {
				sb.WriteString("PM")
			}
		case 'P':
			if t.Hour() < 12 {
				sb.WriteString("am")
			} else {
				sb.WriteString("pm")
			}
		case 'Z':
			abbr, _ := t.Zone()
			sb.WriteString(abbr)
		case 'z':
			sb.WriteString(tzOffset(t, false))
		case 's':
			sb.WriteString(strconv.FormatInt(t.Unix(), 10))
		case 'n':
			sb.WriteByte('\n')
		case 't':
			sb.WriteByte('\t')
		case '%':
			sb.WriteByte('%')
		case 'D':
			sb.WriteString(phpDate("m/d/y", t))
		case 'F':
			sb.WriteString(phpDate("Y-m-d", t))
		case 'T':
			sb.WriteString(phpDate("H:i:s", t))
		case 'R':
			sb.WriteString(phpDate("H:i", t))
		case 'c':
			sb.WriteString(phpDate("D M j H:i:s Y", t))
		case 'x':
			sb.WriteString(phpDate("m/d/y", t))
		case 'X':
			sb.WriteString(phpDate("H:i:s", t))
		case 'V':
			_, w := t.ISOWeek()
			sb.WriteString(fmt.Sprintf("%02d", w))
		case 'G':
			y, _ := t.ISOWeek()
			sb.WriteString(strconv.Itoa(y))
		case 'C':
			sb.WriteString(fmt.Sprintf("%02d", t.Year()/100))
		case 'g':
			y, _ := t.ISOWeek()
			sb.WriteString(fmt.Sprintf("%02d", y%100))
		default:
			sb.WriteByte('%')
			sb.WriteByte(f[i])
		}
	}
	return sb.String()
}
