cd /workspace/src && cat > date.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
	_ "time/tzdata"
)

func (in *Interp) loc() *time.Location {
	l, err := time.LoadLocation(in.timezone)
	if err != nil {
		return time.UTC
	}
	return l
}

var weekdayNames = []string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}
var monthNames = []string{"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}

func isoWeekYear(t time.Time) (int, int) {
	y, w := t.ISOWeek()
	return y, w
}

func phpDate(format string, t time.Time) string {
	var sb strings.Builder
	for i := 0; i < len(format); i++ {
		c := format[i]
		switch c {
		case 'd':
			sb.WriteString(fmt.Sprintf("%02d", t.Day()))
		case 'D':
			sb.WriteString(weekdayNames[t.Weekday()][:3])
		case 'j':
			sb.WriteString(strconv.Itoa(t.Day()))
		case 'l':
			sb.WriteString(weekdayNames[t.Weekday()])
		case 'N':
			wd := int(t.Weekday())
			if wd == 0 {
				wd = 7
			}
			sb.WriteString(strconv.Itoa(wd))
		case 'S':
			d := t.Day()
			switch {
			case d == 1 || d == 21 || d == 31:
				sb.WriteString("st")
			case d == 2 || d == 22:
				sb.WriteString("nd")
			case d == 3 || d == 23:
				sb.WriteString("rd")
			default:
				sb.WriteString("th")
			}
		case 'w':
			sb.WriteString(strconv.Itoa(int(t.Weekday())))
		case 'z':
			sb.WriteString(strconv.Itoa(t.YearDay() - 1))
		case 'W':
			_, w := t.ISOWeek()
			sb.WriteString(fmt.Sprintf("%02d", w))
		case 'F':
			sb.WriteString(monthNames[t.Month()-1])
		case 'm':
			sb.WriteString(fmt.Sprintf("%02d", int(t.Month())))
		case 'M':
			sb.WriteString(monthNames[t.Month()-1][:3])
		case 'n':
			sb.WriteString(strconv.Itoa(int(t.Month())))
		case 't':
			sb.WriteString(strconv.Itoa(daysInMonth(t.Year(), int(t.Month()))))
		case 'L':
			if isLeap(t.Year()) {
				sb.WriteByte('1')
			} else {
				sb.WriteByte('0')
			}
		case 'o':
			y, _ := t.ISOWeek()
			sb.WriteString(strconv.Itoa(y))
		case 'X':
			y := t.Year()
			if y >= 10000 || y < 0 {
				sb.WriteString(fmt.Sprintf("%+05d", y))
			} else {
				sb.WriteString(fmt.Sprintf("%04d", y))
			}
		case 'x':
			y := t.Year()
			if y >= 10000 {
				sb.WriteString(fmt.Sprintf("+%d", y))
			} else {
				sb.WriteString(fmt.Sprintf("%04d", y))
			}
		case 'Y':
			y := t.Year()
			if y < 0 {
				sb.WriteString(fmt.Sprintf("-%04d", -y))
			} else {
				sb.WriteString(fmt.Sprintf("%04d", y))
			}
		case 'y':
			sb.WriteString(fmt.Sprintf("%02d", t.Year()%100))
		case 'a':
			if t.Hour() < 12 {
				sb.WriteString("am")
			} else {
				sb.WriteString("pm")
			}
		case 'A':
			if t.Hour() < 12 {
				sb.WriteString("AM")
			} else {
				sb.WriteString("PM")
			}
		case 'B':
			// swatch internet time
			utc := t.UTC()
			secs := (utc.Hour()*3600 + utc.Minute()*60 + utc.Second() + 3600) % 86400
			sb.WriteString(fmt.Sprintf("%03d", secs*1000/86400))
		case 'g':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			sb.WriteString(strconv.Itoa(h))
		case 'G':
			sb.WriteString(strconv.Itoa(t.Hour()))
		case 'h':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			sb.WriteString(fmt.Sprintf("%02d", h))
		case 'H':
			sb.WriteString(fmt.Sprintf("%02d", t.Hour()))
		case 'i':
			sb.WriteString(fmt.Sprintf("%02d", t.Minute()))
		case 's':
			sb.WriteString(fmt.Sprintf("%02d", t.Second()))
		case 'u':
			sb.WriteString(fmt.Sprintf("%06d", t.Nanosecond()/1000))
		case 'v':
			sb.WriteString(fmt.Sprintf("%03d", t.Nanosecond()/1000000))
		case 'e':
			sb.WriteString(tzName(t))
		case 'I':
			if t.IsDST() {
				sb.WriteByte('1')
			} else {
				sb.WriteByte('0')
			}
		case 'O':
			sb.WriteString(tzOffset(t, false))
		case 'P':
			sb.WriteString(tzOffset(t, true))
		case 'p':
			o := tzOffset(t, true)
			if o == "+00:00" {
				o = "Z"
			}
			sb.WriteString(o)
		case 'T':
			abbr, _ := t.Zone()
			if strings.HasPrefix(abbr, "+") || strings.HasPrefix(abbr, "-") {
				abbr = tzOffset(t, true)
			}
			sb.WriteString(abbr)
		case 'Z':
			_, off := t.Zone()
			sb.WriteString(strconv.Itoa(off))
		case 'c':
			sb.WriteString(phpDate("Y-m-d\\TH:i:sP", t))
		case 'r':
			sb.WriteString(phpDate("D, d M Y H:i:s O", t))
		case 'U':
			sb.WriteString(strconv.FormatInt(t.Unix(), 10))
		case '\\':
			if i+1 < len(format) {
				i++
				sb.WriteByte(format[i])
			}
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

func tzName(t time.Time) string {
	name := t.Location().String()
	if name == "Local" {
		return "UTC"
	}
	return name
}

func tzOffset(t time.Time, colon bool) string {
	_, off := t.Zone()
	sign := "+"
	if off < 0 {
		sign = "-"
		off = -off
	}
	h := off / 3600
	m := (off % 3600) / 60
	if colon {
		return fmt.Sprintf("%s%02d:%02d", sign, h, m)
	}
	return fmt.Sprintf("%s%02d%02d", sign, h, m)
}

func isLeap(y int) bool { return y%4 == 0 && (y%100 != 0 || y%400 == 0) }

func daysInMonth(y, m int) int {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		if isLeap(y) {
			return 29
		}
		return 28
	}
	return 30
}

// ---------- strtotime ----------

type dateParser struct {
	s    string
	pos  int
	base time.Time
	loc  *time.Location
	// result components
	y, m, d       int
	h, mi, sec    int
	ns            int
	haveDate      bool
	haveTime      bool
	timeSet       bool
	relDays, relMonths, relYears int
	relH, relMi, relS int
	weekdayRel    int // -1 none
	weekdayDir    int
	firstLastOf   int // 1 = first day of, 2 = last day of
	tzSet         *time.Location
	tzOffset      *int
	err           bool
	resetTime     bool
	tsSet         bool
	ts            int64
}

var monthMap = map[string]int{
	"jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3, "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6,
	"jul": 7, "july": 7, "aug": 8, "august": 8, "sep": 9, "sept": 9, "september": 9, "oct": 10, "october": 10, "nov": 11, "november": 11, "dec": 12, "december": 12,
}

var weekdayMap = map[string]int{
	"sun": 0, "sunday": 0, "mon": 1, "monday": 1, "tue": 2, "tues": 2, "tuesday": 2, "wed": 3, "wednesday": 3, "thu": 4, "thur": 4, "thurs": 4, "thursday": 4, "fri": 5, "friday": 5, "sat": 6, "saturday": 6,
}

var relUnits = map[string]string{
	"sec": "s", "secs": "s", "second": "s", "seconds": "s",
	"min": "i", "mins": "i", "minute": "i", "minutes": "i",
	"hour": "h", "hours": "h",
	"day": "d", "days": "d",
	"week": "w", "weeks": "w",
	"fortnight": "f", "fortnights": "f",
	"month": "m", "months": "m",
	"year": "y", "years": "y",
	"weekday": "wd", "weekdays": "wd",
	"usec": "us", "usecs": "us", "microsecond": "us", "microseconds": "us",
	"msec": "ms", "msecs": "ms", "millisecond": "ms", "milliseconds": "ms",
	"sat": "", "saturday": "",
}

var relWords = map[string]int{"last": -1, "previous": -1, "this": 0, "next": 1, "first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6, "seventh": 7, "eighth": 8, "ninth": 9, "tenth": 10, "eleventh": 11, "twelfth": 12}

func (p *dateParser) skipSpace() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t' || p.s[p.pos] == ',' || p.s[p.pos] == '\n') {
		p.pos++
	}
}

func (p *dateParser) peekWord() string {
	i := p.pos
	for i < len(p.s) && ((p.s[i] >= 'a' && p.s[i] <= 'z') || (p.s[i] >= 'A' && p.s[i] <= 'Z')) {
		i++
	}
	return strings.ToLower(p.s[p.pos:i])
}

func (p *dateParser) readWord() string {
	w := p.peekWord()
	p.pos += len(w)
	return w
}

func (p *dateParser) readNum() (int, int, bool) {
	i := p.pos
	for i < len(p.s) && isDigit(p.s[i]) {
		i++
	}
	if i == p.pos {
		return 0, 0, false
	}
	n, _ := strconv.Atoi(p.s[p.pos:i])
	l := i - p.pos
	p.pos = i
	return n, l, true
}

func (p *dateParser) peekNumLen() int {
	i := p.pos
	for i < len(p.s) && isDigit(p.s[i]) {
		i++
	}
	return i - p.pos
}

func (p *dateParser) setTime(h, mi, s int) {
	p.h, p.mi, p.sec = h, mi, s
	p.ns = 0
	p.haveTime = true
	p.timeSet = true
}

func (p *dateParser) parseTimeAfterNum(h int) bool {
	// expects ':' consumed next
	if p.pos < len(p.s) && p.s[p.pos] == ':' {
		p.pos++
		mi, l, ok := p.readNum()
		if !ok || l > 2 {
			p.err = true
			return false
		}
		sec := 0
		if p.pos < len(p.s) && p.s[p.pos] == ':' {
			p.pos++
			s2, _, ok := p.readNum()
			if !ok {
				p.err = true
				return false
			}
			sec = s2
			if p.pos < len(p.s) && (p.s[p.pos] == '.' || p.s[p.pos] == ',') {
				p.pos++
				start := p.pos
				frac, l, ok := p.readNum()
				if ok {
					_ = start
					for l < 9 {
						frac *= 10
						l++
					}
					for l > 9 {
						frac /= 10
						l--
					}
					p.ns = frac
				}
			}
		}
		p.setTime(h, mi, sec)
		p.parseMeridian()
		p.parseTZ()
		return true
	}
	return false
}

func (p *dateParser) parseMeridian() {
	save := p.pos
	p.skipSpace()
	w := p.peekWord()
	w = strings.ReplaceAll(w, ".", "")
	if w == "am" || w == "pm" || w == "a" || w == "p" {
		p.pos += len(w)
		if p.pos < len(p.s) && p.s[p.pos] == '.' {
			p.pos++
			if p.pos < len(p.s) && (p.s[p.pos] == 'm' || p.s[p.pos] == 'M') {
				p.pos++
				if p.pos < len(p.s) && p.s[p.pos] == '.' {
					p.pos++
				}
			}
		}
		if w[0] == 'p' && p.h < 12 {
			p.h += 12
		} else if w[0] == 'a' && p.h == 12 {
			p.h = 0
		}
		return
	}
	p.pos = save
}

func (p *dateParser) parseTZ() {
	save := p.pos
	p.skipSpace()
	if p.pos >= len(p.s) {
		return
	}
	c := p.s[p.pos]
	if c == 'Z' || c == 'z' {
		if p.pos+1 >= len(p.s) || !isIdentChar(p.s[p.pos+1]) {
			p.pos++
			off := 0
			p.tzOffset = &off
			return
		}
	}
	if c == '+' || c == '-' {
		sign := 1
		if c == '-' {
			sign = -1
		}
		i := p.pos + 1
		j := i
		for j < len(p.s) && isDigit(p.s[j]) {
			j++
		}
		digits := p.s[i:j]
		var h, m int
		switch len(digits) {
		case 1, 2:
			h, _ = strconv.Atoi(digits)
			if j < len(p.s) && p.s[j] == ':' {
				k := j + 1
				for k < len(p.s) && isDigit(p.s[k]) {
					k++
				}
				m, _ = strconv.Atoi(p.s[j+1 : k])
				j = k
			}
		case 3:
			h, _ = strconv.Atoi(digits[:1])
			m, _ = strconv.Atoi(digits[1:])
		case 4:
			h, _ = strconv.Atoi(digits[:2])
			m, _ = strconv.Atoi(digits[2:])
		default:
			p.pos = save
			return
		}
		off := sign * (h*3600 + m*60)
		p.tzOffset = &off
		p.pos = j
		return
	}
	// named timezone like UTC, GMT, EST or Europe/Paris
	i := p.pos
	for i < len(p.s) && (isIdentChar(p.s[i]) || p.s[i] == '/') {
		i++
	}
	name := p.s[p.pos:i]
	if name == "" {
		p.pos = save
		return
	}
	upper := strings.ToUpper(name)
	abbrs := map[string]int{"UTC": 0, "GMT": 0, "Z": 0, "EST": -5 * 3600, "EDT": -4 * 3600, "CST": -6 * 3600, "CDT": -5 * 3600, "MST": -7 * 3600, "MDT": -6 * 3600, "PST": -8 * 3600, "PDT": -7 * 3600, "CET": 3600, "CEST": 7200, "BST": 3600, "JST": 9 * 3600, "IST": 19800, "EET": 7200, "WET": 0, "AEST": 36000, "MSK": 10800}
	if off, ok := abbrs[upper]; ok {
		if upper == "UTC" || upper == "GMT" {
			p.tzSet = time.UTC
		} else {
			p.tzOffset = &off
		}
		p.pos = i
		return
	}
	if strings.Contains(name, "/") {
		if l, err := time.LoadLocation(name); err == nil {
			p.tzSet = l
			p.pos = i
			return
		}
	}
	p.pos = save
}

func (p *dateParser) parse() bool {
	p.weekdayRel = -1
	for {
		p.skipSpace()
		if p.pos >= len(p.s) {
			break
		}
		if p.err {
			return false
		}
		c := p.s[p.pos]
		switch {
		case c == '@':
			p.pos++
			neg := false
			if p.pos < len(p.s) && p.s[p.pos] == '-' {
				neg = true
				p.pos++
			}
			n, _, ok := p.readNum()
			if !ok {
				return false
			}
			ts := int64(n)
			if p.pos < len(p.s) && p.s[p.pos] == '.' {
				p.pos++
				frac, l, ok := p.readNum()
				if ok {
					for l < 9 {
						frac *= 10
						l++
					}
					p.ns = frac
				}
			}
			if neg {
				ts = -ts
			}
			p.tsSet = true
			p.ts = ts
			p.tzSet = time.UTC
		case isDigit(c):
			if !p.parseNumeric() {
				return false
			}
		case c == '+' || c == '-':
			sign := 1
			if c == '-' {
				sign = -1
			}
			p.pos++
			p.skipSpace()
			n, _, ok := p.readNum()
			if !ok {
				return false
			}
			p.skipSpace()
			unit := p.readWord()
			if !p.applyRel(sign*n, unit) {
				return false
			}
		case (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'):
			if !p.parseWord() {
				return false
			}
		case c == '.' || c == '/':
			p.pos++
		default:
			return false
		}
	}
	return !p.err
}

func (p *dateParser) applyRel(n int, unit string) bool {
	u, ok := relUnits[unit]
	if !ok {
		if wd, ok := weekdayMap[unit]; ok {
			// "+1 monday" etc: treat like "next monday" n times
			p.weekdayRel = wd
			p.weekdayDir = n
			return true
		}
		return false
	}
	switch u {
	case "s":
		p.relS += n
	case "i":
		p.relMi += n
	case "h":
		p.relH += n
	case "d":
		p.relDays += n
	case "w":
		p.relDays += 7 * n
	case "f":
		p.relDays += 14 * n
	case "m":
		p.relMonths += n
	case "y":
		p.relYears += n
	case "wd":
		p.relWeekdays += n
	case "us":
		p.ns += n * 1000
	case "ms":
		p.ns += n * 1000000
	}
	return true
}

func (p *dateParser) parseNumeric() bool {
	start := p.pos
	n, l, _ := p.readNum()
	// time hh:mm
	if p.pos < len(p.s) && p.s[p.pos] == ':' && l <= 2 {
		return p.parseTimeAfterNum(n)
	}
	// ISO date yyyy-mm-dd
	if l == 4 && p.pos < len(p.s) && (p.s[p.pos] == '-' || p.s[p.pos] == '/') {
		sep := p.s[p.pos]
		p.pos++
		m, ml, ok := p.readNum()
		if !ok {
			return false
		}
		if p.pos < len(p.s) && p.s[p.pos] == sep {
			p.pos++
			d, _, ok := p.readNum()
			if !ok {
				return false
			}
			p.y, p.m, p.d = n, m, d
			p.haveDate = true
		} else {
			// yyyy-mm
			p.y, p.m, p.d = n, m, 1
			p.haveDate = true
			_ = ml
		}
		// optional T time
		if p.pos < len(p.s) && (p.s[p.pos] == 'T' || p.s[p.pos] == 't') {
			p.pos++
			h, hl, ok := p.readNum()
			if !ok || hl > 2 {
				return false
			}
			if !p.parseTimeAfterNum(h) {
				// time like T10
				p.setTime(h, 0, 0)
			}
		}
		return true
	}
	// yyyymmdd compact
	if l == 8 && !(p.pos < len(p.s) && p.s[p.pos] == ':') {
		p.y, p.m, p.d = n/10000, (n/100)%100, n%100
		p.haveDate = true
		if p.pos < len(p.s) && (p.s[p.pos] == 'T' || p.s[p.pos] == 't') {
			p.pos++
			h, _, _ := p.readNum()
			p.parseTimeAfterNum(h)
		}
		return true
	}
	// mm/dd/yyyy or mm/dd
	if (l == 1 || l == 2) && p.pos < len(p.s) && p.s[p.pos] == '/' {
		p.pos++
		d, _, ok := p.readNum()
		if !ok {
			return false
		}
		p.m, p.d = n, d
		p.haveDate = true
		if p.pos < len(p.s) && p.s[p.pos] == '/' {
			p.pos++
			y, yl, ok := p.readNum()
			if !ok {
				return false
			}
			if yl <= 2 {
				if y < 70 {
					y += 2000
				} else {
					y += 1900
				}
			}
			p.y = y
		} else {
			p.y = p.base.Year()
		}
		return true
	}
	// dd-mm-yyyy or dd.mm.yyyy or dd-Mon-yyyy
	if (l == 1 || l == 2) && p.pos < len(p.s) && (p.s[p.pos] == '-' || p.s[p.pos] == '.') {
		sep := p.s[p.pos]
		save := p.pos
		p.pos++
		if p.pos < len(p.s) && isDigit(p.s[p.pos]) {
			m, _, _ := p.readNum()
			if p.pos < len(p.s) && p.s[p.pos] == sep {
				p.pos++
				y, yl, ok := p.readNum()
				if !ok {
					return false
				}
				if yl <= 2 {
					if y < 70 {
						y += 2000
					} else {
						y += 1900
					}
				}
				p.y, p.m, p.d = y, m, n
				p.haveDate = true
				return true
			}
			if sep == '.' {
				// hh.mm time? treat as time
				p.setTime(n, m, 0)
				return true
			}
			p.pos = save
			return false
		}
		w := p.readWord()
		if mo, ok := monthMap[w]; ok {
			p.m, p.d = mo, n
			p.haveDate = true
			if p.pos < len(p.s) && p.s[p.pos] == sep {
				p.pos++
				y, yl, ok := p.readNum()
				if ok {
					if yl <= 2 {
						if y < 70 {
							y += 2000
						} else {
							y += 1900
						}
					}
					p.y = y
				}
			} else {
				p.y = p.base.Year()
			}
			return true
		}
		p.pos = save
		return false
	}
	// "15 January 2020" / "15 Jan"
	save := p.pos
	p.skipSpace()
	w := p.peekWord()
	if mo, ok := monthMap[w]; ok && l <= 2 {
		p.pos += len(w)
		p.d, p.m = n, mo
		p.haveDate = true
		p.y = p.base.Year()
		save2 := p.pos
		p.skipSpace()
		if p.pos < len(p.s) && isDigit(p.s[p.pos]) {
			y, yl, _ := p.readNum()
			if p.pos < len(p.s) && p.s[p.pos] == ':' {
				// it's a time
				p.pos = save2
				return true
			}
			if yl == 4 {
				p.y = y
			} else if yl <= 2 {
				if y < 70 {
					y += 2000
				} else {
					y += 1900
				}
				p.y = y
			}
		} else {
			p.pos = save2
		}
		return true
	}
	// number followed by unit: "3 days"
	if u, ok := relUnits[w]; ok && u != "" {
		p.pos += len(w)
		return p.applyRel(n, w)
	}
	if _, ok := weekdayMap[w]; ok {
		p.pos += len(w)
		return p.applyRel(n, w)
	}
	// am/pm time like "3pm"
	if (w == "am" || w == "pm") && l <= 2 {
		p.setTime(n, 0, 0)
		p.parseMeridian()
		return true
	}
	p.pos = save
	// 4-digit year alone
	if l == 4 {
		p.y = n
		p.haveDate = true
		if p.m == 0 {
			p.m = int(p.base.Month())
			p.d = p.base.Day()
		}
		return true
	}
	// hhmm? unsupported
	_ = start
	return false
}

func (p *dateParser) parseWord() bool {
	w := p.readWord()
	switch w {
	case "now":
		return true
	case "today", "midnight":
		p.setTime(0, 0, 0)
		return true
	case "noon":
		p.setTime(12, 0, 0)
		return true
	case "tomorrow":
		p.relDays++
		p.setTime(0, 0, 0)
		return true
	case "yesterday":
		p.relDays--
		p.setTime(0, 0, 0)
		return true
	case "ago":
		p.relDays, p.relMonths, p.relYears = -p.relDays, -p.relMonths, -p.relYears
		p.relH, p.relMi, p.relS = -p.relH, -p.relMi, -p.relS
		p.relWeekdays = -p.relWeekdays
		return true
	case "t":
		// ISO T separator
		return true
	case "of":
		return true
	case "at", "on", "the", "and":
		return true
	}
	if mo, ok := monthMap[w]; ok {
		p.m = mo
		p.haveDate = true
		p.skipSpace()
		if p.pos < len(p.s) && isDigit(p.s[p.pos]) {
			n, l, _ := p.readNum()
			if p.pos < len(p.s) && p.s[p.pos] == ':' {
				// time follows; month only
				p.d = 1
				p.y = p.base.Year()
				return p.parseTimeAfterNum(n)
			}
			if l == 4 {
				p.y = n
				p.d = 1
			} else {
				p.d = n
				// ordinal suffix
				sw := p.peekWord()
				if sw == "st" || sw == "nd" || sw == "rd" || sw == "th" {
					p.pos += len(sw)
				}
				p.y = p.base.Year()
				save := p.pos
				p.skipSpace()
				if p.pos < len(p.s) && isDigit(p.s[p.pos]) {
					y, yl, _ := p.readNum()
					if p.pos < len(p.s) && p.s[p.pos] == ':' {
						p.pos = save
					} else if yl == 4 {
						p.y = y
					} else {
						p.pos = save
					}
				} else {
					p.pos = save
				}
			}
		} else {
			p.d = 1
			p.y = p.base.Year()
		}
		return true
	}
	if wd, ok := weekdayMap[w]; ok {
		p.weekdayRel = wd
		p.weekdayDir = 0
		if !p.timeSet {
			p.setTime(0, 0, 0)
		}
		return true
	}
	if n, ok := relWords[w]; ok {
		p.skipSpace()
		next := p.peekWord()
		if next == "day" {
			save := p.pos
			p.pos += len(next)
			p.skipSpace()
			if p.peekWord() == "of" {
				p.pos += 2
				if w == "first" {
					p.firstLastOf = 1
				} else if w == "last" {
					p.firstLastOf = 2
				} else {
					return false
				}
				if !p.timeSet {
					p.setTime(0, 0, 0)
				}
				// followed by "next month" etc or a month name
				return true
			}
			p.pos = save
		}
		if wd, ok := weekdayMap[next]; ok {
			p.pos += len(next)
			p.weekdayRel = wd
			if w == "this" {
				p.weekdayDir = 0
			} else {
				p.weekdayDir = n
			}
			if !p.timeSet {
				p.setTime(0, 0, 0)
			}
			return true
		}
		if u, ok := relUnits[next]; ok && u != "" {
			p.pos += len(next)
			if w == "this" {
				return true
			}
			return p.applyRel(n, next)
		}
		return false
	}
	if u, ok := relUnits[w]; ok && u != "" {
		// bare unit e.g. "week" => +1? PHP: "week" alone invalid? treat as 1
		return p.applyRel(1, w)
	}
	// timezone name
	p.pos -= len(w)
	save := p.pos
	p.parseTZ()
	if p.pos == save {
		return false
	}
	return true
}

func (in *Interp) strtotime(s string, base time.Time) (time.Time, bool) {
	s = strings.TrimSpace(s)
	p := &dateParser{s: s, base: base, loc: base.Location()}
	if s == "" {
		return base, false
	}
	if !p.parse() {
		return base, false
	}
	loc := base.Location()
	if p.tzSet != nil {
		loc = p.tzSet
	} else if p.tzOffset != nil {
		loc = time.FixedZone(tzOffsetName(*p.tzOffset), *p.tzOffset)
	}
	if p.tsSet {
		t := time.Unix(p.ts, int64(p.ns)).In(loc)
		t = t.AddDate(p.relYears, p.relMonths, p.relDays)
		t = t.Add(time.Duration(p.relH)*time.Hour + time.Duration(p.relMi)*time.Minute + time.Duration(p.relS)*time.Second)
		if p.tzSet == nil && p.tzOffset == nil {
			t = t.In(base.Location())
		}
		return t, true
	}
	b := base.In(loc)
	y, m, d := b.Year(), int(b.Month()), b.Day()
	h, mi, sec, ns := b.Hour(), b.Minute(), b.Second(), b.Nanosecond()
	if p.haveDate {
		if p.y != 0 || p.m != 0 {
			y = p.y
			if p.y == 0 {
				y = b.Year()
			}
		}
		if p.m != 0 {
			m = p.m
		}
		if p.d != 0 {
			d = p.d
		}
		if !p.timeSet {
			h, mi, sec, ns = 0, 0, 0, 0
		}
	}
	if p.timeSet {
		h, mi, sec, ns = p.h, p.mi, p.sec, p.ns
	}
	// relative months/years applied first (PHP: y/m/d relative then h/i/s)
	y += p.relYears
	m += p.relMonths
	if p.firstLastOf != 0 {
		// normalize month then set day
		t := time.Date(y, time.Month(m), 1, h, mi, sec, ns, loc)
		if p.firstLastOf == 1 {
			d = 1
		} else {
			d = daysInMonth(t.Year(), int(t.Month()))
		}
		y, m = t.Year(), int(t.Month())
	}
	d += p.relDays
	t := time.Date(y, time.Month(m), d, h, mi, sec, ns, loc)
	if p.weekdayRel >= 0 {
		cur := int(t.Weekday())
		diff := p.weekdayRel - cur
		switch {
		case p.weekdayDir == 0:
			if diff < 0 {
				diff += 7
			}
		case p.weekdayDir > 0:
			if diff <= 0 {
				diff += 7
			}
			diff += 7 * (p.weekdayDir - 1)
		case p.weekdayDir < 0:
			if diff >= 0 {
				diff -= 7
			}
			diff += 7 * (p.weekdayDir + 1)
		}
		t = t.AddDate(0, 0, diff)
	}
	if p.relWeekdays != 0 {
		n := p.relWeekdays
		step := 1
		if n < 0 {
			step = -1
			n = -n
		}
		for n > 0 {
			t = t.AddDate(0, 0, step)
			if t.Weekday() != time.Saturday && t.Weekday() != time.Sunday {
				n--
			}
		}
	}
	t = t.Add(time.Duration(p.relH)*time.Hour + time.Duration(p.relMi)*time.Minute + time.Duration(p.relS)*time.Second)
	if p.tzSet == nil && p.tzOffset == nil {
		return t, true
	}
	return t, true
}

func tzOffsetName(off int) string {
	sign := "+"
	if off < 0 {
		sign = "-"
		off = -off
	}
	return fmt.Sprintf("%s%02d:%02d", sign, off/3600, (off%3600)/60)
}

