func firstChar(s string) byte {
	if s == "" {
		return ' '
	}
	return s[0]
}

func tzType(name string) int {
	if strings.HasPrefix(name, "+") || strings.HasPrefix(name, "-") {
		return 1
	}
	if strings.Contains(name, "/") || name == "UTC" {
		return 3
	}
	return 2
}

func (in *Interp) loadTZ(name string) (*time.Location, bool) {
	if strings.HasPrefix(name, "+") || strings.HasPrefix(name, "-") {
		p := &dateParser{s: name}
		p.parseTZ()
		if p.tzOffset != nil {
			return time.FixedZone(tzOffsetName(*p.tzOffset), *p.tzOffset), false
		}
		return nil, true
	}
	if strings.EqualFold(name, "utc") || strings.EqualFold(name, "z") {
		return time.UTC, false
	}
	l, err := time.LoadLocation(name)
	if err != nil {
		return nil, true
	}
	return l, false
}

