package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

type dateTimeData struct {
	t time.Time
}

type dateIntervalData struct {
	y, m, d, h, i, s int
	f                float64
	invert           bool
	days             int // -1 => false
	hasDays          bool
}

type dateTZData struct {
	loc  *time.Location
	name string
}

func (in *Interp) dtData(o *Object) *dateTimeData {
	if d, ok := o.internal.(*dateTimeData); ok {
		return d
	}
	d := &dateTimeData{t: time.Now().In(in.loc())}
	o.internal = d
	return d
}

func (in *Interp) newDateTime(cls *Class, t time.Time) *Object {
	o := in.newObject(cls)
	o.internal = &dateTimeData{t: t}
	return o
}

func (in *Interp) parseDateTimeString(s string, loc *time.Location, cls string) (time.Time, bool) {
	base := time.Now().In(loc)
	if s == "" || strings.EqualFold(s, "now") {
		return base, true
	}
	t, ok := in.strtotime(s, base)
	if !ok {
		return base, false
	}
	return t, true
}

func (in *Interp) dateIntervalFromSpec(spec string) (*dateIntervalData, bool) {
	// ISO8601 duration PnYnMnDTnHnMnS or PnW
	if len(spec) < 2 || spec[0] != 'P' {
		return nil, false
	}
	d := &dateIntervalData{days: -1}
	s := spec[1:]
	inTime := false
	num := ""
	any := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == 'T' {
			inTime = true
			continue
		}
		if isDigit(c) {
			num += string(c)
			continue
		}
		if num == "" {
			return nil, false
		}
		n, _ := strconv.Atoi(num)
		num = ""
		any = true
		switch {
		case c == 'Y' && !inTime:
			d.y = n
		case c == 'M' && !inTime:
			d.m = n
		case c == 'W' && !inTime:
			d.d += n * 7
		case c == 'D' && !inTime:
			d.d += n
		case c == 'H' && inTime:
			d.h = n
		case c == 'M' && inTime:
			d.i = n
		case c == 'S' && inTime:
			d.s = n
		default:
			return nil, false
		}
	}
	if num != "" || !any {
		return nil, false
	}
	return d, true
}

func (in *Interp) newDateInterval(d *dateIntervalData) *Object {
	o := in.newObject(in.classes["dateinterval"])
	o.internal = d
	in.syncIntervalProps(o)
	return o
}

func (in *Interp) syncIntervalProps(o *Object) {
	d := o.internal.(*dateIntervalData)
	o.props.SetStr("y", int64(d.y))
	o.props.SetStr("m", int64(d.m))
	o.props.SetStr("d", int64(d.d))
	o.props.SetStr("h", int64(d.h))
	o.props.SetStr("i", int64(d.i))
	o.props.SetStr("s", int64(d.s))
	o.props.SetStr("f", d.f)
	if d.invert {
		o.props.SetStr("invert", int64(1))
	} else {
		o.props.SetStr("invert", int64(0))
	}
	if d.hasDays {
		o.props.SetStr("days", int64(d.days))
	} else {
		o.props.SetStr("days", false)
	}
	o.props.SetStr("from_string", false)
}

func (in *Interp) intervalFromProps(o *Object) *dateIntervalData {
	d, ok := o.internal.(*dateIntervalData)
	if !ok {
		d = &dateIntervalData{}
		o.internal = d
	}
	d.y = int(toInt(in.getProp(o, "y")))
	d.m = int(toInt(in.getProp(o, "m")))
	d.d = int(toInt(in.getProp(o, "d")))
	d.h = int(toInt(in.getProp(o, "h")))
	d.i = int(toInt(in.getProp(o, "i")))
	d.s = int(toInt(in.getProp(o, "s")))
	d.f = toFloat(in.getProp(o, "f"))
	d.invert = toBool(in.getProp(o, "invert"))
	return d
}

func applyInterval(t time.Time, d *dateIntervalData, sign int) time.Time {
	if d.invert {
		sign = -sign
	}
	t = t.AddDate(sign*d.y, sign*d.m, sign*d.d)
	t = t.Add(time.Duration(sign) * (time.Duration(d.h)*time.Hour + time.Duration(d.i)*time.Minute + time.Duration(d.s)*time.Second + time.Duration(d.f*1e9)))
	return t
}

func dateDiff(a, b time.Time) *dateIntervalData {
	// compute y/m/d/h/i/s difference like PHP (b - a)
	d := &dateIntervalData{hasDays: true}
	invert := false
	if b.Before(a) {
		a, b = b, a
		invert = true
	}
	// convert b to a's location for component diff
	b = b.In(a.Location())
	y := b.Year() - a.Year()
	m := int(b.Month()) - int(a.Month())
	dd := b.Day() - a.Day()
	h := b.Hour() - a.Hour()
	mi := b.Minute() - a.Minute()
	s := b.Second() - a.Second()
	ns := b.Nanosecond() - a.Nanosecond()
	if ns < 0 {
		ns += 1e9
		s--
	}
	if s < 0 {
		s += 60
		mi--
	}
	if mi < 0 {
		mi += 60
		h--
	}
	if h < 0 {
		h += 24
		dd--
	}
	if dd < 0 {
		// borrow days from previous month of b
		pm := b.Month() - 1
		py := b.Year()
		if pm < 1 {
			pm = 12
			py--
		}
		dim := daysInMonth(py, int(pm))
		if a.Day() > dim {
			dd += a.Day()
		} else {
			dd += dim
		}
		m--
	}
	if m < 0 {
		m += 12
		y--
	}
	d.y, d.m, d.d, d.h, d.i, d.s = y, m, dd, h, mi, s
	d.f = float64(ns) / 1e9
	d.invert = invert
	// total days
	da := time.Date(a.Year(), a.Month(), a.Day(), 0, 0, 0, 0, time.UTC)
	db := time.Date(b.Year(), b.Month(), b.Day(), 0, 0, 0, 0, time.UTC)
	days := int(db.Sub(da).Hours() / 24)
	if b.Hour()*3600+b.Minute()*60+b.Second() < a.Hour()*3600+a.Minute()*60+a.Second() {
		days--
	}
	d.days = days
	return d
}

func formatInterval(d *dateIntervalData, f string) string {
	var sb strings.Builder
	for i := 0; i < len(f); i++ {
		if f[i] != '%' || i+1 >= len(f) {
			sb.WriteByte(f[i])
			continue
		}
		i++
		switch f[i] {
		case 'Y':
			sb.WriteString(fmt.Sprintf("%04d", d.y))
		case 'y':
			sb.WriteString(strconv.Itoa(d.y))
		case 'M':
			sb.WriteString(fmt.Sprintf("%02d", d.m))
		case 'm':
			sb.WriteString(strconv.Itoa(d.m))
		case 'D':
			sb.WriteString(fmt.Sprintf("%02d", d.d))
		case 'd':
			sb.WriteString(strconv.Itoa(d.d))
		case 'H':
			sb.WriteString(fmt.Sprintf("%02d", d.h))
		case 'h':
			sb.WriteString(strconv.Itoa(d.h))
		case 'I':
			sb.WriteString(fmt.Sprintf("%02d", d.i))
		case 'i':
			sb.WriteString(strconv.Itoa(d.i))
		case 'S':
			sb.WriteString(fmt.Sprintf("%02d", d.s))
		case 's':
			sb.WriteString(strconv.Itoa(d.s))
		case 'F':
			sb.WriteString(fmt.Sprintf("%06d", int(d.f*1e6)))
		case 'f':
			sb.WriteString(strconv.Itoa(int(d.f * 1e6)))
		case 'a':
			if d.hasDays {
				sb.WriteString(strconv.Itoa(d.days))
			} else {
				sb.WriteString("(unknown)")
			}
		case 'R':
			if d.invert {
				sb.WriteByte('-')
			} else {
				sb.WriteByte('+')
			}
		case 'r':
			if d.invert {
				sb.WriteByte('-')
			}
		case '%':
			sb.WriteByte('%')
		default:
			sb.WriteByte('%')
			sb.WriteByte(f[i])
		}
	}
	return sb.String()
}

// createFromFormat parses according to PHP's DateTime::createFromFormat format
func (in *Interp) createFromFormat(format, value string, loc *time.Location) (time.Time, bool) {
	now := time.Now().In(loc)
	y, mo, d := now.Year(), int(now.Month()), now.Day()
	h, mi, s, ns := now.Hour(), now.Minute(), now.Second(), 0
	timeSet, dateSet := false, false
	resetAll := false
	pos := 0
	var ts *int64
	var tzLoc *time.Location
	readNum := func(maxLen int) (int, bool) {
		start := pos
		if pos < len(value) && (value[pos] == '-' || value[pos] == '+') && maxLen > 4 {
			pos++
		}
		for pos < len(value) && isDigit(value[pos]) && pos-start < maxLen {
			pos++
		}
		if pos == start {
			return 0, false
		}
		n, err := strconv.Atoi(value[start:pos])
		return n, err == nil
	}
	for i := 0; i < len(format); i++ {
		c := format[i]
		switch c {
		case 'd', 'j':
			n, ok := readNum(2)
			if !ok {
				return now, false
			}
			d = n
			dateSet = true
		case 'm', 'n':
			n, ok := readNum(2)
			if !ok {
				return now, false
			}
			mo = n
			dateSet = true
		case 'Y':
			n, ok := readNum(4)
			if !ok {
				return now, false
			}
			y = n
			dateSet = true
		case 'y':
			n, ok := readNum(2)
			if !ok {
				return now, false
			}
			if n < 70 {
				y = 2000 + n
			} else {
				y = 1900 + n
			}
			dateSet = true
		case 'H', 'G':
			n, ok := readNum(2)
			if !ok {
				return now, false
			}
			h = n
			timeSet = true
		case 'h', 'g':
			n, ok := readNum(2)
			if !ok {
				return now, false
			}
			h = n
			timeSet = true
		case 'i':
			n, ok := readNum(2)
			if !ok {
				return now, false
			}
			mi = n
			timeSet = true
		case 's':
			n, ok := readNum(2)
			if !ok {
				return now, false
			}
			s = n
			timeSet = true
		case 'u', 'v':
			start := pos
			n, ok := readNum(9)
			if !ok {
				return now, false
			}
			l := pos - start
			for l < 9 {
				n *= 10
				l++
			}
			ns = n
			timeSet = true
		case 'A', 'a':
			if pos+2 <= len(value) {
				ap := strings.ToLower(value[pos : pos+2])
				pos += 2
				if ap == "pm" && h < 12 {
					h += 12
				} else if ap == "am" && h == 12 {
					h = 0
				}
			}
		case 'D', 'l':
			for pos < len(value) && ((value[pos] >= 'a' && value[pos] <= 'z') || (value[pos] >= 'A' && value[pos] <= 'Z')) {
				pos++
			}
		case 'M', 'F':
			start := pos
			for pos < len(value) && ((value[pos] >= 'a' && value[pos] <= 'z') || (value[pos] >= 'A' && value[pos] <= 'Z')) {
				pos++
			}
			m2, ok := monthMap[strings.ToLower(value[start:pos])]
			if !ok {
				return now, false
			}
			mo = m2
			dateSet = true
		case 'U':
			n, ok := readNum(20)
			if !ok {
				return now, false
			}
			v := int64(n)
			ts = &v
		case 'e', 'T', 'O', 'P':
			p := &dateParser{s: value, pos: pos}
			p.parseTZ()
			if p.tzSet != nil {
				tzLoc = p.tzSet
			} else if p.tzOffset != nil {
				tzLoc = time.FixedZone(tzOffsetName(*p.tzOffset), *p.tzOffset)
			}
			pos = p.pos
		case '!':
			y, mo, d, h, mi, s, ns = 1970, 1, 1, 0, 0, 0, 0
			resetAll = true
		case '|':
			if !dateSet {
				y, mo, d = 1970, 1, 1
			}
			if !timeSet {
				h, mi, s, ns = 0, 0, 0, 0
			}
			resetAll = true
		case '?':
			pos++
		case '*':
			for pos < len(value) && !(value[pos] == ' ' || value[pos] == ',' || value[pos] == ';' || value[pos] == ':' || value[pos] == '/' || value[pos] == '.' || value[pos] == '-' || value[pos] == '(' || value[pos] == ')') {
				pos++
			}
		case '+':
			pos = len(value)
		case '\\':
			i++
			if i < len(format) && pos < len(value) && value[pos] == format[i] {
				pos++
			}
		case '#':
			if pos < len(value) && strings.IndexByte(";:/.,-()", value[pos]) >= 0 {
				pos++
			} else {
				return now, false
			}
		default:
			if pos < len(value) && value[pos] == c {
				pos++
			} else {
				return now, false
			}
		}
	}
	if pos < len(value) {
		return now, false
	}
	_ = resetAll
	if !resetAll && !timeSet && dateSet {
		// PHP keeps current time when not specified (unless ! or |)
	}
	if tzLoc != nil {
		loc = tzLoc
	}
	if ts != nil {
		return time.Unix(*ts, 0).In(loc), true
	}
	return time.Date(y, time.Month(mo), d, h, mi, s, ns, loc), true
}

func (in *Interp) initDateClasses() {
	tzClass := in.defineClass("DateTimeZone", "", nil, []nativeMethod{
		{name: "__construct", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			name := toStr(args[0])
			loc, err := in.loadTZ(name)
			if err {
				in.throwError("DateInvalidTimeZoneException", fmt.Sprintf("DateTimeZone::__construct(): Unknown or bad timezone (%s)", name))
			}
			this.internal = &dateTZData{loc: loc, name: name}
			return nil
		}},
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value {
			return this.internal.(*dateTZData).name
		}},
		{name: "getOffset", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			dt := args[0].(*Object)
			t := in.dtData(dt).t.In(this.internal.(*dateTZData).loc)
			_, off := t.Zone()
			return int64(off)
		}},
		{name: "listIdentifiers", static: true, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
			return NewListArray([]Value{"UTC", "Europe/London", "Europe/Paris", "Europe/Berlin", "America/New_York", "America/Chicago", "America/Los_Angeles", "Asia/Tokyo", "Australia/Sydney"})
		}},
		{name: "__debugInfo", fn: func(in *Interp, this *Object, args []Value) Value {
			a := NewArray()
			d := this.internal.(*dateTZData)
			a.SetStr("timezone_type", int64(tzType(d.name)))
			a.SetStr("timezone", d.name)
			return a
		}},
	})
	in.addConst(tzClass, "UTC", int64(1024))
	in.addConst(tzClass, "ALL", int64(2047))
	in.addConst(tzClass, "EUROPE", int64(128))
	in.addConst(tzClass, "AMERICA", int64(2))
	in.addConst(tzClass, "ASIA", int64(16))

	dtMethods := func(immutable bool) []nativeMethod {
		// helper: for immutable return clone, else modify in place
		target := func(in *Interp, this *Object) *Object {
			if immutable {
				n := in.newObject(this.class)
				d := in.dtData(this)
				n.internal = &dateTimeData{t: d.t}
				return n
			}
			return this
		}
		className := "DateTime"
		if immutable {
			className = "DateTimeImmutable"
		}
		return []nativeMethod{
			{name: "__construct", max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
				loc := in.loc()
				if len(args) > 1 && args[1] != nil {
					if tz, ok := args[1].(*Object); ok {
						loc = tz.internal.(*dateTZData).loc
					}
				}
				s := "now"
				if len(args) > 0 && args[0] != nil {
					s = toStr(args[0])
				}
				t, ok := in.parseDateTimeString(s, loc, className)
				if !ok {
					in.throwError("DateMalformedStringException", fmt.Sprintf("%s::__construct(): Failed to parse time string (%s) at position 0 (%c): The timezone could not be found in the database", className, s, firstChar(s)))
				}
				this.internal = &dateTimeData{t: t}
				return nil
			}},
			{name: "format", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				return phpDate(toStr(args[0]), in.dtData(this).t)
			}},
			{name: "getTimestamp", fn: func(in *Interp, this *Object, args []Value) Value {
				return in.dtData(this).t.Unix()
			}},
			{name: "setTimestamp", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				d.t = time.Unix(toInt(args[0]), 0).In(d.t.Location())
				return o
			}},
			{name: "getTimezone", fn: func(in *Interp, this *Object, args []Value) Value {
				t := in.dtData(this).t
				tz := in.newObject(in.classes["datetimezone"])
				name := tzName(t)
				if strings.HasPrefix(name, "+") || strings.HasPrefix(name, "-") || name == "" {
					name = tzOffset(t, true)
				}
				tz.internal = &dateTZData{loc: t.Location(), name: name}
				return tz
			}},
			{name: "setTimezone", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				if tz, ok := args[0].(*Object); ok {
					d.t = d.t.In(tz.internal.(*dateTZData).loc)
				}
				return o
			}},
			{name: "getOffset", fn: func(in *Interp, this *Object, args []Value) Value {
				_, off := in.dtData(this).t.Zone()
				return int64(off)
			}},
			{name: "getMicrosecond", fn: func(in *Interp, this *Object, args []Value) Value {
				return int64(in.dtData(this).t.Nanosecond() / 1000)
			}},
			{name: "setMicrosecond", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				t := d.t
				d.t = time.Date(t.Year(), t.Month(), t.Day(), t.Hour(), t.Minute(), t.Second(), int(toInt(args[0]))*1000, t.Location())
				return o
			}},
			{name: "modify", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				s := toStr(args[0])
				t, ok := in.strtotime(s, d.t)
				if !ok {
					in.throwError("DateMalformedStringException", fmt.Sprintf("%s::modify(): Failed to parse time string (%s) at position 0 (%c)", className, s, firstChar(s)))
				}
				d.t = t
				return o
			}},
			{name: "setDate", min: 3, max: 3, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				t := d.t
				d.t = time.Date(int(toInt(args[0])), time.Month(toInt(args[1])), int(toInt(args[2])), t.Hour(), t.Minute(), t.Second(), t.Nanosecond(), t.Location())
				return o
			}},
			{name: "setISODate", min: 2, max: 3, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				t := d.t
				y, w := int(toInt(args[0])), int(toInt(args[1]))
				dow := 1
				if len(args) > 2 {
					dow = int(toInt(args[2]))
				}
				// Jan 4th is always in week 1
				jan4 := time.Date(y, 1, 4, t.Hour(), t.Minute(), t.Second(), t.Nanosecond(), t.Location())
				wd := int(jan4.Weekday())
				if wd == 0 {
					wd = 7
				}
				week1Mon := jan4.AddDate(0, 0, -(wd - 1))
				d.t = week1Mon.AddDate(0, 0, (w-1)*7+(dow-1))
				return o
			}},
			{name: "setTime", min: 2, max: 4, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				t := d.t
				sec := 0
				us := 0
				if len(args) > 2 {
					sec = int(toInt(args[2]))
				}
				if len(args) > 3 {
					us = int(toInt(args[3]))
				}
				d.t = time.Date(t.Year(), t.Month(), t.Day(), int(toInt(args[0])), int(toInt(args[1])), sec, us*1000, t.Location())
				return o
			}},
			{name: "add", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				iv, ok := args[0].(*Object)
				if !ok {
					in.throwError("TypeError", className+"::add(): Argument #1 ($interval) must be of type DateInterval, "+typeName(args[0])+" given")
				}
				d.t = applyInterval(d.t, in.intervalFromProps(iv), 1)
				return o
			}},
			{name: "sub", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := target(in, this)
				d := in.dtData(o)
				iv, ok := args[0].(*Object)
				if !ok {
					in.throwError("TypeError", className+"::sub(): Argument #1 ($interval) must be of type DateInterval, "+typeName(args[0])+" given")
				}
				d.t = applyInterval(d.t, in.intervalFromProps(iv), -1)
				return o
			}},
			{name: "diff", min: 1, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
				other, ok := args[0].(*Object)
				if !ok {
					in.throwError("TypeError", className+"::diff(): Argument #1 ($targetObject) must be of type DateTimeInterface, "+typeName(args[0])+" given")
				}
				d := dateDiff(in.dtData(this).t, in.dtData(other).t)
				if len(args) > 1 && toBool(args[1]) {
					d.invert = false
				}
				return in.newDateInterval(d)
			}},
			{name: "createFromFormat", static: true, min: 2, max: 3, fn: func(in *Interp, this *Object, args []Value) Value {
				loc := in.loc()
				if len(args) > 2 && args[2] != nil {
					if tz, ok := args[2].(*Object); ok {
						loc = tz.internal.(*dateTZData).loc
					}
				}
				t, ok := in.createFromFormat(toStr(args[0]), toStr(args[1]), loc)
				if !ok {
					return false
				}
				cls := in.frame.staticClass
				if cls == nil {
					cls = in.classes[strings.ToLower(className)]
				}
				return in.newDateTime(cls, t)
			}},
			{name: "createFromInterface", static: true, min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := args[0].(*Object)
				return in.newDateTime(in.classes[strings.ToLower(className)], in.dtData(o).t)
			}},
			{name: "createFromMutable", static: true, min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := args[0].(*Object)
				return in.newDateTime(in.classes[strings.ToLower(className)], in.dtData(o).t)
			}},
			{name: "createFromImmutable", static: true, min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				o := args[0].(*Object)
				return in.newDateTime(in.classes[strings.ToLower(className)], in.dtData(o).t)
			}},
			{name: "createFromTimestamp", static: true, min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				f := toFloat(args[0])
				sec := int64(f)
				ns := int64((f - float64(sec)) * 1e9)
				return in.newDateTime(in.classes[strings.ToLower(className)], time.Unix(sec, ns).In(time.FixedZone("+00:00", 0)))
			}},
			{name: "getLastErrors", static: true, fn: func(in *Interp, this *Object, args []Value) Value { return false }},
			{name: "__debugInfo", fn: func(in *Interp, this *Object, args []Value) Value {
				return in.dateTimeDebug(this)
			}},
			{name: "__serialize", fn: func(in *Interp, this *Object, args []Value) Value {
				return in.dateTimeDebug(this)
			}},
			{name: "__wakeup", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
			{name: "__set_state", static: true, min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
				arr := args[0].(*Array)
				ds, _ := arr.GetStr("date")
				tzs, _ := arr.GetStr("timezone")
				loc, _ := in.loadTZ(toStr(tzs))
				t, _ := in.parseDateTimeString(toStr(ds), loc, className)
				return in.newDateTime(in.classes[strings.ToLower(className)], t)
			}},
		}
	}
	dt := in.defineClass("DateTime", "", []string{"DateTimeInterface"}, dtMethods(false))
	dt.internalInit = func(in *Interp, o *Object) { o.internal = &dateTimeData{t: time.Now().In(in.loc())} }
	dti := in.defineClass("DateTimeImmutable", "", []string{"DateTimeInterface"}, dtMethods(true))
	dti.internalInit = dt.internalInit
	for _, c := range []*Class{dt, dti, in.classes["datetimeinterface"]} {
		in.addConst(c, "ATOM", "Y-m-d\\TH:i:sP")
		in.addConst(c, "COOKIE", "l, d-M-Y H:i:s T")
		in.addConst(c, "ISO8601", "Y-m-d\\TH:i:sO")
		in.addConst(c, "ISO8601_EXPANDED", "X-m-d\\TH:i:sP")
		in.addConst(c, "RFC822", "D, d M y H:i:s O")
		in.addConst(c, "RFC850", "l, d-M-y H:i:s T")
		in.addConst(c, "RFC1036", "D, d M y H:i:s O")
		in.addConst(c, "RFC1123", "D, d M Y H:i:s O")
		in.addConst(c, "RFC7231", "D, d M Y H:i:s \\G\\M\\T")
		in.addConst(c, "RFC2822", "D, d M Y H:i:s O")
		in.addConst(c, "RFC3339", "Y-m-d\\TH:i:sP")
		in.addConst(c, "RFC3339_EXTENDED", "Y-m-d\\TH:i:s.vP")
		in.addConst(c, "RSS", "D, d M Y H:i:s O")
		in.addConst(c, "W3C", "Y-m-d\\TH:i:sP")
	}
	// DateInterval
	di := in.defineClass("DateInterval", "", nil, []nativeMethod{
		{name: "__construct", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			spec := toStr(args[0])
			d, ok := in.dateIntervalFromSpec(spec)
			if !ok {
				in.throwError("DateMalformedIntervalStringException", fmt.Sprintf("DateInterval::__construct(): Unknown or bad format (%s)", spec))
			}
			this.internal = d
			in.syncIntervalProps(this)
			return nil
		}},
		{name: "format", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.intervalFromProps(this)
			if dd, ok := this.internal.(*dateIntervalData); ok {
				d.days = dd.days
				d.hasDays = dd.hasDays
			}
			return formatInterval(d, toStr(args[0]))
		}},
		{name: "createFromDateString", static: true, min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			s := toStr(args[0])
			p := &dateParser{s: s, base: time.Now(), loc: time.UTC}
			p.weekdayRel = -1
			if !p.parse() {
				in.warn(fmt.Sprintf("DateInterval::createFromDateString(): Unknown or bad format (%s) at position 0 (%c): The timezone could not be found in the database", s, firstChar(s)))
				return false
			}
			d := &dateIntervalData{y: p.relYears, m: p.relMonths, d: p.relDays, h: p.relH, i: p.relMi, s: p.relS}
			o := in.newDateInterval(d)
			o.props.SetStr("from_string", true)
			o.props.Delete(StrKey("days"))
			o.props.SetStr("days", false)
			return o
		}},
		{name: "__debugInfo", fn: func(in *Interp, this *Object, args []Value) Value {
			return this.props.Clone()
		}},
	})
	di.autoProps = true
	di.Decl.AllowDynamic = true
	di.internalInit = func(in *Interp, o *Object) {
		o.internal = &dateIntervalData{}
	}
	// DatePeriod
	dp := in.defineClass("DatePeriod", "", []string{"IteratorAggregate"}, []nativeMethod{
		{name: "__construct", min: 1, max: 4, fn: func(in *Interp, this *Object, args []Value) Value {
			start, _ := args[0].(*Object)
			if start == nil {
				in.throwError("Error", "DatePeriod::__construct() ISO interval strings not supported")
			}
			iv, _ := args[1].(*Object)
			this.props.SetStr("start", start)
			this.props.SetStr("interval", iv)
			this.props.SetStr("include_start_date", true)
			this.props.SetStr("include_end_date", false)
			opts := int64(0)
			if len(args) > 3 {
				opts = toInt(args[3])
			}
			if len(args) > 2 {
				if end, ok := args[2].(*Object); ok {
					this.props.SetStr("end", end)
					this.props.SetStr("recurrences", nil)
				} else {
					this.props.SetStr("end", nil)
					this.props.SetStr("recurrences", toInt(args[2]))
				}
			}
			if opts&1 != 0 {
				this.props.SetStr("include_start_date", false)
			}
			if opts&2 != 0 {
				this.props.SetStr("include_end_date", true)
			}
			return nil
		}},
		{name: "getIterator", fn: func(in *Interp, this *Object, args []Value) Value {
			start := in.getProp(this, "start").(*Object)
			iv := in.getProp(this, "interval").(*Object)
			d := in.intervalFromProps(iv)
			arr := NewArray()
			t := in.dtData(start).t
			includeStart := toBool(in.getProp(this, "include_start_date"))
			includeEnd := toBool(in.getProp(this, "include_end_date"))
			if end, ok := in.getProp(this, "end").(*Object); ok {
				et := in.dtData(end).t
				cur := t
				first := true
				for cur.Before(et) || (includeEnd && cur.Equal(et)) {
					if !first || includeStart {
						arr.Append(in.newDateTime(start.class, cur))
					}
					first = false
					cur = applyInterval(cur, d, 1)
				}
			} else {
				n := int(toInt(in.getProp(this, "recurrences")))
				cur := t
				if includeStart {
					arr.Append(in.newDateTime(start.class, cur))
				}
				for i := 0; i < n; i++ {
					cur = applyInterval(cur, d, 1)
					arr.Append(in.newDateTime(start.class, cur))
				}
			}
			it := in.newObject(in.classes["arrayiterator"])
			arr.rc++
			it.internal = arr
			return it
		}},
		{name: "getStartDate", fn: func(in *Interp, this *Object, args []Value) Value { return in.getProp(this, "start") }},
		{name: "getEndDate", fn: func(in *Interp, this *Object, args []Value) Value { return in.getProp(this, "end") }},
		{name: "getDateInterval", fn: func(in *Interp, this *Object, args []Value) Value { return in.getProp(this, "interval") }},
		{name: "getRecurrences", fn: func(in *Interp, this *Object, args []Value) Value { return in.getProp(this, "recurrences") }},
	})
	in.addConst(dp, "EXCLUDE_START_DATE", int64(1))
	in.addConst(dp, "INCLUDE_END_DATE", int64(2))
	dp.autoProps = true

	// procedural aliases
	in.reg("date_create", 0, 2, func(in *Interp, args []Value) Value {
		loc := in.loc()
		if len(args) > 1 && args[1] != nil {
			if tz, ok := args[1].(*Object); ok {
				loc = tz.internal.(*dateTZData).loc
			}
		}
		s := "now"
		if len(args) > 0 && args[0] != nil {
			s = toStr(args[0])
		}
		t, ok := in.parseDateTimeString(s, loc, "DateTime")
		if !ok {
			return false
		}
		return in.newDateTime(in.classes["datetime"], t)
	})
	in.reg("date_create_immutable", 0, 2, func(in *Interp, args []Value) Value {
		loc := in.loc()
		if len(args) > 1 && args[1] != nil {
			if tz, ok := args[1].(*Object); ok {
				loc = tz.internal.(*dateTZData).loc
			}
		}
		s := "now"
		if len(args) > 0 && args[0] != nil {
			s = toStr(args[0])
		}
		t, ok := in.parseDateTimeString(s, loc, "DateTimeImmutable")
		if !ok {
			return false
		}
		return in.newDateTime(in.classes["datetimeimmutable"], t)
	})
	in.reg("date_format", 2, 2, func(in *Interp, args []Value) Value {
		return phpDate(toStr(args[1]), in.dtData(args[0].(*Object)).t)
	})
	in.reg("date_diff", 2, 3, func(in *Interp, args []Value) Value {
		return in.newDateInterval(dateDiff(in.dtData(args[0].(*Object)).t, in.dtData(args[1].(*Object)).t))
	})
	in.reg("date_add", 2, 2, func(in *Interp, args []Value) Value {
		o := args[0].(*Object)
		d := in.dtData(o)
		d.t = applyInterval(d.t, in.intervalFromProps(args[1].(*Object)), 1)
		return o
	})
	in.reg("date_sub", 2, 2, func(in *Interp, args []Value) Value {
		o := args[0].(*Object)
		d := in.dtData(o)
		d.t = applyInterval(d.t, in.intervalFromProps(args[1].(*Object)), -1)
		return o
	})
	in.reg("date_modify", 2, 2, func(in *Interp, args []Value) Value {
		o := args[0].(*Object)
		d := in.dtData(o)
		t, ok := in.strtotime(toStr(args[1]), d.t)
		if !ok {
			return false
		}
		d.t = t
		return o
	})
	in.reg("date_timestamp_get", 1, 1, func(in *Interp, args []Value) Value {
		return in.dtData(args[0].(*Object)).t.Unix()
	})
	in.reg("date_interval_format", 2, 2, func(in *Interp, args []Value) Value {
		return formatInterval(in.intervalFromProps(args[0].(*Object)), toStr(args[1]))
	})
	in.reg("timezone_open", 1, 1, func(in *Interp, args []Value) Value {
		name := toStr(args[0])
		loc, err := in.loadTZ(name)
		if err {
			in.warn(fmt.Sprintf("timezone_open(): Unknown or bad timezone (%s)", name))
			return false
		}
		o := in.newObject(in.classes["datetimezone"])
		o.internal = &dateTZData{loc: loc, name: name}
		return o
	})
	in.reg("date_create_from_format", 2, 3, func(in *Interp, args []Value) Value {
		loc := in.loc()
		if len(args) > 2 && args[2] != nil {
			if tz, ok := args[2].(*Object); ok {
				loc = tz.internal.(*dateTZData).loc
			}
		}
		t, ok := in.createFromFormat(toStr(args[0]), toStr(args[1]), loc)
		if !ok {
			return false
		}
		return in.newDateTime(in.classes["datetime"], t)
	})
}

func firstChar(s string) byte {
	if s == "" {
		return ' '
	}
	return s[0]
}

func tzType(name string) int {
	if strings.HasPrefix(name, "+") || strings.HasPrefix(name, "-") {
		return 1
	}
	if strings.Contains(name, "/") || name == "UTC" {
		return 3
	}
	return 2
}

func (in *Interp) loadTZ(name string) (*time.Location, bool) {
	if strings.HasPrefix(name, "+") || strings.HasPrefix(name, "-") {
		p := &dateParser{s: name}
		p.parseTZ()
		if p.tzOffset != nil {
