// pseudo-bcrypt: $2y$cost$ + 22 char salt + 31 char hash (sha256 based, not real bcrypt)
const bcAlphabet = "./ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

func bcEncode(b []byte) string {
	enc := base64.NewEncoding(bcAlphabet).WithPadding(base64.NoPadding)
	return enc.EncodeToString(b)
}

func pseudoBcrypt(pass string, cost int, salt string) string {
	h := sha256.Sum256([]byte(salt + pass))
	for i := 0; i < 1<<uint(min(cost, 14)); i++ {
		h = sha256.Sum256(append(h[:], []byte(pass)...))
	}
	return fmt.Sprintf("$2y$%02d$%s%s", cost, salt, bcEncode(h[:])[:31])
}

func bcryptGenerate(pass string, cost int) (string, error) {
	if cost < 4 || cost > 31 {
		return "", fmt.Errorf("bad cost")
	}
	raw := make([]byte, 16)
	rand.Read(raw)
	salt := bcEncode(raw)[:22]
	return pseudoBcrypt(pass, cost, salt), nil
}

func bcryptCost(h string) (int, error) {
	if len(h) < 7 || !strings.HasPrefix(h, "$2") {
		return 0, fmt.Errorf("bad hash")
	}
	var c int
	_, err := fmt.Sscanf(h[4:6], "%d", &c)
	return c, err
}

func bcryptCompare(h string, pass string) bool {
	cost, err := bcryptCost(h)
	if err != nil || len(h) != 60 {
		return false
