		{name: "getSubIterator", max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*riiState)
			d := len(st.stack) - 1
			if len(args) > 0 && args[0] != nil {
				d = int(toInt(args[0]))
			}
			if d < 0 || d >= len(st.stack) {
				return nil
			}
			return st.stack[d]
		}},
		{name: "setMaxDepth", max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			d := int64(-1)
			if len(args) > 0 {
				d = toInt(args[0])
			}
			this.props.SetRaw(StrKey("\x00maxDepth"), d)
			return nil
		}},
		{name: "getMaxDepth", fn: func(in *Interp, this *Object, args []Value) Value {
			d, _ := this.props.Get(StrKey("\x00maxDepth"))
			if toInt(d) < 0 {
				return false
			}
			return d
		}},
		{name: "callHasChildren", fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*riiState)
			return in.callMethodByName(st.stack[len(st.stack)-1], "hasChildren", nil)
		}},
		{name: "callGetChildren", fn: func(in *Interp, this *Object, args []Value) Value {
			st := this.internal.(*riiState)
			return in.callMethodByName(st.stack[len(st.stack)-1], "getChildren", nil)
		}},
		{name: "beginChildren", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
		{name: "endChildren", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
		{name: "beginIteration", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
		{name: "endIteration", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
		{name: "nextElement", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
	})
	in.addConst(rii, "LEAVES_ONLY", int64(0))
	in.addConst(rii, "SELF_FIRST", int64(1))
	in.addConst(rii, "CHILD_FIRST", int64(2))
	in.addConst(rii, "CATCH_GET_CHILD", int64(16))
	rii.internalInit = func(in *Interp, o *Object) { o.internal = &riiState{} }
	in.defineClass("EmptyIterator", "", []string{"Iterator"}, []nativeMethod{
		{name: "current", fn: func(in *Interp, this *Object, args []Value) Value {
			in.throwError("BadMethodCallException", "Accessing the value of an EmptyIterator")
			return nil
		}},
		{name: "key", fn: func(in *Interp, this *Object, args []Value) Value {
			in.throwError("BadMethodCallException", "Accessing the key of an EmptyIterator")
			return nil
		}},
		{name: "next", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
		{name: "rewind", fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
		{name: "valid", fn: func(in *Interp, this *Object, args []Value) Value { return false }},
	})
	in.defineClass("RegexIterator", "FilterIterator", nil, []nativeMethod{
		{name: "__construct", min: 2, max: 5, fn: func(in *Interp, this *Object, args []Value) Value {
			setInner(in, this, args[0])
			this.props.SetRaw(StrKey("\x00re"), args[1])
			return nil
		}},
