			r := in.callValue("preg_match", []Value{re, in.toStr(cur)})
			return toInt(r) > 0
		}},
	})
	in.defineClass("ArrayAccess_", "", nil, nil)
	delete(in.classes, "arrayaccess_")
}

type riiState struct {
	stack []*Object
	valid bool
	pendingSelf bool
	visitedSelf map[*Object]bool
}

func (in *Interp) riiRewind(this *Object) {
	st := this.internal.(*riiState)
	root, _ := this.props.Get(StrKey("\x00root"))
	st.stack = []*Object{root.(*Object)}
	st.visitedSelf = map[*Object]bool{}
	in.callMethodByName(root.(*Object), "rewind", nil)
	in.callMethodByName(this, "beginIteration", nil)
	in.riiSettle(this, false)
}

// riiSettle positions the iterator on the next valid element according to mode
func (in *Interp) riiSettle(this *Object, advanced bool) {
	st := this.internal.(*riiState)
	modeV, _ := this.props.Get(StrKey("\x00mode"))
	mode := toInt(modeV)
	maxDV, _ := this.props.Get(StrKey("\x00maxDepth"))
	maxD := toInt(maxDV)
	for {
		if len(st.stack) == 0 {
			st.valid = false
			in.callMethodByName(this, "endIteration", nil)
			return
		}
		top := st.stack[len(st.stack)-1]
		if !toBool(in.callMethodByName(top, "valid", nil)) {
			// pop
			if len(st.stack) == 1 {
				st.valid = false
				in.callMethodByName(this, "endIteration", nil)
				return
			}
			st.stack = st.stack[:len(st.stack)-1]
			in.callMethodByName(this, "endChildren", nil)
			parent := st.stack[len(st.stack)-1]
			if mode == 2 {
				// CHILD_FIRST: now yield the parent element itself
				st.valid = true
				st.pendingSelf = true
				return
			}
			in.callMethodByName(parent, "next", nil)
			continue
		}
		hasChildren := toBool(in.callMethodByName(this, "callHasChildren", nil)) && (maxD < 0 || int64(len(st.stack)-1) < maxD)
		if hasChildren {
			if mode == 1 && !st.visitedSelf[top] {
				// SELF_FIRST: yield parent first
				st.visitedSelf[top] = true
				st.valid = true
				return
			}
			if mode == 2 && st.pendingSelf {
				st.pendingSelf = false
				st.valid = true
				return
			}
			delete(st.visitedSelf, top)
			child := in.callMethodByName(this, "callGetChildren", nil).(*Object)
			in.callMethodByName(child, "rewind", nil)
			st.stack = append(st.stack, child)
			in.callMethodByName(this, "beginChildren", nil)
			continue
		}
		st.valid = true
		in.callMethodByName(this, "nextElement", nil)
		return
	}
}

func (in *Interp) riiNext(this *Object) {
	st := this.internal.(*riiState)
	if len(st.stack) == 0 {
		return
	}
	modeV, _ := this.props.Get(StrKey("\x00mode"))
	mode := toInt(modeV)
	top := st.stack[len(st.stack)-1]
	if mode == 1 && st.visitedSelf[top] {
		// descend into children now
		in.riiSettle(this, true)
		return
	}
	if mode == 2 && st.pendingSelf {
		st.pendingSelf = false
		in.callMethodByName(top, "next", nil)
		in.riiSettle(this, true)
		return
	}
	in.callMethodByName(top, "next", nil)
	in.riiSettle(this, true)
}

func (in *Interp) appendSkip(this *Object) {
	its, _ := this.props.Get(StrKey("\x00its"))
	arr := its.(*Array)
	for {
		idx, _ := this.props.Get(StrKey("\x00idx"))
		cur, ok := arr.Get(IntKey(toInt(idx)))
		if !ok {
			return
		}
		if toBool(in.callMethodByName(cur.(*Object), "valid", nil)) {
			return
		}
		next := toInt(idx) + 1
		this.props.SetRaw(StrKey("\x00idx"), next)
		nxt, ok := arr.Get(IntKey(next))
		if !ok {
			return
		}
		in.callMethodByName(nxt.(*Object), "rewind", nil)
	}
}

func (in *Interp) cachingFetch(this *Object) {
	v, _ := this.props.Get(StrKey("\x00inner"))
	inner := v.(*Object)
	if toBool(in.callMethodByName(inner, "valid", nil)) {
		this.props.SetRaw(StrKey("\x00cur"), in.callMethodByName(inner, "current", nil))
		this.props.SetRaw(StrKey("\x00key"), in.callMethodByName(inner, "key", nil))
		this.props.SetRaw(StrKey("\x00hasCur"), true)
		in.callMethodByName(inner, "next", nil)
	} else {
		this.props.SetRaw(StrKey("\x00hasCur"), false)
	}
}
