package main

import (
	"fmt"
)

// evalInclude handles include/require
func (in *Interp) evalInclude(fr *Frame, x *IncludeExpr) Value {
	pathV := in.eval(fr, x.E)
	path := in.toStr(pathV)
	once := x.Kind == "include_once" || x.Kind == "require_once"
	isRequire := x.Kind == "require" || x.Kind == "require_once"
	resolved := in.resolveIncludePath(path, fr.file)
	if resolved == "" {
		if isRequire {
			in.warn(fmt.Sprintf("%s(%s): Failed to open stream: No such file or directory", x.Kind, path))
			in.fatal(fmt.Sprintf("Uncaught Error: Failed opening required '%s' (include_path='%s')", path, in.ini["include_path"]))
		}
		in.warn(fmt.Sprintf("%s(%s): Failed to open stream: No such file or directory", x.Kind, path))
		in.warn(fmt.Sprintf("%s(): Failed opening '%s' for inclusion (include_path='%s')", x.Kind, path, in.ini["include_path"]))
		return false
	}
	if once && in.included[resolved] {
		return true
	}
	in.included[resolved] = true
	data, err := readFileBytes(resolved)
	if err != nil {
		return false
	}
	toks, lerr := Lex(string(data), resolved)
	if lerr != nil {
		le := lerr.(*LexError)
		panic(&FatalSignal{msg: le.Msg, file: resolved, line: le.Line})
	}
	stmts, perr := Parse(toks, resolved)
	if perr != nil {
		pe := perr.(*ParseError)
		in.raiseErrorAt(E_PARSE, pe.Msg, resolved, pe.Line)
		panic(&ExitSignal{code: 255})
	}
	in.includeStack = append(in.includeStack, resolved)
	// execute in the current scope but with the included file name
	nfr := &Frame{vars: fr.vars, this: fr.this, class: fr.class, staticClass: fr.staticClass, fn: fr.fn, args: fr.args, file: resolved, caller: fr, callLine: fr.line, depth: in.depth, funcName: x.Kind, isInclude: true, gen: fr.gen, closure: fr.closure}
	prev := in.frame
	in.frame = nfr
	in.traceStack = append(in.traceStack, nfr)
	defer func() {
		in.frame = prev
		in.traceStack = in.traceStack[:len(in.traceStack)-1]
	}()
	in.hoistDecls(stmts, nfr)
	c := in.execStmts(nfr, stmts)
	if c == cReturn {
		return nfr.retVal
	}
	return int64(1)
}

func (in *Interp) resolveIncludePath(path string, curFile string) string {
	if path == "" {
		return ""
	}
	cands := []string{}
	if path[0] == '/' {
		cands = append(cands, path)
	} else if len(path) > 1 && (path[:2] == "./" || path[:3] == "../") {
		cands = append(cands, in.resolvePath(path))
	} else {
		cands = append(cands, in.resolvePath(path))
		cands = append(cands, dirOf(curFile)+"/"+path)
	}
	for _, c := range cands {
		if fileExists(c) {
			return c
		}
	}
	return ""
}

func (in *Interp) initIteratorClasses() {
