{"command":"cd /workspace/src && cat > reflection.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

type reflData struct {
	cls    *Class
	method *Method
	fn     *Function
	prop   *PropInfo
	propName string
	param  *Param
	paramIdx int
	th     *TypeHint
	typeName string
	closure *Object
	enumCase *Object
	constName string
}

func (in *Interp) rd(o *Object) *reflData {
	d, ok := o.internal.(*reflData)
	if !ok {
		d = &reflData{}
		o.internal = d
	}
	return d
}

func (in *Interp) newReflType(th *TypeHint) Value {
	if th == nil {
		return nil
	}
	o := in.newObject(in.classes["reflectionnamedtype"])
	if len(th.Names) > 1 || (len(th.Names) == 1 && th.Nullable && th.Names[0] == "null") {
		nonNull := 0
		for _, n := range th.Names {
			if n != "null" {
				nonNull++
			}
		}
		if nonNull > 1 {
			if th.Intersection {
				o = in.newObject(in.classes["reflectionintersectiontype"])
			} else {
				o = in.newObject(in.classes["reflectionuniontype"])
			}
		}
	}
	o.internal = &reflData{th: th}
	return o
}

func (in *Interp) newReflParam(fn *Function, p *Param, idx int, cls *Class) *Object {
	o := in.newObject(in.classes["reflectionparameter"])
	o.internal = &reflData{fn: fn, param: p, paramIdx: idx, cls: cls}
	o.props.SetStr("name", p.Name)
	return o
}

func (in *Interp) reflParams(fn *Function, cls *Class) *Array {
	arr := NewArray()
	if fn.Decl != nil {
		for i, p := range fn.Decl.Params {
			arr.Append(in.newReflParam(fn, p, i, cls))
		}
	} else {
		for i, n := range fn.ParamNames {
			p := &Param{Name: n}
			if i >= fn.MinArgs {
				p.Default = &NullLit{}
			}
			arr.Append(in.newReflParam(fn, p, i, cls))
		}
	}
	return arr
}

func (in *Interp) newReflMethod(m *Method, cls *Class) *Object {
	o := in.newObject(in.classes["reflectionmethod"])
	o.internal = &reflData{method: m, fn: m.Fn, cls: cls}
	o.props.SetStr("name", m.Name)
	o.props.SetStr("class", m.Class.Name)
	return o
}

func (in *Interp) newReflProp(pi *PropInfo, name string, cls *Class) *Object {
	o := in.newObject(in.classes["reflectionproperty"])
	o.internal = &reflData{prop: pi, propName: name, cls: cls}
	o.props.SetStr("name", name)
	if pi != nil {
		o.props.SetStr("class", pi.Class.Name)
	} else {
		o.props.SetStr("class", cls.Name)
	}
	return o
}

func (in *Interp) newReflClass(cls *Class) *Object {
	c := in.classes["reflectionclass"]
	if cls.isEnum() {
		c = in.classes["reflectionenum"]
	}
	o := in.newObject(c)
	o.internal = &reflData{cls: cls}
	o.props.SetStr("name", cls.Name)
	return o
}

func (in *Interp) reflClassArg(v Value, fname string) *Class {
	switch x := v.(type) {
	case *Object:
		return x.class
	case string:
		c := in.lookupClass(x)
		if c == nil {
			in.throwError("ReflectionException", fmt.Sprintf("Class \"%s\" does not exist", x))
		}
		return c
	}
	in.throwError("ReflectionException", fmt.Sprintf("Class \"%s\" does not exist", toStr(v)))
	return nil
}

func (in *Interp) initReflectionClasses() {
	in.defineClass("ReflectionException", "Exception", nil, nil)
	in.defineInterface("Reflector", []string{"Stringable"}, nil)
	modifierNames := func(vis string, static, abstract, final bool) int64 {
		m := int64(0)
		switch vis {
		case "public":
			m |= 1
		case "protected":
			m |= 2
		case "private":
			m |= 4
		}
		if static {
			m |= 16
		}
		if final {
			m |= 32
		}
		if abstract {
			m |= 64
		}
		return m
	}
	// ReflectionNamedType
	in.defineClass("ReflectionType", "", []string{"Stringable"}, []nativeMethod{
		{name: "allowsNull", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			if th.Nullable {
				return true
			}
			for _, n := range th.Names {
				if n == "null" || n == "mixed" {
					return true
				}
			}
			return false
		}},
		{name: "__toString", fn: func(in *Interp, this *Object, args []Value) Value {
			return in.typeHintString(in.rd(this).th)
		}},
	})
	in.defineClass("ReflectionNamedType", "ReflectionType", nil, []nativeMethod{
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			for _, n := range th.Names {
				if n != "null" {
					return in.displayTypeName(n)
				}
			}
			return "null"
		}},
		{name: "isBuiltin", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			for _, n := range th.Names {
				if n == "null" {
					continue
				}
				switch n {
				case "int", "float", "string", "bool", "array", "callable", "iterable", "object", "mixed", "void", "never", "false", "true":
					return true
				}
				return false
			}
			return true
		}},
	})
	in.defineClass("ReflectionUnionType", "ReflectionType", nil, []nativeMethod{
		{name: "getTypes", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			arr := NewArray()
			for _, n := range th.Names {
				arr.Append(in.newReflType(&TypeHint{Names: []string{n}}))
			}
			return arr
		}},
	})
	in.defineClass("ReflectionIntersectionType", "ReflectionType", nil, []nativeMethod{
		{name: "getTypes", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			arr := NewArray()
			for _, n := range th.Names {
				arr.Append(in.newReflType(&TypeHint{Names: []string{n}}))
			}
			return arr
		}},
	})
	// ReflectionParameter
	in.defineClass("ReflectionParameter", "", []string{"Reflector"}, []nativeMethod{
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Name }},
		{name: "getPosition", fn: func(in *Interp, this *Object, args []Value) Value { return int64(in.rd(this).paramIdx) }},
		{name: "getType", fn: func(in *Interp, this *Object, args []Value) Value { return in.newReflType(in.rd(this).param.Type) }},
		{name: "hasType", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Type != nil }},
		{name: "isOptional", fn: func(in *Interp, this *Object, args []Value) Value {
			p := in.rd(this).param
			return p.Default != nil || p.Variadic
		}},
		{name: "isDefaultValueAvailable", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Default != nil }},
		{name: "getDefaultValue", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.param.Default == nil {
				in.throwError("ReflectionException", "Internal error: Failed to retrieve the default value")
			}
			fr := &Frame{vars: map[string]*Ref{}, class: d.cls, staticClass: d.cls, file: in.curFile(), line: in.curLine()}
			return in.eval(fr, d.param.Default)
		}},
		{name: "isVariadic", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Variadic }},
		{name: "isPassedByReference", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.ByRef }},
		{name: "allowsNull", fn: func(in *Interp, this *Object, args []Value) Value {
			p := in.rd(this).param
			if p.Type == nil {
				return true
			}
			if p.Type.Nullable {
				return true
			}
			for _, n := range p.Type.Names {
				if n == "null" || n == "mixed" {
					return true
				}
			}
			return false
		}},
		{name: "isPromoted", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Promote != "" }},
		{name: "getDeclaringFunction", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Method != nil {
				return in.newReflMethod(d.fn.Method, d.cls)
			}
			o := in.newObject(in.classes["reflectionfunction"])
			o.internal = &reflData{fn: d.fn}
			o.props.SetStr("name", d.fn.Name)
			return o
		}},
		{name: "getAttributes", max: 2, fn: func(in *Interp, this *Object, args []Value) Value { return NewArray() }},
		{name: "__toString", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			opt := "required"
			if d.param.Default != nil || d.param.Variadic {
				opt = "optional"
			}
			ts := ""
			if d.param.Type != nil {
				ts = in.typeHintString(d.param.Type) + " "
			}
			return fmt.Sprintf("Parameter #%d [ <%s> %s$%s ]", d.paramIdx, opt, ts, d.param.Name)
		}},
	})
	// ReflectionFunctionAbstract / ReflectionFunction
	fnMethods := []nativeMethod{
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl != nil && d.fn.Decl.Name == "{closure}" {
				return "{closure}"
			}
			return d.fn.Name
		}},
		{name: "getShortName", fn: func(in *Interp, this *Object, args []Value) Value {
			n := in.rd(this).fn.Name
			if i := strings.LastIndexByte(n, '\\'); i >= 0 {
				return n[i+1:]
			}
			return n
		}},
		{name: "getParameters", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			return in.reflParams(d.fn, d.cls)
		}},
		{name: "getNumberOfParameters", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl != nil {
				return int64(len(d.fn.Decl.Params))
			}
			if d.fn.MaxArgs >= 0 {
				return int64(d.fn.MaxArgs)
			}
			return int64(len(d.fn.ParamNames))
		}},
		{name: "getNumberOfRequiredParameters", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl != nil {
				n := 0
				for _, p := range d.fn.Decl.Params {
					if p.Default == nil && !p.Variadic {
						n++
					}
				}
				return int64(n)
			}
			return int64(d.fn.MinArgs)
		}},
		{name: "getReturnType", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl == nil {
				return nil
			}
			return in.newReflType(d.fn.Decl.ReturnType)
		}},
		{name: "hasReturnType", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			return d.fn.Decl != nil && d.fn.Decl.ReturnType != nil
		}},
		{name: "isVariadic", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl == nil {
				return d.fn.MaxArgs < 0
			}
			for _, p := range d.fn.Decl.Params {
				if p.Variadic {
					return true
				}
			}
			return false
		}},
		{name: "isStatic", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.method != nil {
