package main

import (
	"fmt"
	"strings"
)

type reflData struct {
	cls    *Class
	method *Method
	fn     *Function
	prop   *PropInfo
	propName string
	param  *Param
	paramIdx int
	th     *TypeHint
	typeName string
	closure *Object
	enumCase *Object
	constName string
}

func (in *Interp) rd(o *Object) *reflData {
	d, ok := o.internal.(*reflData)
	if !ok {
		d = &reflData{}
		o.internal = d
	}
	return d
}

func (in *Interp) newReflType(th *TypeHint) Value {
	if th == nil {
		return nil
	}
	o := in.newObject(in.classes["reflectionnamedtype"])
	if len(th.Names) > 1 || (len(th.Names) == 1 && th.Nullable && th.Names[0] == "null") {
		nonNull := 0
		for _, n := range th.Names {
			if n != "null" {
				nonNull++
			}
		}
		if nonNull > 1 {
			if th.Intersection {
				o = in.newObject(in.classes["reflectionintersectiontype"])
			} else {
				o = in.newObject(in.classes["reflectionuniontype"])
			}
		}
	}
	o.internal = &reflData{th: th}
	return o
}

func (in *Interp) newReflParam(fn *Function, p *Param, idx int, cls *Class) *Object {
	o := in.newObject(in.classes["reflectionparameter"])
	o.internal = &reflData{fn: fn, param: p, paramIdx: idx, cls: cls}
	o.props.SetStr("name", p.Name)
	return o
}

func (in *Interp) reflParams(fn *Function, cls *Class) *Array {
	arr := NewArray()
	if fn.Decl != nil {
		for i, p := range fn.Decl.Params {
			arr.Append(in.newReflParam(fn, p, i, cls))
		}
	} else {
		for i, n := range fn.ParamNames {
			p := &Param{Name: n}
			if i >= fn.MinArgs {
				p.Default = &NullLit{}
			}
			arr.Append(in.newReflParam(fn, p, i, cls))
		}
	}
	return arr
}

func (in *Interp) newReflMethod(m *Method, cls *Class) *Object {
	o := in.newObject(in.classes["reflectionmethod"])
	o.internal = &reflData{method: m, fn: m.Fn, cls: cls}
	o.props.SetStr("name", m.Name)
	o.props.SetStr("class", m.Class.Name)
	return o
}

func (in *Interp) newReflProp(pi *PropInfo, name string, cls *Class) *Object {
	o := in.newObject(in.classes["reflectionproperty"])
	o.internal = &reflData{prop: pi, propName: name, cls: cls}
	o.props.SetStr("name", name)
	if pi != nil {
		o.props.SetStr("class", pi.Class.Name)
	} else {
		o.props.SetStr("class", cls.Name)
	}
	return o
}

func (in *Interp) newReflClass(cls *Class) *Object {
	c := in.classes["reflectionclass"]
	if cls.isEnum() {
		c = in.classes["reflectionenum"]
	}
	o := in.newObject(c)
	o.internal = &reflData{cls: cls}
	o.props.SetStr("name", cls.Name)
	return o
}

func (in *Interp) reflClassArg(v Value, fname string) *Class {
	switch x := v.(type) {
	case *Object:
		return x.class
	case string:
		c := in.lookupClass(x)
		if c == nil {
			in.throwError("ReflectionException", fmt.Sprintf("Class \"%s\" does not exist", x))
		}
		return c
	}
	in.throwError("ReflectionException", fmt.Sprintf("Class \"%s\" does not exist", toStr(v)))
	return nil
}

func (in *Interp) initReflectionClasses() {
	in.defineClass("ReflectionException", "Exception", nil, nil)
	in.defineInterface("Reflector", []string{"Stringable"}, nil)
	modifierNames := func(vis string, static, abstract, final bool) int64 {
		m := int64(0)
		switch vis {
		case "public":
			m |= 1
		case "protected":
			m |= 2
		case "private":
			m |= 4
		}
		if static {
			m |= 16
		}
		if final {
			m |= 32
		}
		if abstract {
			m |= 64
		}
		return m
	}
	// ReflectionNamedType
	in.defineClass("ReflectionType", "", []string{"Stringable"}, []nativeMethod{
		{name: "allowsNull", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			if th.Nullable {
				return true
			}
			for _, n := range th.Names {
				if n == "null" || n == "mixed" {
					return true
				}
			}
			return false
		}},
		{name: "__toString", fn: func(in *Interp, this *Object, args []Value) Value {
			return in.typeHintString(in.rd(this).th)
		}},
	})
	in.defineClass("ReflectionNamedType", "ReflectionType", nil, []nativeMethod{
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			for _, n := range th.Names {
				if n != "null" {
					return in.displayTypeName(n)
				}
			}
			return "null"
		}},
		{name: "isBuiltin", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			for _, n := range th.Names {
				if n == "null" {
					continue
				}
				switch n {
				case "int", "float", "string", "bool", "array", "callable", "iterable", "object", "mixed", "void", "never", "false", "true":
					return true
				}
				return false
			}
			return true
		}},
	})
	in.defineClass("ReflectionUnionType", "ReflectionType", nil, []nativeMethod{
		{name: "getTypes", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			arr := NewArray()
			for _, n := range th.Names {
				arr.Append(in.newReflType(&TypeHint{Names: []string{n}}))
			}
			return arr
		}},
	})
	in.defineClass("ReflectionIntersectionType", "ReflectionType", nil, []nativeMethod{
		{name: "getTypes", fn: func(in *Interp, this *Object, args []Value) Value {
			th := in.rd(this).th
			arr := NewArray()
			for _, n := range th.Names {
				arr.Append(in.newReflType(&TypeHint{Names: []string{n}}))
			}
			return arr
		}},
	})
	// ReflectionParameter
	in.defineClass("ReflectionParameter", "", []string{"Reflector"}, []nativeMethod{
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Name }},
		{name: "getPosition", fn: func(in *Interp, this *Object, args []Value) Value { return int64(in.rd(this).paramIdx) }},
		{name: "getType", fn: func(in *Interp, this *Object, args []Value) Value { return in.newReflType(in.rd(this).param.Type) }},
		{name: "hasType", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Type != nil }},
		{name: "isOptional", fn: func(in *Interp, this *Object, args []Value) Value {
			p := in.rd(this).param
			return p.Default != nil || p.Variadic
		}},
		{name: "isDefaultValueAvailable", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Default != nil }},
		{name: "getDefaultValue", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.param.Default == nil {
				in.throwError("ReflectionException", "Internal error: Failed to retrieve the default value")
			}
			fr := &Frame{vars: map[string]*Ref{}, class: d.cls, staticClass: d.cls, file: in.curFile(), line: in.curLine()}
			return in.eval(fr, d.param.Default)
		}},
		{name: "isVariadic", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Variadic }},
		{name: "isPassedByReference", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.ByRef }},
		{name: "allowsNull", fn: func(in *Interp, this *Object, args []Value) Value {
			p := in.rd(this).param
			if p.Type == nil {
				return true
			}
			if p.Type.Nullable {
				return true
			}
			for _, n := range p.Type.Names {
				if n == "null" || n == "mixed" {
					return true
				}
			}
			return false
		}},
		{name: "isPromoted", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).param.Promote != "" }},
		{name: "getDeclaringFunction", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Method != nil {
				return in.newReflMethod(d.fn.Method, d.cls)
			}
			o := in.newObject(in.classes["reflectionfunction"])
			o.internal = &reflData{fn: d.fn}
			o.props.SetStr("name", d.fn.Name)
			return o
		}},
		{name: "getAttributes", max: 2, fn: func(in *Interp, this *Object, args []Value) Value { return NewArray() }},
		{name: "__toString", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			opt := "required"
			if d.param.Default != nil || d.param.Variadic {
				opt = "optional"
			}
			ts := ""
			if d.param.Type != nil {
				ts = in.typeHintString(d.param.Type) + " "
			}
			return fmt.Sprintf("Parameter #%d [ <%s> %s$%s ]", d.paramIdx, opt, ts, d.param.Name)
		}},
	})
	// ReflectionFunctionAbstract / ReflectionFunction
	fnMethods := []nativeMethod{
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl != nil && d.fn.Decl.Name == "{closure}" {
				return "{closure}"
			}
			return d.fn.Name
		}},
		{name: "getShortName", fn: func(in *Interp, this *Object, args []Value) Value {
			n := in.rd(this).fn.Name
			if i := strings.LastIndexByte(n, '\\'); i >= 0 {
				return n[i+1:]
			}
			return n
		}},
		{name: "getParameters", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			return in.reflParams(d.fn, d.cls)
		}},
		{name: "getNumberOfParameters", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl != nil {
				return int64(len(d.fn.Decl.Params))
			}
			if d.fn.MaxArgs >= 0 {
				return int64(d.fn.MaxArgs)
			}
			return int64(len(d.fn.ParamNames))
		}},
		{name: "getNumberOfRequiredParameters", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl != nil {
				n := 0
				for _, p := range d.fn.Decl.Params {
					if p.Default == nil && !p.Variadic {
						n++
					}
				}
				return int64(n)
			}
			return int64(d.fn.MinArgs)
		}},
		{name: "getReturnType", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl == nil {
				return nil
			}
			return in.newReflType(d.fn.Decl.ReturnType)
		}},
		{name: "hasReturnType", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			return d.fn.Decl != nil && d.fn.Decl.ReturnType != nil
		}},
		{name: "isVariadic", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl == nil {
				return d.fn.MaxArgs < 0
			}
			for _, p := range d.fn.Decl.Params {
				if p.Variadic {
					return true
				}
			}
			return false
		}},
		{name: "isStatic", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.method != nil {
				return d.method.Static
			}
			if d.closure != nil {
				return d.closure.internal.(*Closure).isStatic
			}
			return false
		}},
		{name: "isClosure", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).closure != nil }},
		{name: "isUserDefined", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).fn.Decl != nil }},
		{name: "isInternal", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).fn.Decl == nil }},
		{name: "isGenerator", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			return d.fn.Decl != nil && d.fn.Decl.IsGenerator
		}},
		{name: "returnsReference", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			return d.fn.Decl != nil && d.fn.Decl.ByRefReturn
		}},
		{name: "getDocComment", fn: func(in *Interp, this *Object, args []Value) Value { return false }},
		{name: "getFileName", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl == nil {
				return false
			}
			return d.fn.Decl.File
		}},
		{name: "getStartLine", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl == nil {
				return false
			}
			return int64(d.fn.Decl.Line)
		}},
		{name: "getEndLine", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.fn.Decl == nil {
				return false
			}
			return int64(d.fn.Decl.EndLine)
		}},
		{name: "getNamespaceName", fn: func(in *Interp, this *Object, args []Value) Value {
			n := in.rd(this).fn.Name
			if i := strings.LastIndexByte(n, '\\'); i >= 0 {
				return n[:i]
			}
			return ""
		}},
		{name: "getStaticVariables", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			arr := NewArray()
			if d.closure != nil {
				cl := d.closure.internal.(*Closure)
				for _, n := range cl.boundOrder {
					arr.SetStr(n, cl.bound[n].V)
				}
			}
			for k, r := range d.fn.statics {
				arr.SetStr(k, r.V)
			}
			return arr
		}},
		{name: "getAttributes", max: 2, fn: func(in *Interp, this *Object, args []Value) Value { return NewArray() }},
		{name: "getClosureThis", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.closure != nil {
				return d.closure.internal.(*Closure).this
			}
			return nil
		}},
		{name: "getClosureScopeClass", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.closure != nil {
				if sc := d.closure.internal.(*Closure).scope; sc != nil {
					return in.newReflClass(sc)
				}
			}
			return nil
		}},
	}
	in.defineClass("ReflectionFunctionAbstract", "", []string{"Reflector"}, fnMethods)
	in.defineClass("ReflectionFunction", "ReflectionFunctionAbstract", nil, []nativeMethod{
		{name: "__construct", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			switch x := args[0].(type) {
			case *Object:
				cl, ok := x.internal.(*Closure)
				if !ok {
					in.throwError("ReflectionException", "Function does not exist")
				}
				d.fn = cl.fn
				d.closure = x
				d.cls = cl.scope
				this.props.SetStr("name", "{closure}")
				if cl.fn.Decl == nil || cl.fn.Decl.Name != "{closure}" {
					this.props.SetStr("name", cl.fn.Name)
				}
			case string:
				fn := in.functions[strings.ToLower(strings.TrimPrefix(x, "\\"))]
				if fn == nil {
					in.throwError("ReflectionException", fmt.Sprintf("Function %s() does not exist", x))
				}
				d.fn = fn
				this.props.SetStr("name", fn.Name)
			default:
				in.throwError("ReflectionException", "Function does not exist")
			}
			return nil
		}},
		{name: "invoke", max: -1, fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.closure != nil {
				return in.callValue(d.closure, args)
			}
			return in.callFunction(d.fn, args, nil, nil, nil, nil, in.frame, in.frame.line)
		}},
		{name: "invokeArgs", max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			var a []Value
			if len(args) > 0 {
				if arr, ok := args[0].(*Array); ok {
					a = arr.ValuesDeref()
				}
			}
			if d.closure != nil {
				return in.callValue(d.closure, a)
			}
			return in.callFunction(d.fn, a, nil, nil, nil, nil, in.frame, in.frame.line)
		}},
		{name: "getClosure", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			if d.closure != nil {
				return d.closure
			}
			return in.closureFromFunction(d.fn, nil, nil)
		}},
		{name: "isAnonymous", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			return d.fn.Decl != nil && d.fn.Decl.Name == "{closure}"
		}},
		{name: "__toString", fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			return fmt.Sprintf("Function [ <user> function %s ] {\n}\n", d.fn.Name)
		}},
	})
	in.defineClass("ReflectionMethod", "ReflectionFunctionAbstract", nil, []nativeMethod{
		{name: "__construct", min: 1, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
			var cls *Class
			var mname string
			if len(args) == 1 {
				s := toStr(args[0])
				idx := strings.Index(s, "::")
				if idx < 0 {
					in.throwError("ReflectionException", "ReflectionMethod::__construct(): Argument #1 ($objectOrMethod) must be a valid method name")
				}
				cls = in.reflClassArg(s[:idx], "ReflectionMethod")
				mname = s[idx+2:]
			} else {
				cls = in.reflClassArg(args[0], "ReflectionMethod")
				mname = toStr(args[1])
			}
			m := cls.findMethod(strings.ToLower(mname))
			if m == nil {
				in.throwError("ReflectionException", fmt.Sprintf("Method %s::%s() does not exist", cls.Name, mname))
			}
			d := in.rd(this)
			d.method = m
			d.fn = m.Fn
			d.cls = cls
			this.props.SetStr("name", m.Name)
			this.props.SetStr("class", m.Class.Name)
			return nil
		}},
		{name: "isPublic", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).method.Visibility == "public" }},
		{name: "isPrivate", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).method.Visibility == "private" }},
		{name: "isProtected", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).method.Visibility == "protected" }},
		{name: "isAbstract", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).method.Abstract }},
		{name: "isFinal", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).method.Final }},
		{name: "isConstructor", fn: func(in *Interp, this *Object, args []Value) Value { return strings.ToLower(in.rd(this).method.Name) == "__construct" }},
		{name: "isDestructor", fn: func(in *Interp, this *Object, args []Value) Value { return strings.ToLower(in.rd(this).method.Name) == "__destruct" }},
		{name: "getModifiers", fn: func(in *Interp, this *Object, args []Value) Value {
			m := in.rd(this).method
			return modifierNames(m.Visibility, m.Static, m.Abstract, m.Final)
		}},
		{name: "getDeclaringClass", fn: func(in *Interp, this *Object, args []Value) Value { return in.newReflClass(in.rd(this).method.Class) }},
		{name: "setAccessible", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value { return nil }},
		{name: "invoke", max: -1, fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			var obj *Object
			if len(args) > 0 {
				obj, _ = args[0].(*Object)
				args = args[1:]
			}
			if d.method.Static {
				return in.callFunction(d.fn, args, nil, d.method.Class, d.cls, nil, in.frame, in.frame.line)
			}
			if obj == nil {
				in.throwError("ReflectionException", fmt.Sprintf("Trying to invoke non static method %s::%s() without an object", d.method.Class.Name, d.method.Name))
			}
			return in.callFunction(d.fn, args, obj, d.method.Class, obj.class, nil, in.frame, in.frame.line)
		}},
		{name: "invokeArgs", max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			var obj *Object
			if len(args) > 0 {
				obj, _ = args[0].(*Object)
			}
			var a []Value
			if len(args) > 1 {
				if arr, ok := args[1].(*Array); ok {
					a = arr.ValuesDeref()
				}
			}
			if d.method.Static {
				return in.callFunction(d.fn, a, nil, d.method.Class, d.cls, nil, in.frame, in.frame.line)
			}
			if obj == nil {
				in.throwError("ReflectionException", fmt.Sprintf("Trying to invoke non static method %s::%s() without an object", d.method.Class.Name, d.method.Name))
			}
			return in.callFunction(d.fn, a, obj, d.method.Class, obj.class, nil, in.frame, in.frame.line)
		}},
		{name: "getClosure", max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			d := in.rd(this)
			var obj *Object
			if len(args) > 0 {
				obj, _ = args[0].(*Object)
			}
			if d.method.Static {
				return in.closureFromMethod(d.method, nil, d.cls)
			}
			return in.closureFromMethod(d.method, obj, d.cls)
		}},
		{name: "getPrototype", fn: func(in *Interp, this *Object, args []Value) Value {
			in.throwError("ReflectionException", fmt.Sprintf("Method %s::%s does not have a prototype", in.rd(this).method.Class.Name, in.rd(this).method.Name))
			return nil
		}},
		{name: "hasPrototype", fn: func(in *Interp, this *Object, args []Value) Value { return false }},
		{name: "__toString", fn: func(in *Interp, this *Object, args []Value) Value {
			m := in.rd(this).method
			return fmt.Sprintf("Method [ <user> %s method %s ] {\n}\n", m.Visibility, m.Name)
		}},
	})
	in.addConst(in.classes["reflectionmethod"], "IS_STATIC", int64(16))
	in.addConst(in.classes["reflectionmethod"], "IS_PUBLIC", int64(1))
	in.addConst(in.classes["reflectionmethod"], "IS_PROTECTED", int64(2))
	in.addConst(in.classes["reflectionmethod"], "IS_PRIVATE", int64(4))
	in.addConst(in.classes["reflectionmethod"], "IS_ABSTRACT", int64(64))
	in.addConst(in.classes["reflectionmethod"], "IS_FINAL", int64(32))
	// ReflectionProperty
	in.defineClass("ReflectionProperty", "", []string{"Reflector"}, []nativeMethod{
		{name: "__construct", min: 2, max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
			cls := in.reflClassArg(args[0], "ReflectionProperty")
			name := toStr(args[1])
			pi := cls.findProp(name)
			if pi == nil {
				if _, spi := cls.findStaticProp(name); spi != nil {
					pi = spi
				} else if o, ok := args[0].(*Object); ok {
					if _, exists := o.props.Get(StrKey(name)); !exists {
						in.throwError("ReflectionException", fmt.Sprintf("Property %s::$%s does not exist", cls.Name, name))
					}
				} else {
					in.throwError("ReflectionException", fmt.Sprintf("Property %s::$%s does not exist", cls.Name, name))
				}
			}
			d := in.rd(this)
			d.prop = pi
			d.propName = name
			d.cls = cls
			this.props.SetStr("name", name)
			if pi != nil {
				this.props.SetStr("class", pi.Class.Name)
			} else {
				this.props.SetStr("class", cls.Name)
			}
			return nil
		}},
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value { return in.rd(this).propName }},
		{name: "getValue", max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
