package main

// Vars is a small variable table: linear slice for few entries, map for many.
type Vars struct {
	names []string
	refs  []*Ref
	m     map[string]*Ref
}

const varsMapThreshold = 12

func newVars(n int) *Vars {
	if n > 8 {
		n = 8
	}
	return &Vars{names: make([]string, 0, n), refs: make([]*Ref, 0, n)}
}

func (v *Vars) get(name string) (*Ref, bool) {
	if v.m != nil {
		r, ok := v.m[name]
		return r, ok
	}
	for i, n := range v.names {
		if n == name {
			return v.refs[i], true
		}
	}
	return nil, false
}

func (v *Vars) set(name string, r *Ref) {
	if v.m != nil {
		v.m[name] = r
		return
	}
	for i, n := range v.names {
		if n == name {
			v.refs[i] = r
			return
		}
	}
	if len(v.names) >= varsMapThreshold {
		v.m = make(map[string]*Ref, len(v.names)*2)
		for i, n := range v.names {
			v.m[n] = v.refs[i]
		}
		v.m[name] = r
		v.names = nil
		v.refs = nil
		return
	}
	v.names = append(v.names, name)
	v.refs = append(v.refs, r)
}

func (v *Vars) del(name string) {
	if v.m != nil {
		delete(v.m, name)
		return
	}
	for i, n := range v.names {
		if n == name {
			last := len(v.names) - 1
			v.names[i] = v.names[last]
			v.refs[i] = v.refs[last]
			v.names = v.names[:last]
			v.refs = v.refs[:last]
			return
		}
	}
}

func (v *Vars) each(fn func(name string, r *Ref)) {
	if v.m != nil {
		for n, r := range v.m {
			fn(n, r)
		}
		return
	}
	for i, n := range v.names {
		fn(n, v.refs[i])
	}
}

func (v *Vars) length() int {
	if v.m != nil {
		return len(v.m)
	}
	return len(v.names)
}
