package main

type Fiber struct {
	callback  Value
	obj       *Object
	started   bool
	finished  bool
	running   bool
	suspended bool
	retVal    Value
	transfer  Value
	resumeCh  chan resumeMsg
	yieldCh   chan yieldMsg
	savedFrame *Frame
	savedDepth int
	savedTrace []*Frame
	prev      *Fiber
