func (in *Interp) initFiberClass() {
	in.defineClass("FiberError", "Error", nil, nil)
	fiberOf := func(in *Interp, this *Object) *Fiber {
		f, _ := this.internal.(*Fiber)
		if f == nil {
			in.throwError("FiberError", "Fiber has not been constructed")
		}
		return f
	}
	in.defineClass("Fiber", "", nil, []nativeMethod{
		{name: "__construct", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			in.argCallable("Fiber::__construct", args, 0)
			f := &Fiber{callback: args[0], obj: this, resumeCh: make(chan resumeMsg), yieldCh: make(chan yieldMsg)}
			incRef(args[0])
			this.internal = f
			return nil
		}},
		{name: "start", max: -1, fn: func(in *Interp, this *Object, args []Value) Value {
			f := fiberOf(in, this)
			if f.started {
				in.throwError("FiberError", "Cannot start a fiber that has already been started")
			}
			f.started = true
			go func() {
				var result yieldMsg
				defer func() {
					if r := recover(); r != nil {
						if _, ok := r.(genDestroySignal); ok {
							result = yieldMsg{done: true}
						} else {
							result = yieldMsg{done: true, panicVal: r}
						}
					}
					f.yieldCh <- result
				}()
				<-f.resumeCh
				f.retVal = in.callValue(f.callback, args)
				result = yieldMsg{done: true}
			}()
			return in.fiberSwitch(f, resumeMsg{})
		}},
		{name: "resume", max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			f := fiberOf(in, this)
			if !f.started || !f.suspended || f.finished {
				in.throwError("FiberError", "Cannot resume a fiber that is not suspended")
			}
			var v Value
			if len(args) > 0 {
				v = args[0]
			}
			return in.fiberSwitch(f, resumeMsg{send: v})
		}},
		{name: "throw", min: 1, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			f := fiberOf(in, this)
			if !f.started || !f.suspended || f.finished {
				in.throwError("FiberError", "Cannot resume a fiber that is not suspended")
			}
			ex, _ := args[0].(*Object)
			return in.fiberSwitch(f, resumeMsg{throw: ex})
		}},
		{name: "getReturn", fn: func(in *Interp, this *Object, args []Value) Value {
			f := fiberOf(in, this)
			if !f.finished {
				if !f.started {
					in.throwError("FiberError", "Cannot get fiber return value: The fiber has not been started")
				}
				in.throwError("FiberError", "Cannot get fiber return value: The fiber has not returned")
			}
			return f.retVal
		}},
		{name: "isStarted", fn: func(in *Interp, this *Object, args []Value) Value { return fiberOf(in, this).started }},
		{name: "isSuspended", fn: func(in *Interp, this *Object, args []Value) Value { f := fiberOf(in, this); return f.suspended && !f.finished }},
		{name: "isRunning", fn: func(in *Interp, this *Object, args []Value) Value { f := fiberOf(in, this); return f.running && !f.finished }},
		{name: "isTerminated", fn: func(in *Interp, this *Object, args []Value) Value { return fiberOf(in, this).finished }},
		{name: "suspend", static: true, max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			f := in.currentFiber
			if f == nil {
				in.throwError("FiberError", "Cannot suspend outside of fiber")
			}
			var v Value
			if len(args) > 0 {
				v = args[0]
			}
			// we are inside the fiber goroutine: send suspend, wait for resume
			f.suspended = true
			f.running = false
			f.yieldCh <- yieldMsg{val: v}
			msg := <-f.resumeCh
			f.suspended = false
			f.running = true
			if msg.destroy {
				panic(genDestroySignal{})
			}
			if msg.throw != nil {
				panic(&ThrowSignal{obj: msg.throw})
			}
			return msg.send
		}},
		{name: "getCurrent", static: true, fn: func(in *Interp, this *Object, args []Value) Value {
			if in.currentFiber == nil {
				return nil
			}
			return in.currentFiber.obj
		}},
	})
}

// fiberSwitch transfers control into the fiber until it suspends or finishes
func (in *Interp) fiberSwitch(f *Fiber, msg resumeMsg) Value {
	cFrame, cDepth, cTrace := in.frame, in.depth, in.traceStack
	prevFiber := in.currentFiber
	f.prev = prevFiber
	in.currentFiber = f
	if f.savedFrame != nil {
		in.frame = f.savedFrame
		in.depth = f.savedDepth
		in.traceStack = f.savedTrace
	} else {
		in.depth = cDepth + 1
	}
	f.running = true
	f.obj.rc++
	f.resumeCh <- msg
	ym := <-f.yieldCh
	f.obj.rc--
	f.savedFrame, f.savedDepth, f.savedTrace = in.frame, in.depth, in.traceStack
	in.frame, in.depth, in.traceStack = cFrame, cDepth, cTrace
	in.currentFiber = prevFiber
	if ym.done {
		f.finished = true
		f.running = false
		f.suspended = false
		if ym.panicVal != nil {
			panic(ym.panicVal)
		}
		return nil
	}
	return ym.val
}
