{"command":"cd /workspace/src && cat >> reflection.go <<'EOF'

// attribute reflection
func (in *Interp) attrsArray(attrs []AttrDecl, args []Value, scope *Class) *Array {
	arr := NewArray()
	var filter string
	flags := int64(0)
	if len(args) > 0 && args[0] != nil {
		filter = strings.ToLower(strings.TrimPrefix(toStr(args[0]), "\\"))
	}
	if len(args) > 1 {
		flags = toInt(args[1])
	}
	for _, a := range attrs {
		if filter != "" {
			ln := strings.ToLower(a.Name)
			if flags&2 != 0 { // IS_INSTANCEOF
				c := in.lookupClass(a.Name)
				fc := in.lookupClass(filter)
				if c == nil || fc == nil || !c.isSubclassOf(fc) {
					continue
				}
			} else if ln != filter {
				continue
			}
		}
		o := in.newObject(in.classes["reflectionattribute"])
		ad := a
		o.internal = &reflAttr{decl: &ad, scope: scope}
		arr.Append(o)
	}
	return arr
}

type reflAttr struct {
	decl  *AttrDecl
	scope *Class
}

func (in *Interp) initReflectionAttribute() {
	in.defineClass("ReflectionAttribute", "", []string{"Reflector"}, []nativeMethod{
		{name: "getName", fn: func(in *Interp, this *Object, args []Value) Value {
			return this.internal.(*reflAttr).decl.Name
		}},
		{name: "getArguments", fn: func(in *Interp, this *Object, args []Value) Value {
			ra := this.internal.(*reflAttr)
			fr := &Frame{vars: newVars(2), class: ra.scope, staticClass: ra.scope, file: in.curFile(), line: ra.decl.Line}
			arr := NewArray()
			for _, a := range ra.decl.Args {
				v := in.eval(fr, a.Expr)
				if a.Name != "" {
					arr.SetStr(a.Name, v)
				} else {
					arr.Append(v)
				}
			}
			return arr
		}},
		{name: "newInstance", fn: func(in *Interp, this *Object, args []Value) Value {
			ra := this.internal.(*reflAttr)
			cls := in.lookupClass(ra.decl.Name)
			if cls == nil {
				in.throwError("Error", fmt.Sprintf("Attribute class \"%s\" not found", ra.decl.Name))
			}
			fr := &Frame{vars: newVars(2), class: ra.scope, staticClass: ra.scope, file: in.curFile(), line: ra.decl.Line}
			return in.instantiate(cls, fr, ra.decl.Args, nil)
		}},
		{name: "getTarget", fn: func(in *Interp, this *Object, args []Value) Value { return int64(1) }},
		{name: "isRepeated", fn: func(in *Interp, this *Object, args []Value) Value { return false }},
		{name: "__toString", fn: func(in *Interp, this *Object, args []Value) Value {
			return "Attribute [ " + this.internal.(*reflAttr).decl.Name + " ]\n"
		}},
	})
	in.addConst(in.classes["reflectionattribute"], "IS_INSTANCEOF", int64(2))
	// Attribute class itself
	attr := in.defineClass("Attribute", "", nil, []nativeMethod{
		{name: "__construct", max: 1, fn: func(in *Interp, this *Object, args []Value) Value {
			flags := int64(63)
			if len(args) > 0 {
				flags = toInt(args[0])
			}
			this.props.SetStr("flags", flags)
			return nil
		}},
	})
	in.addProp(attr, "flags", "public", int64(63))
	for name, v := range map[string]int64{"TARGET_CLASS": 1, "TARGET_FUNCTION": 2, "TARGET_METHOD": 4, "TARGET_PROPERTY": 8, "TARGET_CLASS_CONSTANT": 16, "TARGET_PARAMETER": 32, "TARGET_ALL": 63, "IS_REPEATABLE": 64} {
		in.addConst(attr, name, v)
	}
	in.defineClass("AllowDynamicProperties", "", nil, nil)
	in.defineClass("SensitiveParameter", "", nil, nil)
	in.defineClass("ReturnTypeWillChange", "", nil, nil)
	in.defineClass("Override", "", nil, nil)
	in.defineClass("Deprecated", "", nil, []nativeMethod{
		{name: "__construct", max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
			if len(args) > 0 {
				this.props.SetStr("message", args[0])
			}
			if len(args) > 1 {
				this.props.SetStr("since", args[1])
			}
			return nil
		}},
	})
	// replace getAttributes implementations
	setAttrs := func(clsName string, get func(in *Interp, this *Object) ([]AttrDecl, *Class)) {
		c := in.classes[clsName]
		in.addNativeMethod(c, nativeMethod{name: "getAttributes", max: 2, fn: func(in *Interp, this *Object, args []Value) Value {
			attrs, scope := get(in, this)
			return in.attrsArray(attrs, args, scope)
		}})
	}
	setAttrs("reflectionclass", func(in *Interp, this *Object) ([]AttrDecl, *Class) {
		c := in.rd(this).cls
		if c.Decl == nil {
			return nil, c
		}
		return c.Decl.Attrs, c
	})
	setAttrs("reflectionfunctionabstract", func(in *Interp, this *Object) ([]AttrDecl, *Class) {
		d := in.rd(this)
		if d.fn.Decl == nil {
			return nil, d.cls
		}
		return d.fn.Decl.Attrs, d.cls
	})
	setAttrs("reflectionproperty", func(in *Interp, this *Object) ([]AttrDecl, *Class) {
		d := in.rd(this)
		if d.prop == nil || d.prop.Decl == nil {
			return nil, d.cls
		}
		if d.prop.Decl.Attrs == nil && d.prop.Class.Decl != nil {
			// promoted property: attrs on ctor param
			for _, m := range d.prop.Class.Decl.Methods {
				if strings.ToLower(m.Name) == "__construct" {
					for _, p := range m.Params {
						if p.Promote != "" && p.Name == d.prop.Name {
							return p.Attrs, d.cls
						}
					}
				}
			}
		}
		return d.prop.Decl.Attrs, d.cls
	})
	setAttrs("reflectionparameter", func(in *Interp, this *Object) ([]AttrDecl, *Class) {
		d := in.rd(this)
		return d.param.Attrs, d.cls
	})
	setAttrs("reflectionclassconstant", func(in *Interp, this *Object) ([]AttrDecl, *Class) {
		d := in.rd(this)
		if d.cls.Decl != nil {
			for _, cc := range d.cls.Decl.Consts {
				if cc.Name == d.constName {
					return cc.Attrs, d.cls
				}
			}
			for _, ec := range d.cls.Decl.Cases {
				if ec.Name == d.constName {
					return ec.Attrs, d.cls
				}
			}
		}
		return nil, d.cls
	})
}
