package main

import (
	crand "crypto/rand"
	"encoding/binary"
	"math"
)

type randEngine interface {
	next32() uint32
}

type secureEngine struct{}

func (secureEngine) next32() uint32 {
	var b [4]byte
	crand.Read(b[:])
	return binary.LittleEndian.Uint32(b[:])
}

type mtEngine struct{ m *MtRand }

func (e *mtEngine) next32() uint32 { return e.m.next32() }

func rangeFromEngine(e randEngine, min, max int64) int64 {
	umax := uint64(max) - uint64(min)
	if umax == 0 {
		return min
	}
	if umax > math.MaxUint32 {
		result := uint64(e.next32())<<32 | uint64(e.next32())
		if umax == math.MaxUint64 {
			return min + int64(result)
		}
		umax++
		if umax&(umax-1) != 0 {
			limit := math.MaxUint64 - (math.MaxUint64 % umax) - 1
			for result > limit {
				result = uint64(e.next32())<<32 | uint64(e.next32())
			}
		}
		return min + int64(result%umax)
	}
	r32 := e.next32()
	um := uint32(umax)
	if um == math.MaxUint32 {
		return min + int64(r32)
	}
	um++
	if um&(um-1) != 0 {
		limit := uint32(math.MaxUint32 - (math.MaxUint32 % uint64(um)) - 1)
		for r32 > limit {
			r32 = e.next32()
		}
	}
	return min + int64(r32%um)
}

