<?php
// Interface constant + abstract + interface default via trait, __toString in string contexts, comparisons of objects
class Money implements JsonSerializable, Stringable {
    private function __construct(private int $cents, private string $cur) {}
    public static function of(float $amt, string $cur = 'USD'): self { return new self((int)round($amt * 100), $cur); }
    public function add(Money $o): self { $this->assertSame($o); return new self($this->cents + $o->cents, $this->cur); }
    public function mul(float $f): self { return new self((int)round($this->cents * $f), $this->cur); }
    private function assertSame(Money $o): void { if ($o->cur !== $this->cur) throw new InvalidArgumentException("Currency mismatch: {$this->cur} vs {$o->cur}"); }
    public function __toString(): string { return sprintf("%s %s", number_format($this->cents / 100, 2), $this->cur); }
    public function jsonSerialize(): array { return ['amount' => $this->cents / 100, 'currency' => $this->cur]; }
    public function equals(Money $o): bool { return $this == $o; }
    public function cents(): int { return $this->cents; }
}
$a = Money::of(19.99); $b = Money::of(5.01); $sum = $a->add($b);
echo $sum, " | ", $sum->mul(1.5), " | ", json_encode([$a, $b]), " | ", $a->equals(Money::of(19.99)) ? 'eq' : 'ne', " | ", $a == $b ? 'eq' : 'ne', " | ", $a < $b ? 'lt' : 'ge', "\n";
