echo "Total: $sum", " ", strlen($sum), " ", str_pad($sum, 12, '*', STR_PAD_LEFT), " ", in_array("25.00 USD", [$sum]) ? 'found' : 'no', " ", $sum . "", " ", (string)$sum === "25.00 USD" ? 'same' : 'diff', "\n";
$items = [Money::of(3), Money::of(1), Money::of(2)]; usort($items, fn($x, $y) => $x->cents() <=> $y->cents()); echo implode(", ", $items), "\n";
